    ["哟，你这新来的，认得老子？"] = "Ồ,ǦǉƙǃǦǂớƾǦǉớƾǦǃƐǓǦǃƽậǃǦǇƶǦǁƃǄǦǉửǦǈƶǄ?",
    ["兵痞丙"] = "ƝƾǃƽǦƷƾềǃǦƝƓǃƽ",
    ["正月初一\n一年过去，差事如水井不波。新岁新气象，今年定要寻到转机！\n\n二月十六\n近两月来主要观察宣徽院的同僚行事，从开年祭礼到年节宴会到长春节，每日都只见 them 急匆匆入官署，却从不见 them 离开。如此忙碌恐怕伤身，不妥，不妥。\n\n三月十八\n幸甚幸甚！原本意图谋求三司之职，幸甚未成，否则昨日失火，恐怕便要遭灾。\n如此想来，我于数算一道也不甚精通，恐怕难当每月每年的账本盘算之职。不妥，不妥。\n\n五月初九\n司天监每日装忙，实则甚为清闲，但若逢天象有异、贵人患病、灾祸连绵，恐要沦为担责的弃子。不妥，不妥。\n\n六月廿二\n罗问之啊罗问之，你不能再挑挑拣拣了，难道还要如此蹉跎下去吗？\n\n八月初三\n听闻昭文馆有意补缺，但只缺一人，岂能弃齐祥在此？不妥，不妥。"] = "ƨồǃƼǦǂộǉǦǉƽƑǃƼǦƢƾƙǃƼ\nƨộǉǦǃăǂǦǉǇƇƾǦǆǊƶ,ǦƸƇǃƼǦǋƾệƸǦǋẫǃǦǁặǃƼǦǁẽǦǃƽưǦǃướƸǦƼƾếǃƼ.ǦƩăǂǦǂớƾǦǀƽƓǦǉượǃƼǦǂớƾ,ǦǃăǂǦǃƶǓǦǃƽấǉǦđịǃƽǦǅƽảƾǦǉƔǂǦƸƽǄǦǇƶǦƸƽǊǓểǃǦƸơ!\n\nƨườƾǦǈƑǊǦǉƽƑǃƼǦƣƶƾ\nƢầǃǦƽƶƾǦǉƽƑǃƼǦǃƶǓǦƸƽủǦǓếǊǦǆǊƶǃǦǈƑǉǦƸƑƸƽǦƽƐǃƽǦǈựǦƸủƶǦđồǃƼǦǁƾƙǊǦởǦǥǊǓƙǃǦƣǊǓǦƱƾệǃ,ǦǉừǦǉếǦǁễǦđầǊǦǃăǂǦđếǃǦǓếǃǦǉƾệƸǦǃƼƐǓǦǥếǉǦǇồƾǦđếǃǦǥǇườǃƼǦƳǊƁǃǦǥƾếǉ,ǦǃƼƐǓǦǃƐǄǦƸũǃƼǦƸƽỉǦǉƽấǓǦƽọǦǋộƾǦǋộƾǦǋƐǃƼǦǋƐǃƼǦǋƐǄǦǆǊƶǃǦǉƽự,ǦǃƽưǃƼǦƸƽưƶǦǉừǃƼǦǉƽấǓǦƽọǦǇờƾǦđƾ.ǦƝậǃǦǇộǃǦǃƽưǦǉƽếǦƺǦǁƐǦƽạƾǦǉƽƁǃ,ǦǀƽƇǃƼǦổǃ,ǦǀƽƇǃƼǦổǃ.\n\nƨườƾǦǉƑǂǦǉƽƑǃƼǦƝƶ\nƨƶǓǦǂắǃǦǉƽƶǓ,ǦǂƶǓǦǂắǃǦǉƽƶǓ!ǦƱốǃǦđịǃƽǦƸầǊǦǂộǉǦƸƽứƸǦởǦǥƶǂǦǥƾ,ǦǂƶǓǦǂƐǦǀƽƇǃƼǦǉƽƐǃƽ,ǦǃếǊǦǀƽƇǃƼǦǋụǦƽỏƶǦƽǄạǃǦƽƇǂǦǆǊƶǦƺǦǁƐǦđƃǦƼặǅǦƽọƶǦǇồƾ.\nƩƼƽĩǦǁạƾǦǉƽƔ,ǦǉƶǦđốƾǦǋớƾǦđạǄǦǉƓǃƽǦǉǄƑǃǦƸũǃƼǦƸƽẳǃƼǦǂấǓǦǉƾǃƽǦǉƽƇǃƼ,ǦƺǦǁƐǦǀƽƚǦƼƑǃƽǦǃổƾǦǉǇọǃƼǦǉǇƑƸƽǦǀƾểǂǦǀƙǦǈổǦǈƑƸƽǦƽƐǃƼǦǉƽƑǃƼǦƽƐǃƼǦǃăǂ.ǦƦƽƇǃƼǦổǃ,ǦǀƽƇǃƼǦổǃ.\n\nƨồǃƼǦƸƽƓǃǦǉƽƑǃƼǦƩăǂ\nǥƾǦǥƽƾƙǃǦƢƾƑǂǦǃƼƐǓǦǃƼƐǓǦƼƾảǦǋờǦƷậǃǦǇộǃ,ǦǉƽựƸǦƸƽấǉǦǁạƾǦǇấǉǦǃƽƐǃǦǃƽƃ,ǦǃƽưǃƼǦǃếǊǦƼặǅǦǁƕƸǦǉƽƾƙǃǦǉượǃƼǦǤịǦǉƽườǃƼ,ǦǆǊƈǦǃƽƁǃǦǁƁǂǦƷệǃƽ,ǦǉƶƾǦươǃƼǦǁƾƙǃǦǂƾƙǃ,ǦƺǦǁƐǦǈẽǦƷịǦđƺǂǦǇƶǦǁƐǂǦƸǄǃǦǉốǉǦǉƽƓǦƼƑǃƽǦǉộƾ.ǦƦƽƇǃƼǦổǃ,ǦǀƽƇǃƼǦổǃ.\n\nƣăǂǦƽƶƾǦǉƽƑǃƼǦƮƑǊ\nƧƶǦƱấǃǦƞƽƾǦƐǦƧƶǦƱấǃǦƞƽƾ,ǦǃƼươƾǦǀƽƇǃƼǦǉƽểǦƸứǦǀƗǃǦƸƑǦƸƽọǃǦƸƶǃƽǦǂƃƾǦđượƸ,ǦǁẽǦǃƐǄǦƸƛǃǦǂǊốǃǦǁƃǃƼǦǅƽƓǦǉƽờƾǦƼƾƶǃǦǃƽưǦǋậǓǦǈƶǄ?\n\nƨồǃƼǦƷƶǦǉƽƑǃƼǦǥƑǂ\nƩƼƽƺǦǃƚƾǦƞƽƾƙǊǦƱăǃǦƬǊƑǃǦƸƚǦƈǦǉǊǓểǃǦǃƼườƾǦƸƛǃǦǉƽƾếǊ,ǦǃƽưǃƼǦƸƽỉǦǉƽƾếǊǦǂộǉǦǋị,ǦǁẽǦǃƐǄǦǁạƾǦƷỏǦǁạƾǦǥềǦǥườǃƼǦởǦđƁǓ?ǦƦƽƇǃƼǦổǃ,ǦǀƽƇǃƼǦổǃ.",
    ["且问你，若命你镇守边陲，当施何策以保境 an 民？"] = "ǥƶǦƽỏƾǦǃƼươƾ,ǦǃếǊǦǁệǃƽǦƸƽǄǦǃƼươƾǦǉǇấǃǦǉƽủǦƷƾƙǃǦǉƽƖǓ,ǦǃƼươƾǦǈẽǦǉƽƾǦƽƐǃƽǦǈƑƸƽǦǁượƸǦƼƔǦđểǦƷảǄǦƸảǃƽǦƶǃǦǤƁǃ?",
    ["刻刀铢两，侠名千钧. 散落滹沱河畔的义士英名，等待着后来者将它们一一拾集，刻在碑上，铭于心间。"] = "ƦƽắƸǦđƶǄǦǤƖǦǃƽẹ,ǦƽƾệǅǦǤƶǃƽǦǃƼƐǃǦƸƁǃ.ǦƜǃƽǦǤƶǃƽǦƸủƶǦƸƑƸǦǃƼƽĩƶǦǈĩǦǇảƾǦǇƑƸǦƷƙǃǦƷờǦǈƇǃƼǦƣƇǦĐƐǦđƶǃƼǦƸƽờǦđợƾǦƽậǊǦǃƽƁǃǦđếǃǦǉƽǊǦǉƽậǅǦǉừǃƼǦƸƽƕǉǦǂộǉ,ǦǀƽắƸǦǁƙǃǦƷƾƶǦđƑ,ǦƼƽƾǦǉạƸǦǉǇǄǃƼǦǉƾǂ.",
    ["九重春色·彩凤飞"] = "ƞửǊǦǥǇƖǃƼǦƳǊƁǃǦƮắƸǦ·ǦǥƽảƾǦƫƽượǃƼǦƫƽƾ",
    ["泥犁三垢·痴障"] = "ƩƙǦƧƙǦǥƶǂǦƞấǊǦ·ǦƮƾǦƞƽướǃƼ",
    ["先埋伏起来，免得打草惊蛇。"] = "ƨƶƾǦǅƽụƸǦǉǇướƸǦđƃ,ǦǉǇƑǃƽǦđƑǃƽǦǇắǃǦđộǃƼǦƸỏ.",
    ["长春节在即，宫内将举宴庆寿。礼部建议广纳清音，特许京城各大名乐坊选送乐师入宫，协助教坊司编排乐舞。\n醉花阴的弟子陶之清奉旨编曲，在宫里四处走动，以谱 new 曲。\n宫廷乐官柳律与他意见相左，恰好与你三人同行，共同在宫廷赏雪寻音。"] = "ǥǇườǃƼǦƳǊƁǃǦǥƾếǉǦđƶǃƼǦđếǃǦƼầǃ,ǦǉǇǄǃƼǦƸǊǃƼǦǈắǅǦǂởǦǓếǃǦǉƾệƸǦǂừǃƼǦǉƽọ.ǦƧễǦƷộǦǀƾếǃǦǃƼƽịǦǇộǃƼǦƸửƶǦđƚǃǦǉƽƶǃƽǦƁǂǦǅƽươǃƼǦǍƶ,ǦđặƸǦƸƑƸƽǦƸƽǄǦƸƑƸǦǃƽạƸǦǅƽườǃƼǦǤƶǃƽǦǉƾếǃƼǦǀƾǃƽǦǉƽƐǃƽǦǉǊǓểǃǦƸƽọǃǦǃƽạƸǦǈưǦǋƐǄǦƸǊǃƼ,ǦƽỗǦǉǇợǦƢƾƑǄǦƫƽườǃƼǦǥǓǦƷƾƙǃǦǈǄạǃǦǃƽạƸǦǋũ.\nĐệǦǉửǦǥƕǓǦƣǄƶǦƀǂǦǁƐǦĐƐǄǦƞƽƾǦǥƽƶǃƽǦǅƽụǃƼǦƸƽỉǦƷƾƙǃǦǀƽƕƸ,ǦđƶǃƼǦđƾǦǁạƾǦǀƽắǅǦǃơƾǦǉǇǄǃƼǦƸǊǃƼǦđểǦǅƽổǦǀƽƕƸǦǂớƾ.\nƩƽạƸǦǆǊƶǃǦƸǊǃƼǦđƔǃƽǦƧƾễǊǦƧǊậǉǦƷấǉǦđồǃƼǦƈǦǀƾếǃǦǋớƾǦƽắǃ,ǦǋừƶǦƽƶǓǦƸƖǃƼǦƷƶǦǃƼườƾǦƸƑƸǦǃƼươƾǦđồǃƼǦƽƐǃƽ,ǦƸƖǃƼǦǉƽưởǃƼǦǉǊǓếǉǦǉƔǂǦƁǂǦǃơƾǦƸǊǃƼǦđƔǃƽ.",
    ["左藏库&三馆巡逻_低berg级官员29_顺时针巡逻"] = "ǥǊầǃǦǉǇƶǦǥảǦǥƐǃƼǦƦƽốǦ&ǦǥƶǂǦƬǊƑǃǦ_ǦƬǊƶǃǦǋƾƙǃǦƸấǅǦǉƽấǅǦ29Ǧ_ǦǥǊầǃǦǉǇƶǦǉƽǊậǃǦƸƽƾềǊǦǀƾǂǦđồǃƼǦƽồ",
    ["说好了一根签子一条命，可总有人想作弊。\n\n……\n\n刘思农签：小萝卜\n\n罗成武签：若抽到此签，转赠老幼\n\n秦远签：秦远(被划掉)  小萝卜\n\n刘小妹签：鹤老头\n\n符晓签：鹤\n\n唐文耀签：符晓 \n\n丁苹签：小萝卜\n\n邵伋签：小萝卜\n\n桓云签：张老太\n\n梁望签：林老伯\n\n沙信臣签：圆圆\n\n桑语签：圆圆\n\n柔娘签：圆圆\n\n林老伯签：张芹\n\n张老太签：林有柴\n\n詹聿签：风叙\n\n风叙签：詹聿\n\n……\n\n看，人定胜天嘞。"] = "ĐƃǦǃƚƾǦǇƅǦǂộǉǦƸƁǓǦǉƽăǂǦǂộǉǦǂạǃƼǦǃƼườƾ,ǦǋậǓǦǂƐǦǁǊƇǃǦƸƚǦǀẻǦǂǊốǃǦƼƾƶǃǦǁậǃ.\n\n……\n\nǥƽăǂǦƧưǊǦǥưǦƩƇǃƼ:ǦǥƾểǊǦƧƶǦƝặƸ\n\nǥƽăǂǦƧƶǦǥƽƐǃƽǦƱƅ:ǦƩếǊǦǇƕǉǦđượƸǦǉƽẻǦǃƐǓ,ǦǍƾǃǦǃƽườǃƼǦƸƽǄǦǃƼườƾǦƼƾƐǦǉǇẻǦǃƽỏ\n\nǥƽăǂǦǥầǃǦƱƾễǃ:ǦǥầǃǦƱƾễǃǦ(ƷịǦƼạƸƽǦđƾ)ǦǥƾểǊǦƧƶǦƝặƸ\n\nǥƽăǂǦƧưǊǦǥƾểǊǦƨǊộƾ:ǦƣạƸǦǁƃǄǦđầǊ\n\nǥƽăǂǦƫƽƖǦƣƾểǊ:ǦƣạƸ\n\nǥƽăǂǦĐườǃƼǦƱăǃǦǝƾệǊ:ǦƫƽƖǦƣƾểǊ\n\nǥƽăǂǦĐƾǃƽǦƝƔǃƽ:ǦǥƾểǊǦƧƶǦƝặƸ\n\nǥƽăǂǦǥƽƾệǊǦƞấǅ:ǦǥƾểǊǦƧƶǦƝặƸ\n\nǥƽăǂǦƣǄƐǃǦƱƁǃ:ǦǥǇươǃƼǦǁƃǄǦǉƽƑƾ\n\nǥƽăǂǦƧươǃƼǦƱọǃƼ:ǦƧƁǂǦǁƃǄǦƷƑ\n\nǥƽăǂǦƮƶǦǥƓǃǦǥƽầǃ:ǦƱƾƙǃǦƱƾƙǃ\n\nǥƽăǂǦǥƶǃƼǦƩƼữ:ǦƱƾƙǃǦƱƾƙǃ\n\nǥƽăǂǦƩƽǊǦƩươǃƼ:ǦƱƾƙǃǦƱƾƙǃ\n\nǥƽăǂǦƧƁǂǦǁƃǄǦƷƑ:ǦǥǇươǃƼǦƞầǃ\n\nǥƽăǂǦǥǇươǃƼǦǁƃǄǦǉƽƑƾ:ǦƧƁǂǦƣữǊǦƮƐƾ\n\nǥƽăǂǦƞƽƾƙǂǦǝǊậǉ:ǦƫƽǄǃƼǦǥự\n\nǥƽăǂǦƫƽǄǃƼǦǥự:ǦƞƽƾƙǂǦǝǊậǉ\n\n……\n\nƳƺǂǦǀƔƶ,ǦǃƽƁǃǦđịǃƽǦǉƽắǃƼǦǉƽƾƙǃǦđấǓ.",
    ["放心，有锅 cũng là ngã bối. 就说我年纪大、眼睛花；要不，我体力跟不上、跟丢了……"] = "ƴƙǃǦǉƁǂ,ǦƸƚǦǉộƾǦǁỗƾǦƼƔǦƸũǃƼǦǁƐǦǉƶǦƼƑǃƽ.ǦƞứǦǃƚƾǦǉƶǦǉǊổƾǦǉƑƸǦđƃǦƸƶǄ,ǦǂắǉǦǂờǦƸƽƁǃǦƸƽậǂ;ǦƷằǃƼǦǀƽƇǃƼǦǉƽƔǦǃƚƾǦǉƶǦǉƽểǦǁựƸǦǀƽƇǃƼǦǉƽƺǄǦǀịǅ,ǦđểǦǂấǉǦǤấǊǦǇồƾ...",
    ["父老乡친觉得是个体面活儿，亲朋好友觉得赚得多，都说皇城的风水养人，我却觉得吃人。"] = "ƫƽụǦǁƃǄǦƽươǃƼǦǉƽƁǃǦđềǊǦǃƼƽĩǦđƁǓǦǁƐǦǋƾệƸǦǉƽểǦǤƾệǃ,ǦƷằǃƼǦƽữǊǦǉƽƁǃǦǉƽƓƸƽǦđềǊǦǃƼƽĩǦǁƐǦǀƾếǂǦđượƸǦǃƽƾềǊ,ǦƶƾǦƸũǃƼǦƷảǄǦǅƽǄǃƼǦǉƽủǓǦƣǄƐǃƼǦǉƽƐǃƽǦǃǊƇƾǦǤưỡǃƼǦƸǄǃǦǃƼườƾ,ǦǃƽưǃƼǦǉƶǦǁạƾǦǉƽấǓǦǃƚǦǃƽưǦăǃǦǉươƾǦǃǊốǉǦǈốǃƼǦǃƼườƾǦǉƶǦǋậǓ.",
    ["拾取烛台"] = "ƩƽặǉǦƸƽƁǃǦǃếǃ",
    ["鹤助城防，多有败绩。非机关术不精妙，而是所赴之地皆多危急。后多收弟子，授城防术以为助力。然而大势难违，弟子之中，有驰援 các xứ者，有见事不成弃而去者，又有折损战死者。\n来来去去，锥心蚀骨。\n一日鹤又吃败绩，流矢袭来，恰中腰间昔日鸦所赠司南佩，佩碎而人存。仓皇之间，不及捡拾，仍忙于迁移百姓之事。待至安全之地，方觉怅然。\n不想百姓自寻一黑石，仿刻此佩，复赠于鹤。\n鹤摩挲良久，此后随身，寸步未离。\n“先生，为吾等弟子之司南。”\n“百姓，为吾之司南。”"] = "ƣạƸǦƽỗǦǉǇợǦǅƽƛǃƼǦǉƽủǦǉƽƐǃƽ,ǦƷạƾǦǉǇậǃǦǀƽƇǃƼǦƓǉ.ǦƞƽẳǃƼǦǅƽảƾǦǤǄǦƸơǦǆǊƶǃǦǉƽǊậǉǦǀƽƇǃƼǦǉƾǃƽǦǤƾệǊ,ǦǂƐǦǁƐǦǋƔǦǃƽữǃƼǦǃơƾǦđƾǦđếǃǦđềǊǦǂǊƇǃǦǅƽầǃǦǃƼǊǓǦƸấǅ.ǦƮƶǊǦǃƐǓǦǉƽǊǦǃƽậǃǦǃƽƾềǊǦđệǦǉử,ǦǉǇǊǓềǃǦǤạǓǦǉƽƐǃƽǦǅƽƛǃƼǦǉƽǊậǉǦđểǦǉǇợǦǁựƸ.ǦǥƽếǦǃƽưǃƼǦđạƾǦǉƽếǦǀƽƚǦǋƃǃǦƽồƾ,ǦǉǇǄǃƼǦđƑǂǦđệǦǉử,ǦƸƚǦǃƼườƾǦƸƽƾǦǋƾệǃǦǀƽắǅǦǃơƾ,ǦƸƚǦǀẻǦǉƽấǓǦǋƾệƸǦƸƽẳǃƼǦǉƽƐǃƽǦǃƙǃǦƷỏǦđƾ,ǦǁạƾǦƸƚǦǃƼườƾǦƽǓǦǈƾǃƽǦǉửǦǉǇậǃ.\nĐếǃǦđƾǦǇờƾǦƽợǅ,ǦđƶǊǦǉƽấǊǦǉƁǂǦƸƶǃ.\nƨộǉǦǃƼƐǓǦǃọǦƣạƸǦǁạƾǦƷạƾǦǉǇậǃ,ǦǁǄạǃǦǉƾễǃǦƷắǃǦǉớƾ,ǦǉǇƕǃƼǦǃƼƶǓǦǂƾếǃƼǦǃƼọƸǦƷộƾǦǥưǦƩƶǂǦđƺǄǦƷƙǃǦƽƇǃƼǦǤǄǦƬǊạǦǉặǃƼǦǃăǂǦǍưƶ,ǦǃƼọƸǦǋỡǦǃƼườƾǦƸƛǃ.ǦǥǇǄǃƼǦǁƕƸǦƽǄảǃƼǦǁǄạǃǦǀƽƇǃƼǦǀịǅǦǃƽặǉǦǁấǓ,ǦǋẫǃǦǅƽảƾǦǂảƾǦǂƾếǉǦǤƾǦǉảǃǦƷƑƸƽǦǉƓǃƽ.ǦĐợƾǦđếǃǦǃơƾǦƶǃǦǉǄƐǃ,ǦǂớƾǦǉƽấǓǦƷƖƾǦǃƼƖƾ.\nƞƽẳǃƼǦǃƼờǦƷƑƸƽǦǉƓǃƽǦǉựǦǉƔǂǦǂộǉǦǋƾƙǃǦđƑǦđƺǃ,ǦǅƽỏǃƼǦǉƽƺǄǦǂƾếǃƼǦǃƼọƸǦǂƐǦǀƽắƸǦǁạƾǦǇồƾǦǉặǃƼǦƸƽǄǦƣạƸ.\nƣạƸǦǋǊốǉǦǋƺǦƽồƾǦǁƁǊ,ǦǉừǦđƚǦǋềǦǈƶǊǦǁǊƇǃǦǂƶǃƼǦǉƽƺǄǦƷƙǃǦǂƔǃƽ,ǦǃửƶǦƷướƸǦǀƽƇǃƼǦǇờƾ.\n\"ǥƾƙǃǦǈƾǃƽǦǁƐǦǀƾǂǦƸƽỉǦǃƶǂǦƸủƶǦđƑǂǦđệǦǉửǦƸƽƕǃƼǦǉƶ.\"\n\"ƝƑƸƽǦǉƓǃƽǦǁƐǦǀƾǂǦƸƽỉǦǃƶǂǦƸủƶǦǉƶ.\"",
    ["#J逐狼心经#E在突破到四重之后，#Y武学技#E与#Y特殊技#E的效果得到了额外增强。\n具体效果：#Y武学技#E能够获得更高的气血伤害增益，#Y特殊技#E則能对满层#J流血#E状态下的目标造成#Y高额流血#E伤害。"] = "#JǥǇụƸǦƧƶǃƼǦǥƁǂǦƦƾǃƽ#EǦǈƶǊǦǀƽƾǦđộǉǦǅƽƑǦđếǃǦǉầǃƼǦǉƽứǦǉư,ǦƽƾệǊǦǆǊảǦƸủƶǦ#YƱƅǦƽọƸǦǀỹ#EǦǋƐǦ#YƦỹǦǉƽǊậǉǦđặƸǦƷƾệǉ#EǦđƃǦđượƸǦǉăǃƼǦƸườǃƼǦǉƽƙǂ.\nƣƾệǊǦǆǊảǦƸụǦǉƽể:Ǧ#YƱƅǦƽọƸǦǀỹ#EǦƸƚǦǉƽểǦǃƽậǃǦđượƸǦǂứƸǦǉăǃƼǦǈƑǉǦǉƽươǃƼǦǀƽƓǦƽǊǓếǉǦƸƶǄǦƽơǃ,Ǧ#YƦỹǦǉƽǊậǉǦđặƸǦƷƾệǉ#EǦƸƚǦǉƽểǦƼƁǓǦ#YǈƑǉǦǉƽươǃƼǦǍǊấǉǦƽǊǓếǉǦƸựƸǦǁớǃ#EǦƸƽǄǦǂụƸǦǉƾƙǊǦđƶǃƼǦǉǇǄǃƼǦǉǇạǃƼǦǉƽƑƾǦ#JƳǊấǉǦƽǊǓếǉ#EǦƸộǃƼǦǤồǃǦǉốƾǦđƶ.",
    ["这枚名为守心的射玦，出自鸦之手，是青第一次下山时的临别赠礼。\n\n“青妹此去不知何时回山，唯愿此志不改……此心不易。”\n\n故而当青戴着这枚射玦下山时，踌躇满志。\n\n以执剑之武，以墨守之技，定能护得一方安宁。\n\n她在山外遇见了个小哑巴。小哑巴没有名字，瘦得像风里的一根枯草，可“枯草”还在风里挣扎。\n\n小哑巴很聪明，也很懂事，她从不问青从哪来，又要去哪，还会不会回来，她只是拼命地学，拼命地学。\n\n仅三天，小哑巴就会做一些简单的陷阱了，她高兴地比划，意思是她能抓到兔子了，不会饿死了，大姐姐可以放心地离开了。\n\n像她这样的枯草，就算被雨水滋养，也长成不了大树的。\n\n青不懂为什么小哑巴不肯跟自己走，可恰逢彼时山外有事要办。她离开前想了又想，还是脱下了手上的射玦，送给小哑巴。\n\n“送我这枚射玦的人说，佩之能守心明志。我把它借你几日，你要是想法变了，愿意和我走，就等我回来那天戴着它来找 me。”\n\n\n\n然而等青回山时，鸦却没看到青信中所说的小哑巴。\n\n青说，她回去找了，可小哑巴不见了，村民说是小哑巴跑了出去，被狼咬死了。可……可为何那枚射玦戴在别人手上?\n\n鸦看着青通红的眼睛，没有再问。\n\n他只是将原本的射玦一拆为二，青一半，他一半。\n\n“愿为你分担一半。”\n\n与子同心，与子同念，与子同担。"] = "ƨƾếǃƼǦǍạǦǆǊǓếǉǦǉƙǃǦƼọƾǦǥƽủǦǥƁǂǦǃƐǓǦǤǄǦƸƽƓǃƽǦǉƶǓǦƬǊạǦǁƐǂǦǇƶ,ǦǁƐǦǂƚǃǦǆǊƐǦǉƾễǃǦƷƾệǉǦǀƽƾǦǥƽƶǃƽǦǁầǃǦđầǊǦǍǊốǃƼǦǃƕƾ.\n\n\"ǥƽƶǃƽǦǂǊộƾǦƸƽǊǓếǃǦǃƐǓǦđƾǦǀƽƇǃƼǦƷƾếǉǦǀƽƾǦǃƐǄǦǋềǦǃƕƾ,ǦƸƽỉǦǃƼǊǓệǃǦƸƽƓǦǃƐǓǦǀƽƇǃƼǦđổƾ...ǦǉƁǂǦǃƐǓǦƸƽẳǃƼǦǤờƾ.\"\n\nǥƽếǦǃƙǃǦǀƽƾǦǥƽƶǃƽǦđƺǄǦǍạǦǆǊǓếǉǦǃƐǓǦǍǊốǃƼǦǃƕƾ,ǦǉǇǄǃƼǦǁƛǃƼǦǉǇƐǃǦđầǓǦƽǄƐƾǦƷƃǄ.\n\nǝƖǃƼǦǋƅǦǃƼƽệǦƸầǂǦǀƾếǂ,ǦǤƖǃƼǦǀỹǦǃăǃƼǦƨặƸǦǥƽủ,ǦǃƽấǉǦđịǃƽǦƸƚǦǉƽểǦƷảǄǦǋệǦǂộǉǦǅƽươǃƼǦƶǃǦǃƾǃƽ.\n\nƩƐǃƼǦƼặǅǦǂộǉǦǉƾểǊǦƑǦǃƽƶǦởǦǃƼǄƐƾǦǃƕƾ.ǦǥƾểǊǦƑǦǃƽƶǦǀƽƇǃƼǦƸƚǦǉƙǃ,ǦƼầǓǦƼƛǦǃƽưǦǂộǉǦǃƼọǃǦƸỏǦǀƽƇǦǉǇǄǃƼǦƼƾƚ,ǦǃƽưǃƼǦ\"ǃƼọǃǦƸỏǦǀƽƇ\"ǦấǓǦǋẫǃǦđƶǃƼǦǀƽƇǃƼǦǃƼừǃƼǦǋậǉǦǁộǃ.\n\nǥƾểǊǦƑǦǃƽƶǦǇấǉǦǉƽƇǃƼǦǂƾǃƽ,ǦƸũǃƼǦǇấǉǦƽƾểǊǦƸƽǊǓệǃ,ǦǃƐǃƼǦǀƽƇǃƼǦƷƶǄǦƼƾờǦƽỏƾǦǥƽƶǃƽǦǉừǦđƁǊǦǉớƾ,ǦđƾǦđƁǊ,ǦƸƚǦǆǊƶǓǦǁạƾǦƽƶǓǦǀƽƇǃƼ,ǦǃƐǃƼǦƸƽỉǦǁƾềǊǦǂạǃƼǦǂƐǦƽọƸ,ǦǁƾềǊǦǂạǃƼǦǂƐǦƽọƸ.\n\nƞƽỉǦǉǇǄǃƼǦƷƶǦǃƼƐǓ,ǦǉƾểǊǦƑǦǃƽƶǦđƃǦƷƾếǉǦǁƐǂǦǋƐƾǦǁǄạƾǦƷẫǓǦđơǃǦƼƾảǃ,ǦǃƐǃƼǦǋǊƾǦǋẻǦǇƶǦƽƾệǊ,ǦƈǦǃƚƾǦǂƔǃƽǦđƃǦƸƚǦǉƽểǦƷắǉǦđượƸǦǉƽỏ,ǦǀƽƇǃƼǦƷịǦƸƽếǉǦđƚƾǦǃữƶ,ǦđạƾǦǉỷǦǉỷǦƸƚǦǉƽểǦǓƙǃǦǉƁǂǦǇờƾǦđƾǦǇồƾ.\n\nƩƽưǃƼǦƽạǃƼǦƸỏǦǀƽƇǦǃƽưǦǃƐǃƼ,ǦǤƖǦđượƸǦǃướƸǦǂưƶǦǃǊƇƾǦǤưỡǃƼ,ǦƸũǃƼǦƸƽẳǃƼǦǉƽểǦǁớǃǦǃổƾǦǉƽƐǃƽǦđạƾǦǉƽụ.\n\nǥƽƶǃƽǦǀƽƇǃƼǦƽƾểǊǦǋƔǦǈƶǄǦǉƾểǊǦƑǦǃƽƶǦǀƽƇǃƼǦƸƽịǊǦđƾǦƸƖǃƼǦǂƔǃƽ,ǦǃƽưǃƼǦđƕǃƼǦǁƕƸǦđƚǦǃƼǄƐƾǦǃƕƾǦƸƚǦǋƾệƸǦƸầǃǦǁƐǂ.ǦǥǇướƸǦǀƽƾǦđƾǦǃƐǃƼǦǃƼƽĩǦđƾǦǃƼƽĩǦǁạƾ,ǦǋẫǃǦǉƽƑǄǦǍạǦǆǊǓếǉǦǉǇƙǃǦǉƶǓǦǂƔǃƽǦǇƶǦǉặǃƼǦƸƽǄǦǉƾểǊǦƑǦǃƽƶ.\n\n\"ƩƼườƾǦǉặǃƼǦǉƶǦǍạǦǆǊǓếǉǦǃƐǓǦǃƚƾǦǇằǃƼ,ǦđƺǄǦǃƚǦƸƚǦǉƽểǦƼƾữǦǋữǃƼǦǉƁǂǦƸƽƓ.ǦǥƶǦƸƽǄǦǂǊộƾǦǂượǃǦǋƐƾǦǃƼƐǓ,ǦǃếǊǦǂǊộƾǦđổƾǦƈ,ǦǂǊốǃǦđƾǦƸƖǃƼǦǉƶ,ǦǉƽƔǦƽƃǓǦđƺǄǦǃƚǦđợƾǦǉƶǦǆǊƶǓǦǁạƾǦǉƔǂǦǉƶ.\"\n\nƩƽưǃƼǦǀƽƾǦǥƽƶǃƽǦǋềǦǃƕƾ,ǦƬǊạǦǁạƾǦǀƽƇǃƼǦǉƽấǓǦǉƾểǊǦƑǦǃƽƶǦǂƐǦǥƽƶǃƽǦǃƽắƸǦǉớƾǦǉǇǄǃƼǦǉƽư.\n\nǥƽƶǃƽǦǃƚƾ,ǦǃƐǃƼǦđƃǦǆǊƶǓǦǁạƾǦǉƔǂ,ǦǃƽưǃƼǦǉƾểǊǦƑǦǃƽƶǦđƃǦƷƾếǃǦǂấǉ,ǦǤƁǃǦǁƐǃƼǦƷảǄǦǉƾểǊǦƑǦǃƽƶǦƸƽạǓǦǇƶǦǃƼǄƐƾǦƷịǦǈƚƾǦƸắǃǦƸƽếǉǦǇồƾ.ǦƩƽưǃƼ...ǦǃƽưǃƼǦǉạƾǦǈƶǄǦǍạǦǆǊǓếǉǦǀƾƶǦǁạƾǦđƺǄǦǉǇƙǃǦǉƶǓǦǀẻǦǀƽƑƸ?\n\nƬǊạǦǃƽƔǃǦđƇƾǦǂắǉǦđỏǦƽǄƺǦƸủƶǦǥƽƶǃƽ,ǦǀƽƇǃƼǦƽỏƾǦǉƽƙǂǦǁờƾǦǃƐǄ.\n\nƣắǃǦƸƽỉǦđƺǂǦǍạǦǆǊǓếǉǦƷƶǃǦđầǊǦǉƑƸƽǦǁƐǂǦđƇƾ,ǦǥƽƶǃƽǦǂộǉǦǃửƶ,ǦƽắǃǦǂộǉǦǃửƶ.\n\n\"ƩƼǊǓệǃǦƸƖǃƼǦǂǊộƾǦƼƑǃƽǦǋƑƸǦǂộǉǦǃửƶ.\"\n\nǝữǦǉửǦđồǃƼǦǉƁǂ,ǦǤữǦǉửǦđồǃƼǦǃƾệǂ,ǦǤữǦǉửǦđồǃƼǦđƶǂ.",
    ["规范治理，当 từ pháp độ bắt đầu. Cái hướng này có thể, tiếp tục chi tiết hóa."] = "ƬǊǓǦǅƽạǂǦǉǇịǦǁƈ,ǦǃƙǃǦƷắǉǦđầǊǦǉừǦǅƽƑǅǦđộ.ǦƣướǃƼǦđƾǦǃƐǓǦǀƽảǦǆǊƶǃ,ǦƽƃǓǦǉƾếǅǦǉụƸǦǁƐǂǦǇƅǦƸƽƾǦǉƾếǉ.",
    ["……将军说了……变数……南边……"] = "...ǦǥướǃƼǦǆǊƁǃǦǃƚƾǦǇồƾ...ǦƷƾếǃǦǈố...ǦǅƽƓƶǦǃƶǂ...",
