    ["惆怅画屏一株雪，知是清风不负期. "] = "ǥǇƖǦǉǇướǃƼǦƽọƶǦƷƔǃƽǦǃƽấǉǦƸƽƾǦǉǊǓếǉ,ǦǉǇƾǦǉƽịǦǉƽƶǃƽǦǅƽǄǃƼǦƷấǉǦǅƽụǦǀỳ.Ǧ(ƩƼẩǃǦǃƼơǦǉǇướƸǦƷƔǃƽǦƽọƶǦǂộǉǦǃƽƐǃƽǦǉǊǓếǉ,ǦƷƾếǉǦǇằǃƼǦƼƾƚǦǉƽƶǃƽǦƸƽẳǃƼǦǅƽụǦƽẹǃǦǉƽề)",
    ["通篇皆是情绪之言，于国事并无助益. "] = "ƞảǦƷƐƾǦǉǄƐǃǦǁƐǦǁờƾǦǁẽǦƸảǂǦǉƓǃƽ,ǦƸƽẳǃƼǦƸƚǦƓƸƽǦƼƔǦƸƽǄǦǆǊốƸǦǈự.",
    ["米粮味道如何，并非朝堂议事之范畴. "] = "ƨƖƾǦǋịǦƼạǄǦǉƽƚƸǦǉƽếǦǃƐǄ,ǦǀƽƇǃƼǦǉƽǊộƸǦǅƽạǂǦǋƾǦǃƼƽịǦǈựǦǉạƾǦǉǇƾềǊǦđƔǃƽ.",
    ["这宫里头平日里死气沉沉的，今日倒是有几分生气. "] = "ǥǇǄǃƼǦƸǊǃƼǦǃƐǓǦǃƼƐǓǦǉƽườǃƼǦǋốǃǦǉĩǃƽǦǂịƸƽ,ǦƽƇǂǦǃƶǓǦǍƺǂǦǇƶǦǁạƾǦƸƚǦǋƐƾǦǅƽầǃǦǈƾǃƽǦǀƽƓ.",
    ["符击余嘉共著的宣传册，书页中另附一张授课优惠券. "] = "ƞǊốǃǦǈƑƸƽǦǃƽỏǦǤǄǦƫƽƖǦƦƓƸƽǦǋƐǦǝưǦƢƾƶǦƸƖǃƼǦǈǄạǃ,ǦǉǇǄǃƼǦǉǇƶǃƼǦǈƑƸƽǦƸƚǦǀƘǂǦǉƽƺǄǦǂộǉǦǅƽƾếǊǦƼƾảǂǦƼƾƑǦǤạǓǦƽọƸ.",
    ["天泉弟子，为助王清师叔而秉刀赴义，急切地想前往战场，让手中的刀能早日帮上王清师叔. "] = "ĐệǦǉửǦǥƽƾƙǃǦǥǊǓềǃ,ǦǋƔǦƼƾƕǅǦƱươǃƼǦǥƽƶǃƽǦǈưǦǉƽƕƸǦǂƐǦƸầǂǦđƶǄǦƽƐǃƽǦƽƾệǅ,ǦǃƚǃƼǦǁƛǃƼǦǂǊốǃǦǇƶǦƸƽƾếǃǦǉǇườǃƼǦđểǦǉƽƶǃƽǦđƶǄǦǉǇǄǃƼǦǉƶǓǦǈớǂǦƼƾƕǅǦƓƸƽǦđượƸǦƸƽǄǦǈưǦǉƽƕƸ.",
