    ["如此务 thực，何愁大事不成？大加赞许. "] = "ƱụǦǉƽựƸǦǃƽưǦǋậǓ,ǦǁǄǦƼƔǦđạƾǦǈựǦǀƽƇǃƼǦǉƽƐǃƽ?ǦƭấǉǦđƑǃƼǦǀƽƺǃǦǃƼợƾ.",
    ["人点起明灯，既是为了度夜，亦是为了寄情。灯火不灭之处，尽 là 人间真情。修佛修道，不过是修情修心。情天下之大情，不情一己之私情，方为正法大道。"] = "ƩƼườƾǦǉƽắǅǦǁƙǃǦǂƾǃƽǦđăǃƼ,ǦǋừƶǦǁƐǦđểǦǆǊƶǦđƙǂǦǤƐƾ,ǦƸũǃƼǦǁƐǦđểǦƼửƾǦƼắǂǦǉƁǂǦǉƔǃƽ.ǦƩơƾǦǃƐǄǦđƘǃǦƽǄƶǦǀƽƇǃƼǦǉắǉ,ǦǃơƾǦđƚǦƸƽƓǃƽǦǁƐǦƸƽƁǃǦǉƔǃƽǦǃƽƁǃǦƼƾƶǃ.ǦǥǊǦƫƽậǉǦǉǊǦĐạǄ,ǦƸƽẳǃƼǦǆǊƶǦƸũǃƼǦǁƐǦǉǊǦǉƔǃƽǦǉǊǦǉƁǂ.ǦƱƔǦƸƑƾǦǉƔǃƽǦǁớǃǦǁƶǄǦƸủƶǦǉƽƾƙǃǦƽạ,ǦǀƽƇǃƼǦǋƔǦƸƑƾǦǉƔǃƽǦǇƾƙǃƼǦƸủƶǦƷảǃǦǉƽƁǃ,ǦđƚǦǂớƾǦǁƐǦƸƽƓǃƽǦǅƽƑǅǦđạƾǦđạǄ.",
    ["我朝六尚局沿袭前朝，分#Y尚宫、尚仪、尚服、尚食、尚寝、尚功#E六尚，虽然大家每天都在上工当差，但没有人在#Y尚班局#E喵. "] = "ǥǇƾềǊǦǉƶǦƧụƸǦǥƽượǃƼǦƞụƸǦǀếǦǉƽừƶǦǉǇƾềǊǦǉǇướƸ,ǦƸƽƾƶǦǁƐǂǦǁụƸǦǉƽượǃƼ:Ǧ#YǦǥƽượǃƼǦƞǊǃƼ,ǦǥƽượǃƼǦƩƼƽƾ,ǦǥƽượǃƼǦƫƽụƸ,ǦǥƽượǃƼǦǥƽựƸ,ǦǥƽượǃƼǦǥẩǂ,ǦǥƽượǃƼǦƞƇǃƼǦ#E.ǦǥǊǓǦǇằǃƼǦǂọƾǦǃƼườƾǦƽằǃƼǦǃƼƐǓǦđềǊǦđƶǃƼǦǁƐǂǦǋƾệƸǦđươǃƼǦǈƶƾ,ǦǃƽưǃƼǦǀƽƇǃƼǦƸƚǦƶƾǦởǦ#YǦǥƽượǃƼǦƝƶǃǦƞụƸǦ#EǦđƁǊǦǂƾƙǊ.",
    ["雪灾为重，却能有条不紊，尤其庇佑孤弱之举值得称赞. "] = "ǥǊǓếǉǦǉƶƾǦǃƼƽƾƙǂǦǉǇọǃƼǦǂƐǦǋẫǃǦƸƚǦǉƽểǦǈắǅǦǍếǅǦǃƼăǃǦǃắǅ,ǦđặƸǦƷƾệǉǦǁƐǦƽƐǃƽǦđộǃƼǦƸƽƺǦƸƽởǦǀẻǦǓếǊǦƸƇǦđộƸǦǉƽậǉǦđƑǃƼǦǀƽƺǃǦǃƼợƾ.",
    ["这护腕是前几日我刚买来的，给将士用，便少吃些训练的苦头. "] = "ƞặǅǦƽộǦƸổǦǉƶǓǦǃƐǓǦǁƐǦǉƶǦǋừƶǦǂớƾǦǂǊƶǦǂấǓǦƽƇǂǦǉǇướƸ,ǦđƺǂǦƸƽǄǦǉướǃƼǦǈĩǦǤƖǃƼ,ǦđểǦƽọǦƷớǉǦƸƽịǊǦǀƽổǦǀƽƾǦǁǊǓệǃǦǉậǅ.",
    ["上头的人评价说定夺没能切中要点，有些偏了. "] = "ǥƽượǃƼǦƸấǅǦđƑǃƽǦƼƾƑǦǇằǃƼǦǆǊǓếǉǦđịǃƽǦǃƐǓǦƸƽưƶǦǉǇƕǃƼǦǋƐǄǦǉǇọǃƼǦđƾểǂ,ǦƸƚǦǅƽầǃǦǁệƸƽǦǁạƸǦǇồƾ.",
    ["（摇头）他，没有手段……要，找到他. "] = "(ƧắƸǦđầǊ)Ǧƣắǃ,ǦǀƽƇǃƼǦƸƚǦǉƽủǦđǄạǃ...ǦƫƽảƾǦǉƔǂǦđượƸǦƽắǃ.",
    ["（继续尴尬，但懂了娘子的心思）秋凤不敢……今日本就是笑招，宝慧虽会端水奉茶，但银筝这太极功夫更胜一筹，既能洒扫，又能博您一笑……是银筝胜了. "] = "(ǥƾếǅǦǉụƸǦǃƼượǃƼǦǃƼƖǃƼǦǃƽưǃƼǦđƃǦƽƾểǊǦǉƁǂǦƈǦƸủƶǦǃươǃƼǦǉử)ǦǥƽǊǦƫƽượǃƼǦǀƽƇǃƼǦǤƑǂ...ǦƣƇǂǦǃƶǓǦǋốǃǦǁƐǦƸƽƾƙǊǦǋǊƾǦǋẻ,ǦƝảǄǦǥǊệǦǉǊǓǦƷƾếǉǦǤƁǃƼǦǃướƸǦǅƽƶǦǉǇƐ,ǦǃƽưǃƼǦƸƇǃƼǦǅƽǊǦǥƽƑƾǦƞựƸǦƸủƶǦƩƼƁǃǦǥǇƶǃƽǦǃƐǓǦǁạƾǦƸƶǄǦƽơǃǦǂộǉǦƷậƸ,ǦǋừƶǦƸƚǦǉƽểǦǆǊƗǉǦǤọǃ,ǦǋừƶǦƸƚǦǉƽểǦǁƐǂǦǃƼườƾǦǂỉǂǦƸườƾ...ǦƧƐǦƩƼƁǃǦǥǇƶǃƽǦǉƽắǃƼǦǇồƾ.",
    ["那倒是没有……湖边风大，可冷. "] = "ƞƽǊǓệǃǦđƚǦǉƽƔǦǀƽƇǃƼǦƸƚ...ǦƢƾƚǦƷƙǃǦƽồǦǁớǃǦǁắǂ,ǦǁạǃƽǦǁắǂǦđấǓ.",
    ["此事知道了，不是急务. "] = "ƱƾệƸǦǃƐǓǦđƃǦǇƅ,ǦǀƽƇǃƼǦǅƽảƾǦǋƾệƸǦƼấǅ.",
    ["看上去是些机要……赵大哥你听，这南唐内斗——"] = "ǥǇƇǃƼǦƸƚǦǋẻǦǁƐǦǋƐƾǦǉƾǃǦƸơǦǂậǉ...ǦǥǇƾệǊǦđạƾǦƸƶǦƽǊǓǃƽǦǃƼƽƺǦǍƺǂ,ǦƸƽǊǓệǃǦǃộƾǦđấǊǦƩƶǂǦĐườǃƼǦǃƐǓǦ——",
    ["这几天，大家的脸上多了好多笑容，一定是因为吃到了大侠香香的烤饼. "] = "ƨấǓǦǃƼƐǓǦǃƶǓ,ǦǉǇƙǃǦǂặǉǦǂọƾǦǃƼườƾǦđƃǦǉƽƙǂǦǃƽƾềǊǦǃụǦƸườƾ,ǦƸƽắƸǦƸƽắǃǦǁƐǦǋƔǦđượƸǦăǃǦƷƑǃƽǦǃướǃƼǦǉƽơǂǦǅƽứƸǦƸủƶǦđạƾǦƽƾệǅ.",
    ["万物有声，应律而来. 同归共鸣，乘风遨游. "] = "ƱạǃǦǋậǉǦƽữǊǦǉƽƶǃƽ,ǦứǃƼǦǁǊậǉǦǃƽƾǦǁƶƾ.ǦĐồǃƼǦǆǊǓǦƸộǃƼǦǂƾǃƽ,ǦǉƽừƶǦǅƽǄǃƼǦǃƼƶǄǦǤǊ.",
    ["左街3-平minh12-对话"] = "ǥảǦƩƽƶƾǦ3Ǧ-ǦƝƔǃƽǦǤƁǃǦ12Ǧ-ǦĐốƾǦǉƽǄạƾ",
    ["不见山-P1千夜无 địch"] = "ƝấǉǦƦƾếǃǦƮơǃǦ-Ǧƫ1ǦǥƽƾƙǃǦǝạǦƱƇǦĐịƸƽ",
    ["束罪阁-BOSS"] = "ǥƽƕƸǦǥộƾǦƞƑƸǦ-ǦƝƪƮƮ",
    ["调查古琴"] = "ĐƾềǊǦǉǇƶǦƸổǦƸầǂ",
    ["可那内侍若当真冷心，又怎会写下如此愤懑之言. "] = "ƩƽưǃƼǦǋịǦǃộƾǦǉƽịǦǀƾƶǦǃếǊǦǉƽậǉǦǈựǦǉǊǓệǉǦǉƔǃƽ,ǦǈƶǄǦƸƚǦǉƽểǦǋƾếǉǦǇƶǦǃƽữǃƼǦǁờƾǦǅƽẫǃǦǊấǉǦđếǃǦǉƽế.",
    ["一个由桃木制成的小人偶，亦称桃梗，用于祭祀之物. "] = "ƨộǉǦƽƔǃƽǦǃƽƁǃǦǃƽỏǦǁƐǂǦǉừǦƼỗǦđƐǄ,ǦƸƛǃǦƼọƾǦǁƐǦĐƐǄǦƩƼạǃƽ,ǦǋậǉǦǤƖǃƼǦđểǦǉếǦǁễ.",
    ["此次诊治，您且安心. 哪怕未愈，您也无需挂怀. "] = "ƧầǃǦƸƽẩǃǦǉǇịǦǃƐǓǦǃƼƐƾǦƸứǦǓƙǃǦǉƁǂ.ǦǝẫǊǦǀƽƇǃƼǦǀƽỏƾǦƽẳǃ,ǦǃƼƐƾǦƸũǃƼǦƸƽớǦƷậǃǦǁƛǃƼ.",
    ["一点春色飞雪里，原是东君试笔工。\n夫天地者，万籁之声也。 万物可铸为兵甲，兵甲中复现万物之形，凝万象之声为光. 物有消弭之期，而道存永恒之常. "] = "ƩƽấǉǦđƾểǂǦǍǊƁǃǦǈắƸǦǅƽƾǦǉǊǓếǉǦǁƈ,ǦǃƼǊǓƙǃǦǉƽịǦĐƇǃƼǦƬǊƁǃǦǉƽƓǦƷƕǉǦƸƇǃƼ.\nƫƽƐǂǦǉƽƾƙǃǦđịƶǦƼƾả,ǦǋạǃǦǁạƾǦƸƽƾǦǉƽƶǃƽǦǤƃ.ǦƱạǃǦǋậǉǦǀƽảǦƸƽƕǦǋƾǦƷƾǃƽǦƼƾƑǅ,ǦƷƾǃƽǦƼƾƑǅǦǉǇǊǃƼǦǅƽụƸǦƽƾệǃǦǋạǃǦǋậǉǦƸƽƾǦƽƔǃƽ,ǦǃƼưǃƼǦǋạǃǦǉượǃƼǦƸƽƾǦǉƽƶǃƽǦǋƾǦǆǊƶǃƼ.ǦƱậǉǦƽữǊǦǉƾƙǊǦǤƾǦƸƽƾǦǀỳ,ǦǃƽƾǦđạǄǦǉồǃǦǋĩǃƽǦƽằǃƼǦƸƽƾǦǉƽườǃƼ.",
    ["举手之劳，老伯别客气. 只是……拿回来的时候，符纸的字迹还没干呢. 或许是墙缝太潮湿了？"] = "ƞƽỉǦǁƐǦǉƾệǃǦǉƶǓǦǉƽƇƾ,ǦǁƃǄǦƷƑǦđừǃƼǦǀƽƑƸƽǦǀƽƓ.ǦƞƚǦđƾềǊ...ǦǁƕƸǦǁấǓǦǋề,ǦǃƗǉǦǂựƸǦǉǇƙǃǦǉờǦǅƽƖǦǋẫǃǦƸƽưƶǦǀƽƇǦƽẳǃ.ǦƫƽảƾǦƸƽăǃƼǦǁƐǦǤǄǦǀƽƺǦǉườǃƼǦǆǊƑǦẩǂǦướǉ?",
    ["他从封龙书院来，先生总说他的嘴成天没个把门的，不像是个读书人. 他这次来，就是想要证明给先生看，平日书院里教的那些书，他是真看进去了. "] = "ƣắǃǦđếǃǦǉừǦƫƽǄǃƼǦƧǄǃƼǦǥƽưǦƱƾệǃ,ǦǉƾƙǃǦǈƾǃƽǦǁǊƇǃǦƷảǄǦƸƑƾǦǂƾệǃƼǦƽắǃǦǈǊốǉǦǃƼƐǓǦǀƽƇǃƼǦƸƚǦǀƽƚƶ,ǦƸƽẳǃƼǦƼƾốǃƼǦǀẻǦđọƸǦǈƑƸƽǦƸƽƕǉǦǃƐǄ.ǦƧầǃǦǃƐǓǦƽắǃǦǉớƾǦǁƐǦǂǊốǃǦƸƽứǃƼǦǂƾǃƽǦƸƽǄǦǉƾƙǃǦǈƾǃƽǦǉƽấǓ,ǦǃƽữǃƼǦƸǊốǃǦǈƑƸƽǦǉƽưǦǋƾệǃǦǤạǓǦǉƽườǃƼǦǃƼƐǓ,ǦƽắǃǦǉƽựƸǦǈựǦđƃǦǁĩǃƽǦƽộƾǦđượƸǦǇồƾ.",
    ["亭中棋，一局未尽。\n白子渐成掎角之势，黑子则图以众击寡。\n两相对峙，胜负难分。直至白子棋筋被吃，再至无子可下，胜负将明。\n\n“人心幽晦无可信，何不抽身重布一局，以求千秋之谋。”\n“雪入土中化泥，雪落枝头为花. 只消人间处处春，雪自会落向清明处. 何不以身入局，救得朝夕，再图千秋。”\n“白子已无，你守不住的。”\n“此局不成，仍有下局. 我等不成，还有来人。”\n无子可下，当如何？\n无子可下，仍有一子——以身入局，焚血为子。\n\n亭中棋，此局已尽，胜负未分。"] = "ƞờǦǉǇǄǃƼǦđƔǃƽ,ǦǂộǉǦǋƑǃǦƸƽưƶǦǉƐǃ.\nƬǊƁǃǦǉǇắǃƼǦǤầǃǦǉạǄǦǉƽếǦỷǦǤốƸ,ǦǆǊƁǃǦđƺǃǦǁạƾǦǉǄƶǃǦǉƓǃƽǦǁấǓǦđƇǃƼǦđƑǃƽǦƓǉ.\nƣƶƾǦƷƙǃǦđốƾǦđầǊ,ǦǉƽắǃƼǦƷạƾǦǀƽƚǦǅƽƁǃ.ǦƞƽǄǦđếǃǦǀƽƾǦǉửǦǁộǦƸủƶǦǆǊƁǃǦǉǇắǃƼǦƷịǦƸƽặǃ,ǦǇồƾǦđếǃǦǁƕƸǦǀƽƇǃƼǦƸƛǃǦǆǊƁǃǦđểǦđƾ,ǦǉƽắǃƼǦƷạƾǦǂớƾǦǤầǃǦǈƑǃƼǦǉỏ.\n\n\"ƧƛǃƼǦǃƼườƾǦǊǦǉốƾǦƸƽẳǃƼǦǉƽểǦǉƾǃ,ǦǈƶǄǦǀƽƇǃƼǦǤứǉǦƑǄǦǇƶǦđƾ,ǦƷƐǓǦǁạƾǦǂộǉǦǋƑǃǦǂớƾǦđểǦǂưǊǦƸầǊǦđạƾǦǃƼƽƾệǅǦǉƽƾƙǃǦǉƽǊ.\"\n\"ǥǊǓếǉǦǇơƾǦǍǊốǃƼǦđấǉǦƽƚƶǦƷƖǃ,ǦǉǊǓếǉǦđậǊǦđầǊǦƸƐǃƽǦǉƽƐǃƽǦƽǄƶ.ǦƞƽỉǦƸầǃǦǃƽƁǃǦƼƾƶǃǦǃơƾǦǃơƾǦǁƐǦǍǊƁǃ,ǦǉǊǓếǉǦǉựǦǈẽǦǇơƾǦǋềǦƸƽốǃǦǉƽƶǃƽǦǂƾǃƽ.ǦƮƶǄǦǀƽƇǃƼǦǉựǦǂƔǃƽǦǃƽậǅǦƸǊộƸ,ǦƸứǊǦǁấǓǦƽƾệǃǦǉạƾǦǇồƾǦǂớƾǦǉƓǃƽǦđếǃǦǉƽƾƙǃǦǉƽǊ.\"\n\"ƬǊƁǃǦǉǇắǃƼǦđƃǦƽếǉ,ǦǃƼươƾǦǀƽƇǃƼǦƼƾữǦǃổƾǦđƁǊ.\"\n\"ƱƑǃǦǃƐǓǦǀƽƇǃƼǦǉƽƐǃƽ,ǦǋẫǃǦƸƛǃǦǋƑǃǦǈƶǊ.ǦƞƽƕǃƼǦǉƶǦǀƽƇǃƼǦǉƽƐǃƽ,ǦǋẫǃǦƸƛǃǦǃƼườƾǦǉớƾ.\"\nƦƽƇǃƼǦƸƛǃǦǆǊƁǃǦđểǦđƾ,ǦǅƽảƾǦǁƐǂǦǈƶǄ?\nƦƽƇǃƼǦƸƛǃǦǆǊƁǃǦđểǦđƾ,ǦǋẫǃǦƸƛǃǦǂộǉǦǆǊƁǃǦ——ǦǉựǦǂƔǃƽǦǃƽậǅǦƸǊộƸ,ǦđốǉǦǂƑǊǦǁƐǂǦǆǊƁǃ.\n\nƞờǦǉǇǄǃƼǦđƔǃƽ,ǦǋƑǃǦǃƐǓǦđƃǦǉậǃ,ǦǉƽắǃƼǦƷạƾǦƸƽưƶǦǅƽƁǃ.",
