    ["一枚刻着“天神千万”的契丹压胜钱. "] = "ƨộǉǦđồǃƼǦǉƾềǃǦÁǅǦǥƽắǃƼǦƸủƶǦƦƽƾếǉǦĐƶǃǦƸƚǦǀƽắƸǦƸƽữǦ\"ǥƽƾƙǃǦǥƽầǃǦǥƽƾƙǃǦƱạǃ\".",
    ["测试组件"] = "ƧƾǃƽǦǀƾệǃǦǉƽửǦǃƼƽƾệǂ",
    ["江湖事，朝堂事，在马车内铺开第一层真相……皇帝？宝库？我？"] = "ƞƽǊǓệǃǦƼƾƶǃƼǦƽồ,ǦƸƽǊǓệǃǦǉǇƾềǊǦđườǃƼ,ǦƷƙǃǦǉǇǄǃƼǦǍƺǦǃƼựƶǦǅƽơƾǦƷƐǓǦǁớǅǦƸƽƁǃǦǉướǃƼǦđầǊǦǉƾƙǃ……ǦƣǄƐǃƼǦđế?ǦƝảǄǦǀƽố?Ǧǥƶ?",
    ["平日里爱看话本的文官，被安排来应付武官，但胆子小，不敢得罪人。    "] = "ƱăǃǦǆǊƶǃǦǃƼƐǓǦǉƽườǃƼǦǉƽƓƸƽǦđọƸǦǉƽǄạƾǦƷảǃ,ǦđượƸǦǈắǅǦǍếǅǦđếǃǦđểǦứǃƼǦǅƽƚǦǋƅǦǆǊƶǃ,ǦǃƽưǃƼǦǃƽƑǉǦƼƶǃ,ǦǀƽƇǃƼǦǤƑǂǦđắƸǦǉộƾǦǃƼườƾǦǀƽƑƸ.",
    ["{}释放水人"] = "{}ǦǉǇƾệǊǦƽồƾǦǥƽủǓǦƩƽƁǃ",
