    ["雨残英，鲤娉婷. 池烟醉柳，荷露流金。"] = "ƱũǦǉƐǃǦƶǃƽ,ǦǁƈǦǈƓǃƽǦđƔǃƽ.ǦǥǇƔǦǓƙǃǦǉƕǓǦǁƾễǊ,ǦƽƐǦǁộǦǁưǊǦǀƾǂ.",
    ["啧啧，真是个做探子的好料。"] = "ƞƽậƸǦƸƽậƸ,ǦǆǊảǦǁƐǦǂộǉǦǂầǂǦǃǄǃǦǁƐǂǦǉƽƑǂǦǉửǦǉốǉ.",
    ["本次组队玩家："] = "ƩƼườƾǦƸƽơƾǦǁậǅǦđộƾǦǁầǃǦǃƐǓ:",
    ["做宫女呢，最重要的是收心。能安安稳稳活着，保条命 in cung里，就不错了！"] = "ƧƐǂǦƸǊǃƼǦǃữǦấǓǦǂƐ,ǦǆǊƶǃǦǉǇọǃƼǦǃƽấǉǦǁƐǦƷƾếǉǦƼƾữǦǂƔǃƽ.ǦƞƚǦǉƽểǦƶǃǦổǃǦǂƐǦǈốǃƼ,ǦƼƾữǦđượƸǦƸƑƾǦǂạǃƼǦǉǇǄǃƼǦƸǊǃƼǦǃƐǓǦǁƐǦǉốǉǦǁắǂǦǇồƾ!",
    ["跟被绑的官员对话"] = "ĐốƾǦǉƽǄạƾǦǋớƾǦǆǊƶǃǦǋƾƙǃǦƷịǦǉǇƚƾ",
    ["金茂  内侍（中年-男性）"] = "ƦƾǂǦƨậǊǦǦƩộƾǦǉƽịǦ(ǥǇǊǃƼǦǃƾƙǃ-Ʃƶǂ)",
    ["差点饿晕的费小飞悟出了道理：宫廷规ệc quy củ nghiêm khắc, cũng chẳng qua là “Thiên hạ đệ nhất đại phạn trang”, cứ vững bước mà đi, ở đâu chạy bàn cũng đều là một trường tu hành."] = "ƫƽƓǦǥƾểǊǦƫƽƾǦǈǊƈǉǦǃữƶǦđƚƾǦǃƼấǉǦđƃǦǃƼộǦǇƶǦđạǄǦǁƈ:ǦƬǊǓǦƸủǦƸǊǃƼǦđƔǃƽǦǃƼƽƾƙǂǦǃƼặǉ,ǦƸũǃƼǦƸƽẳǃƼǦǆǊƶǦǁƐǦ\"ǥƽƾƙǃǦƽạǦđệǦǃƽấǉǦđạƾǦǉửǊǦǁƁǊ\",ǦƸứǦǋữǃƼǦƷướƸǦǂƐǦđƾ,ǦởǦđƁǊǦǁƐǂǦƸƽạǓǦƷƐǃǦƸũǃƼǦđềǊǦǁƐǦǂộǉǦǉǇườǃƼǦǉǊǦƽƐǃƽ.",
    ["到底是押宝这红顶的，还是玄衣의？"] = "ƭốǉǦƸǊộƸǦǁƐǦđặǉǦƸượƸǦǋƐǄǦǀẻǦđộƾǦǂũǦđỏ,ǦƽƶǓǦǁƐǦǀẻǦǂặƸǦƽǊǓềǃǦǓ?",
    ["我授水击面罗于他. 水击面罗，一如水碓之制. 稍做改动，便可劈砍……是为水锯。"] = "ǥƶǦǉǇǊǓềǃǦǥƽủǓǦƦƓƸƽǦǝƾệǃǦƧƶǦƸƽǄǦƽắǃ.ǦǥƽủǓǦƦƓƸƽǦǝƾệǃǦƧƶǦƼƾốǃƼǦǃƽưǦƸƽếǦđộǦƸủƶǦƸốƾǦƼƾƃǦƼạǄǦƸƽạǓǦƷằǃƼǦǃướƸ.ǦƞƽỉǦƸầǃǦǉƽƶǓǦđổƾǦǂộǉǦƸƽƕǉǦǁƐǦƸƚǦǉƽểǦƸƽƗǂǦƷổ……ǦấǓǦƼọƾǦǁƐǦǥƽủǓǦƞưƶ.",
    ["“璎璎，禁中宫人也，性沉毅，怀侠气。一夜巡更，忽闻瓦动，刹时一黑衣客坠于阶前，气若游丝. 璎璎匿之冷宫，及醒，方知其为当世豪侠，为取神剑，涉险入禁.\n侠问何以报，璎请授剑. 侠曰：‘汝年岁既长，根骨已定. 习武如逆水行舟，恐难甚至. ’\n璎再拜，曰：‘精卫衔微木，将以填沧海. 一岁不成，则期十载. 此生不成，亦无悔也. ’\n言罢，庭柏飒飒，似作金戈鸣. 侠壮其志，拊掌称善，遂传衣钵. \n江湖所称‘侠女璎璎’，盖始于此。”"] = "\"ƜǃƽǦƜǃƽ,ǦǁƐǦƸǊǃƼǦǃƽƁǃǦǉǇǄǃƼǦƸấǂǦƸǊǃƼ,ǦǉƓǃƽǦǉƔǃƽǦǉǇầǂǦǃƼƽị,ǦƇǂǦǁƛǃƼǦƽƾệǅǦǀƽƓ.ǦƨộǉǦđƙǂǦđƾǦǉǊầǃ,ǦƷỗǃƼǦǃƼƽƺǦǉƾếǃƼǦǃƼƚƾǦđộǃƼ,ǦǉǇǄǃƼǦƸƽớǅǦǂắǉǦǂộǉǦǋịǦǀƽƑƸƽǦƑǄǦđƺǃǦǇơƾǦǍǊốǃƼǦǉǇướƸǦǉƽềǂ,ǦǀƽƓǦǉứƸǦǂǄǃƼǦǂƶǃƽ.ǦƜǃƽǦƜǃƽǦƼƾấǊǦǃƼườƾǦǋƐǄǦǁƃǃƽǦƸǊǃƼ,ǦđếǃǦǀƽƾǦǉỉǃƽǦǁạƾǦǂớƾǦƷƾếǉǦđƚǦǁƐǦƽƐǄǦƽƾệǅǦđươǃƼǦǉƽế,ǦǋƔǦǁấǓǦǉƽầǃǦǀƾếǂǦǂƐǦǂạǄǦƽƾểǂǦǃƽậǅǦƸấǂ.\nƣƾệǅǦƽỏƾǦǁấǓǦƼƔǦƷƑǄǦđƑǅ,ǦƜǃƽǦǍƾǃǦđượƸǦǉǇǊǓềǃǦǀƾếǂ.ǦƣƾệǅǦǃƚƾ:Ǧ'ƩƼươƾǦǉǊổƾǦǉƑƸǦđƃǦǁớǃ,ǦƸăǃǦƸốǉǦđƃǦđịǃƽ.ǦƣọƸǦǋƅǦǃƽưǦƸƽƘǄǦǉƽǊǓềǃǦǃƼượƸǦǃướƸ,ǦƺǦǇằǃƼǦǀƽƚǦđạǉǦǉớƾǦđƓƸƽ.'\nƜǃƽǦƷƑƾǦǁạǓǦǁầǃǦǃữƶ,Ǧǃƚƾ:Ǧ'ǥƾǃƽǦƱệǦǃƼậǂǦƸƐǃƽǦƸƁǓǦǃƽỏ,ǦǃƼǊǓệǃǦǁấǅǦƷƾểǃǦǀƽơƾ.ǦƨộǉǦǃăǂǦǀƽƇǃƼǦǉƽƐǃƽǦǉƽƔǦƽẹǃǦǂườƾǦǃăǂ.ǦĐờƾǦǃƐǓǦǀƽƇǃƼǦǉƽƐǃƽǦƸũǃƼǦƸƽẳǃƼǦƽốƾǦǉƾếƸ.'\nƩƚƾǦđǄạǃ,ǦƸƁǓǦƷƑƸƽǦǉǇǄǃƼǦǈƁǃǦǍƐǄǦǍạƸ,ǦǉựƶǦǃƽưǦǉƾếǃƼǦǀƾǂǦǆǊƶǦǋƶǃƼǦǋọǃƼ.ǦƣƾệǅǦƸảǂǦǀƽƑƾǦƸƽƓǦǀƽƓǦđƚ,ǦǋỗǦǉƶǓǦǀƽƺǃǦƽƶǓ,ǦƷƘǃǦǉǇǊǓềǃǦǁạƾǦǓǦƷƑǉ.\nƢƾƶǃƼǦƽồǦƼọƾǦǁƐǦ'ƣƾệǅǦǃữǦƜǃƽǦƜǃƽ',ǦǋốǃǦƷắǉǦđầǊǦǉừǦđƁǓ.\"",
    ["我……我才没有！我不过是想着要给百姓们尝尝鲜"] = "ǥƶ……ǦǉƶǦǂớƾǦǀƽƇǃƼǦƸƚ!ǦǥƶǦƸƽẳǃƼǦǆǊƶǦǁƐǦǂǊốǃǦđểǦƷƑƸƽǦǉƓǃƽǦđượƸǦǃếǂǦǉƽửǦƸƽƕǉǦƽươǃƼǦǋịǦǂớƾǦǁạǦǉƽƇƾ",
    ["鹞为逼迫燕交出乌金，拔剑上前，欲祀血问诛.\n而燕以身抵剑，宁死不说.\n二人互不相让，被鹏制止. 晋中原也趁机提出了巨子冲替之策。"] = "ǝƾƙǊǦǋƔǦƗǅǦƴếǃǦƼƾƶǄǦǇƶǦƆǦƦƾǂǦđƃǦǉǊốǉǦǀƾếǂǦǉƾếǃǦǁƙǃ,ǦǂǊốǃǦǤƖǃƼǦǂƑǊǦǉếǦǀƾếǂ.Ǧ\nƨƐǦƴếǃǦǁấǓǦǉƽƁǃǦƸảǃǦǀƾếǂ,ǦǉƽƐǦƸƽếǉǦǀƽƇǃƼǦǃƚƾ.Ǧ\nƣƶƾǦǃƼườƾǦǀƽƇǃƼǦƶƾǦǃƽườǃƼǦƶƾ,ǦƷịǦƝằǃƼǦǃƼăǃǦǁạƾ.ǦǥấǃǦǥǇǊǃƼǦƩƼǊǓƙǃǦƸũǃƼǦǉƽừƶǦƸơǦđềǦǇƶǦǈƑƸƽǦǁượƸǦƞựǦǥửǦǍǊǃƼǦǉƽế.",
    ["朝廷立法，求的是长治久安，非一时之痛快。严惩盗贼可以，修律不必. "] = "ǥǇƾềǊǦđƔǃƽǦǁậǅǦǅƽƑǅǦǁƐǦƸầǊǦǈựǦǉǇườǃƼǦǉǇịǦƸửǊǦƶǃ,ǦǀƽƇǃƼǦǅƽảƾǦǋƔǦƸƑƾǦǀƽǄƑƾǦƸƽƓǦǃƽấǉǦǉƽờƾ.ǦƩƼƽƾƙǂǦǉǇịǦđạǄǦǉặƸǦǉƽƔǦđượƸ,ǦƸƛǃǦǈửƶǦǁǊậǉǦǉƽƔǦǀƽƇǃƼǦƸầǃǦǉƽƾếǉ.",
    ["未佩戴通行令牌，不可擅自离宫. 请回吧。"] = "ƞƽưƶǦđƺǄǦǉƽƇǃƼǦƽƐǃƽǦǁệǃƽǦƷƐƾ,ǦǀƽƇǃƼǦđượƸǦǉựǦƈǦǇờƾǦƸǊǃƼ.ǦƨờƾǦǆǊƶǓǦǋềǦƸƽǄ.",
    ["我还讨了个赏. 说不得过两天，你便要再见到我了。"] = "ǥƶǦƸƛǃǦǍƾǃǦđượƸǦǂộǉǦǅƽầǃǦǉƽưởǃƼǦǃữƶ.ǦƝƾếǉǦđƁǊǦƽƶƾǦǃƼƐǓǦǃữƶǦǃƼươƾǦǁạƾǦƼặǅǦǉƶǦđấǓ.",
    ["契丹贵族骑兵，辽国君主组建的心腹部队. "] = "ƦỵǦƷƾǃƽǦǆǊƈǦǉộƸǦƦƽƾếǉǦĐƶǃ,ǦđộƾǦǆǊƁǃǦǉƽƁǃǦǉƓǃǦǤǄǦǆǊƁǃǦƸƽủǦƧƾƙǊǦǆǊốƸǦǉƽƐǃƽǦǁậǅ.",
    ["长按{}释放旋风浮空目标{}突进并击飞目标"] = "ƩƽấǃǦƼƾữǦ{}ǦǉƽƾǦǉǇƾểǃǦǥǄƐǃǦƫƽǄǃƼǦƽấǉǦǉǊǃƼǦǂụƸǦǉƾƙǊǦ{}ǦđộǉǦǀƓƸƽǦǋƐǦđƑǃƽǦƷƶǓǦǂụƸǦǉƾƙǊ",
    ["西汉时，胡厘率墨门弟子隐于太行，依山筑城. 然四顾皆千仞绝壁，欲于此立城，几若登天. 为免门人遭险坠之患，胡厘不辞艰辛，跋涉群山，遍访山民，求学登山术. 历时三月，风霜浸骨，终得登山术一十八式. 此后胡厘更是以技入武，融墨家千机于索法当中传于门人，名为“千机索天”，取意可索太行之天，亦可索苍生之天. "] = "ǥƽờƾǦǥƁǓǦƣƑǃ,ǦƣồǦƧǓǦǤẫǃǦđệǦǉửǦƨặƸǦǂƇǃǦẩǃǦƸưǦǉạƾǦǥƽƑƾǦƣƐǃƽ,ǦǤựƶǦǋƐǄǦǃƕƾǦǍƁǓǦǉƽƐǃƽ.ǦƩƽưǃƼǦǃƽƔǃǦǆǊƶǃƽǦđềǊǦǁƐǦǋƑƸƽǦđƑǦǤựǃƼǦđứǃƼǦǃƼƽƔǃǦǉǇượǃƼ,ǦǂǊốǃǦǁậǅǦǉƽƐǃƽǦởǦđƁǓǦƸƽẳǃƼǦǀƽƑƸǦǃƐǄǦǁƙǃǦǉǇờƾ.ǦĐểǦǉǇƑǃƽǦǂƇǃǦǃƽƁǃǦƼặǅǦƽọƶǦǇơƾǦǍǊốǃƼǦǋựƸǦǈƁǊ,ǦƣồǦƧǓǦǀƽƇǃƼǦǆǊảǃǦƼƾƶǃǦǀƽổ,ǦǁặǃǦǁộƾǦǆǊƶǦǃƼƐǃǦǃƕƾǦǃǄǃ,ǦǉƽăǂǦƽỏƾǦǤƁǃǦǈơǃǦƸướƸ,ǦǉƔǂǦƽọƸǦǉƽǊậǉǦǁƺǄǦǃƕƾ.ǦǥǇảƾǦǆǊƶǦƷƶǦǉƽƑǃƼ,ǦǅƽǄǃƼǦǈươǃƼǦǉƽấǂǦƸốǉ,ǦƸǊốƾǦƸƖǃƼǦđắƸǦđượƸǦǂườƾǦǉƑǂǦǉƽứƸǦǁƺǄǦǃƕƾǦǉƽǊậǉ.ǦǥừǦđƚǦǋềǦǈƶǊǦƣồǦƧǓǦđƺǂǦǀỹǦǉƽǊậǉǦǃƽậǅǦǋƐǄǦǋƅǦƽọƸ,ǦǤǊǃƼǦƽợǅǦǥƽƾƙǃǦƞơǦƸủƶǦƨặƸǦƼƾƶǦǋƐǄǦǉǇǄǃƼǦǉỏƶǦǅƽƑǅǦǉǇǊǓềǃǦǁạƾǦƸƽǄǦǂƇǃǦǃƽƁǃ,ǦǁấǓǦǉƙǃǦǁƐǦ\"ǥƽƾƙǃǦƞơǦǥỏƶǦǥƽƾƙǃ\",ǦǃƼụǦƈǦƸƚǦǉƽểǦǉƔǂǦǀƽƚƶǦđượƸǦǉǇờƾǦƸƶǄǦǥƽƑƾǦƣƐǃƽ,ǦƸũǃƼǦƸƚǦǉƽểǦǉƔǂǦǀƽƚƶǦđượƸǦǉǇờƾǦƸƶǄǦƸủƶǦǉƽươǃƼǦǈƾǃƽ.",
    ["驿站茶凳，用于来往客人休息. "] = "ƢƽếǦǉǇƐǦǉǇạǂǦǍƑ,ǦǤƖǃƼǦƸƽǄǦǀƽƑƸƽǦǋƃǃƼǦǁƶƾǦǃƼƽỉǦƸƽƁǃ.",
    ["此议可. 着礼部牵头，拟定纲要与初版条文，呈阅. "] = "ÝǦǀƾếǃǦǃƐǓǦđượƸ.ǦƢƾƶǄǦƧễǦƷộǦƸƽủǦǉǇƔ,ǦǈǄạǃǦǉƽảǄǦƸươǃƼǦǓếǊǦǋƐǦƸƑƸǦđƾềǊǦǀƽǄảǃǦƷảǃǦđầǊ,ǦǉǇƔǃƽǦǤǊǓệǉ.",
    ["鹳长老精心挑选的六篇文献之一，厚厚的一摞书卷寄托着他对你的殷切期望，集齐一套后找鹳长老兑换奖励。\n《织网》勘定司最新力作，荟萃了《织网》自建刊百年以来的研究精华，包含了每年的最佳创新奖、最佳专利奖以及最佳论文。尤其难得的是，纪念册还列出了这些优秀作品在后世的深远影响。站在巨人的肩膀上，总是能看得更远，此书可谓是今人选题立项时必备的参考资料。  "] = "ƨộǉǦǉǇǄǃƼǦǈƑǊǦǉƽƾƙǃǦǋăǃǦƽƾếǃǦǤǄǦƬǊƑǃǦǉǇưởǃƼǦǁƃǄǦǤƐǓǦƸƇǃƼǦǉǊǓểǃǦƸƽọǃ,ǦǂộǉǦƸƽồǃƼǦǈƑƸƽǦǤƐǓǦƸộǂǦƼửƾǦƼắǂǦǀỳǦǋọǃƼǦǉƽƶǦǉƽƾếǉǦƸủƶǦǃƼƐƾǦǤƐǃƽǦƸƽǄǦǃƼươƾ,ǦǈƶǊǦǀƽƾǦǉƽǊǦǉƽậǅǦđủǦƷộǦƽƃǓǦǉƔǂǦƬǊƑǃǦǉǇưởǃƼǦǁƃǄǦđểǦđổƾǦǉƽưởǃƼ.\n<ƞƽứƸǦƱƅǃƼ>ǦǁƐǦǉƑƸǦǅƽẩǂǦǉƁǂǦđắƸǦǂớƾǦǃƽấǉǦƸủƶǦƦƽƑǂǦĐịǃƽǦǥƾ,ǦƽộƾǦǉụǦǉƾǃƽǦƽǄƶǦǃƼƽƾƙǃǦƸứǊǦƸủƶǦ<ƞƽứƸǦƱƅǃƼ>ǦǀểǦǉừǦǀƽƾǦǉƽƐǃƽǦǁậǅǦǉƛƶǦǈǄạǃǦǉǇăǂǦǃăǂǦǃƶǓ,ǦƷƶǄǦƼồǂǦƸƑƸǦƼƾảƾǦƮƑǃƼǦǉạǄǦǃƽấǉ,ǦƼƾảƾǦƝằǃƼǦǈƑǃƼǦƸƽếǦǉốǉǦǃƽấǉǦǋƐǦƧǊậǃǦǋăǃǦƽƶǓǦǃƽấǉǦƽƐǃƼǦǃăǂ.ǦĐặƸǦƷƾệǉǦƽƾếǂǦƸƚǦǁƐ,ǦǉậǅǦǀỷǦǃƾệǂǦƸƛǃǦǁƾệǉǦǀƙǦảǃƽǦƽưởǃƼǦǈƁǊǦǇộǃƼǦƸủƶǦǃƽữǃƼǦǉƑƸǦǅƽẩǂǦưǊǦǉƕǦǃƐǓǦđốƾǦǋớƾǦƽậǊǦǉƽế.ǦĐứǃƼǦǉǇƙǃǦǋƶƾǦǃƼườƾǦǀƽổǃƼǦǁồǦƷƶǄǦƼƾờǦƸũǃƼǦǃƽƔǃǦǍƶǦƽơǃ,ǦƸǊốǃǦǈƑƸƽǦǃƐǓǦƸƚǦǉƽểǦƸǄƾǦǁƐǦǉƐƾǦǁƾệǊǦǉƽƶǂǦǀƽảǄǦǉƽƾếǉǦǓếǊǦƸƽǄǦǃƼườƾǦǃƶǓǦǀƽƾǦƸƽọǃǦđềǦǉƐƾǦǁậǅǦǤựǦƑǃ.",
    ["高清外观 resource 将在外观 resource 下载完成后自动继续下载。"] = "ǥƐƾǦǃƼǊǓƙǃǦǃƼǄạƾǦƽƔǃƽǦƸƽấǉǦǁượǃƼǦƸƶǄǦǈẽǦǉựǦđộǃƼǦǉƾếǅǦǉụƸǦǉảƾǦǍǊốǃƼǦǈƶǊǦǀƽƾǦǉƐƾǦǃƼǊǓƙǃǦǃƼǄạƾǦƽƔǃƽǦƽǄƐǃǦǉấǉ.",
    ["恤囚亦是防患于未然，此为善政. 所奏之事，准了。"] = "ǥƽươǃƼǦǍƚǉǦǉƖǦǃƽƁǃǦƸũǃƼǦǁƐǦđểǦǅƽƛǃƼǦƽọƶǦǀƽƾǦƸƽưƶǦǍảǓǦǇƶ,ǦđƁǓǦǁƐǦǉƽƾệǃǦƸƽƓǃƽ.ǦƩƽữǃƼǦǋƾệƸǦǉấǊǦǁƙǃ,ǦǉǇẫǂǦƸƽǊẩǃǦǉấǊ.",
    ["钱冲击波"] = "ǥƾềǃǦǍǊǃƼǦǀƓƸƽǦƷƶ",
    ["左菊正在盘点自己去年“年度计划”的完成情况，不由就发出了一声“这世上怎会有如此优秀的人儿”的慨叹，官人 cũng 来听听她的汇报呢？"] = "ǥảǦƞƕƸǦđƶǃƼǦǀƾểǂǦǀƙǦǉƔǃƽǦƽƔǃƽǦƽǄƐǃǦǉƽƐǃƽǦ\"ǀếǦƽǄạƸƽǦǃăǂ\"ǦƸủƶǦǂƔǃƽǦǃăǂǦǃƼǄƑƾ,ǦǀƽƇǃƼǦǃƗǃǦǃổƾǦǉƾếǃƼǦǉƽởǦǤƐƾ:Ǧ\"ǥǇƙǃǦđờƾǦǃƐǓǦǈƶǄǦǁạƾǦƸƚǦǃƼườƾǦưǊǦǉƕǦđếǃǦǃƽườǃƼǦǃƐǓ\",ǦǆǊƶǃǦǃƽƁǃǦƸũǃƼǦđếǃǦǃƼƽƺǦǃƐǃƼǦƷƑǄǦƸƑǄǦđƾ?",
    ["官署-官署正门守ử vệ2-武德司低级侍卫"] = "ƬǊƶǃǦǉƽựǦ-ǦƱệǦƷƾǃƽǦƸửƶǦƸƽƓǃƽǦǆǊƶǃǦǉƽựǦ2Ǧ-ǦǥƽịǦǋệǦǈơǦƸấǅǦƱƅǦĐứƸǦǥǓ",
    ["刚接手铺子时，谷问秋抱着想要超越爹娘的志气，一口气研制了四种新鲜糕点。\n雕花的玉露团，半透明的糍糕……这些书上学来的糕点又好看又好吃，对比下来，传统敦实的五色糕就显得有些土气。\n第一个月，问秋得意地捧着账本，向爹娘道喜。\n第二个月，收入陡转直下，连五色糕也突然无人问津。算下来，这两个月问秋连钻研新糕点的本金都没赚回来。\n\n“这附近前前后后也有人卖过这些新鲜样式，可你看，哪一家不是撑不过两三个月？”\n娘亲的劝告语气温软，可问秋心下依旧不服气。\n问秋甚至偷听到有人说她家的口味变了。哪里变了？用的是一样的原料，花的是一样的心力，她甚至还得熬夜去做新的糕点。\n“你一开始卖别的，别人自然觉得你没像以前那样专心做五色糕了。”\n问秋多想把心剖出来给客人们看看，但 she 不能一个个地去和顾客们解释，也不能拉着他们半夜来看 she 做糕点。\n\n爹娘没有怪她，可 she 不愿让老一辈的招牌砸在自己手里。第三个月，铺子又只卖五色糕了。\n收入慢慢回来一些，虽然不如从前，但至少不亏了。\n她娘见问秋情绪不高，又劝说 she 不如先问问顾客们都喜欢写什么，再作盘算也不迟。\n第二天，问秋一边卖糕，一边留心搭话。\n西边的杜娘子说，五色糕，还得配着酒喝，那才有味。\n东边的黄三爷说，等到重阳，登高吹风，和友人一同吃糕点赏菊花，方是乐事一桩。\n问秋心里慢慢有了新的主意。\n来买五色糕，就得捎上一壶菊花酒嘛！"] = "ƦƽƾǦǂớƾǦǉƾếǅǦǆǊảǃǦƸửƶǦǉƾệǂ,ǦƞốƸǦƱấǃǦǥƽǊǦǂƶǃƼǦƸƽƓǦǀƽƓǦǂǊốǃǦǋượǉǦǆǊƶǦƸƽƶǦǂẹ,ǦǂộǉǦƽơƾǦǃƼƽƾƙǃǦƸứǊǦǇƶǦƷốǃǦǁǄạƾǦƷƑǃƽǦǃƼọǉǦǂớƾǦǁạ.\nƩƼọƸǦƧộǦĐǄƐǃǦƸƽạǂǦƽǄƶ,ǦƷƑǃƽǦǃếǅǦƷƑǃǦǉǇǄǃƼǦǈǊốǉ……ǦƩƽữǃƼǦǂƚǃǦƷƑǃƽǦƽọƸǦǉừǦǉǇǄǃƼǦǈƑƸƽǦǃƐǓǦǋừƶǦđẹǅǦǋừƶǦǃƼǄǃ,ǦǈǄǦǈƑǃƽǦǇƶ,ǦǂƚǃǦƷƑǃƽǦǃƼũǦǈắƸǦǉǇǊǓềǃǦǉƽốǃƼǦǤƐǓǦǤặǃǦǁạƾǦƸƚǦǋẻǦƽơƾǦǆǊƙǦǂƖƶ.\nǥƽƑǃƼǦđầǊǦǉƾƙǃ,ǦƱấǃǦǥƽǊǦđắƸǦƈǦƷưǃƼǦǈổǦǈƑƸƽǦđếǃǦƸƽƕƸǦǂừǃƼǦƸƽƶǦǂẹ.\nǥƽƑǃƼǦǉƽứǦƽƶƾ,ǦǉƽǊǦǃƽậǅǦǈụǉǦƼƾảǂǦǉƽƙǦǉƽảǂ,ǦǃƼƶǓǦƸảǦƷƑǃƽǦǃƼũǦǈắƸǦƸũǃƼǦđộǉǦǃƽƾƙǃǦǀƽƇǃƼǦƶƾǦđǄƑƾǦƽǄƐƾ.ǦǥƓǃƽǦǇƶ,ǦƽƶƾǦǉƽƑǃƼǦǃƐǓǦƱấǃǦǥƽǊǦǃƼƶǓǦƸảǦǉƾềǃǦǋốǃǦǃƼƽƾƙǃǦƸứǊǦƷƑǃƽǦǂớƾǦƸũǃƼǦƸƽưƶǦǀƾếǂǦǁạƾǦđượƸ.\n\n\"ƬǊƶǃƽǦđƁǓǦǉǇướƸǦǈƶǊǦƸũǃƼǦƸƚǦǃƼườƾǦƷƑǃǦǂấǓǦǀƾểǊǦǂớƾǦǁạǦǃƐǓ,ǦǃƽưǃƼǦƸǄǃǦǍƺǂ,ǦƸƚǦǃƽƐǦǃƐǄǦǉǇụǦǃổƾǦǆǊƑǦƽƶƾǦƷƶǦǉƽƑǃƼǦđƁǊ?\"\nƧờƾǦǀƽǊǓƙǃǦƸủƶǦǃươǃƼǦǉửǦǤịǊǦǤƐǃƼ,ǦǃƽưǃƼǦǉǇǄǃƼǦǁƛǃƼǦƱấǃǦǥƽǊǦǋẫǃǦǀƽƇǃƼǦǅƽụƸ.\nƱấǃǦǥƽǊǦǉƽậǂǦƸƽƓǦƸƛǃǦǃƼƽƺǦǁỏǂǦđượƸǦƸƚǦǃƼườƾǦǃƚƾǦǀƽẩǊǦǋịǦǃƽƐǦƸƇǦđƃǦǉƽƶǓǦđổƾ.ǦǥƽƶǓǦđổƾǦƸƽỗǦǃƐǄ?ǦƩƼǊǓƙǃǦǁƾệǊǦǋẫǃǦǉƽế,ǦǉƁǂǦƽǊǓếǉǦǋẫǃǦǋậǓ,ǦƸƇǦǉƽậǂǦƸƽƓǦƸƛǃǦǅƽảƾǦǉƽứƸǦđƙǂǦđểǦǁƐǂǦƷƑǃƽǦǂớƾ.\n\"ƩƼƶǓǦǉừǦđầǊǦƸǄǃǦđƃǦƷƑǃǦǉƽứǦǀƽƑƸ,ǦǃƼườƾǦǉƶǦđươǃƼǦǃƽƾƙǃǦƸảǂǦǉƽấǓǦƸǄǃǦǀƽƇǃƼǦƸƛǃǦƸƽǊǓƙǃǦǉƁǂǦǁƐǂǦƷƑǃƽǦǃƼũǦǈắƸǦǃƽưǦǉǇướƸǦǃữƶ.\"\nƱấǃǦǥƽǊǦƸƽỉǦǂǊốǃǦǂổǦǍẻǦǁƛǃƼǦǂƔǃƽǦǇƶǦƸƽǄǦǀƽƑƸƽǦǍƺǂ,ǦǃƽưǃƼǦƸƇǦǀƽƇǃƼǦǉƽểǦƼƾảƾǦǉƽƓƸƽǦǋớƾǦǉừǃƼǦǃƼườƾǦǂộǉ,ǦƸũǃƼǦǀƽƇǃƼǦǉƽểǦǀƗǄǦƽọǦđếǃǦǍƺǂǦƸƇǦǁƐǂǦƷƑǃƽǦǁƕƸǦǃửƶǦđƙǂ.\n\nƞƽƶǦǂẹǦǀƽƇǃƼǦǉǇƑƸƽǦƸƇ,ǦǃƽưǃƼǦƸƇǦǀƽƇǃƼǦǂǊốǃǦƷảǃƼǦƽƾệǊǦƸủƶǦǉƽếǦƽệǦǉǇướƸǦƷịǦƽủǓǦƽǄạƾǦǉǇǄǃƼǦǉƶǓǦǂƔǃƽ.ǦĐếǃǦǉƽƑǃƼǦǉƽứǦƷƶ,ǦƸửƶǦǉƾệǂǦǁạƾǦƸƽỉǦƷƑǃǦƷƑǃƽǦǃƼũǦǈắƸ.\nǥƽǊǦǃƽậǅǦǤầǃǦǆǊƶǓǦǁạƾǦǂộǉǦƸƽƕǉ,ǦǉǊǓǦǀƽƇǃƼǦƷằǃƼǦǁƕƸǦǉǇướƸ,ǦǃƽưǃƼǦƓǉǦǃƽấǉǦǀƽƇǃƼǦƸƛǃǦǁỗǦǋốǃ.\nƨẹǦǉƽấǓǦƱấǃǦǥƽǊǦǉƁǂǦǉƔǃƽǦǀƽƇǃƼǦǋǊƾ,ǦǁạƾǦǀƽǊǓƙǃǦƸƇǦƽƶǓǦǁƐǦƽỏƾǦǀƽƑƸƽǦƽƐǃƼǦǍƺǂǦƽọǦǉƽƓƸƽǦƼƔ,ǦǇồƾǦǉƓǃƽǦǉǄƑǃǦƸũǃƼǦƸƽưƶǦǂǊộǃ.\nƩƼƐǓǦƽƇǂǦǈƶǊ,ǦƱấǃǦǥƽǊǦǋừƶǦƷƑǃǦƷƑǃƽ,ǦǋừƶǦđểǦƈǦǉǇƛǦƸƽǊǓệǃ.\nĐỗǦǃươǃƼǦǉửǦǅƽƓƶǦǥƁǓǦǃƚƾ,ǦƷƑǃƽǦǃƼũǦǈắƸǦǅƽảƾǦǤƖǃƼǦǀƘǂǦǋớƾǦǇượǊǦǂớƾǦđủǦǋị.\nƣǄƐǃƼǦǉƶǂǦƼƾƶǦǅƽƓƶǦĐƇǃƼǦǃƚƾ,ǦđợƾǦđếǃǦǥǇƖǃƼǦǝươǃƼ,ǦǁƺǄǦǃƕƾǦƽƚǃƼǦƼƾƚ,ǦƸƖǃƼǦƷằǃƼǦƽữǊǦăǃǦƷƑǃƽǦǉƽưởǃƼǦƸƕƸǦǂớƾǦǁƐǦǂộǉǦǉƽƕǦǋǊƾ.\nǥǇǄǃƼǦǁƛǃƼǦƱấǃǦǥƽǊǦǤầǃǦǃảǓǦǇƶǦƈǦǉưởǃƼǦǂớƾ.\nĐếǃǦǂǊƶǦƷƑǃƽǦǃƼũǦǈắƸ,ǦǉƽƔǦǅƽảƾǦǂƶǃƼǦǉƽƺǄǦǂộǉǦǋƛǦǇượǊǦƽǄƶǦƸƕƸǦƸƽứ!",
    ["左街2-平min4-对话"] = "ǥảǦǃƽƶƾǦ2Ǧ-ǦƝƔǃƽǦǤƁǃǦ4Ǧ-ǦĐốƾǦǉƽǄạƾ",
    ["对战规则:\n1V1 竞技对决，需在限定时间内决出胜负：率先击败对方玩家即可获胜；若倒计时结束仍未分胜负，则总伤害量更高的一方胜出。为保障公平竞技，对战期间禁止借助任何外力，且不可离开指定对战区域。胜利方将继承擂主身份，败者需退出擂台。擂主达成连胜战绩，可解锁专属奖励与荣誉成就。\n叫阵规则:\n当擂台无擂主时，玩家可主动发起挑战，挑战方式分为两种：\n「公开挑战」：向所有参与擂台玩法的玩家发送对战邀请，等待其他玩家响应；\n「指名挑战」：从已参与擂台玩法的玩家中，选择特定对象单独发送对战邀请。  "] = "ƬǊǓǦǉắƸǦđốƾǦƸƽƾếǃ:\nĐốƾǦǆǊǓếǉǦƸạǃƽǦǀỹǦ1Ʊ1,ǦƸầǃǦǅƽƁǃǦđịǃƽǦǉƽắǃƼǦǉƽǊƶǦǉǇǄǃƼǦǉƽờƾǦƼƾƶǃǦƼƾớƾǦƽạǃ:ǦƩƼườƾǦđƑǃƽǦƷạƾǦđốƾǦǅƽươǃƼǦǉǇướƸǦǈẽǦƼƾƐǃƽǦƸƽƾếǃǦǉƽắǃƼ;ǦǃếǊǦƽếǉǦǉƽờƾǦƼƾƶǃǦǂƐǦǋẫǃǦƸƽưƶǦǅƽƁǃǦǉƽắǃƼǦƷạƾ,ǦƷƙǃǦƸƚǦǉổǃƼǦǁượǃƼǦǈƑǉǦǉƽươǃƼǦƸƶǄǦƽơǃǦǈẽǦǉƽắǃƼ.ǦĐểǦđảǂǦƷảǄǦƸƇǃƼǦƷằǃƼ,ǦǉǇǄǃƼǦǉƽờƾǦƼƾƶǃǦđốƾǦƸƽƾếǃǦƸấǂǦǈửǦǤụǃƼǦƷấǉǦǀỳǦǃƼǄạƾǦǁựƸǦǃƐǄ,ǦđồǃƼǦǉƽờƾǦǀƽƇǃƼǦđượƸǦǇờƾǦǀƽỏƾǦǀƽǊǦǋựƸǦđốƾǦƸƽƾếǃǦƸƽỉǦđịǃƽ.ǦƝƙǃǦǉƽắǃƼǦǈẽǦǀếǦǉƽừƶǦǉƽƁǃǦǅƽậǃǦƧƇƾǦƸƽủ,ǦƷƙǃǦǉƽǊƶǦǅƽảƾǦǇờƾǦǀƽỏƾǦǁƇƾǦđƐƾ.ǦƧƇƾǦƸƽủǦđạǉǦđượƸǦǉƽƐǃƽǦǉƓƸƽǦǉƽắǃƼǦǁƾƙǃǦǉƾếǅǦƸƚǦǉƽểǦǂởǦǀƽƚƶǦǅƽầǃǦǉƽưởǃƼǦđộƸǦǆǊǓềǃǦǋƐǦǉƽƐǃƽǦǉựǊǦǋƾǃƽǦǤự.\nƬǊǓǦǉắƸǦǀƽƾƙǊǦƸƽƾếǃ:\nƦƽƾǦǁƇƾǦđƐƾǦǀƽƇǃƼǦƸƚǦƧƇƾǦƸƽủ,ǦǃƼườƾǦƸƽơƾǦƸƚǦǉƽểǦƸƽủǦđộǃƼǦǅƽƑǉǦđộǃƼǦǀƽƾƙǊǦƸƽƾếǃ,ǦƸƚǦƽƶƾǦƽƔǃƽǦǉƽứƸ:\n[ƞƇǃƼǦǀƽƶƾǦǀƽƾƙǊǦƸƽƾếǃ]:ǦƢửƾǦǁờƾǦǂờƾǦđốƾǦƸƽƾếǃǦđếǃǦǉấǉǦƸảǦǃƼườƾǦƸƽơƾǦǉƽƶǂǦƼƾƶǦǁốƾǦƸƽơƾǦǁƇƾǦđƐƾ,ǦƸƽờǦǃƼườƾǦǀƽƑƸǦǅƽảǃǦƽồƾ;\n[ƞƽỉǦđịǃƽǦǀƽƾƙǊǦƸƽƾếǃ]:ǦƞƽọǃǦǂộǉǦđốƾǦǉượǃƼǦƸụǦǉƽểǦǉừǦǃƽữǃƼǦǃƼườƾǦƸƽơƾǦđƃǦǉƽƶǂǦƼƾƶǦǁƇƾǦđƐƾǦđểǦƼửƾǦǁờƾǦǂờƾǦđốƾǦƸƽƾếǃǦǇƾƙǃƼ.",
    ["青山执笔·浮名无寄"] = "ǥƽƶǃƽǦƮơǃǦƞƽấǅǦƝƕǉǦ·ǦƫƽƖǦǝƶǃƽǦƱƇǦƦƈ",
