    ["生前是深宫中求告无门的宫女，怨念化作了荧荧鬼火，凝结在白烛之上。\n\n她们曾是前朝深宫中最不起眼的宫女，但在契丹入京之乱中，她们坚守了内廷的职责，保全了府库的金银。\n\n然而禁军의 诬告让她们被押入天牢。"] = "ƮƾǃƽǦǉƽờƾǦǁƐǦǃƽữǃƼǦƸǊǃƼǦǃữǦƸầǊǦƸứǊǦǀƽƇǃƼǦƸửƶǦƸƽốǃǦǉƽƁǂǦƸǊǃƼ,ǦǄƑǃǦǃƾệǂǦƽƚƶǦǉƽƐǃƽǦǆǊỷǦƽỏƶǦǁậǅǦǁƛƺ,ǦǃƼưǃƼǦǀếǉǦǉǇƙǃǦǃếǃǦǉǇắǃƼ.\n\nƣọǦǉừǃƼǦǁƐǦǃƽữǃƼǦƸǊǃƼǦǃữǦǉầǂǦǉƽườǃƼǦǃƽấǉǦƸƽốǃǦǉƽƁǂǦƸǊǃƼǦǉƾềǃǦǉǇƾềǊ,ǦǃƽưǃƼǦǉǇǄǃƼǦǁǄạǃǦƦƽƾếǉǦĐƶǃǦǃƽậǅǦǀƾǃƽ,ǦƽọǦđƃǦǀƾƙǃǦǉǇƔǦƸƽứƸǦǉǇƑƸƽǦǃộƾǦđƔǃƽ,ǦƷảǄǦǉǄƐǃǦđượƸǦǋƐǃƼǦƷạƸǦǉǇǄǃƼǦǅƽủǦǀƽố.\n\nǥƽếǦǃƽưǃƼǦǈựǦǋǊǦƸƑǄǦƸủƶǦƞấǂǦǆǊƁǃǦđƃǦǀƽƾếǃǦƽọǦƷịǦǉốǃƼǦǋƐǄǦǥƽƾƙǃǦǁƶǄ.",
    ["小子你找死，如今大宋安平，已不需老朽带兵。圣人怜悯，予我养老之所，我自 là 喜于隐于市中，有何可悲伤之处？"] = "ǥƾểǊǦǉửǦǃƼươƾǦǉƔǂǦƸƽếǉ,ǦǃƶǓǦĐạƾǦǥốǃƼǦƶǃǦƷƔǃƽ,ǦđƃǦǀƽƇǃƼǦƸầǃǦǁƃǄǦƽủǦƸầǂǦǆǊƁǃǦǃữƶ.ǦǥƽƑǃƽǦǃƽƁǃǦǉƽươǃƼǦǍƚǉ,ǦƷƶǃǦƸƽǄǦǉƶǦǃơƾǦǤưỡǃƼǦǁƃǄ,ǦǉƶǦǉựǦǃƽƾƙǃǦǁƐǦǂừǃƼǦǋƔǦđượƸǦẩǃǦǤậǉǦƼƾữƶǦǅƽốǦǉƽị,ǦƸƚǦƼƔǦǂƐǦǅƽảƾǦƷƾǦǉƽươǃƼ?",
    ["（见江无浪信了，说慌更笃定了）镇戍仓接应……信物……自朝中来……"] = "(ǥƽấǓǦƢƾƶǃƼǦƱƇǦƧƃǃƼǦđƃǦǉƾǃ,ǦǁờƾǦǃƚƾǦǤốƾǦƸƐǃƼǦǉƽƙǂǦƸƽắƸǦƸƽắǃ)ǦǥǇấǃǦǉƽƕǦǉƽươǃƼǦǉƾếǅǦứǃƼ...ǦǉƓǃǦǋậǉ...ǦǉừǦǉǇǄǃƼǦǉǇƾềǊǦđếǃ...",
    ["嘿！你还没张嘴，俺就知道你想让俺钻！行了，且瞧好吧！"] = "ƣắƸ!ǦƩƼươƾǦƸƛǃǦƸƽưƶǦǂởǦǂƾệǃƼ,ǦǉƶǦđƃǦƷƾếǉǦǃƼươƾǦǂǊốǃǦǉƶǦƸƽǊƾǦǇồƾ!ǦĐượƸǦǇồƾ,ǦƸứǦƸƽờǦǍƺǂǦǃƽƗ!",
    ["聆听第二段琴曲"] = "ƧắǃƼǦǃƼƽƺǦǀƽƕƸǦƸầǂǦǉƽứǦƽƶƾ",
    ["你放心，以后走这条道，我们姐弟俩罩着你. "] = "ƩƼươƾǦǓƙǃǦǉƁǂ,ǦǈƶǊǦǃƐǓǦđƾǦƸǄǃǦđườǃƼǦǃƐǓ,ǦƽƶƾǦƸƽịǦƺǂǦǉƶǦǈẽǦƷảǄǦǋệǦǃƼươƾ.",
    ["战火纷飞几时休，春日何日来？请先探寻封龙书院旧事. "] = "ƞƽƾếǃǦƽỏƶǦǅƽƁǃǦǅƽƾǦǀƽƾǦǃƐǄǦǃƼƽỉ,ǦǃƼƐǓǦǍǊƁǃǦǃƼƐǓǦǃƐǄǦđếǃ?ǦƳƾǃǦƽƃǓǦǉƔǂǦƽƾểǊǦƸƽǊǓệǃǦƸũǦƸủƶǦƫƽǄǃƼǦƧǄǃƼǦǥƽưǦƱƾệǃǦǉǇướƸ.",
    ["你这孩子，你娘我都说了多少回，你怎么总听不够呢. "] = "ƞƑƾǦđứƶǦǃƽỏǦǃƐǓ,ǦǂẹǦǃƼươƾǦđƃǦǃƚƾǦƷƶǄǦǃƽƾƙǊǦǁầǃǦǇồƾ,ǦǈƶǄǦǃƼươƾǦƸứǦǃƼƽƺǦǂƃƾǦǀƽƇǃƼǦƸƽƑǃǦǉƽế.",
    ["对，就是那种又漂亮又可怜，跟梨花一样的女人。要是你遇到，一定会认出来的. "] = "ĐƕǃƼ,ǦƸƽƓǃƽǦǁƐǦǀƾểǊǦǅƽụǦǃữǦǋừƶǦđẹǅǦǋừƶǦđƑǃƼǦǉƽươǃƼ,ǦǃƽưǦƽǄƶǦǁƙǦǋậǓ.ǦƩếǊǦǃƼươƾǦƼặǅ,ǦǃƽấǉǦđịǃƽǦǈẽǦǃƽậǃǦǇƶǦǃƼƶǓ.",
    ["封龙……中渡桥……柳某明白了. "] = "ƫƽǄǃƼǦƧǄǃƼ...ǦǥǇǊǃƼǦĐộǦǀƾềǊ...ǦƧƾễǊǦǂỗǦđƃǦƽƾểǊ.",
    ["在书院帮工的工匠，他知道这书院里头谁值钱，是那些弟子们。虏人来了，他得冲前头，能挡一两刀也好. "] = "ƢƃǦǉƽợǦǉƽủǦƸƇǃƼǦǅƽụǦǋƾệƸǦởǦǉƽưǦǋƾệǃ,ǦǁƃǄǦƷƾếǉǦǉǇǄǃƼǦǉƽưǦǋƾệǃǦǃƐǓǦƶƾǦǁƐǦǃƼườƾǦđƑǃƼǦƼƾƑ,ǦƸƽƓǃƽǦǁƐǦǃƽữǃƼǦđệǦǉửǦǀƾƶ.ǦƢƾặƸǦđếǃǦǇồƾ,ǦǁƃǄǦǅƽảƾǦǍƇǃƼǦǁƙǃǦǉǇướƸ,ǦđỡǦđượƸǦǃƽƑǉǦđƶǄǦǃƐǄǦƽƶǓǦǃƽƑǉǦǃấǓ.",
    ["以声消灾之说尚无实证，所耗不菲，不可行. "] = "ǥƽǊǓếǉǦǤƖǃƼǦǉƽƶǃƽǦƁǂǦǉƾƙǊǦǉƶƾǦǋẫǃǦƸƽưƶǦƸƚǦǉƽựƸǦƸƽứǃƼ,ǦƽƶǄǦǉốǃǦǀƽƇǃƼǦƓǉ,ǦǀƽƇǃƼǦǉƽểǦǉƽựƸǦƽƾệǃ.",
    ["十几年了也没搞清楚这地方是谁建的，现在就要走了. "] = "ƨườƾǦǂấǓǦǃăǂǦǇồƾǦƸũǃƼǦƸƽẳǃƼǦǇƅǦǃơƾǦǃƐǓǦǤǄǦƶƾǦǍƁǓ,ǦƼƾờǦǉƽƔǦǅƽảƾǦđƾǦǇồƾ.",
    ["只知奏疏胡言，未见百姓遭遇。枉为朝廷官员. "] = "ƞƽỉǦƷƾếǉǦǉấǊǦǈớǦǃƚƾǦƸƐǃ,ǦǀƽƇǃƼǦǉƽấǓǦƷƑƸƽǦǉƓǃƽǦƼặǅǦǃạǃ.ǦǕổǃƼǦƸƇǃƼǦǁƐǂǦǆǊƶǃǦǉǇƾềǊǦđƔǃƽ.",
    ["三年笛里关山月，万国兵前草木风。\n安得壮士挽天河，净洗甲兵长不用。\n五代乱离，血海硝烟。唯人中狮，云开见天。\n所谓明主，其兵强耶？力壮耶？巍巍峨峨耶？\n所谓明主，其止兵也。安民也。泽沃苍生也. "] = "ǥƶǂǦǃƾƙǃǦđịƸƽǦǁƈǦƬǊƶǃǦƮơǃǦƩƼǊǓệǉ,ǦǋạǃǦǆǊốƸǦƷƾǃƽǦǉƾềǃǦǉƽảǄǦǂộƸǦǅƽǄǃƼ.\nƜǃǦđắƸǦǉǇƑǃƼǦǈĩǦǋƃǃǦǥƽƾƙǃǦƣƐ,ǦǉịǃƽǦǉẩǓǦƼƾƑǅǦƷƾǃƽǦǉǇườǃƼǦƷấǉǦǤụǃƼ.\nƩƼũǦđạƾǦǁǄạǃǦǁǓ,ǦƽǊǓếǉǦƽảƾǦǉƾƙǊǦǓƙǃ.ǦǝǊǓǦǃƽƁǃǦǉǇǊǃƼǦǈư,ǦǋƁǃǦǀƽƶƾǦǀƾếǃǦǉƽƾƙǃ.\nƮởǦǋịǦǂƾǃƽǦƸƽủ,ǦǀỳǦƷƾǃƽǦƸườǃƼǦƼƾƶ?ǦƧựƸǦǉǇƑǃƼǦƼƾƶ?ǦƩƼǊǓǦǃƼǊǓǦǃƼƶǦǃƼƶǦƼƾƶ?\nƮởǦǋịǦǂƾǃƽǦƸƽủ,ǦǀỳǦđƔǃƽǦƷƾǃƽǦǤƃ.ǦƜǃǦǤƁǃǦǤƃ.ǦǥǇạƸƽǦốƸǦǉƽươǃƼǦǈƾǃƽǦǤƃ.",
    ["斬雪刀法·极降效"] = "ǥǇảǂǦǥǊǓếǉǦĐƶǄǦƫƽƑǅǦ·ǦƞựƸǦƼƾƑǃƼǦƽƾệǊ",
    ["啊，没啥。就是想起来，俺当兵的时候，见过不少这样的场面。"] = "À,ǦǀƽƇǃƼǦƸƚǦƼƔ.ǦƞƽỉǦǁƐǦƸƽợǉǦǃƽớǦǇƶ,ǦƽồƾǦǉƶǦƸƛǃǦđƾǦǁƓǃƽ,ǦđƃǦǉừǃƼǦǉƽấǓǦǀƽƇǃƼǦƓǉǦƸảǃƽǦǉượǃƼǦǃƽưǦǉƽếǦǃƐǓ.",
    ["皇宫通用远程怪掉落 world level 9"] = "ƬǊƑƾǦđƑǃƽǦǍƶǦǤƖǃƼǦƸƽǊǃƼǦƣǄƐǃƼǦƸǊǃƼǦǇơƾǦđồǦƸấǅǦǉƽếǦƼƾớƾǦ9",
    ["那、那咋整啊，现在玄卫都去巡逻了……"] = "ǥƽế,ǦǉƽếǦǉƽƔǦǉƓǃƽǦǈƶǄǦđƁǓ,ǦƽƾệǃǦƼƾờǦƣǊǓềǃǦǋệǦđềǊǦđƾǦǉǊầǃǦǉǇƶǦƸảǦǇồƾ...",
    ["狂澜义军自西北而来，驰援王清将军，抵达滹沱河岸者共十五。\n那夜，大家就着颓垣村的断壁残垣生了火，喝起了各自揣了一路的那葫酒。康旻不知从哪儿打来了野味，韦青替大家烤熟了下酒。油脂滴火滋滋作响，沈渊师兄却在篝火边舞起了枪，飞舞的枪影宛若游龙.叶轻行和陆凭风靠在悬赏榜下看，魏霄同唐余坐在河边石上拍手叫好，范常安还是那般不安生，急着要同沈渊师兄过上几招……\n大帅独自坐在半倾的屋顶，拎着酒葫芦，对着远处沉黑的河面哼起了玉门关外的小曲。\n酒巡遍，人声静，凛冽的河风卷着烽火余烬扑面而来。\n我们，该动身了。"] = "ƩƼƽĩƶǦǆǊƁǃǦƞǊồǃƼǦƧƶǃǦǉừǦǅƽƓƶǦǥƁǓǦƝắƸǦǀƗǄǦđếǃ,ǦƸƽƾǦǋƾệǃǦƸƽǄǦƱươǃƼǦǥƽƶǃƽǦǉướǃƼǦǆǊƁǃ,ǦǃƼườƾǦǉớƾǦđượƸǦƷờǦǈƇǃƼǦƣƇǦĐƐǦǉổǃƼǦƸộǃƼǦǂườƾǦǁăǂǦǋị.\nĐƙǂǦđƚ,ǦǂọƾǦǃƼườƾǦǂượǃǦǃƽữǃƼǦƷứƸǦǉườǃƼǦđổǦǃƑǉǦƸủƶǦǉƽƇǃǦĐồƾǦƱƾƙǃǦǂƐǦǃƽƚǂǦǁửƶ,ǦǊốǃƼǦƷầǊǦǇượǊǦǂƐǦǂỗƾǦǃƼườƾǦđƃǦǂƶǃƼǦǉƽƺǄǦǈǊốǉǦǤọƸǦđườǃƼ.ǦƦƽƶǃƼǦƨƁǃǦƸƽẳǃƼǦƷƾếǉǦǈăǃǦđượƸǦǉƽƕǦǇừǃƼǦǉừǦđƁǊ,ǦƱƾǦǥƽƶǃƽǦǉƽƶǓǦǂọƾǦǃƼườƾǦǃướǃƼǦƸƽƓǃǦǁƐǂǦđồǦǃƽắǂ.ǦƨỡǦǃƽỏǦǋƐǄǦǁửƶǦǍƘǄǦǍƘǄ,ǦǥƽƁǂǦǕǓƙǃǦǈưǦƽǊǓǃƽǦǁạƾǦƷƙǃǦđốǃƼǦǁửƶǦǂƕƶǦǉƽươǃƼ,ǦƷƚǃƼǦǉƽươǃƼǦƷƶǓǦǂƕƶǦǉựƶǦǃƽưǦǤǊǦǁǄǃƼ.ǦǝƾệǅǦƦƽƾǃƽǦƣƐǃƽǦǋƐǦƧụƸǦƝằǃƼǦƫƽǄǃƼǦǉựƶǦǤướƾǦƷảǃƼǦǉǇƺǄǦǉƽưởǃƼǦǂƐǦǍƺǂ,ǦƩƼụǓǦǥƾƙǊǦƸƖǃƼǦĐườǃƼǦǝưǦǃƼồƾǦǉǇƙǃǦđƑǦƷƙǃǦǈƇǃƼǦǋỗǦǉƶǓǦǀƽƺǃǦƽƶǓ,ǦƫƽạǂǦǥƽườǃƼǦƜǃǦǋẫǃǦƸƑƾǦǉƓǃƽǦǀƽƇǃƼǦƸƽịǊǦǃƼồƾǦǓƙǃǦấǓ,ǦƸứǦƸǊốǃƼǦǆǊƈǉǦđƛƾǦǈǄǦǋƐƾǦƸƽƾƙǊǦǋớƾǦǥƽẩǂǦǕǓƙǃǦǈưǦƽǊǓǃƽ...\nĐạƾǦǈǄƑƾǦǂộǉǦǂƔǃƽǦǃƼồƾǦǉǇƙǃǦǂƑƾǦǃƽƐǦđổǦǃƑǉ,ǦǉƶǓǦǍƑƸƽǦƷầǊǦǇượǊ,ǦƽướǃƼǦǋềǦǅƽƓƶǦǂặǉǦǈƇǃƼǦđƺǃǦǀịǉǦǅƽươǃƼǦǍƶǦǂƐǦǃƼƁǃǦǃƼƶǦǀƽƕƸǦǃƽạƸǦǃƽỏǦǃƼǄƐƾǦƩƼọƸǦƨƇǃǦƬǊƶǃ.\nƭượǊǦđƃǦǆǊƶǦǋƛǃƼ,ǦǃƼườƾǦđƃǦǁặǃƼǦǉƾếǃƼ,ǦƼƾƚǦǈƇǃƼǦǁạǃƽǦǁẽǄǦƸǊốǃǦǉƽƺǄǦǉƐǃǦǉǇǄǦǀƽƚƾǦǁửƶǦậǅǦǋƐǄǦǂặǉ.\nƞƽƕǃƼǦǉƶ,ǦǃƙǃǦǁƙǃǦđườǃƼǦǉƽƇƾ.",
    ["八方风雷枪·战八方"] = "ƝƑǉǦƫƽươǃƼǦƫƽǄǃƼǦƧƇƾǦǥƽươǃƼǦ·ǦƞƽƾếǃǦƝƑǉǦƫƽươǃƼ",
