    ["要想让枯树长叶，让老百姓有口饭吃……"] = "ƨǊốǃǦƸƽǄǦƸƁǓǦǀƽƇǦđƁǂǦƸƽồƾ,ǦƸƽǄǦƷƑƸƽǦǉƓǃƽǦƸƚǦǂƾếǃƼǦƸơǂǦăǃ...",
    ["还挺有意思，就像以前，跟小时候的俺弟一起耍似的。"] = "ƞũǃƼǦǉƽƕǦǋịǦđấǓ,ǦƼƾốǃƼǦǃƽưǦǉǇướƸǦǀƾƶǦƸƖǃƼǦđệǦđệǦǉƶǦƸƽơƾǦđƖƶǦǁƕƸǦǃƽỏǦǋậǓ.",
    ["还是走吧，既然 them 敢这么光明正大……恐怕庄子里的人已经遇害了。单凭我们两人，去了也是徒劳。"] = "ƩƙǃǦđƾǦǉƽƇƾ,ǦǂộǉǦǀƽƾǦƸƽƕǃƼǦǤƑǂǦǆǊƶǃƼǦǂƾǃƽǦƸƽƓǃƽǦđạƾǦǉƽếǦǃƐǓ...ǦƺǦǁƐǦǃƼườƾǦǉǇǄǃƼǦǉǇƶǃƼǦǋƾƙǃǦđƃǦƼặǅǦǃạǃǦǇồƾ.ǦƞƽỉǦǤựƶǦǋƐǄǦƽƶƾǦǃƼườƾǦƸƽƕǃƼǦǉƶ,ǦƸƚǦđƾǦƸũǃƼǦǋƇǦǤụǃƼ.",
    ["浓汁酱香的肉丸，粒粒饱满，美味 but 略显普通。得高人指点冠名，以“肉质优良，食之增肌”为卖点，引江湖中人竞相购买。"] = "ƱƾƙǃǦǉƽịǉǦǈốǉǦđậǂǦđƐ,ǦǋƾƙǃǦǃƐǄǦǋƾƙǃǦǃấǓǦƸăǃƼǦǉǇƛǃ,ǦǉƽơǂǦǃƼǄǃǦǃƽưǃƼǦƽơƾǦǅƽổǦǉƽƇǃƼ.ǦĐượƸǦƸƶǄǦǃƽƁǃǦƸƽỉǦđƾểǂǦđặǉǦǉƙǃ,ǦǁấǓǦǀƽẩǊǦƽƾệǊǦ\"ǉƽịǉǦƸƽấǉǦǁượǃƼǦƸƶǄ,ǦăǃǦǋƐǄǦǉăǃƼǦƸơ\"ǦǁƐǂǦđƾểǂǦƷƑǃǦƽƐǃƼ,ǦǉƽǊǦƽƕǉǦǃƼườƾǦǉǇǄǃƼǦƼƾƶǃƼǦƽồǦǉǇƶǃƽǦǃƽƶǊǦǂǊƶ.",
    ["【无名剑法】蓄力技【无以为家】在未进战状态、真气护盾存续期间及【退亦有方】剑气释放5秒内开始蓄力，即可在完成二段蓄力时额外发射多道剑气。多道剑气发射时，会额外消耗耐力提升伤害，每点耐力可提升#Y1%#E，最高#Y20%#E。"] = "[ƱƇǦǝƶǃƽǦƦƾếǂǦƫƽƑǅ]ǦƦỹǦǃăǃƼǦǉụǦǁựƸǦ[ƱƇǦǝĩǦƱƾǦƢƾƶ]ǦǀƽƾǦƷắǉǦđầǊǦǉụǦǁựƸǦǉǇǄǃƼǦǉǇạǃƼǦǉƽƑƾǦƸƽưƶǦǋƐǄǦƸƽƾếǃǦđấǊ,ǦǉǇǄǃƼǦǉƽờƾǦƼƾƶǃǦǀƽƾƙǃǦƸƽƁǃǦǀƽƓǦƸƛǃǦǉồǃǦǉạƾ,ǦƽǄặƸǦǉǇǄǃƼǦǋƛǃƼǦ5ǦƼƾƁǓǦǈƶǊǦǀƽƾǦƼƾảƾǦǅƽƚǃƼǦǀƾếǂǦǀƽƓǦ[ǥƽǄƑƾǦǝƾệƸǦƣữǊǦƫƽươǃƼ],ǦǈẽǦǅƽƑǉǦǉƽƙǂǦǃƽƾềǊǦđạǄǦǀƾếǂǦǀƽƓǦǀƽƾǦƽǄƐǃǦǉƽƐǃƽǦǉụǦǁựƸǦđǄạǃǦƽƶƾ.ǦƦƽƾǦǅƽƑǉǦǃƽƾềǊǦđạǄǦǀƾếǂǦǀƽƓ,ǦǈẽǦǉƾƙǊǦƽƶǄǦǉƽƙǂǦǉƽểǦǁựƸǦđểǦǉăǃƼǦǈƑǉǦǉƽươǃƼ,ǦǂỗƾǦđƾểǂǦǉƽểǦǁựƸǦǉăǃƼǦ#Y1%#E,ǦǉốƾǦđƶǦ#Y20%#E.",
    ["心法：剑气纵横·三重"] = "ǥƁǂǦǅƽƑǅ:ǦƦƾếǂǦƦƽƓǦǥƖǃƼǦƣǄƐǃƽǦ·ǦǥầǃƼǦ3",
    ["那些箱子顶上，应该能通到梯子那儿。唯一的路，就是底下这个洞。"] = "ǥǇƙǃǦǃƚƸǦǂấǓǦƸƑƾǦƽƛǂǦđƚǦƸƽắƸǦǁƐǦǉƽƇǃƼǦđếǃǦƸƽỗǦƸƑƾǦǉƽƶǃƼ.ǦƞǄǃǦđườǃƼǦǤǊǓǦǃƽấǉǦƸƽƓǃƽǦǁƐǦƸƑƾǦǁỗǦƷƙǃǦǤướƾǦǃƐǓ.",
    ["卫悬对天下局势颇为关心，只因他等这一天已经很久了——或是为了名震江湖，又或是另有所图。但旁人不知的是，这位自南方遥遥奔赴 mà lai đích hiệp khách，已经等到了他要的那个时机。"] = "ƱệǦƣǊǓềǃǦǋốǃǦǇấǉǦǆǊƶǃǦǉƁǂǦđếǃǦđạƾǦƸụƸǦǉƽƾƙǃǦƽạ,ǦƷởƾǦǁẽǦƽắǃǦđƃǦđợƾǦǃƼƐǓǦǃƐǓǦǉừǦǇấǉǦǁƁǊǦǇồƾǦ—ǦƽǄặƸǦǁƐǦđểǦǋƶǃƼǦǤƶǃƽǦƼƾƶǃƼǦƽồ,ǦƽǄặƸǦǁƐǦǋƔǦǂộǉǦǂưǊǦđồǦǀƽƑƸ.ǦƩƽưǃƼǦǃƼườƾǦǃƼǄƐƾǦǀƽƇǃƼǦƽƶǓǦƷƾếǉǦǇằǃƼ,ǦǋịǦƽƾệǅǦǀƽƑƸƽǦǁặǃǦǁộƾǦđườǃƼǦǍƶǦǉừǦǅƽươǃƼǦƩƶǂǦǉớƾǦǃƐǓǦđƃǦđợƾǦđượƸǦǉƽờƾǦƸơǦǂƐǦƽắǃǦǂǄǃƼǦǂǊốǃ.",
    ["八方风雷枪·风雷啸"] = "ƝƑǉǦƫƽươǃƼǦƫƽǄǃƼǦƧƇƾǦǥƽươǃƼǦ·ǦƫƽǄǃƼǦƧƇƾǦƦƽƾếǊ",
    ["行啊！说起来，你一个人，从老家到开封，现在还跑进皇宫大内了，真不简单!"] = "ĐượƸǦđấǓ!ǦƩƽắƸǦǂớƾǦǃƽớ,ǦǂộǉǦǂƔǃƽǦǃƼươƾǦǉừǦǆǊƙǦǃƽƐǦđếǃǦƦƽƶƾǦƫƽǄǃƼ,ǦƼƾờǦƸƛǃǦƸƽạǓǦđượƸǦǋƐǄǦǉậǃǦǉƽƁǂǦƸǊǃƼǦǃộƾǦǋƾệǃ,ǦǉƽậǉǦƸƽẳǃƼǦđơǃǦƼƾảǃ!",
    ["路过后苑池畔，只见冰封的湖面上人影绰绰，往来 như phi……深宫之内，何时兴起了这般比试？"] = "ĐƾǦǃƼƶǃƼǦǆǊƶǦƷờǦǉǇƔǦƣậǊǦǕǓểǃ,ǦƸƽỉǦǉƽấǓǦǉǇƙǃǦǂặǉǦƽồǦđƚǃƼǦƷăǃƼǦƷƚǃƼǦǃƼườƾǦƸƽậǅǦƸƽờǃ,ǦǆǊƶǦǁạƾǦǃƽưǦƷƶǓ...ǦǥǇǄǃƼǦǉƽƁǂǦƸǊǃƼǦǃƐǓ,ǦǉừǦƷƶǄǦƼƾờǦǁạƾǦǇộǦǁƙǃǦǀƾểǊǦǉỉǦǉƽƓǦǉƽếǦǃƐǓ?",
    ["百因必有果，你的大侠就是 i！"] = "ƝƑƸƽǦǃƽƁǃǦǉấǉǦƽữǊǦǆǊả,ǦđạƾǦƽƾệǅǦƸủƶǦǃƼươƾǦƸƽƓǃƽǦǁƐǦǉƶ!",
    ["内藏有取会之禁，宫禁好赐之制，外廷莫得 mà tri。凡今岁时，士庶家以钱分遗家人辈，目曰节料；或岁正、冬节，纵之呼博，目曰则剧。习尚已久，亦不究所由始。"] = "ƩộƾǦǉƐǃƼǦƸƚǦƸấǂǦǁệǃƽǦǋềǦƽộƾǦƽọǅ,ǦƸǊǃƼǦƸấǂǦƸƚǦƸƽếǦđộǦƷƶǃǦǉặǃƼ,ǦǃƼǄạƾǦđƔǃƽǦǀƽƇǃƼǦǉƽểǦƽƶǓǦƷƾếǉ.ǦƫƽƐǂǦǁƕƸǦǁễǦǉếǉ,ǦǃƽƐǦǈĩǦǉƽứǦđƺǂǦǉƾềǃǦƸƽƾƶǦƸƽǄǦǃƼườƾǦǉƽƁǃ,ǦƼọƾǦǁƐǦǥƾếǉǦƧƾệǊ;ǦƽǄặƸǦǋƐǄǦǤịǅǦǥếǉ,ǦĐƇǃƼǦƞƽƓ,ǦǉƽảǦƸửƶǦđƑǃƽǦƷạƸ,ǦƼọƾǦǁƐǦǥắƸǦƦịƸƽ.ǦǥậǅǦǉụƸǦđƃǦǁƁǊǦđờƾ,ǦƸũǃƼǦƸƽẳǃƼǦƶƾǦǉǇǊǓǦƸứǊǦǃƼǊồǃǦƼốƸǦǉừǦđƁǊ.",
    ["完成完成「花灯燃昼明」引导任务且达到10级后开启活动"] = "ƣǄƐǃǦǉƽƐǃƽǦǃƽƾệǂǦǋụǦǤẫǃǦđườǃƼǦ[ƣǄƶǦĐăǃƼǦƩƽƾƙǃǦǥǇƕǦƨƾǃƽ]ǦǋƐǦđạǉǦƸấǅǦ10ǦđểǦǂởǦƽǄạǉǦđộǃƼ",
    ["俺这爪子咋跟你猜？你就放心往前走吧，俺来替你按板子。"] = "ƞƑƾǦǂƚǃƼǦǃƐǓǦƸủƶǦǉƶǦǈƶǄǦǂƐǦǄẳǃǦǉƖǦǉƔǦǋớƾǦǃƼươƾǦđượƸ?ǦƩƼươƾǦƸứǦǓƙǃǦǉƁǂǦđƾǦǉƾếǅǦđƾ,ǦǉƶǦǈẽǦǃƽấǃǦǉấǂǦǋƑǃǦƸƽǄǦǃƼươƾ.",
    ["{}切换武器{}消耗摧鼓效果释放感知技获得破阵效果"] = "{}ǦƸƽǊǓểǃǦđổƾǦǋũǦǀƽƓǦ{}ǦǉƾƙǊǦƽƶǄǦƽƾệǊǦứǃƼǦǥƽƇƾǦƞổǦǉƽƾǦǉǇƾểǃǦǀỹǦǃăǃƼǦƸảǂǦǉǇƾǦǃƽậǃǦƽƾệǊǦứǃƼǦƫƽƑǦǥǇậǃ",
    ["两人一起从右边下台（缺少功能）"] = "ƣƶƾǦǃƼườƾǦƸƖǃƼǦǍǊốǃƼǦđƐƾǦǉừǦƷƙǃǦǅƽảƾǦ(ǉƽƾếǊǦǉƓǃƽǦǃăǃƼ)",
    ["后来，人走了，马没了，家散了，庄子迁了……我们却还是又养出了许多好 ma，养出了夜露飞光……"] = "ƮƶǊǦǃƐǓ,ǦǃƼườƾǦđƾ,ǦǃƼựƶǦǂấǉ,ǦǃƽƐǦǉƶǃ,ǦǉǇƶǃƼǦǋƾƙǃǦǤờƾǦƸƽỗ...ǦǃƽưǃƼǦƸƽƕǃƼǦǉƶǦǋẫǃǦǃǊƇƾǦǤưỡǃƼǦđượƸǦǉƽƙǂǦǃƽƾềǊǦǃƼựƶǦǉốǉ,ǦǃǊƇƾǦǤưỡǃƼǦđượƸǦǝạǦƧộǦƫƽƾǦƬǊƶǃƼ...",
    ["岂敢，岂敢，仍然难以与伍大人那追风骏 ma 相提并论。"] = "ĐƁǊǦǤƑǂ,ǦđƁǊǦǤƑǂ,ǦǋẫǃǦǀƽƚǦǁƛǃƼǦǈǄǦƷƔǦǋớƾǦǉǊấǃǦǂƃǦǥǇǊǓǦƫƽǄǃƼǦƸủƶǦƩƼũǦđạƾǦǃƽƁǃ.",
    ["啊？是吗？我琢磨厝……灯……没坏……亮……"] = "ƣả?ǦǥƽếǦǈƶǄ?ǦǥƶǦđƶǃƼǦǃƼẫǂǦǃƼƽĩ...ǦđƘǃ...ǦƸƽưƶǦƽỏǃƼ...ǦǈƑǃƼ...",
    ["汪汪，汪！汪汪汪，汪汪汪汪汪汪汪汪汪？汪汪！汪汪汪汪汪汪。\n\n……\n\n少东家：\n\n哥又来同你叨叨乐子啦！\n\n这一趟出游，哥算是涨了见识，刚一进开封城，就叫一看门的狗给拦住了。那狗三催四请，非要哥去什么皇城脚下，听什么“汪汪队唠嗑年终总结大会”。别的不说，现场狗粮管够，还热闹得紧。\n\n光是逛了一小会儿，哥就听了不少壁角。\n\n什么下属暗恋头儿啊，什么宫里头的官爷今天穿了身什么私服啦……嗐，听得哥那是嘴角就没下来过！\n\n哦对了，哥还在现场遇见个跟我撞脸的大黄狗，竟也叫伏禄娃的名儿。\n\n那伏禄二娃虚荣得紧，逢狗就吹自己跟了个名声响的游侠，好像是叫什么、什么$C$L#Y$PN#E$C的……哥没听过，也不在乎！\n\n出门在外，身份是自个儿给 of，哥当即将你的家业同人品，夸得那是天花乱坠，杀得对面那是无地自容。\n\n那伏禄小二娃竟还敢同哥犟嘴，张口就是“我们少东家会捡别人擦屁股用的小树杈，你们会吗？我们少东家杀人又抢马，往人家屁股蛋子上射完箭还能跑掉，你们能吗？我们少东家一年能整八次容，你们能吗？”\n\n听得哥那是一愣一愣！\n\n不过，少东家你放心，输狗不输阵，靠着哥这口亮嗓门，到底没落了你的面子！\n\n好了不多说了，前头那台上突然站了个狗模狗样的汪，瞧那架势，是要发号施令了，你等哥回去后再同你细唠。\n\n你最靠谱的伏禄娃留"] = "ƢƁǊǦƼƁǊ,ǦƼƁǊ!ǦƢƁǊǦƼƁǊǦƼƁǊ,ǦƼƁǊǦƼƁǊǦƼƁǊǦƼƁǊǦƼƁǊǦƼƁǊǦƼƁǊǦƼƁǊǦƼƁǊ?ǦƢƁǊǦƼƁǊ!ǦƢƁǊǦƼƁǊǦƼƁǊǦƼƁǊǦƼƁǊǦƼƁǊ.\n\n...\n\nǥƽƾếǊǦđƇǃƼǦƼƾƶ:\n\nƞƶǦǁạƾǦǉớƾǦǉƑǃǦǤƚƸǦƸƽǊǓệǃǦǋǊƾǦǋớƾǦđệǦđƁǓ!\n\nƞƽǊǓếǃǦǤǊǦǃƼǄạǃǦǃƐǓǦƸƶǦƸǄƾǦǃƽưǦđƃǦǂởǦǂƶǃƼǦǉầǂǦǂắǉ,ǦǋừƶǦǂớƾǦǋƐǄǦǉƽƐǃƽǦƦƽƶƾǦƫƽǄǃƼǦđƃǦƷịǦǂộǉǦƸǄǃǦƸƽƚǦƼƑƸǦƸổǃƼǦƸƽặǃǦǁạƾ.ǦƞǄǃǦƸƽƚǦđƚǦǂờƾǦǂọƸǦǃƽƾệǉǦǉƔǃƽ,ǦƸứǦǃƽấǉǦǆǊǓếǉǦƷắǉǦƸƶǦǅƽảƾǦǉớƾǦƸƽƁǃǦǉƽƐǃƽǦƽǄƐǃƼǦƸǊǃƼ,ǦǃƼƽƺǦƸƑƾǦƼƔǦǂƐǦ\"ĐạƾǦƽộƾǦǉổǃƼǦǀếǉǦƸǊốƾǦǃăǂǦƸủƶǦđộƾǦƢƁǊǦƢƁǊ\".ǦƞƽưƶǦǃƚƾǦƸƽǊǓệǃǦǀƽƑƸ,ǦđồǦăǃǦƸƽǄǦƸƽƚǦǉạƾǦƽƾệǃǦǉǇườǃƼǦƷƶǄǦǃǄ,ǦǁạƾǦƸƛǃǦǃƑǄǦǃƽƾệǉǦǋƇǦƸƖǃƼ.\n\nƞƽỉǦǂớƾǦǤạǄǦƸƽơƾǦǂộǉǦǁƑǉ,ǦƸƶǦđƃǦǃƼƽƺǦǁỏǂǦđượƸǦƷƶǄǦǃƽƾƙǊǦǁƐǦƸƽǊǓệǃǦǀƓǃǦǀẽ.\n\nƩƐǄǦǁƐǦƸấǅǦǤướƾǦǉƽầǂǦǂếǃǦđạƾǦƸƶ,ǦǃƐǄǦǁƐǦǆǊƶǃǦƼƾƶǦǉǇǄǃƼǦƸǊǃƼǦƽƇǂǦǃƶǓǦǂặƸǦƷộǦǉƽườǃƼǦǅƽụƸǦƼƔ...ǦƣạƾǦƸƶǦƸườƾǦđếǃǦǃỗƾǦǀƽƚƺǦǂƾệǃƼǦƸƽẳǃƼǦǀƽƗǅǦǁạƾǦđượƸ!\n\nÀǦđƕǃƼǦǇồƾ,ǦƸƶǦƸƛǃǦƼặǅǦǂộǉǦƸǄǃǦƸƽƚǦǋƐǃƼǦƸƚǦƼươǃƼǦǂặǉǦǓǦƽệǉǦƸƶǦǉạƾǦđƚ,ǦǉƽếǦǂƐǦƸũǃƼǦǉƙǃǦǁƐǦƫƽụƸǦƧộƸǦƪƶ.\n\nǥƽằǃƼǦƫƽụƸǦƧộƸǦƩƽịǦƪƶǦđƚǦƽƑǂǦǤƶǃƽǦƽƃǄǦǋƇǦƸƖǃƼ,ǦƼặǅǦƸǄǃǦƸƽƚǦǃƐǄǦƸũǃƼǦǀƽǄƺǦǀƽǄƶǃƼǦǂƔǃƽǦđƾǦǉƽƺǄǦǂộǉǦǋịǦǤǊǦƽƾệǅǦǁừǃƼǦǤƶǃƽ,ǦƽƔǃƽǦǃƽưǦǉƙǃǦǁƐǦƸƑƾǦƼƔǦǂƐǦ$ƞ$Ƨ#Y$PƩ#E$ƞǦấǓ...ǦƞƶǦƸƽưƶǦǃƼƽƺǦƷƶǄǦƼƾờ,ǦƸũǃƼǦƸƽẳǃƼǦǉƽƘǂǦǆǊƶǃǦǉƁǂ!\n\nĐƾǦǇƶǦǃƼǄƐƾ,ǦǉƽƁǃǦǅƽậǃǦǁƐǦǤǄǦǂƔǃƽǦǉựǦǉạǄ,ǦƸƶǦǁậǅǦǉứƸǦđƺǂǦƼƾƶǦǃƼƽƾệǅǦƸƖǃƼǦǃƽƁǃǦǅƽẩǂǦƸủƶǦđệǦǇƶǦǀƽƺǃǦǉớƾǦǉậǃǦǉǇờƾǦǍƶǃƽ,ǦǀƽƾếǃǦđốƾǦǅƽươǃƼǦǍấǊǦƽổǦǀƽƇǃƼǦƷƾếǉǦƼƾấǊǦǂặǉǦǋƐǄǦđƁǊ.\n\nǥƽằǃƼǦƫƽụƸǦƧộƸǦƩƽịǦƪƶǦƸǄǃǦđƚǦƸƛǃǦǤƑǂǦƸƃƾǦǁạƾǦƸƶ,ǦǂởǦǂƾệǃƼǦǇƶǦǁƐǦ\"ǥƽƾếǊǦđƇǃƼǦƼƾƶǦƸƽƕǃƼǦǉƶǦƷƾếǉǦǃƽặǉǦƸƐǃƽǦƸƁǓǦǃƽỏǦǃƼườƾǦǀƽƑƸǦǤƖǃƼǦƸƽƖƾǦđƓǉ,ǦƸƑƸǦǃƼươƾǦƷƾếǉǦǀƽƇǃƼ?ǦǥƽƾếǊǦđƇǃƼǦƼƾƶǦƸƽƕǃƼǦǉƶǦƼƾếǉǦǃƼườƾǦƸướǅǦǃƼựƶ,ǦƷắǃǦǉƙǃǦǋƐǄǦǂƇǃƼǦǃƼườƾǦǉƶǦǍǄǃƼǦƸƛǃǦƸƽạǓǦǉƽǄƑǉǦđượƸ,ǦƸƑƸǦǃƼươƾǦǁƐǂǦđượƸǦǀƽƇǃƼ?ǦǥƽƾếǊǦđƇǃƼǦƼƾƶǦƸƽƕǃƼǦǉƶǦǂộǉǦǃăǂǦƸƚǦǉƽểǦǅƽẫǊǦǉƽǊậǉǦǉƽẩǂǦǂỹǦǉƑǂǦǁầǃ,ǦƸƑƸǦǃƼươƾǦǁƐǂǦđượƸǦǀƽƇǃƼ?\"\n\nƩƼƽƺǦǂƐǦƸƶǦƸũǃƼǦǅƽảƾǦǃƼớǦǃƼườƾǦǇƶǦǁǊƇǃ!\n\nƩƽưǃƼǦǂƐǦǥƽƾếǊǦđƇǃƼǦƼƾƶǦǓƙǃǦǉƁǂ,ǦǉƽǊƶǦƸƽƚǦǀƽƇǃƼǦǉƽǊƶǦǉǇậǃ,ǦǃƽờǦǋƐǄǦƸƑƾǦƼƾọǃƼǦǄƶǃƽǦǋƐǃƼǦǃƐǓǦƸủƶǦƸƶ,ǦǇốǉǦƸǊộƸǦƸũǃƼǦǀƽƇǃƼǦđểǦđệǦǂấǉǦǂặǉ!\n\nǥƽƇƾǦǀƽƇǃƼǦǃƚƾǦǃƽƾềǊǦǃữƶ,ǦǉǇƙǃǦƸƑƾǦđƐƾǦǅƽƓƶǦǉǇướƸǦƷỗǃƼǦƸƚǦǂộǉǦƸǄǃǦƼƁǊǦƼƁǊǦǉǇƇǃƼǦǇấǉǦǇƶǦǤƑǃƼǦđứǃƼǦǁƙǃ,ǦǃƽƔǃǦđƾệǊǦƷộǦđƚǦǁƐǦǈắǅǦǇƶǦǁệǃƽǦǇồƾ,ǦđệǦđợƾǦƸƶǦǋềǦǇồƾǦƸƶǦǀểǦǀỹǦƸƽǄǦǃƼƽƺ.\n\nƫƽụƸǦƧộƸǦƪƶǦđƑǃƼǦǉƾǃǦǃƽấǉǦƸủƶǦđệǦđểǦǁạƾǦǉƽư",
    ["<特殊技：流风回雪>每连续命中同一单位6次（间隔不超过2秒），就会使目标额外受到10点真气伤害，目标5秒内不会再次受到该效果. "] = "<ƦỹǦǃăǃƼǦđặƸǦƷƾệǉ:ǦƧưǊǦƫƽǄǃƼǦƣồƾǦǥǊǓếǉ>ǦƨỗƾǦǀƽƾǦđƑǃƽǦǉǇƕǃƼǦǁƾƙǃǦǉƾếǅǦƸƖǃƼǦǂộǉǦǂụƸǦǉƾƙǊǦ6ǦǁầǃǦ(ǀƽǄảǃƼǦƸƑƸƽǦǀƽƇǃƼǦǆǊƑǦ2ǦƼƾƁǓ),ǦǈẽǦǀƽƾếǃǦǂụƸǦǉƾƙǊǦƸƽịǊǦǉƽƙǂǦ10ǦđƾểǂǦǈƑǉǦǉƽươǃƼǦƸƽƁǃǦǀƽƓ,ǦǂụƸǦǉƾƙǊǦǉǇǄǃƼǦ5ǦƼƾƁǓǦǈẽǦǀƽƇǃƼǦƸƽịǊǦǁạƾǦƽƾệǊǦứǃƼǦǃƐǓ.",
    ["<武学技：履虚扫尘>命中真气低于30%的的单位时，会为目标附加持续 5 秒的禁止疾跑及跳跃效果. "] = "<ƦỹǦǃăǃƼǦǋƅǦƽọƸ:ǦƧƈǦƣưǦǥảǄǦǥǇầǃ>ǦƦƽƾǦđƑǃƽǦǉǇƕǃƼǦǂụƸǦǉƾƙǊǦƸƚǦƸƽƁǃǦǀƽƓǦǉƽấǅǦƽơǃǦ30%,ǦǈẽǦđƓǃƽǦǀƘǂǦƽƾệǊǦứǃƼǦƸấǂǦƸƽạǓǦǃƽƶǃƽǦǋƐǦǃƽảǓǦǤǊǓǦǉǇƔǦ5ǦƼƾƁǓǦǁƙǃǦǂụƸǦǉƾƙǊ.",
    ["<特殊技：万军破>对强韧单位可造成额外20点真气伤害，并造成 0.5 秒定身，使自身回复 20 点耐力，每 5 秒可触发一次. "] = "<ƦỹǦǃăǃƼǦđặƸǦƷƾệǉ:ǦƱạǃǦƬǊƁǃǦƫƽƑ>ǦƞƚǦǉƽểǦƼƁǓǦǉƽƙǂǦ20ǦđƾểǂǦǈƑǉǦǉƽươǃƼǦƸƽƁǃǦǀƽƓǦǁƙǃǦǂụƸǦǉƾƙǊǦƸườǃƼǦǃƽậǃ,ǦđồǃƼǦǉƽờƾǦƼƁǓǦđịǃƽǦǉƽƁǃǦ0.5ǦƼƾƁǓ,ǦƼƾƕǅǦƷảǃǦǉƽƁǃǦƽồƾǦǅƽụƸǦ20ǦđƾểǂǦƷềǃǦƷỉ,ǦǂỗƾǦ5ǦƼƾƁǓǦƸƚǦǉƽểǦǀƓƸƽǦƽǄạǉǦǂộǉǦǁầǃ.",
    ["养成数据加载중"] = "ĐƶǃƼǦǉảƾǦǤữǦǁƾệǊǦǃǊƇƾǦǤưỡǃƼ",
