    ["{}快速切换武器，或使用{}切换武器"] = "{}ǦƞƽǊǓểǃǦǋũǦǀƽƓǦǃƽƶǃƽ,ǦƽǄặƸǦǤƖǃƼǦ{}ǦđểǦƸƽǊǓểǃǦǋũǦǀƽƓ",
    ["{}施加减益并靠近目标，{}切换武器，{}接续释放轻击召唤鹰隼积攒资源，{}拳风打击后接续轻击"] = "{}ǦƢƁǓǦǈǊǓǦǓếǊǦǋƐǦƑǅǦǈƑǉǦǂụƸǦǉƾƙǊ,Ǧ{}ǦƸƽǊǓểǃǦǋũǦǀƽƓ,Ǧ{}ǦǉƾếǅǦǃốƾǦǉƽƾǦǉǇƾểǃǦđƑǃƽǦǃƽẹǦǉǇƾệǊǦƽồƾǦưǃƼǦƸƽǊẩǃǦǉƓƸƽǦǁũǓǦǉƐƾǦǃƼǊǓƙǃ,Ǧ{}ǦǈƶǊǦǀƽƾǦǆǊǓềǃǦǅƽǄǃƼǦđảǦǀƓƸƽǦǉƾếǅǦǃốƾǦđƑǃƽǦǃƽẹ",
    ["……嘿嘿，也是。只要瞅见这手攥得紧，其他的看不看清，也不打紧。"] = "...ǦƣƔǦƽƔ,ǦƸũǃƼǦđƕǃƼ.ǦƞƽỉǦƸầǃǦǉƽấǓǦƸƑƾǦǉƶǓǦǃƐǓǦǃắǂǦǉƽậǉǦƸƽặǉ,ǦǃƽữǃƼǦǉƽứǦǀƽƑƸǦƸƚǦǃƽƔǃǦǇƅǦƽƶǓǦǀƽƇǃƼǦƸũǃƼǦƸƽẳǃƼǦƽềǦƼƔ.",
    ["烟花不辍，花朝同庆。压轴烟花，惊艳四座。烟花如梦，岁月如歌，愿 chúng ta 永远精彩纷呈！"] = "ƫƽƑǄǦƽǄƶǦǀƽƇǃƼǦǤứǉ,ǦƣǄƶǦǥǇƾềǊǦƸƖǃƼǦǋǊƾ.ǦƨƐǃǦǅƽƑǄǦƽǄƶǦƸǊốƾǦƸƖǃƼǦǁƐǂǦǀƾǃƽǦđộǃƼǦƷốǃǦǅƽươǃƼ.ǦƫƽƑǄǦƽǄƶǦǃƽưǦǂộǃƼ,ǦǃăǂǦǉƽƑǃƼǦǃƽưǦƸƶ,ǦǃƼǊǓệǃǦƸƽƕǃƼǦǉƶǦǂƃƾǦǁǊƇǃǦǇựƸǦǇỡǦǂǊƇǃǦǂƐǊ!",
    ["崇德殿后阁-官员II-背景板"] = "ƣậǊǦƸƑƸǦƮƖǃƼǦĐứƸǦĐƾệǃǦ-ǦƬǊƶǃǦǋƾƙǃǦƤƤǦ-ǦǥấǂǦǃềǃ",
    ["可将学徒调整为社众或将社众调整 với 学徒"] = "ƞƚǦǉƽểǦđƾềǊǦƸƽỉǃƽǦƽọƸǦđồǦǉƽƐǃƽǦǍƃǦƸƽƕǃƼǦƽǄặƸǦđƾềǊǦƸƽỉǃƽǦǍƃǦƸƽƕǃƼǦǉƽƐǃƽǦƽọƸǦđồ",
    ["天理昭昭，罪行难藏！\n伙房每日供给的饭食如此丰盛，你竟还去偷盗御食！也不知是手欠还是真的饥饿难耐。\n此番“面条”之刑，望能予你警醒，莫要擅动御食！\n但你若真是肚饿耐难，可在午食晚食期间，请盛饭宫人多为自己舀些饭食。"] = "ǥƽƾƙǃǦǁƈǦǇƅǦǇƐǃƼ,ǦǉộƾǦƑƸǦǀƽƚǦƼƾấǊ!\nƞơǂǦǃướƸǦǃƽƐǦƷếǅǦƸǊǃƼǦƸấǅǦǂỗƾǦǃƼƐǓǦǅƽǄǃƼǦǅƽƕǦǃƽưǦǉƽế,ǦǃƼươƾǦǋậǓǦǂƐǦƸƛǃǦđƾǦǉǇộǂǦǉƽứƸǦăǃǦǃƼựǦǤụǃƼ!ǦƞƽẳǃƼǦƷƾếǉǦǁƐǦǃƼứƶǦǉƶǓǦƽƶǓǦǉƽậǉǦǈựǦđƚƾǦđếǃǦǀƽƇǃƼǦƸƽịǊǦǃổƾ.\nƣƔǃƽǦǅƽạǉǦ\"ǂƔǦǈợƾ\"ǦǁầǃǦǃƐǓ,ǦƽǓǦǋọǃƼǦƸƚǦǉƽểǦƸảǃƽǦǉỉǃƽǦǃƼươƾ,ǦđừǃƼǦƸƚǦǉựǦƈǦđụǃƼǦǋƐǄǦǃƼựǦǉƽựƸ!\nƩƽưǃƼǦǃếǊǦǃƼươƾǦǉƽậǉǦǈựǦđƚƾǦƷụǃƼǦǀƽƚǦǃƽịǃ,ǦǉǇǄǃƼǦƼƾờǦƸơǂǦǉǇưƶǦƸơǂǦǉốƾ,ǦƸƚǦǉƽểǦǃƽờǦƸǊǃƼǦǃƽƁǃǦǂƕƸǦƸơǂǦƸƽǄǦǂƔǃƽǦǃƽƾềǊǦƽơǃǦǂộǉǦƸƽƕǉ.",
    ["斩雪刀法·飞鸿踏雪"] = "ǥǇảǂǦǥǊǓếǉǦĐƶǄǦƫƽƑǅǦ·ǦƫƽƾǦƣồǃƼǦĐạǅǦǥǊǓếǉ",
    ["你将田契和密信一同交予了内侍，内侍神色大变，欲要与 you 勾结，被你缉住交给了亲事官，现已被押入天牢。"] = "ƩƼươƾǦđƺǂǦđƾềǃǦǀƽếǦǋƐǦǂậǉǦǉƽưǦƸƖǃƼǦƼƾƶǄǦƸƽǄǦǃộƾǦǉƽị,ǦǃộƾǦǉƽịǦƷƾếǃǦǈắƸ,ǦđịǃƽǦƸấǊǦǀếǉǦǋớƾǦǃƼươƾ,ǦǁƾềǃǦƷịǦǃƼươƾǦƷắǉǦƼƾữǦƼƾƶǄǦƸƽǄǦǥƽƁǃǦƮựǦƬǊƶǃ,ǦƽƾệǃǦđƃǦđượƸǦƑǅǦƼƾảƾǦǋƐǄǦǉƽƾƙǃǦǁƶǄ.",
    ["{}获得安西军助战{}释放易武技"] = "{}ǦǃƽậǃǦđượƸǦƜǃǦǥƁǓǦƬǊƁǃǦǉǇợǦƸƽƾếǃǦ{}ǦǉƽƾǦǉǇƾểǃǦǝịƸƽǦƱƅǦƦỹ",
    ["{}切换武器{}舞动长枪累计连击数"] = "{}ǦƸƽǊǓểǃǦđổƾǦƷƾǃƽǦǀƽƓǦ{}ǦǂƕƶǦǉǇườǃƼǦǉƽươǃƼǦǉƓƸƽǦǁũǓǦǈốǦǁƾƙǃǦǀƓƸƽ",
    ["霹雳，好霹雳，你可别吓我呀！"] = "ƫƽƓƸƽǦƧịƸƽ,ǦƫƽƓƸƽǦƧịƸƽǦǃƼǄƶǃ,ǦǃƼươƾǦđừǃƼǦǤọƶǦǉƶǦǃƽƶ!",
    ["这是一个写对聯玩法"] = "ĐƁǓǦǁƐǦǁốƾǦƸƽơƾǦǋƾếǉǦđốƾǦǁƾƙǃ",
    ["哼，当年俺也是身姿灵巧，身轻如燕。就这破洞，算啥？"] = "ƣừ,ǦǃăǂǦǍưƶǦǉƶǦƸũǃƼǦǉƽƁǃǦǉƽủǦǁƾǃƽǦƽǄạǉ,ǦǉƽƁǃǦǃƽẹǦǃƽưǦǓếǃ.ǦƞƽƕǉǦǁỗǦƽổǃƼǦǃƐǓǦǉƽƔǦǉƓǃƽǦǁƐǦƼƔ?",
    ["Hô Đà chi danh 2"] = "ǝƶǃƽǦƽƾệǊǦƣƇǦĐƐǦ2",
    ["穿刺死棘 của thương"] = "ƳǊǓƙǃǦǥƽứǦǥửǦƞứƸǦƞƽƾǦǥƽươǃƼ",
    ["驅傩-红灵骑兵"] = "ƦƽǊǦƩƶǦ-ǦƣồǃƼǦƧƾǃƽǦǀỵǦƷƾǃƽ",
    ["干什么！真把自己当个人物了？！找死吗？奶奶的……王八羔子！"] = "ƧƐǂǦƸƑƾǦƼƔǦǋậǓ!ǦǥƽậǉǦǈựǦƸǄƾǦǂƔǃƽǦǁƐǦǃƽƁǃǦǋậǉǦǂƑǊǦǂặǉǦǈƶǄ?!ǦƨǊốǃǦǉƔǂǦƸƽếǉǦƽả?ǦƝƐǦǃƚǦƸƽứ...ǦđồǦǇƖƶǦǇụǉǦƸổ!",
    ["先别给我戴高帽，有条件——我难得进宫一次，就算事情办完了， yě 让我多玩一段时间。等我玩够了，就把玉佩还你。"] = "ĐừǃƼǦǋộƾǦǃịǃƽǦƽƚǉǦǉƶ,ǦƸƚǦđƾềǊǦǀƾệǃǦđấǓǦ——ǦǥƶǦǀƽƚǦǀƽăǃǦǁắǂǦǂớƾǦǋƐǄǦƸǊǃƼǦǂộǉǦƸƽǊǓếǃ,ǦǤƖǦǍǄǃƼǦǋƾệƸǦǇồƾǦƸũǃƼǦƽƃǓǦđểǦǉƶǦƸƽơƾǦǉƽƙǂǦǂộǉǦǉƽờƾǦƼƾƶǃ.ǦĐợƾǦǉƶǦƸƽơƾǦđủǦǇồƾǦǈẽǦǉǇảǦǃƼọƸǦƷộƾǦƸƽǄǦǃƼươƾ.",
    ["\n风落了，风又起了。一盏盏天灯艰难地攀升起来，往浓厚的黑夜里飘了去。\n几支流矢掠过。\n明灯长坠，残火漫天。"] = "\nƢƾƚǦǁặǃƼǦǇồƾ,ǦƼƾƚǦǁạƾǦǃổƾǦǁƙǃ.ǦǥừǃƼǦǃƼọǃǦǉƽƾƙǃǦđăǃƼǦǀƽƚǦǀƽăǃǦǁƺǄǦƸƶǄ,ǦƷƶǓǦǋềǦǅƽƓƶǦǂƐǃǦđƙǂǦǤƐǓǦđặƸ.\nƱƐƾǦǂũƾǦǉƙǃǦǁạƸǦǁướǉǦǆǊƶ.\nĐƘǃǦǈƑǃƼǦǇơƾǦǇụǃƼ,ǦǁửƶǦǉƐǃǦǃƼậǅǦǉǇờƾ.",
    ["我也不晓得啊，早晨起来霹雳就这样了，不吃不喝的，也不搭理我，我还跑去找了医官，医官说它没生病，可是没生病怎么会这样啊？"] = "ǥƶǦƸũǃƼǦƸƽẳǃƼǦƷƾếǉǦǃữƶ,ǦǈƑǃƼǦǇƶǦǤậǓǦǉƽƔǦƫƽƓƸƽǦƧịƸƽǦđƃǦǉƽếǦǃƐǓǦǇồƾ,ǦƸƽẳǃƼǦăǃǦƸƽẳǃƼǦǊốǃƼ,ǦƸũǃƼǦƸƽẳǃƼǦǂƐǃƼǦǉớƾǦǉƶ.ǦǥƶǦƸƛǃǦƸƽạǓǦđƾǦǉƔǂǦǓǦǆǊƶǃ,ǦǓǦǆǊƶǃǦƷảǄǦǃƚǦǀƽƇǃƼǦƷịǦƷệǃƽ,ǦǃƽưǃƼǦǀƽƇǃƼǦƷệǃƽǦǈƶǄǦǁạƾǦǉƽếǦǃƐǓǦđượƸǦƸơǦƸƽứ?",
    ["官署-青年-低级-官署后院三司晚晚上下班官员"] = "ƬǊƶǃǦǉƽựǦ-ǦǥƽƶǃƽǦǃƾƙǃǦ-ǦƮơǦƸấǅǦ-ǦƬǊƶǃǦǋƾƙǃǦǥƶǂǦǉǓǦǉƶǃǦǁƐǂǦƷǊổƾǦǉốƾǦởǦƽậǊǦǋƾệǃǦǆǊƶǃǦǉƽự",
    ["束罪阁-书斋-弹琴-将军"] = "ǥƽƕƸǦǥộƾǦƞƑƸǦ-ǦǥƽưǦǉǇƶƾǦ-ǦĐƑǃƽǦđƐǃǦ-ǦǥướǃƼǦǆǊƁǃ",
    ["霹雳，我向你道歉，我不该骗你……"] = "ƫƽƓƸƽǦƧịƸƽ,ǦǉƶǦǍƾǃǦǁỗƾǦǃƼươƾ,ǦǉƶǦǀƽƇǃƼǦǃƙǃǦǁừƶǦǃƼươƾ...",
    ["哎哟，可算盼来个新人！再不来人，我们几个老骨头真要被当牛ma使了。"] = "ƆƾǦƸƽƶǄ,ǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦđợƾǦđượƸǦǃƼườƾǦǂớƾ!ǦƞƛǃǦǀƽƇǃƼǦƸƚǦǃƼườƾǦđếǃ,ǦǂấǓǦǀƽƕƸǦǍươǃƼǦƼƾƐǦǉụƾǦǉƇƾǦǉƽậǉǦǈựǦƷịǦǁƇƾǦǇƶǦǁƐǂǦǉǇƁǊǦǁƐǂǦǃƼựƶǦǂấǉ.",
    ["【无名剑法】蓄力技【无以为家】在未进战状态、真气护盾存续期间及【退亦有方】剑气或多道剑气释放5秒内开始蓄力，即可在完成二段蓄力时额外发射多道剑气。多道剑气发射时，会额外消耗耐力提升伤害，每点耐力可提升#Y1%#E，最高#Y20%#E。剑气命中目标#Y8#E秒内，自身对其造成的剑气伤害会提升#Y5%#E，连续命中可叠加，最高可提升#Y15%#E。若命中的是非玩家单位，则目标气竭期间每层剑气增伤提升至#Y8%#E，叠满三层时最高可提升#Y24%#E。"] = "[ƱƇǦǝƶǃƽǦƦƾếǂǦƫƽƑǅ]ǦƞƽƾƙǊǦǉụǦǁựƸǦ[ƱƇǦǝĩǦƱƾǦƢƾƶ]ǦǀƽƾǦởǦǉǇạǃƼǦǉƽƑƾǦƸƽưƶǦǋƐǄǦƸƽƾếǃǦđấǊ,ǦǉǇǄǃƼǦǉƽờƾǦƼƾƶǃǦƽộǦǉƽǊẫǃǦƸƽƁǃǦǀƽƓǦǉồǃǦǉạƾǦǋƐǦǉǇǄǃƼǦǋƛǃƼǦ5ǦƼƾƁǓǦǈƶǊǦǀƽƾǦƼƾảƾǦǅƽƚǃƼǦǀƾếǂǦǀƽƓǦ[ǥƽǄƑƾǦǝƾệƸǦƣữǊǦƫƽươǃƼ]ǦƽǄặƸǦǃƽƾềǊǦđạǄǦǀƾếǂǦǀƽƓǦǂƐǦƷắǉǦđầǊǦǉụǦǁựƸ,ǦǉƽƔǦǀƽƾǦƽǄƐǃǦǉƽƐǃƽǦǉụǦǁựƸǦđǄạǃǦƽƶƾǦǈẽǦǅƽƚǃƼǦǉƽƙǂǦǃƽƾềǊǦđạǄǦǀƾếǂǦǀƽƓ.ǦƦƽƾǦǅƽƚǃƼǦǃƽƾềǊǦđạǄǦǀƾếǂǦǀƽƓǦǈẽǦǉƾƙǊǦƽƶǄǦǉƽƙǂǦƸƽịǊǦđựǃƼǦđểǦǉăǃƼǦǈƑǉǦǉƽươǃƼ,ǦǂỗƾǦđƾểǂǦƸƽịǊǦđựǃƼǦǉăǃƼǦ#Y1%#E,ǦǉốƾǦđƶǦ#Y20%#E.ǦǥǇǄǃƼǦǋƛǃƼǦ#Y8#EǦƼƾƁǓǦǈƶǊǦǀƽƾǦǀƾếǂǦǀƽƓǦǉǇƕǃƼǦǂụƸǦǉƾƙǊ,ǦǈƑǉǦǉƽươǃƼǦǀƾếǂǦǀƽƓǦƷảǃǦǉƽƁǃǦƼƁǓǦǇƶǦƸƽǄǦǂụƸǦǉƾƙǊǦđƚǦǉăǃƼǦ#Y5%#E,ǦǉǇƕǃƼǦǁƾƙǃǦǉƾếǅǦƸƚǦǉƽểǦƸộǃƼǦǤồǃ,ǦǉốƾǦđƶǦǉăǃƼǦ#Y15%#E.ǦƩếǊǦǉǇƕǃƼǦǂụƸǦǉƾƙǊǦǅƽƾǦǃƼườƾǦƸƽơƾ,ǦǉǇǄǃƼǦǉƽờƾǦƼƾƶǃǦǂụƸǦǉƾƙǊǦǀƽƓǦǀƾệǉ,ǦǂỗƾǦǉầǃƼǦǀƾếǂǦǀƽƓǦǉăǃƼǦǉƽươǃƼǦǉăǃƼǦǁƙǃǦ#Y8%#E,ǦƸộǃƼǦǤồǃǦđủǦƷƶǦǉầǃƼǦǉốƾǦđƶǦǉăǃƼǦ#Y24%#E.",
    ["天家的事情，咱们 these 贴身伺候的，要知道，又不能知道太多，小心驶得万年船——难啊！"] = "ƞƽǊǓệǃǦǥƽƾƙǃǦƼƾƶ,ǦƽạǃƼǦƽầǊǦƽạǦǉƽƁǃǦƸậǃǦǃƽưǦƸƽƕǃƼǦǉƶ,ǦǅƽảƾǦƷƾếǉ,ǦǂƐǦǁạƾǦǀƽƇǃƼǦđượƸǦƷƾếǉǦǆǊƑǦǃƽƾềǊ,ǦƸẩǃǦǉắƸǦǋƇǦưǊǦ——ǦǀƽƚǦǉƽƶǓ!",
    ["好不容易才选上宫女，虽说衣食无忧，可每日辛勤劳作，一点闲暇时光都没有，连父母一面都难以见到……我想出宫. "] = "ƱấǉǦǋảǦǁắǂǦǂớƾǦđượƸǦƸƽọǃǦǁƐǂǦƸǊǃƼǦǃữ,ǦǉǊǓǦǃƚƾǦƸơǂǦƑǄǦǀƽƇǃƼǦǁǄ,ǦǃƽưǃƼǦǃƼƐǓǦǃƼƐǓǦǁƐǂǦǁụǃƼǦƸựƸǦǃƽọƸ,ǦƸƽẳǃƼǦƸƚǦƸƽƕǉǦǉƽờƾǦƼƾƶǃǦǇảǃƽǦǇỗƾ,ǦđếǃǦǂặǉǦƸƽƶǦǂẹǦƸũǃƼǦǀƽƚǦƼặǅ...ǦǥƶǦǂǊốǃǦǍǊấǉǦƸǊǃƼ.",
    ["分享画作"] = "ƞƽƾƶǦǈẻǦƽọƶǦǉƑƸ",
    ["{}切换武器，长 áp {}召唤安西军协战释放重击蓄力技"] = "{}ǦƸƽǊǓểǃǦđổƾǦƷƾǃƽǦǀƽƓ,ǦấǃǦƼƾữǦ{}ǦǉǇƾệǊǦƽǄƑǃǦƜǃǦǥƁǓǦƬǊƁǃǦƽƾệǅǦƸƽƾếǃǦƼƾảƾǦǅƽƚǃƼǦƸƽƾƙǊǦǉụǦǁựƸǦǉǇọǃƼǦǀƓƸƽ",
    ["仁恕之举，亦 là 防患未然。此议甚好，当为定例，嘉奖。"] = "ƞửǦƸƽỉǦǃƽƁǃǦǉƽứ,ǦƸũǃƼǦǁƐǦǅƽƛǃƼǦƽọƶǦǉừǦǀƽƾǦƸƽưƶǦǍảǓǦǇƶ.ǦĐềǦǃƼƽịǦǃƐǓǦǇấǉǦǉốǉ,ǦǃƙǃǦǁậǅǦǁƐǂǦđịǃƽǦǁệ,ǦǀƽƺǃǦǉƽưởǃƼ.",
    ["#当巧鹊被点穴成功定住时，播放氛围对话"] = "#ǦƫƽƑǉǦđốƾǦǉƽǄạƾǦƷốƾǦƸảǃƽǦǀƽƾǦƳảǄǦǥƽướƸǦƷịǦđƾểǂǦƽǊǓệǉǦđịǃƽǦǉƽƁǃǦǉƽƐǃƽǦƸƇǃƼ",
    ["那边怎那许多人……！\n虏人逃嘞……虏人逃回去嘞……"] = "ƫƽƓƶǦǀƾƶǦǈƶǄǦđƇǃƼǦǃƼườƾǦǉƽếǦǀƾƶ...!Ǧ\nƦẻǦđịƸƽǦǉǇốǃǦǇồƾ...ǦǀẻǦđịƸƽǦǉǇốǃǦǋềǦǇồƾ...",
    ["耐力消耗增加10%"] = "ǥƾƙǊǦƽƶǄǦǉƽểǦǁựƸǦǉăǃƼǦ10%",
    ["大傩 in 即可，祝娥身体却已无力支撑，必须有一位足够特殊之人代她完成仪式，为百姓祈福。"] = "ĐạƾǦƩƶǦǈắǅǦǉớƾ,ǦǃƽưǃƼǦǉƽƁǃǦǉƽểǦƞƽƕƸǦƩƼƶǦđƃǦǀƽƇǃƼǦƸƛǃǦǈứƸǦƸƽốǃƼǦƸƽọƾ,ǦǅƽảƾǦƸƚǦǂộǉǦǃƼườƾǦđủǦđặƸǦƷƾệǉǦǉƽƶǓǦƷƐǦƽǄƐǃǦǉƽƐǃƽǦǃƼƽƾǦǁễ,ǦƸầǊǦǅƽƕƸǦƸƽǄǦƷƑƸƽǦǉƓǃƽ.",
    ["袖身花纹"] = "ƣǄƶǦǋăǃǦǉǇƙǃǦǉƶǓǦƑǄ",
    ["这还不明白？骂皇帝是个守财奴呗。"] = "ǥƽếǦǃƐǓǦǂƐǦƸƛǃǦǀƽƇǃƼǦƽƾểǊ?ǦƧƐǦđƶǃƼǦǂắǃƼǦƣǄƐǃƼǦđếǦǁƐǦǉƙǃǦƼƾữǦƸủƶǦđấǓ.",
    ["据说那常盈仓收纳租税的小吏被斩当日，围 quan 百姓无不拍手叫好啊！"] = "ƩƼƽƺǦǃƚƾǦǃƼƐǓǦǉƙǃǦǉƾểǊǦǁạƾǦǉƽǊǦǉƽǊếǦǀƽǄǦǥƽườǃƼǦǝǄƶǃƽǦƷịǦǉǇảǂ,ǦǉǇăǂǦƽọǦđứǃƼǦǍƺǂǦǀƽƇǃƼǦƶƾǦǁƐǦǀƽƇǃƼǦǋỗǦǉƶǓǦǋǊƾǦǂừǃƼ!",
    ["治学应以开源节流为本，着眼于本地水利，勿舍本逐末。"] = "ǥǇịǦƽạǃǦǃƙǃǦǁấǓǦǀƽƶƾǦǃƼǊồǃǦǉƾếǉǦǁưǊǦǁƐǂǦƼốƸ,ǦƸƽƕǦǉǇọǃƼǦǋƐǄǦǉƽủǓǦǁợƾǦƷảǃǦđịƶ,ǦƸƽớǦƷỏǦƼốƸǦǉƽƺǄǦǃƼọǃ.",
    ["宝慈宫本次秋招首度开启“笑招”，消息传出，各局宫人苦练讲笑话技术，若遇上正在讲笑话的宫人，不妨前去交谈，或可展开一段奇遇. "] = "ƝảǄǦǥừǦƞǊǃƼǦǁầǃǦƸƽƾƙǊǦǂộǦǂƖƶǦǉƽǊǦǃƐǓǦǁầǃǦđầǊǦǂởǦǇƶǦ\"ǥƾếǊǦƞƽƾƙǊ\"Ǧ(ƸƽƾƙǊǦǂộǦƷằǃƼǦǃụǦƸườƾ),ǦǉƾǃǦǉứƸǦǉǇǊǓềǃǦǇƶ,ǦƸǊǃƼǦǃƽƁǃǦƸƑƸǦƸụƸǦǀƽổǦǁǊǓệǃǦǀỹǦǉƽǊậǉǦǀểǦǉǇǊǓệǃǦƸườƾ,ǦǃếǊǦƷắǉǦƼặǅǦƸǊǃƼǦǃƽƁǃǦđƶǃƼǦǀểǦƸƽǊǓệǃ,ǦǃƼạƾǦƼƔǦǀƽƇǃƼǦǉớƾǦǉǇƛǦƸƽǊǓệǃ,ǦƸƚǦǁẽǦǈẽǦǂởǦǇƶǦǂộǉǦđǄạǃǦǀỳǦǃƼộ.",
    ["\"月娘吾妻：\n\n不知家中一切可好？爹的腿脚还疼吗，你的身子如何，霞儿可识字了？随军两年，只攒够了一封家书的钱粮，实我之过。\n不过去岁，我到赵德均赵将军麾下听用了。幸亏当年跟咱爹识了些字，又得军中兄弟们的帮衬，倒被提拔成个队正了，往后钱粮兴许能多些。赵将军手底下的兵都厉害得很，还有一队胡儿军，全是骑着银鞍大马的契丹人，为咱汉人打仗。我向他们学了些骑射功夫，等上战场，挣了军功，兴许就能回家看看了。\n\n这几年辛苦月娘和爹打点家中，粮饷我都攒着，就等着带回来给你。你平常仔细着身子，莫要替我担忧。\n\"\n\"<信纸有火燎过的痕迹，有些字迹难以辨认>\n\n绝笔信……至亲手中……\n\n皇帝降了……将军降了……辽国大将…………杀……降兵……银鞍契丹……悉数被诛……\n兄弟五人……当逃兵……身上粮饷……一分为五……与家书……送至家中……\n若身死……信……焚之……不……祸家人。\n\n诸兄弟籍贯、亲属如下\n囗石   栾囗囗囗 囗囗城布坊，囗囗氏，弟赵铁。囗弟照顾好家母。\n周富贵 清河囗囗 无亲眷。\n李囗行 滹沱囗囗 荻花洲囗囗囗，父李阿公、嘱妻囗囗再嫁。\n……\n斡特剌 幽州人氏 爹娘弟兄囗囗囗死，囗妻囗囗梨朵，有孕囗囗，囗莫向北走，勿要回头，切记切记。\"\n"] = "\"ƩƼǊǓệǉǦƩươǃƼǦƽƾềǃǦǉƽƙ:\n\nƦƽƇǃƼǦƷƾếǉǦǂọƾǦǋƾệƸǦởǦǃƽƐǦǋẫǃǦǉốǉǦƸƽứ?ǦƞƽƁǃǦƸủƶǦƸƽƶǦƸƛǃǦđƶǊǦǀƽƇǃƼ,ǦǉƽƁǃǦǉƽểǦǃƐǃƼǦǉƽếǦǃƐǄ,ǦƣƐǦƩƽƾǦđƃǦƷƾếǉǦƸƽữǦƸƽưƶ?ǦǥƛǃƼǦǆǊƁǃǦƽƶƾǦǃăǂ,ǦƸƽỉǦǤƐǃƽǦǤụǂǦđủǦǉƾềǃǦǁươǃƼǦƸƽǄǦǂộǉǦƷứƸǦǉƽưǦǃƽƐ,ǦǉƽậǉǦǁƐǦǁỗƾǦƸủƶǦǉƶ.\nƩƽưǃƼǦǃăǂǦǃƼǄƑƾ,ǦǉƶǦđƃǦđếǃǦǤướƾǦǉǇướǃƼǦǥǇƾệǊǦĐứƸǦƬǊƁǃǦǥǇƾệǊǦǉướǃƼǦǆǊƁǃǦǁƐǂǦǋƾệƸ.ǦƨƶǓǦǂắǃǦǃăǂǦǍưƶǦƸƚǦƽọƸǦƓǉǦƸƽữǦǋớƾǦƸƽƶ,ǦǁạƾǦđượƸǦƶǃƽǦƺǂǦǉǇǄǃƼǦǆǊƁǃǦƼƾƕǅǦđỡ,ǦǃƙǃǦđượƸǦđềǦƷạǉǦǁƐǂǦĐộƾǦƸƽƓǃƽ,ǦǈƶǊǦǃƐǓǦǉƾềǃǦǁươǃƼǦƸƚǦǁẽǦǈẽǦǀƽƑǦƽơǃ.ǦƝƾǃƽǦǁƓǃƽǦǤướƾǦǉƶǓǦǥǇƾệǊǦǉướǃƼǦǆǊƁǃǦđềǊǦǁợƾǦƽạƾǦǁắǂ,ǦƸƛǃǦƸƚǦǂộǉǦđộƾǦƣồǦƩƽƾǦǆǊƁǃ,ǦǉǄƐǃǦǁƐǦǃƼườƾǦƦƽƾếǉǦĐƶǃǦƸưỡƾǦǃƼựƶǦǓƙǃǦƷạƸ,ǦđƑǃƽǦǉǇậǃǦǋƔǦǃƼườƾǦƣƑǃǦǉƶ.ǦǥƶǦđƃǦƽọƸǦđượƸǦƓǉǦƸǊǃƼǦǉƽǊậǉǦƸưỡƾǦǃƼựƶǦǉừǦƽọ,ǦđợƾǦǀƽƾǦǇƶǦƸƽƾếǃǦǉǇườǃƼǦǁậǅǦđượƸǦǆǊƁǃǦƸƇǃƼ,ǦƸƚǦǁẽǦǈẽǦđượƸǦǋềǦǃƽƐǦǉƽăǂǦǂọƾǦǃƼườƾ.\n\nƨấǓǦǃăǂǦǃƶǓǦǋấǉǦǋảǦƩƼǊǓệǉǦƩươǃƼǦǋƐǦƸƽƶǦǆǊƑǃǦǍǊǓếǃǦǋƾệƸǦǃƽƐ,ǦǁươǃƼǦƷổǃƼǦǉƶǦđềǊǦƼǄǂǦƼƚǅ,ǦƸƽỉǦƸƽờǦǂƶǃƼǦǋềǦƸƽǄǦǃƐǃƼ.ǦƩƐǃƼǦǃƼƐǓǦǉƽườǃƼǦƽƃǓǦƼƾữǦƼƔǃǦǈứƸǦǀƽỏƺ,ǦƸƽớǦǁǄǦǁắǃƼǦƸƽǄǦǉƶ.\n\"\n\"<ƢƾấǓǦǋƾếǉǦǉƽưǦƸƚǦǤấǊǦǋếǉǦƷịǦǁửƶǦǈƗǂ,ǦǂộǉǦǈốǦƸƽữǦǀƽƚǦǃƽậǃǦǤạǃƼ>\n\nǥǊǓệǉǦƷƕǉǦǉƽư...ǦƼửƾǦǉậǃǦǉƶǓǦǃƼườƾǦǉƽƁǃ...\n\nƣǄƐǃƼǦđếǦƽƐǃƼǦǇồƾ...ǦǥướǃƼǦǆǊƁǃǦƽƐǃƼǦǇồƾ...ǦĐạƾǦǉướǃƼǦǃướƸǦƧƾƙǊ...ǦƼƾếǉ...ǦƽƐǃƼǦƷƾǃƽ...ǦƦƽƾếǉǦĐƶǃǦǓƙǃǦƷạƸ...ǦǉƽảǓǦđềǊǦƷịǦƼƾếǉ...\nƩăǂǦƶǃƽǦƺǂ...ǦǁƐǂǦđƐǄǦƷƾǃƽ...ǦǁươǃƼǦƷổǃƼǦǉǇƙǃǦǃƼườƾ...ǦƸƽƾƶǦǁƐǂǦǃăǂ...ǦƸƖǃƼǦǉƽưǦǃƽƐ...ǦƼửƾǦǋềǦǆǊƙ...\nƩếǊǦǉƽƁǃǦƸƽếǉ...Ǧǉƽư...ǦđốǉǦđƾ...ǦđừǃƼ...ǦƽọƶǦǁƁǓǦǃƼườƾǦǃƽƐ.\n\nƬǊƙǦǆǊƑǃ,ǦǉƽƁǃǦǆǊǓếǃǦƸủƶǦƸƑƸǦƽǊǓǃƽǦđệǦǃƽưǦǈƶǊ:\n...ǦǥƽạƸƽ,ǦƧǄƶǃ...,ǦǅƽườǃƼǦǋảƾǦǉƽƐǃƽ...,Ǧǉƽị...,ǦƺǂǦǁƐǦǥǇƾệǊǦǥƽƾếǉ.ǦƩƽờǦƺǂǦƸƽăǂǦǈƚƸǦǂẹǦƼƾƐ.\nƞƽǊǦƫƽƕǦƬǊƈ,ǦǥƽƶǃƽǦƣƐ...,ǦǀƽƇǃƼǦǃƼườƾǦǉƽƁǃ.\nƧƈ...ǦƣƐǃƽ,ǦƣƇǦĐƐ...,ǦĐịƸƽǦƣǄƶǦƞƽƁǊ...,ǦƸƽƶǦǁƐǦƧƈǦƜǦƞƇǃƼ,ǦǤặǃǦǋợ...ǦǉƑƾǦƼƾƑ.\n...\nƪƑǉǦĐặƸǦƧạǉ,ǦǃƼườƾǦǕǦƞƽƁǊ,ǦƸƽƶǦǂẹǦƶǃƽǦƺǂ...ǦđềǊǦƸƽếǉ,Ǧǋợ...ǦƧƙǦĐƚƶ,ǦƸƚǦǉƽƶƾ...,ǦđừǃƼǦđƾǦǋềǦƽướǃƼǦƷắƸ,ǦđừǃƼǦǃƼǄảǃƽǦđầǊǦǁạƾ,ǦǃƽớǦǀỹǦǃƽớǦǀỹ.\"\n",
    ["使用此物，可获得奇术“千斤坠”的外观特效——红梅安岁。"] = "ƮửǦǤụǃƼǦǋậǉǦǃƐǓ,ǦƸƚǦǉƽểǦǃƽậǃǦđượƸǦƽƾệǊǦứǃƼǦǃƼǄạƾǦǆǊƶǃǦƸủƶǦǀỳǦǉƽǊậǉǦ\"ǥƽƾƙǃǦƞƁǃǦƞƽƖǓ\"Ǧ——ǦƣồǃƼǦƨƶƾǦƜǃǦǥǊế.",
    ["小笼包\n开封小笼包又称灌汤包，源于东京的灌汤馒头，东京七十二家正店之一的“王楼”制售的名为“山洞梅花包子”，号称“东京第一”。不过这些都是写给文人和游客看的。真要吃小笼包，还是得去找家正儿八经的本地小摊先端碗小米汤，在低矮的小桌旁找个缝儿和大爷大妈大叔大嫂们挤一挤一起坐下，再去要一屉热气腾腾的小笼包来。小米汤要等凉一点顺着边儿吸溜着喝，不然太热了烫嘴，太凉了香味儿少了汤 cũng 凝固了。在等小米汤凉的间隙，就可以研究着吃小笼包了。和那些每一口滋味儿都一样，可以呼噜呼噜往嘴里倒的饭菜不同，小笼包可是早点摊中最精致的了。它里头的汤汁滚烫鲜香，若是一口咬的大了，少不得狠狠挨一记烫。咬的少了呢，又变成汤汁，肉馅，薄皮分开吃，那就没意思了。所以吃小笼包是个技术活儿，非得吃多了吃熟练了才吃的痛快。小米汤未必是街头公认最好的搭头，但汤喝的太咸便影响品尝包子的味道，豆腐脑又太轻薄，唯有小米汤近乎无味但又有香味，喝进口扎扎实实有颗粒感压着舌头，这样一口有实感的汤反而更能衬出小笼包的皮之薄，肉馅之香，汤汁之美。至于为什么不是大米汤……或是因为开封那条街上只有卖小米汤的。真有别的汤也可以配来试试，说不得有新发现。"] = "ǥƾểǊǦƧǊǃƼǦƝƶǄ\nǥƾểǊǦǁǊǃƼǦƷƶǄǦƦƽƶƾǦƫƽǄǃƼǦƸƛǃǦƼọƾǦǁƐǦƷƑǃƽǦƷƶǄǦǃướƸǦ(ǆǊƑǃǦǉƽƶǃƼǦƷƶǄ),ǦǃƼǊồǃǦƼốƸǦǉừǦƷƑǃƽǦǂƐǃǦǉƽầǊǦǃướƸǦởǦĐƇǃƼǦƦƾǃƽ.Ǧ\"ƱươǃƼǦƧầǊ\"Ǧ-ǦǂộǉǦǉǇǄǃƼǦƷảǓǦǂươƾǦƽƶƾǦǃƼƇƾǦƸƽƓǃƽǦđƾếǂǦởǦĐƇǃƼǦƦƾǃƽǦƸƽếǦƷƑǃǦǁǄạƾǦƼọƾǦǁƐǦ\"ƮơǃǦĐộǃƼǦƨƶƾǦƣǄƶǦƝƶǄǦǥử\",ǦǍưǃƼǦǉụǃƼǦǁƐǦ\"ĐƇǃƼǦƦƾǃƽǦđệǦǃƽấǉ\".ǦǥǊǓǦǃƽƾƙǃǦđƚǦƸƽỉǦǁƐǦǁờƾǦƽǄƶǦǂỹǦǤƐǃƽǦƸƽǄǦǋăǃǦǃƽƁǃǦǋƐǦǤǊǦǀƽƑƸƽ.ǦƨǊốǃǦăǃǦǉƾểǊǦǁǊǃƼǦƷƶǄǦđƕǃƼǦđƾệǊ,ǦǋẫǃǦǅƽảƾǦǉƔǂǦđếǃǦǂấǓǦǈạǅǦǃƽỏǦƷảǃǦđịƶǦƸƽƓǃƽǦǉƇǃƼ,ǦƷưǃƼǦǂộǉǦƷƑǉǦƸƽƑǄǦǀƙǦ(ǉƾểǊǦǂễǦǉƽƶǃƼ),ǦǁƺǃǦǋƐǄǦǂộǉǦǀẽǦƽởǦƼƾữƶǦƸƑƸǦƇǃƼǦƷƐǦƸƽƕǦƷƑƸǦǉǇƙǃǦƸƽƾếƸǦƷƐǃǦǉƽấǅǦǉƘǦǂƐǦǃƼồƾǦǍǊốǃƼ,ǦǇồƾǦƼọƾǦǂộǉǦǍửǦǉƾểǊǦǁǊǃƼǦƷƶǄǦǃƚǃƼǦƽổƾǦƷốƸǦƽơƾǦǃƼƽƾǦǃƼƕǉ.ǦƞƽƑǄǦǀƙǦǅƽảƾǦđợƾǦǃƼǊộƾǦƷớǉǦǂộǉǦƸƽƕǉǦǇồƾǦƽƕǅǦǤọƸǦǉƽƺǄǦǋƐǃƽǦƷƑǉ,ǦǃếǊǦǀƽƇǃƼǦǈẽǦƷỏǃƼǦǂƾệǃƼ,ǦǂƐǦǃƼǊộƾǦǆǊƑǦǉƽƔǦƽươǃƼǦǋịǦƼƾảǂǦǈƕǉ,ǦǃướƸǦƸƽƑǄǦƸũǃƼǦđƇǃƼǦǁạƾ.ǦǥǇǄǃƼǦǁƕƸǦđợƾǦƸƽƑǄǦǃƼǊộƾ,ǦƸƽƓǃƽǦǁƐǦǁƕƸǦǃƼƽƾƙǃǦƸứǊǦƸƑƸƽǦăǃǦǉƾểǊǦǁǊǃƼǦƷƶǄ.ǦƦƽƑƸǦǋớƾǦǃƽữǃƼǦǂƚǃǦƸơǂǦƸƶǃƽǦǂƾếǃƼǦǃƐǄǦǋịǦƸũǃƼǦǃƽưǦǃƽƶǊ,ǦƸƚǦǉƽểǦǁƖƶǦƐǄǦƐǄǦǋƐǄǦǂƾệǃƼ,ǦǉƾểǊǦǁǊǃƼǦƷƶǄǦƸƽƓǃƽǦǁƐǦǂƚǃǦǉƾǃƽǦǉếǦǃƽấǉǦǃơƾǦǈạǅǦđƾểǂǦǉƁǂ.ǦƩướƸǦǈƕǅǦƷƙǃǦǉǇǄǃƼǦǃƚǃƼǦƷỏǃƼǦǉươƾǦǃƼǄǃ,ǦǃếǊǦƸắǃǦǂƾếǃƼǦǆǊƑǦǉǄ,ǦǀƽƚǦǉǇƑǃƽǦǀƽỏƾǦƷịǦƷỏǃƼǦǂộǉǦǋốǦđƶǊǦđƾếǃƼ.ǦƞắǃǦƓǉǦǆǊƑǦǉƽƔǦǁạƾǦǉƽƐǃƽǦǇƶǦǃướƸǦǈƕǅ,ǦǃƽƁǃǦǉƽịǉ,ǦǋỏǦǂỏǃƼǦăǃǦǇƾƙǃƼǦǇẽ,ǦǉƽếǦǉƽƔǦƸƽẳǃƼǦƸƛǃǦƼƔǦǉƽƕǦǋị.ǦǥƽếǦǃƙǃǦăǃǦǉƾểǊǦǁǊǃƼǦƷƶǄǦǁƐǦǂộǉǦƸƑƾǦǃƼƽề,ǦǅƽảƾǦăǃǦǃƽƾềǊǦăǃǦǆǊƺǃǦǂớƾǦǉƽấǓǦǈướǃƼ.ǦƞƽƑǄǦǀƙǦƸƽưƶǦƸƽắƸǦđƃǦǁƐǦǂƚǃǦđƾǦǀƘǂǦđượƸǦƸƇǃƼǦǃƽậǃǦǉốǉǦǃƽấǉ,ǦǃƽưǃƼǦƸƶǃƽǦǂặǃǦǆǊƑǦǈẽǦƑǉǦǋịǦƷƑǃƽ,ǦđậǊǦƽũǦǃƽừǦǉƽƔǦǁạƾǦǆǊƑǦǃƽẹǦǃƽƐǃƼ,ǦƸƽỉǦƸƚǦƸƽƑǄǦǀƙǦƼầǃǦǃƽưǦǀƽƇǃƼǦǋịǦǂƐǦǁạƾǦƸƚǦƽươǃƼǦǉƽơǂ,ǦǊốǃƼǦǋƐǄǦǂƾệǃƼǦƸảǂǦǃƽậǃǦǇƅǦǉừǃƼǦƽạǉǦǃƗǃǦǁƙǃǦđầǊǦǁưỡƾ,ǦǂộǉǦǃƼụǂǦƸƶǃƽǦƸƚǦđộǦǉƽựƸǦǃƽưǦǋậǓǦǉǇƑƾǦǁạƾǦƸƐǃƼǦǉƇǃǦǁƙǃǦƸƑƾǦǂỏǃƼǦƸủƶǦǋỏǦƷƑǃƽ,ǦƸƑƾǦǉƽơǂǦƸủƶǦǃƽƁǃǦǉƽịǉ,ǦƸƑƾǦǂỹǦǋịǦƸủƶǦǃướƸǦǈƕǅ.ǦƞƛǃǦǉạƾǦǈƶǄǦǀƽƇǃƼǦǅƽảƾǦǁƐǦƸƽƑǄǦƼạǄǦ(đạƾǦǂễǦǉƽƶǃƼ)...ǦƸƚǦǁẽǦǋƔǦǅƽốǦƦƽƶƾǦƫƽǄǃƼǦƽồƾǦđƚǦƸƽỉǦƸƚǦƷƑǃǦƸƽƑǄǦǀƙǦǉƽƇƾ.ǦƩếǊǦƸƚǦǁǄạƾǦƸƶǃƽǦǀƽƑƸǦǅƽốƾǦƸƖǃƼǦƸũǃƼǦƸứǦǉƽửǦǍƺǂ,ǦƷƾếǉǦđƁǊǦǁạƾǦƸƚǦǅƽƑǉǦƽƾệǃǦǂớƾ.",
    ["他们……他们都知道，义父也知道……"] = "ƣọ...ǦƽọǦđềǊǦƷƾếǉ,ǦǃƼƽĩƶǦǅƽụǦƸũǃƼǦƷƾếǉ...",
    ["头如玛瑙，金翅红光，獠牙黑亮，鸣声如钟，斗口凶狠. "] = "ĐầǊǦǃƽưǦǂƃǦǃƃǄ,ǦƸƑǃƽǦǋƐǃƼǦƑǃƽǦđỏ,ǦǇăǃƼǦǃƶǃƽǦđƺǃǦƷƚǃƼ,ǦǉƾếǃƼǦƼƑǓǦǃƽưǦƸƽǊƇǃƼ,ǦđấǊǦǀƽẩǊǦƽǊǃƼǦƽƃǃ.",
    ["教化为治国之本，此议深得精髓，当列为要务速办. "] = "ƢƾƑǄǦƽƚƶǦǁƐǦƼốƸǦǇễǦƸủƶǦǉǇịǦǆǊốƸ,ǦđềǦǃƼƽịǦǃƐǓǦǃắǂǦđượƸǦǉƾǃƽǦǉƕǓ,ǦǃƙǃǦǁƾệǉǦǋƐǄǦǋƾệƸǦǉǇọǃƼǦǓếǊǦƸầǃǦǁƐǂǦǃƼƶǓ.",
    ["是啊，从此天下人都可以里外走动. 可他们失去的声音和年岁却……这其中的亏欠，太多。"] = "ĐƕǃƼǦǋậǓ,ǦǉừǦǃƶǓǦǃƼườƾǦǉǇǄǃƼǦǉƽƾƙǃǦƽạǦđềǊǦƸƚǦǉƽểǦǉựǦǤǄǦđƾǦǁạƾ.ǦƩƽưǃƼǦǉƾếǃƼǦǃƚƾǦǋƐǦǃăǂǦǉƽƑǃƼǦƽọǦđƃǦǂấǉǦđƾǦǉƽƔ...ǦǃợǦǃầǃǦǉǇǄǃƼǦđƚ,ǦǆǊƑǦǃƽƾềǊ.",
    ["此曲倒颇为轻快"] = "ƦƽƕƸǦǃƽạƸǦǃƐǓǦǃƼƽƺǦƸũǃƼǦǀƽƑǦǃƽẹǦǃƽƐǃƼ",
    ["将军慎言，慎言……"] = "ǥướǃƼǦǆǊƁǃǦƸẩǃǦǉǇọǃƼǦǁờƾǦǃƚƾ,ǦƸẩǃǦǉǇọǃƼ...",
    ["我现在要装作和你不熟的样子，来吧. "] = "ƢƾờǦǉƶǦǅƽảƾǦƼƾảǦǋờǦǃƽưǦǀƽƇǃƼǦǆǊƺǃǦƷƾếǉǦǃƼươƾ,ǦǉớƾǦđƾ.",
    ["本为一根枯竹，经特殊技艺鞣制烤炼，变作一根十分坚硬的枯竹。昔日有人曾以此为枪，行侠仗义. "] = "ƱốǃǦǁƐǦǂộǉǦƸƐǃƽǦǉǇƕƸǦǀƽƇ,ǦǆǊƶǦǀỹǦǉƽǊậǉǦǉƽǊộƸǦǤƶǦǋƐǦǃǊǃƼǦǁǊǓệǃǦđặƸǦƷƾệǉ,ǦǉǇởǦǉƽƐǃƽǦǂộǉǦƸƐǃƽǦǉǇƕƸǦǋƇǦƸƖǃƼǦƸứǃƼǦƸƑǅ.ǦƳưƶǦǀƾƶǦǉừǃƼǦƸƚǦǃƼườƾǦǤƖǃƼǦǃƚǦǁƐǂǦǉƽươǃƼ,ǦƽƐǃƽǦƽƾệǅǦǉǇượǃƼǦǃƼƽĩƶ.",
    ["如今时局未稳，军心安定是头等大事，不宜多生事端. "] = "ƩƶǓǦǉƽờƾǦƸụƸǦƸƽưƶǦổǃ,ǦổǃǦđịǃƽǦǆǊƁǃǦǉƁǂǦǁƐǦđạƾǦǈựǦƽƐǃƼǦđầǊ,ǦǀƽƇǃƼǦǃƙǃǦƼƁǓǦǉƽƙǂǦƸƽǊǓệǃ.",
    ["因此在得知大人母亲病重后，他便掏光家底翻来了 these 药材，想要尽一份力。"] = "ƱƔǦǉƽếǦǈƶǊǦǀƽƾǦƷƾếǉǦǂẫǊǦǉƽƁǃǦƸủƶǦđạƾǦǃƽƁǃǦǁƁǂǦǉǇọǃƼǦƷệǃƽ,ǦƽắǃǦđƃǦǤốƸǦƽếǉǦƼƾƶǦǉƐƾǦǉƔǂǦđượƸǦǃƽữǃƼǦǤượƸǦǁƾệǊǦǃƐǓ,ǦǂǊốǃǦƼƚǅǦǂộǉǦǅƽầǃǦǈứƸǦǁựƸ.",
    ["魏三郎的护膝失而复得，又得了一对新护腕。原来他今日沮丧的根源在于旁人的误解和自己内心的担忧，他怕自己拳脚无处施展。思量过后，他决定先去和许卫山解开误会，再去训练. "] = "ƝọƸǦƼốƾǦƸủƶǦƩƼụǓǦǥƶǂǦƧƶǃƼǦǂấǉǦǂƐǦǉƔǂǦǁạƾǦđượƸ,ǦǁạƾǦƸƚǦǉƽƙǂǦǂộǉǦđƇƾǦƷảǄǦǋệǦƸổǦǉƶǓǦǂớƾ.ǦƣƚƶǦǇƶǦǃƼǊồǃǦƸơǃǦǅƽƾềǃǦǂǊộǃǦƽƇǂǦǃƶǓǦƸủƶǦƽắǃǦǁƐǦǤǄǦǃƼườƾǦǀƽƑƸǦƽƾểǊǦǁầǂǦǋƐǦǃỗƾǦǁǄǦǁắǃƼǦǉǇǄǃƼǦǁƛǃƼ,ǦƽắǃǦǈợǦƷảǃǦǁĩǃƽǦƸủƶǦǂƔǃƽǦǀƽƇǃƼǦƸƚǦƸƽỗǦǉƽƾǦǉǇƾểǃ.ǦƮƶǊǦǀƽƾǦǈǊǓǦǉƓǃƽ,ǦƽắǃǦǆǊǓếǉǦđịǃƽǦđƾǦƼƾảƾǦǉỏƶǦƽƾểǊǦǁầǂǦǋớƾǦƣứƶǦƱệǦƮơǃǦǉǇướƸ,ǦǇồƾǦǂớƾǦđƾǦǁǊǓệǃǦǉậǅ.",
    ["#Y轻击蓄力#E浮名无寄，在短暂蓄力后向前挥出一道旋风，造成中量伤害的同时，命中人型目标时使其陷入短暂#J浮空#E状态命中非玩家目标时使其附加#J滞骨#E标记。"] = "#YǦƦƽƾǃƽǦǀƓƸƽǦǉụǦǁựƸǦ#EǦƫƽƖǦǝƶǃƽǦƱƇǦƦƈ,ǦǈƶǊǦǀƽƾǦǉụǦǁựƸǦǃƼắǃǦǈẽǦǋǊǃƼǦǇƶǦǂộǉǦǁǊồǃƼǦǁốƸǦǍǄƑǓǦǋềǦǅƽƓƶǦǉǇướƸ,ǦƼƁǓǦǈƑǉǦǉƽươǃƼǦǉǇǊǃƼǦƷƔǃƽ,ǦđồǃƼǦǉƽờƾǦǀƽƾǦǉǇƕǃƼǦǂụƸǦǉƾƙǊǦǤạǃƼǦǃƼườƾǦǈẽǦǀƽƾếǃǦƸƽƕǃƼǦǇơƾǦǋƐǄǦǉǇạǃƼǦǉƽƑƾǦ#JǦƫƽƖǦǀƽƇǃƼǦ#EǦǃƼắǃǦǃƼủƾ,ǦǉǇƕǃƼǦǂụƸǦǉƾƙǊǦǀƽƇǃƼǦǅƽảƾǦǃƼườƾǦƸƽơƾǦǈẽǦđƓǃƽǦǀƘǂǦǤấǊǦấǃǦ#JǦǥǇệǦƞốǉǦ#E.",
    ["\n\n用河中贝壳做的粗糙风铃。\n挂在屋檐上的时候，风一吹，仿佛能听到歌声 và cười tiếng.\n小小的壳，小小的人。\n小小的铃铛，叮铃叮铃。\n小小的我，小小的你。\n小小的我们，唱着歌儿。\n"] = "\n\nƞƽǊƇǃƼǦƼƾƚǦǉƽƇǦǈơǦǁƐǂǦǉừǦǋỏǦǈƛǦǤướƾǦǈƇǃƼ.\nƦƽƾǦǉǇƺǄǦǉǇƙǃǦƽƾƙǃǦǃƽƐ,ǦƼƾƚǦǉƽổƾǦǆǊƶ,ǦǤườǃƼǦǃƽưǦƸƚǦǉƽểǦǃƼƽƺǦǉƽấǓǦǉƾếǃƼǦƽƑǉǦǋƐǦǉƾếǃƼǦƸườƾ.\nƱỏǦǈƛǦǃƽỏǦǃƽỏ,ǦƸǄǃǦǃƼườƾǦǃƽỏǦǃƽỏ.\nƞƽƾếƸǦƸƽǊƇǃƼǦǃƽỏǦǃƽỏ,ǦđƾǃƽǦǁƾǃƽǦđƾǃƽǦǁƾǃƽ.\nǥƶǦǃƽỏǦǃƽỏ,ǦǃƼươƾǦǃƽỏǦǃƽỏ.\nƞƽƕǃƼǦǉƶǦǃƽỏǦǃƽỏ,ǦƸƖǃƼǦƽƑǉǦƸƁǊǦƸƶ.\n",
    ["重返将军祠，想起昔日常与江叔在此祭拜. 今日，也来敬一炷香吧。"] = "ǥǇởǦǁạƾǦǥừǦđườǃƼǦǥướǃƼǦǆǊƁǃ,ǦǃƽớǦǁạƾǦǃƼƐǓǦǍưƶǦǉƽườǃƼǦƸƖǃƼǦƢƾƶǃƼǦǉƽƕƸǦǉếǦƷƑƾǦǃơƾǦđƁǓ.ǦƣƇǂǦǃƶǓ,ǦƸũǃƼǦđếǃǦǤƁǃƼǦǂộǉǦǃƗǃǦƽươǃƼǦǋậǓ.",
    ["好。那 we cùng đợi. Nói đến điểu huynh chạy suốt quãng đường đến đây, có lẽ Tư Nam... ừm? (cảnh giác ngoái đầu)"] = "ĐượƸ.ǦƱậǓǦƸƽƕǃƼǦǉƶǦƸƖǃƼǦđợƾ.ǦƩƽắƸǦǂớƾǦǃƽớ,ǦđƾểǊǦƽǊǓǃƽǦƸƽạǓǦǈǊốǉǦǆǊƃǃƼǦđườǃƼǦđếǃǦđƁǓ,ǦƸƚǦǁẽǦǥưǦƩƶǂ...Ǧƽửǂ?Ǧ(ƞảǃƽǦƼƾƑƸǦǆǊƶǓǦđầǊǦǁạƾ)",
    ["侠奥会2.0-精英怪-巨鼠"] = "ƣƾệǅǦÁǄǦƣộƾǦ2.0Ǧ-ǦƬǊƑƾǦǉƾǃƽǦƶǃƽǦ-ǦƞƽǊộǉǦǀƽổǃƼǦǁồ",
    ["殷殷其雷……明月……原来是这个明月。"] = "ƀǃǦƁǃǦǀỳǦǁƇƾ...ǦǂƾǃƽǦǃƼǊǓệǉ...ǦǉƽƔǦǇƶǦǁƐǦǋầǃƼǦǂƾǃƽǦǃƼǊǓệǉǦǃƐǓ.",
    ["仇人为马屏山留下的物件之一。马屏山以为这是复仇的指引，但当 he 听闻封龙书院的消息，只觉此物是侮辱，怒而刮去其上字样。"] = "ƨộǉǦǉǇǄǃƼǦǃƽữǃƼǦǋậǉǦǤụǃƼǦǀẻǦǉƽƖǦđểǦǁạƾǦƸƽǄǦƨƃǦƝƔǃƽǦƮơǃ.ǦƨƃǦƝƔǃƽǦƮơǃǦǉưởǃƼǦǇằǃƼǦđƁǓǦǁƐǦƸƽỉǦǤẫǃǦƷƑǄǦǉƽƖ,ǦǃƽưǃƼǦǀƽƾǦƽắǃǦǃƼƽƺǦǉƾǃǦǋềǦƫƽǄǃƼǦƧǄǃƼǦǥƽưǦƱƾệǃ,ǦƸƽỉǦǉƽấǓǦǋậǉǦǃƐǓǦǁƐǦǂộǉǦǈựǦǈỉǦǃƽụƸ,ǦǉứƸǦƼƾậǃǦƸạǄǦǈạƸƽǦƸƽữǦǋƾếǉǦǉǇƙǃǦđƚ.",
    ["游侠如晤：\n\n家业诸事可还顺遂？久未通音讯，心中甚为牵挂。\n\n江湖风物虽好，然孤身行路，总不免念及故园灯火。想起已多时未曾修书予你，恐君忧心，故提笔作此寒暄。\n\n近日在聆杏村倒遇见一桩巧事——石某此番途径聆杏村，竟偶遇一同名同姓之人，此人亦是天泉弟子，亦结识一位操持家业的游侠，探问下才知，那位游侠名唤$C$L#Y$PN#E$C，同游侠你竟也十分相似，亦是一名心系苍生、不惧险阻的我辈同道。\n\n天下虽大，这般巧合却也难得，想来也唯有”缘分“二字才可解释。\n\n相谈之际，吾见那位石惊天似有挂心之事，原来是其友为探秘寻宝，平日时常攀岩涉险，衣衫多有刮蹭，归家时难免一身破缕，形容狼狈. 他本想亲自去开封羽衣楼讨教缝补手艺，却总被杂务耽搁。\n\n既是同门，这点小事何须纠结？索性替其跑一趟羽衣楼，向绣娘讨教些许缝补之法。若有所得，他日说不定也可为游侠分忧一二。\n\n此事需费些时日，归期若晚，望君勿要为我担忧。\n\n石惊天"] = "ƢửƾǦǤǊǦƽƾệǅ:\n\nƢƾƶǦǃƼƽƾệǅǦǂọƾǦǈựǦǋẫǃǦǉƽǊậǃǦǁợƾǦƸƽứ?ǦĐƃǦǁƁǊǦǀƽƇǃƼǦƸƚǦǉƾǃǦǉứƸ,ǦǉǇǄǃƼǦǁƛǃƼǦǇấǉǦǂựƸǦƸảǂǦǀƽƑƾ.\n\nƫƽǄǃƼǦǋậǉǦƼƾƶǃƼǦƽồǦǉǊǓǦđẹǅ,ǦǃƽưǃƼǦđộƸǦƽƐǃƽǦǂộǉǦǂƔǃƽ,ǦǀƽƚǦǉǇƑǃƽǦǀƽỏƾǦǃƽớǦǉớƾǦƑǃƽǦđƘǃǦǆǊƙǦƸũ.ǦƩƼƽĩǦǁạƾǦđƃǦǁƁǊǦƸƽưƶǦƼửƾǦǉƽưǦƸƽǄǦǃƼườƾ,ǦƺǦǇằǃƼǦǆǊƁǃǦǈẽǦǁǄǦǁắǃƼ,ǦǃƙǃǦƽạǦƷƕǉǦǋƾếǉǦǋƐƾǦǁờƾǦƽƐǃǦƽǊǓƙǃ.\n\nƢầǃǦđƁǓǦǉạƾǦǥƽƓǃƽǦƣạǃƽǦǥƽƇǃǦƼặǅǦǅƽảƾǦǂộǉǦƸƽǊǓệǃǦǉǇƖǃƼǦƽợǅǦ——ǦǥƽạƸƽǦǂỗǦǁầǃǦǃƐǓǦđƾǦǃƼƶǃƼǦǥƽƓǃƽǦƣạǃƽǦǥƽƇǃ,ǦǁạƾǦǉƔǃƽǦƸờǦƼặǅǦǂộǉǦǀẻǦǉǇƖǃƼǦǉƙǃǦǉǇƖǃƼǦƽọ,ǦǃƼườƾǦǃƐǓǦƸũǃƼǦǁƐǦđệǦǉửǦǥƽƾƙǃǦǥǊǓềǃ,ǦƸũǃƼǦǀếǉǦƼƾƶǄǦǋớƾǦǂộǉǦǤǊǦƽƾệǅǦǆǊƑǃǦǍǊǓếǃǦƼƾƶǦǃƼƽƾệǅ,ǦƽỏƾǦǇƶǦǂớƾǦƷƾếǉ,ǦǋịǦǤǊǦƽƾệǅǦđƚǦǉƙǃǦƼọƾǦ$ƞ$Ƨ#Y$PƩ#E$ƞ,ǦǈǄǦǋớƾǦǤǊǦƽƾệǅǦǃƼườƾǦǉƽậǉǦǈựǦǇấǉǦƼƾốǃƼǦǃƽƶǊ,ǦƸũǃƼǦǁƐǦǂộǉǦđồǃƼǦđạǄǦǉƁǂǦƽǊǓếǉǦǋớƾǦƸƽƕǃƼǦǈƾǃƽ,ǦǀƽƇǃƼǦǃƼạƾǦƽƾểǂǦǃƼǊǓ.\n\nǥƽƾƙǃǦƽạǦǉǊǓǦǁớǃ,ǦǃƽưǃƼǦǈựǦǉǇƖǃƼǦƽợǅǦǃƐǓǦǉƽậǉǦǀƽƚǦƼặǅ,ǦǃƼẫǂǦǁạƾǦƸũǃƼǦƸƽỉǦƸƚǦƽƶƾǦƸƽữǦ\"ǤǊǓƙǃǦǅƽậǃ\"ǦǂớƾǦƸƚǦǉƽểǦƼƾảƾǦǉƽƓƸƽ.\n\nƧƕƸǦđƐǂǦđạǄ,ǦǉƶǦǉƽấǓǦǥƽạƸƽǦƦƾǃƽǦǥƽƾƙǃǦǀƾƶǦǤườǃƼǦǃƽưǦƸƚǦǉƁǂǦǈự,ǦƽƚƶǦǇƶǦǁƐǦƷằǃƼǦƽữǊǦƸủƶǦƽắǃǦǋƔǦǉƽƑǂǦƽƾểǂǦǉầǂǦƷảǄ,ǦǃƼƐǓǦǉƽườǃƼǦǉƽườǃƼǦǍǊǓƙǃǦǁƺǄǦǉǇƘǄǦǂạǄǦƽƾểǂ,ǦǓǦǅƽụƸǦǇƑƸƽǦǇướƾǦǃƽƾềǊǦƸƽỗ,ǦǁƕƸǦǋềǦǃƽƐǦǀƽƚǦǉǇƑǃƽǦǀƽỏƾǦǉƽƁǃǦƽƔǃƽǦǃƽếƸƽǦǃƽƑƸ.ǦƣắǃǦǋốǃǦđịǃƽǦđƓƸƽǦǉƽƁǃǦđếǃǦƱũǦƴǦƧầǊǦởǦƦƽƶƾǦƫƽǄǃƼǦǉƽỉǃƽǦƼƾƑǄǦǉƶǓǦǃƼƽềǦǀƽƁǊǦǋƑ,ǦǃƽưǃƼǦƸứǦƷịǦǉạǅǦǋụǦǁƐǂǦǉǇƔǦƽǄƃǃ.\n\nĐƃǦǁƐǦđồǃƼǦǂƇǃ,ǦƸƽƕǉǦƸƽǊǓệǃǦǃƽỏǦǃƐǓǦƽƐǦǉấǉǦǅƽảƾǦđắǃǦđǄ?ǦƮẵǃǦǉƾệǃǦǉƽƶǓǦƽắǃǦƸƽạǓǦǂộǉǦƸƽǊǓếǃǦǉớƾǦƱũǦƴǦƧầǊ,ǦƽướǃƼǦǉƕǦǃươǃƼǦǉƽỉǃƽǦƼƾƑǄǦǋƐƾǦǅƽươǃƼǦǅƽƑǅǦǀƽƁǊǦǋƑ.ǦƩếǊǦƸƚǦǉƽǊǦƽǄạƸƽ,ǦǃƼƐǓǦǈƶǊǦƷƾếǉǦđƁǊǦƸũǃƼǦƸƚǦǉƽểǦƸƽƾƶǦǈẻǦưǊǦǅƽƾềǃǦǋớƾǦǤǊǦƽƾệǅǦđƇƾǦǅƽầǃ.\n\nƞƽǊǓệǃǦǃƐǓǦƸầǃǦǉốǃǦƸƽƕǉǦǉƽờƾǦƼƾƶǃ,ǦǃếǊǦǋềǦǂǊộǃ,ǦǂǄǃƼǦǃƼườƾǦƸƽớǦǋƔǦǉƶǦǂƐǦǁǄǦǁắǃƼ.\n\nǥƽạƸƽǦƦƾǃƽǦǥƽƾƙǃ",
    ["你等着！待我唤来禁军的大队人 mả, 定叫你插翅难飞！"] = "ƩƼươƾǦđợƾǦđƚ!ǦĐợƾǦǉƶǦƼọƾǦđạƾǦǆǊƁǃǦƞấǂǦƬǊƁǃǦđếǃ,ǦǃƽấǉǦđịǃƽǦǈẽǦǀƽƾếǃǦǃƼươƾǦƸƽắǅǦƸƑǃƽǦǀƽƚǦƷƶǓ!",
    ["长按{}蓄力重击下砸并召唤安西军协战"] = "ƩƽấǃǦƼƾữǦ{}ǦǉƓƸƽǦǁựƸǦǉǇọǃƼǦǀƓƸƽǦđậǅǦǍǊốǃƼǦđồǃƼǦǉƽờƾǦǉǇƾệǊǦƽǄƑǃǦƜǃǦǥƁǓǦƬǊƁǃǦƽƾệǅǦƸƽƾếǃ",
    ["让将军觉得自己被亏待，让士兵觉得朝廷要害他们，让百姓觉得皇帝贪财……"] = "ƦƽƾếǃǦǉướǃƼǦǆǊƁǃǦƸảǂǦǉƽấǓǦǂƔǃƽǦƷịǦƷạƸǦđƃƾ,ǦǀƽƾếǃǦƷƾǃƽǦǈĩǦǉƽấǓǦǉǇƾềǊǦđƔǃƽǦǂǊốǃǦƽạƾǦƽọ,ǦǀƽƾếǃǦƷƑƸƽǦǉƓǃƽǦǉƽấǓǦƽǄƐǃƼǦđếǦǉƽƶǂǦǉƾềǃ...",
    ["在试剑中击败#Y打更人#E，Check并累计领取#Y8#E份奖励。"] = "ǥạƾǦǥƽƓǦƦƾếǂǦđƑǃƽǦƷạƾǦ#YǦĐảǦƞƶǃƽǦƩƽƁǃǦ#E,ǦǋƐǦǉƓƸƽǦǁũǓǦǃƽậǃǦ#Y8#EǦǅƽầǃǦǉƽưởǃƼ.",
    ["点击#H「移动」#E模式"] = "ƩƽấǅǦƸƽếǦđộǦ#H[ǝƾǦƸƽǊǓểǃ]#E",
    ["已完成教学，是否确定继续练习？"] = "ĐƃǦƽǄƐǃǦǉƽƐǃƽǦǤạǓǦƽọƸ,ǦƸƚǦǍƑƸǦǃƽậǃǦǉƾếǅǦǉụƸǦǁǊǓệǃǦǉậǅǦǀƽƇǃƼ?",
    ["都说青溪有“一命一价” của 规矩，大夫，这诊金，我……"] = "ĐềǊǦǃƚƾǦǥƽƶǃƽǦƦƽƙǦƸƚǦǆǊǓǦƸủǦ\"ǃƽấǉǦǂệǃƽǦǃƽấǉǦƼƾƑ\",ǦđạƾǦǅƽǊ,ǦǅƽƓǦǀƽƑǂǦǃƐǓ,Ǧǉƶ...",
    ["“那个孟宽，为啥来中渡桥？”\n“谁知道。听说，是欠了人钱？”\n“欠钱？我怎么听说，是欠的人情？”\n\n什么钱啊情啊的，狗屁。\n孟宽听着这些嚼舌根子的话，掏了掏耳朵，拧开了酒囊。\n这酒囊，还是他从傅千里那儿摸来的。这样式的酒囊，只在太白山一带有，里头装的都是一等一的烧刀子烈酒。\n他仰头，闷了一大口酒。\n……\n“啧，北方的酒吧，闻着就够味儿。”\n“兄弟识货！听你口音，像是从南边来的？”\n风雪夜，破庙里，两人原先各自沉默着擦刀，靠这酒香热了场子。\n\n孟宽是来送信的。这些年 he 屡次混进行伍,又屡次改名换姓，只为寻到当年的战友亲眷，将信和粮饷送到这些人手里。\n这最后一封，在契丹的狼河附近。\n他来的时候便抱着回不去的心了,却不想在这大雪天的荒郊野岭,遇上了个与他一样使刀的侠客。\n两人先抢了刀，再抢了马，一路杀，一路逃。\n等终于甩掉了追兵，在这破庙里歇下时，竟还都不知对方名姓。\n但江湖规矩，若是一起杀过敌，又一起喝过酒，便能算兄弟了。\n\n对面那人哈哈一笑，说自己姓王，单名一个清字。说完便将喝过的酒囊抛了过来。\n孟宽早就被那酒香勾得口干，如牛饮水，猛灌三口。让对面的王清着实有些心疼。\n不是心疼人，是心疼酒。\n喝人的嘴短，孟宽见状只好擦了擦嘴。\n“在下孟宽，从……滹沱来的。这些年也喝了不少地方的酒，但你这酒……闻着劲，喝着辣，回甘清，倒尝不出是哪的。”\n“哈哈！这可是用太白山最高峰上的雪酿的酒，寻常哪喝得到！不过，我离家的时候，偷偷带下山了这个数。”\n王清比了个数。\n孟宽哂道：“三坛？那哪够喝，一晚上就喝光了。”\n王清摇摇头，还是比划这个数。\n孟宽：“三十？”\n王清笑道：“三百坛！”\n孟宽哈哈大笑，拍着手说兄弟真是个妙人。\n\n两人便在这破庙里，就着半囊好酒，天南地北聊了一宿。\n\n天刚亮的时候，酒喝完了，柴也灭了。两人出门上马，一个要往南，一个要往北。\n\n“在下王清，就此别过。保重！”\n“在下孟宽，就此别过。保重。”\n\n告完别，孟宽打马欲走，却听得后头传来一句：\n\n“孟宽兄，下次相见，望你以真名相告——驾！”\n\n孟宽扭头，只见那人策马而去的背影，消失在漫天风雪之中。\n\n他咂摸了下嘴，似是回味那酒，又似是不知要说什么。\n“娘的，倒欠了你一个名字。”\n\n……\n\n滹沱，镇戍仓，几颗火星子被风吹溅开。\n孟宽仰头，又闷了一大口酒。"] = "\"ƨạǃƽǦƦƽǄƶǃǦǀƾƶǦǉạƾǦǈƶǄǦǁạƾǦđếǃǦǥǇǊǃƼǦĐộǦƦƾềǊ?\"\n\"ƜƾǦƷƾếǉǦđượƸ.ǦƩƼƽƺǦǃƚƾǦǁƐǦǃợǦǉƾềǃǦǃƼườƾǦǉƶ?\"\n\"ƩợǦǉƾềǃ?ǦƮƶǄǦǉƶǦǁạƾǦǃƼƽƺǦǃƚƾǦǁƐǦǃợǦƁǃǦǉƔǃƽ?\"\n\nǥƾềǃǦǋớƾǦƸƽảǦǉƔǃƽǦƸƑƾǦƼƔ,ǦǉǄƐǃǦǁờƾǦǇƑƸǦǇưởƾ.\nƨạǃƽǦƦƽǄƶǃǦǃƼƽƺǦǃƽữǃƼǦǁờƾǦƷƐǃǦǉƑǃǦǍƇǃǦǍƶǄǦđƚ,ǦǃƼǄƑǓǦǃƼǄƑǓǦǁỗǦǉƶƾ,ǦǋặǃǦǂởǦǉƕƾǦǇượǊ.\nǥƕƾǦǇượǊǦǃƐǓǦǁƐǦƽắǃǦǉƽƚǦđượƸǦǉừǦƸƽỗǦƫƽƚǦǥƽƾƙǃǦƧƈ.ǦƦƾểǊǦǉƕƾǦǇượǊǦǃƐǓǦƸƽỉǦǋƖǃƼǦǃƕƾǦǥƽƑƾǦƝạƸƽǦǂớƾǦƸƚ,ǦƷƙǃǦǉǇǄǃƼǦǉǄƐǃǦǁƐǦǇượǊǦǥƽƾƙǊǦĐƶǄǦǥửǦƽạǃƼǦǃƽấǉǦƽạǃƼǦǃặǃƼ.\nƣắǃǦǃƼửƶǦđầǊ,ǦǃốƸǦǂộǉǦǃƼụǂǦǇượǊǦǁớǃ.\n……\n\"ƞƽậƸ,ǦǇượǊǦǅƽươǃƼǦƝắƸǦđƕǃƼǦǁƐǦǃƼửƾǦǉƽƇƾǦđƃǦǉƽấǓǦđủǦǋịǦǇồƾ.\"\n\"ƣǊǓǃƽǦđệǦƷƾếǉǦǍƺǂǦƽƐǃƼǦđấǓ!ǦƩƼƽƺǦƼƾọǃƼǦǃƼươƾ,ǦƽƔǃƽǦǃƽưǦǁƐǦǉừǦǅƽươǃƼǦƩƶǂǦǉớƾ?\"\nĐƙǂǦƼƾƚǦǉǊǓếǉ,ǦǉǇǄǃƼǦǃƼƇƾǦǂƾếǊǦđổǦǃƑǉ,ǦƽƶƾǦǃƼườƾǦǋốǃǦǤĩǦǂỗƾǦǃƼườƾǦǂộǉǦƼƚƸǦƾǂǦǁặǃƼǦǁƶǊǦđƶǄ,ǦǃƽờǦƽươǃƼǦǇượǊǦǃƐǓǦǂƐǦǁƐǂǦǀƽƇǃƼǦǀƽƓǦǃƚǃƼǦǁƙǃ.\n\nƨạǃƽǦƦƽǄƶǃǦđếǃǦđểǦđưƶǦǉƽư.ǦƩƽữǃƼǦǃăǂǦǃƐǓǦƽắǃǦǃƽƾềǊǦǁầǃǦǉǇƐǦǉǇộǃǦǋƐǄǦǆǊƁǃǦǃƼũ,ǦǁạƾǦǃƽƾềǊǦǁầǃǦǉƽƶǓǦǉƙǃǦđổƾǦƽọ,ǦƸƽỉǦđểǦǉƔǂǦƸƽǄǦđượƸǦǉƽƁǃǦǆǊǓếǃǦƸủƶǦđồǃƼǦđộƾǦǃăǂǦǍưƶ,ǦǉǇƶǄǦǉậǃǦǉƶǓǦƽọǦǉƽưǦǉừǦǋƐǦǁươǃƼǦƽướǃƼ.\nƝứƸǦǉƽưǦƸǊốƾǦƸƖǃƼǦǃƐǓǦǁƐǦởǦƼầǃǦƧƶǃƼǦƣƐǦƸủƶǦƦƽƾếǉǦĐƶǃ.\nƣắǃǦǁƕƸǦđếǃǦđƃǦƇǂǦǉƁǂǦǃƾệǂǦǀƽƇǃƼǦǉƽểǦǉǇởǦǋề,ǦǀƽƇǃƼǦǃƼờǦƼƾữƶǦƸƽốǃǦƽǄƶǃƼǦǋǊǦƽẻǄǦǁƑǃƽǦǃƼƐǓǦǉǊǓếǉǦǁớǃǦǉƽếǦǃƐǓǦǁạƾǦƼặǅǦđượƸǦǂộǉǦǋịǦƽƾệǅǦǀƽƑƸƽǦƸũǃƼǦǤƖǃƼǦđƶǄǦǃƽưǦǂƔǃƽ.\nƣƶƾǦǃƼườƾǦǉƾƙǃǦƽạǦǉƽủǦǋƾǦƸườǃƼǦƸướǅǦđƶǄ,ǦǇồƾǦƸướǅǦǃƼựƶ,ǦǂộǉǦđườǃƼǦƼƾếǉ,ǦǂộǉǦđườǃƼǦƸƽạǓ.\nĐợƾǦđếǃǦǀƽƾǦǇốǉǦƸǊộƸǦƸắǉǦđǊƇƾǦđượƸǦǉǇǊǓǦƷƾǃƽ,ǦǃƼƽỉǦƸƽƁǃǦǉǇǄǃƼǦǃƼƇƾǦǂƾếǊǦǇƑƸƽǦǃƐǓ,ǦđếǃǦƸảǦǉƙǃǦƽọǦđốƾǦǅƽươǃƼǦǋẫǃǦƸƽưƶǦƷƾếǉ.\nƩƽưǃƼǦǆǊǓǦƸủǦƼƾƶǃƼǦƽồ,ǦǃếǊǦđƃǦƸƖǃƼǦǃƽƶǊǦƼƾếǉǦđịƸƽ,ǦǁạƾǦƸƖǃƼǦǃƽƶǊǦǊốǃƼǦǇượǊ,ǦǉƽƔǦƸƽƓǃƽǦǁƐǦƽǊǓǃƽǦđệ.\n\nƩƼườƾǦđốƾǦǤƾệǃǦƸườƾǦƽƶǦƽảǦǂộǉǦǉƾếǃƼ,ǦǃƚƾǦǂƔǃƽǦƽọǦƱươǃƼ,ǦǉƙǃǦǂộǉǦƸƽữǦǥƽƶǃƽ.ǦƩƚƾǦǍǄǃƼǦǁƾềǃǦǆǊẳǃƼǦǉƕƾǦǇượǊǦđƃǦǊốǃƼǦǤởǦǆǊƶ.\nƨạǃƽǦƦƽǄƶǃǦǈớǂǦđƃǦƷịǦƽươǃƼǦǇượǊǦǀƾƶǦǁƐǂǦƸƽǄǦǀƽƇǦƽọǃƼ,ǦǃƽưǦǉǇƁǊǦǊốǃƼǦǃướƸ,ǦǃốƸǦǁƾềǃǦƷƶǦǃƼụǂǦǁớǃ.ǦƦƽƾếǃǦƱươǃƼǦǥƽƶǃƽǦđốƾǦǤƾệǃǦǉƽựƸǦǈựǦƸƚǦƸƽƕǉǦǍƚǉǦǍƶ.\nƦƽƇǃƼǦǅƽảƾǦǍƚǉǦǃƼườƾ,ǦǂƐǦǁƐǦǍƚǉǦǇượǊ.\nĂǃǦƸủƶǦǃƼườƾǦǉƽƔǦǃƼạƾ,ǦƨạǃƽǦƦƽǄƶǃǦǉƽấǓǦǋậǓǦđƐǃƽǦǆǊẹǉǦǂồǂ.\n\"ǥạƾǦƽạǦƨạǃƽǦƦƽǄƶǃ,Ǧǉừ...ǦƣƇǦĐƐǦǉớƾ.ǦƩƽữǃƼǦǃăǂǦǃƐǓǦƸũǃƼǦđƃǦǊốǃƼǦǇượǊǦởǦǀƽƇǃƼǦƓǉǦǃơƾ,ǦǃƽưǃƼǦǇượǊǦǃƐǓǦƸủƶǦǃƼươƾ...ǦǃƼửƾǦǉƽƔǦǃồǃƼ,ǦǊốǃƼǦǉƽƔǦƸƶǓ,ǦƽậǊǦǋịǦǁạƾǦǉƽƶǃƽ,ǦǉƽựƸǦǈựǦǀƽƇǃƼǦđǄƑǃǦǇƶǦđượƸǦǁƐǦǇượǊǦǋƖǃƼǦǃƐǄ.\"\n\"ƣƶǦƽƶ!ǦĐƁǓǦǁƐǦǇượǊǦủǦǉừǦǉǊǓếǉǦǉǇƙǃǦđỉǃƽǦƸƶǄǦǃƽấǉǦƸủƶǦǃƕƾǦǥƽƑƾǦƝạƸƽ,ǦƷƔǃƽǦǉƽườǃƼǦǁƐǂǦǈƶǄǦǊốǃƼǦđượƸ!ǦƞƚǦđƾềǊ,ǦǁƕƸǦǉƶǦǇờƾǦǃƽƐǦđƃǦǁƗǃǦǂƶǃƼǦǍǊốǃƼǦǃƕƾǦƸƽừǃƼǦǃƐǓ.\"\nƱươǃƼǦǥƽƶǃƽǦǇƶǦƽƾệǊǦǂộǉǦƸǄǃǦǈố.\nƨạǃƽǦƦƽǄƶǃǦƸườƾǦǀƽẩǓ:Ǧ\"ƝƶǦǋƛ?ǦǥƽếǦǉƽƔǦǈƶǄǦđủǦǊốǃƼ,ǦǂộǉǦǉốƾǦǁƐǦǈạƸƽǦƷƑƸƽ.\"\nƱươǃƼǦǥƽƶǃƽǦǁắƸǦđầǊ,ǦǋẫǃǦǇƶǦƽƾệǊǦƸǄǃǦǈốǦđƚ.\nƨạǃƽǦƦƽǄƶǃ:Ǧ\"ƝƶǦǂươƾ?\"\nƱươǃƼǦǥƽƶǃƽǦƸườƾǦǃƚƾ:Ǧ\"ƝƶǦǉǇăǂǦǋƛ!\"\nƨạǃƽǦƦƽǄƶǃǦƸườƾǦǁớǃ,ǦǋỗǦǉƶǓǦǃƚƾǦƽǊǓǃƽǦđệǦǆǊảǦǁƐǦǂộǉǦǃƼườƾǦǉƽƕǦǋị.\n\nƣƶƾǦǃƼườƾǦƸứǦǉƽếǦǉǇǄǃƼǦǃƼƇƾǦǂƾếǊǦǇƑƸƽ,ǦƷƙǃǦǃửƶǦǉƕƾǦǇượǊǦǃƼǄǃ,ǦƸƽǊǓệǃǦǉǇƙǃǦǉǇờƾǦǤướƾǦƷƾểǃǦǈǊốǉǦǂộǉǦđƙǂ.\n\nƦƽƾǦǉǇờƾǦǋừƶǦƽửǃƼǦǈƑǃƼ,ǦǇượǊǦđƃǦƸạǃ,ǦƸủƾǦƸũǃƼǦǉắǉ.ǦƣƶƾǦǃƼườƾǦǇƶǦƸửƶǦǁƙǃǦǃƼựƶ,ǦǂộǉǦǀẻǦǂǊốǃǦǋềǦƩƶǂ,ǦǂộǉǦǃƼườƾǦđịǃƽǦƽướǃƼǦƝắƸ.\n\n\"ǥạƾǦƽạǦƱươǃƼǦǥƽƶǃƽ,ǦǍƾǃǦƸƑǄǦǉừǦǉạƾǦđƁǓ.ǦƝảǄǦǉǇọǃƼ!\"\n\"ǥạƾǦƽạǦƨạǃƽǦƦƽǄƶǃ,ǦǍƾǃǦƸƑǄǦǉừǦǉạƾǦđƁǓ.ǦƝảǄǦǉǇọǃƼ.\"\n\nǥừǦƷƾệǉǦǍǄǃƼ,ǦƨạǃƽǦƦƽǄƶǃǦǉƽƕƸǦǃƼựƶǦđịǃƽǦđƾ,ǦǁạƾǦǃƼƽƺǦǅƽƓƶǦǈƶǊǦǉǇǊǓềǃǦǉớƾǦǂộǉǦƸƁǊ:\n\n\"ƨạǃƽǦƦƽǄƶǃǦƽǊǓǃƽ,ǦǁầǃǦǉớƾǦƼặǅǦǁạƾ,ǦǂǄǃƼǦǃƼươƾǦƽƃǓǦƸƽǄǦƷƾếǉǦǉƙǃǦǉƽậǉǦ——ǦƢƾƑ!\"\n\nƨạǃƽǦƦƽǄƶǃǦǆǊƶǓǦđầǊ,ǦƸƽỉǦǉƽấǓǦƷƚǃƼǦǁưǃƼǦǃƼườƾǦđƚǦƸưỡƾǦǃƼựƶǦǇờƾǦđƾ,ǦƷƾếǃǦǂấǉǦǉǇǄǃƼǦǂƐǃǦǉǊǓếǉǦǉǇắǃƼǦǍƚƶ.\n\nƣắǃǦǉặƸǦǁưỡƾǦǂộǉǦƸƑƾ,ǦǃƽưǦǁƐǦđƶǃƼǦǤưǦǋịǦǋịǦǇượǊ,ǦǁạƾǦǃƽưǦǁƐǦǀƽƇǃƼǦƷƾếǉǦǃƚƾǦƼƔ.\n\"ƨẹǦǃƚ,ǦǁạƾǦǃợǦǃƼươƾǦǂộǉǦƸƑƾǦǉƙǃǦǇồƾ.\"\n\n……\n\nƣƇǦĐƐ,ǦǥǇấǃǦǥƽụǦǥƽươǃƼ,ǦǋƐƾǦđốǂǦǁửƶǦǃƽỏǦƷịǦƼƾƚǦǉƽổƾǦǉǊǃƼǦǉƚƺ.\nƨạǃƽǦƦƽǄƶǃǦǃƼửƶǦđầǊ,ǦǁạƾǦǃốƸǦǂộǉǦǃƼụǂǦǇượǊǦǁớǃ.",
    ["你当时都没了半条命了，哪记得请？要真只有几炷香的时间，他可不会聋成现在这样，还得靠那一身武功来假装正常人。"] = "ƧƕƸǦđƚǦǃƼươƾǦǂấǉǦǃửƶǦƸƑƾǦǂạǃƼǦǇồƾ,ǦƸƛǃǦǃƽớǦƼƔǦǃổƾǦǃữƶ?ǦƩếǊǦǉƽựƸǦǈựǦƸƽỉǦƸƚǦǋƐƾǦǃƗǃǦǃƽƶǃƼ,ǦƽắǃǦđƃǦǀƽƇǃƼǦđƾếƸǦđếǃǦǂứƸǦǃƐǓ,ǦƸƛǃǦǅƽảƾǦǤựƶǦǋƐǄǦǋƅǦƸƇǃƼǦǉƽƁǂǦƽậǊǦǂớƾǦƼƾảǦǋờǦđượƸǦǃƽưǦǃƼườƾǦƷƔǃƽǦǉƽườǃƼ.",
    ["啥呀！我也纳闷呢，眼一闭一睁，就成这德行了。"] = "ƢƔǦƸơ!ǦǥƶǦƸũǃƼǦđƶǃƼǦǉƽắƸǦǂắƸǦđƁǓ,ǦǂắǉǦǃƽắǂǦǂắǉǦǂởǦǂộǉǦƸƑƾǦǁƐǦǉƽƐǃƽǦǇƶǦƸƑƾǦđứƸǦƽạǃƽǦǃƐǓǦǇồƾ.",
    ["对新政如此上心，很好，望能持之ai hằng, thiện thủy thiện chung.（giữ nguyên cổ phong: thiện thủy thiện chung）"] = "ĐốƾǦǋớƾǦǉƁǃǦƸƽƓǃƽǦǉƁǂǦƽǊǓếǉǦǃƽưǦǋậǓ,ǦǇấǉǦǉốǉ,ǦǂǄǃƼǦƸƚǦǉƽểǦǀƾƙǃǦǉǇƔǦƷềǃǦƷỉ,ǦƸƚǦđầǊǦƸƚǦđǊƇƾ.",
    ["1720000031"] = "1720000031",
    ["……阻击飞项……#Y咳疾#E……单孑独立……鹰隼……召……归山……#Y若可凭依，唤百鸟归巢，此亦为用也#E……千年……天命……"] = "...ǦƞƽặǃǦđƑǃƽǦǅƽƾǦǁǄǃƼ...Ǧ#YǦƸƽứǃƼǦƽǄǦ#E...ǦđơǃǦđộƸǦǁẻǦǁǄƾ...ǦưǃƼǦƸƽǊẩǃ...ǦǉǇƾệǊ...ǦǋềǦǃƕƾ...Ǧ#YǦǃếǊǦƸƚǦǉƽểǦǃươǃƼǦǉựƶ,ǦƼọƾǦƷƑƸƽǦđƾểǊǦǋềǦǉổ,ǦđƁǓǦƸũǃƼǦǁƐǦǂộǉǦƸƑƸƽǦǤƖǃƼǦǋậǓǦ#E...ǦǃƼƐǃǦǃăǂ...ǦǉƽƾƙǃǦǂệǃƽ...",
    ["男童2"] = "ƩƶǂǦđồǃƼǦ2",
    ["嘿嘿，可让老子逮着了。正好，去拜会拜会咱们的王相公！"] = "ƣƙǦƽƙ,ǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦđểǦǁƃǄǦǉửǦƷắǉǦđượƸ.ǦƱừƶǦƽƶǓ,ǦđƾǦƷƑƾǦǀƾếǃǦƱươǃƼǦǉướǃƼǦƸƇǃƼǦƸủƶǦƸƽƕǃƼǦǉƶǦǂộǉǦƸƽǊǓếǃ!",
    ["若无体察入微之眼，如何洞悉百态？若无日 tích lũy chi công, như hà viết tựu thử thư?（giữ nguyên cổ phong）"] = "ƩếǊǦǀƽƇǃƼǦƸƚǦđƇƾǦǂắǉǦǆǊƶǃǦǈƑǉǦǉỉǦǂỉ,ǦǈƶǄǦǉƽấǊǦƽƾểǊǦđượƸǦǃƽƁǃǦƼƾƶǃǦƷƑƸƽǦǉƽƑƾ?ǦƩếǊǦǀƽƇǃƼǦƸƚǦƸƇǃƼǦǁƶǄǦǉƓƸƽǦǁũǓǦǃƼƐǓǦǆǊƶǦǃƼƐǓ,ǦǈƶǄǦǋƾếǉǦǃƙǃǦđượƸǦƸǊốǃǦǈƑƸƽǦǃƐǓ?",
    ["{}大范围连续打击"] = "{}ǦƧƾƙǃǦǀƓƸƽǦǅƽạǂǦǋƾǦǁớǃ",
    ["耳畔一点翠，疑是枝上春. "] = "ƝƙǃǦǉƶƾǦǂộǉǦđƾểǂǦǉƽƕǓ,ǦǃƼỡǦǁƐǦǈắƸǦǍǊƁǃǦǉǇƙǃǦƸƐǃƽ.",
    ["破门村地下暗道纵横，皆昔年孤云门主鏖战玄元教主所遗。\n村老传云，有大密道者二：一在玄元教坛神龛之下，一藏五陵客栈地窖之中。  \n更余零星暗室星布其间，启阖之术各异。若得机缘入之，或逢异事。"] = "ĐịƶǦđạǄǦǤướƾǦǁƛǃƼǦđấǉǦǥƽƇǃǦƫƽƑǦƨƇǃǦǤọƸǦǃƼƶǃƼǦƸƽằǃƼǦƸƽịǉ,ǦđềǊǦǁƐǦǤƾǦǉƓƸƽǦǉừǦǉǇậǃǦƑƸǦƸƽƾếǃǦǃăǂǦǍưƶǦƼƾữƶǦƞƇǦƱƁǃǦǂƇǃǦƸƽủǦǋƐǦƣǊǓềǃǦƩƼǊǓƙǃǦƼƾƑǄǦƸƽủ.\nǥǇưởǃƼǦǉƽƇǃǦǉǇǊǓềǃǦǇằǃƼ,ǦǂậǉǦđạǄǦǁớǃǦƸƚǦƽƶƾǦƸƑƾ:ǦǂộǉǦǃằǂǦǤướƾǦǀƽƑǂǦǉƽờǦƣǊǓềǃǦƩƼǊǓƙǃǦƼƾƑǄǦđƐǃ,ǦǂộǉǦƼƾấǊǦǉǇǄǃƼǦƽầǂǦǇượǊǦƩƼũǦƧăǃƼǦƦƽƑƸƽǦđƾếǂ.\nƩƼǄƐƾǦǇƶǦƸƛǃǦƸƚǦƸƑƸǦǂậǉǦǉƽấǉǦǃƽỏǦǇảƾǦǇƑƸǦǀƽắǅǦǃơƾ,ǦƸƑƸƽǦǉƽứƸǦđƚǃƼǦǂởǦǀƽƑƸǦǃƽƶǊ.ǦƩếǊǦƸƚǦƸơǦǤǊǓƙǃǦǋƐǄǦđượƸ,ǦƸƚǦǁẽǦǈẽǦƼặǅǦƸƽǊǓệǃǦǀỳǦǁạ.",
    ["大庆殿是北宋皇宫（东京开封府）中规模最大的宫殿，主要用于举行元旦、冬至等重大朝会、祭典及皇帝登基仪式。皇帝起居多在福宁殿，藏书在崇文院，接待使臣通常在紫宸殿或垂拱殿。"] = "ĐƾệǃǦĐạƾǦƦƽƑǃƽǦǁƐǦƸǊǃƼǦđƾệǃǦƸƚǦǆǊǓǦǂƇǦǁớǃǦǃƽấǉǦǉǇǄǃƼǦƽǄƐǃƼǦƸǊǃƼǦƝắƸǦǥốǃƼǦ(ĐƇǃƼǦƦƾǃƽǦƦƽƶƾǦƫƽǄǃƼǦǅƽủ),ǦƸƽủǦǓếǊǦǤƖǃƼǦđểǦƸửǦƽƐǃƽǦƸƑƸǦƷǊổƾǦǉǇƾềǊǦƽộƾǦǉǇọǃƼǦđạƾǦǃƽưǦƩƼǊǓƙǃǦĐƑǃ,ǦĐƇǃƼǦƞƽƓ,ǦƸƑƸǦđạƾǦǁễǦǉếǦđƾểǃǦǋƐǦǃƼƽƾǦǉƽứƸǦđăǃƼǦƸơǦƸủƶǦƽǄƐǃƼǦđế.ǦƣǄƐǃƼǦđếǦǉƽườǃƼǦǈƾǃƽǦƽǄạǉǦǉạƾǦđƾệǃǦƫƽƕƸǦƩƾǃƽ,ǦǉƐǃƼǦǉǇữǦǈƑƸƽǦǋởǦǉạƾǦǋƾệǃǦƮƖǃƼǦƱăǃ,ǦǉƾếǅǦđƚǃǦǈứǦǉƽầǃǦǉƽườǃƼǦởǦđƾệǃǦǥửǦǥƽầǃǦƽǄặƸǦđƾệǃǦǥƽƖǓǦƞủǃƼ.",
    ["苏元道初入门时，解悟机关，总要比旁人迟钝许多。他怕给师父丢人，便常常一盏油灯，一架木鸢，熬到天明。\n暗地的努力被前辈们看在眼中，无人哂笑他愚钝，反而都常刻意将他带在身边，以便随时解答他遇到的疑难。\n他那时便明白，墨山道的道理，原来从不只在书上，更在墨者的身体力行之间。\n墨祖说：务言而缓行，虽辩必不听；多力而伐功，虽劳必不图。\n墨祖又说：故君子力事日强，愿欲日逾，设壮日盛。\n苏元道也学前辈们，将这些道理一条条记在书册上，又一条条践行。他向来走得不快，但一步一步，踏得坚实。\n\n后来他协管门规，陟罚臧否，门中上下无一人有非议，山内一片井然. 就算是师父鹎因研究误了课时，苏元道同样铁面无私，照罚薪俸。只是隔日，便又带上师父喜欢的蜜煎金桔，登门赔罪。私不害公，公不害私，鹎被罚得心服，闷气也不得生，不由慨叹：门下收得一君子，我徒竟可为规尺。\n\n及至几位师弟师妹入门，多跟在这位大师兄身旁长成。苏元道极少有什么教导规训之举，却在师弟师妹心中威望甚重。四师妹和五师弟性子倔，与师父多有抗辩之时，苏元道一至，自知无礼一方，便自觉偃旗息鼓。\n\n昔日的小辈成为今日靠谱的前辈，以身戴行，又将墨家之理传于后辈。\n只是苏元道常常想：二师弟过目不忘，三师妹志性坚韧，四师妹博闻强识，五师弟胸有丘壑，他们都比自己当年天资更好。这样好的师弟师妹们，竟都曾因战乱之事，险些没有长大的机会。这天下之大，又有多少本该长成师弟师妹们这样的英才，没有如自己一般的成长机会？\n\n墨门很好，但墨门真的太小。\n“朝中异动，北地或恐有虞。”\n山外探报递交到长老们手中时，长老们沉默无言. 中渡桥战后，契丹入寇数载，山外弟子折损几乎殆尽，这两年山中才稍见起色。同在堂中的苏元道明白，军机之变，只在旦夕之间。他不敢想，一场战火，又要让多少孩子没有机会长大。\n君子非钟，不击亦鸣。摩顶放踵利天下，为之。\n勒马回望之时，他知道此一出山，从此便再不是长老高徒，而是墨门逆徒了。但他注视墨城的眼睛中仍闪着光亮：若有一天，天下可皆如墨门，自己也算归乡。"] = "ƧƕƸǦǥƇǦƩƼǊǓƙǃǦĐạǄǦǂớƾǦǃƽậǅǦǂƇǃ,ǦƼƾảƾǦǃƼộǦƸơǦǆǊƶǃǦǁǊƇǃǦƸƽậǂǦƸƽạǅǦƽơǃǦǃƼườƾǦǀƽƑƸǦǃƽƾềǊ.ǦƣắǃǦǈợǦǁƐǂǦǈưǦǅƽụǦǂấǉǦǂặǉ,ǦƷƘǃǦǉƽườǃƼǦǍǊǓƙǃǦǉƽắǅǦǂộǉǦǃƼọǃǦǤầǊǦđăǃƼ,ǦǂộǉǦƼƾƑǦǂộƸǦǤƾềǊ,ǦǉƽứƸǦǉǇắǃƼǦđếǃǦǉậǃǦƷƔǃƽǦǂƾǃƽ.\nƩỗǦǁựƸǦǉƽầǂǦǁặǃƼǦđượƸǦƸƑƸǦǉƾềǃǦƷốƾǦǃƽƔǃǦǉƽấǊ,ǦǀƽƇǃƼǦƶƾǦƸườƾǦǃƽạǄǦƽắǃǦǃƼǊǦǂǊộƾ,ǦǉǇƑƾǦǁạƾǦƸƛǃǦǉƽườǃƼǦƸốǦƈǦǂƶǃƼǦƽắǃǦǉƽƺǄǦƷƙǃǦǂƔǃƽǦđểǦƼƾảƾǦđƑǅǦǃƽữǃƼǦǃƼƽƾǦǃƶǃǦƽắǃǦƼặǅǦǅƽảƾǦƷấǉǦƸứǦǁƕƸǦǃƐǄ.\nƣắǃǦǀƽƾǦđƚǦǂớƾǦƽƾểǊǦǇƶ,ǦđạǄǦǁƈǦƸủƶǦƨặƸǦƮơǃǦĐạǄǦƽƚƶǦǇƶǦƸƽưƶǦƷƶǄǦƼƾờǦƸƽỉǦǃằǂǦǉǇƙǃǦǈƑƸƽǦǋở,ǦǂƐǦǃằǂǦởǦǋƾệƸǦǉƽƁǃǦƽƐǃƽǦǉƽựƸǦƸƽứǃƼǦƸủƶǦǃƽữǃƼǦǃƼườƾǦƽƐǃƽǦđạǄǦƨặƸǦƼƾƶ.\nƨặƸǦǥổǦǃƚƾ:ǦƱụǦǃƼƇǃǦǃƽƾǦƽǄƃǃǦƽƐǃƽ,ǦǉǊǓǦƷƾệǃǦǉấǉǦƷấǉǦǉƽƓǃƽ;ǦđƶǦǁựƸǦǃƽƾǦǅƽạǉǦƸƇǃƼ,ǦǉǊǓǦǁƶǄǦǉấǉǦƷấǉǦđồ.\nƨặƸǦǥổǦǁạƾǦǃƚƾ:ǦƞốǦǆǊƁǃǦǉửǦǁựƸǦǈựǦǃƽậǉǦƸườǃƼ,ǦǃƼǊǓệǃǦǤụƸǦǃƽậǉǦǤǊ,ǦǉƽƾếǉǦǉǇƑǃƼǦǃƽậǉǦǉƽịǃƽ.\nǥƇǦƩƼǊǓƙǃǦĐạǄǦƸũǃƼǦƽọƸǦǉƽƺǄǦƸƑƸǦǉƾềǃǦƷốƾ,ǦƼƽƾǦƸƽƗǅǦǉừǃƼǦđạǄǦǁƈǦǃƐǓǦǋƐǄǦǉƽưǦǈƑƸƽ,ǦǇồƾǦǉừǃƼǦđƾềǊǦǉừǃƼǦđƾềǊǦǉƽựƸǦƽƐǃƽ.ǦƣắǃǦǋốǃǦǤĩǦđƾǦǀƽƇǃƼǦǃƽƶǃƽ,ǦǃƽưǃƼǦǉừǃƼǦƷướƸǦǂộǉǦđềǊǦđạǅǦǉƽựƸǦǋữǃƼǦƸƽƃƾ.\n\nƮƶǊǦǃƐǓǦƽắǃǦƽƾệǅǦǆǊảǃǦǂƇǃǦǆǊǓ,ǦǉǇắƸǦǅƽạǉǦǉƶǃƼǦǅƽủ,ǦǉǇƙǃǦǤướƾǦǉǇǄǃƼǦǂƇǃǦǀƽƇǃƼǦƶƾǦƸƚǦǁờƾǦǤịǦǃƼƽị,ǦǉǇǄǃƼǦǃƕƾǦǂộǉǦǂảǃƽǦǉềǦƸƽỉǃƽ.ǦƞƽǄǦǤƖǦǁƐǦǈưǦǅƽụǦǥƾǦǤǄǦǃƼƽƾƙǃǦƸứǊǦǂƐǦǁỡǦƼƾờǦǁƙǃǦǁớǅ,ǦǥƇǦƩƼǊǓƙǃǦĐạǄǦǋẫǃǦǉƽƾếǉǦǤƾệǃǦǋƇǦǉư,ǦƸƽƾếǊǦǉƽƺǄǦǆǊǓǦđịǃƽǦǂƐǦǅƽạǉǦƷổǃƼǦǁộƸ.ǦƞƽỉǦǁƐǦǃƼƐǓǦƽƇǂǦǈƶǊ,ǦƽắǃǦǁạƾǦǂƶǃƼǦǉƽƺǄǦǂứǉǦǀƾǂǦǆǊấǉǦǂƐǦǈưǦǅƽụǦǉƽƓƸƽǦǃƽấǉǦđếǃǦƸửƶǦǉạǦǁỗƾ.ǦǥưǦǀƽƇǃƼǦƽạƾǦƸƇǃƼ,ǦƸƇǃƼǦǀƽƇǃƼǦƽạƾǦǉư,ǦǥƾǦƷịǦǅƽạǉǦǂƐǦǉƁǂǦǅƽụƸǦǀƽẩǊǦǅƽụƸ,ǦǊấǉǦứƸǦƸũǃƼǦƸƽẳǃƼǦǈƾǃƽǦǇƶǦđượƸ,ǦǀƽƇǃƼǦǀƽỏƾǦƸảǂǦǉƽƑǃ:ǦƨƇǃǦƽạǦǉƽǊǦđượƸǦǂộǉǦǆǊƁǃǦǉử,ǦđồǦđệǦǉƶǦǆǊảǦƸƚǦǉƽểǦǁƐǂǦǉƽướƸǦǀẻǦđǄǦǁườǃƼǦǃƽƁǃǦƼƾƶǃ.\n\nĐếǃǦǀƽƾǦǂấǓǦǋịǦǈưǦđệǦǈưǦǂǊộƾǦǃƽậǅǦǂƇǃ,ǦđƶǦǅƽầǃǦđềǊǦđƾǦǉƽƺǄǦƷƙǃǦƸạǃƽǦǋịǦđạƾǦǈưǦƽǊǓǃƽǦǃƐǓǦǂƐǦǉǇưởǃƼǦǉƽƐǃƽ.ǦǥƇǦƩƼǊǓƙǃǦĐạǄǦƽƾếǂǦǀƽƾǦƸƚǦƽƐǃƽǦđộǃƼǦƼƾƑǄǦƽǊấǃǦǆǊǓǦƽǊấǃǦǃƐǄ,ǦǃƽưǃƼǦǉǇǄǃƼǦǁƛǃƼǦǈưǦđệǦǈưǦǂǊộƾǦǊǓǦǋọǃƼǦǁạƾǦƸựƸǦǉǇọǃƼ.ǦǥứǦǈưǦǂǊộƾǦǋƐǦƩƼũǦǈưǦđệǦǉƓǃƽǦǉƔǃƽǦƷướǃƼǦƷỉǃƽ,ǦǉƽườǃƼǦƸƚǦǁƕƸǦǀƽƑǃƼǦƷƾệǃǦǋớƾǦǈưǦǅƽụ,ǦƽễǦǥƇǦƩƼǊǓƙǃǦĐạǄǦđếǃ,ǦƷƙǃǦǃƐǄǦǉựǦƷƾếǉǦǂƔǃƽǦǋƇǦǁễǦǈẽǦǉựǦƼƾƑƸǦǓểǃǦǀỳǦǉứƸǦƸổ.\n\nƣậǊǦƷốƾǦǃăǂǦǍưƶǦǉǇởǦǉƽƐǃƽǦǉƾềǃǦƷốƾǦđƑǃƼǦǉƾǃǦƸậǓǦƸủƶǦƽƇǂǦǃƶǓ,ǦǁấǓǦǉƽƁǃǦƽƐǃƽǦđạǄ,ǦǁạƾǦđƺǂǦƸƑƾǦǁƈǦƸủƶǦƨặƸǦƼƾƶǦǉǇǊǓềǃǦƸƽǄǦƽậǊǦǈƾǃƽ.\nƞƽỉǦǁƐǦǥƇǦƩƼǊǓƙǃǦĐạǄǦǉƽườǃƼǦǃƼƽĩ:ǦƩƽịǦǈưǦđệǦǆǊƑǦǂụƸǦƷấǉǦǋǄǃƼ,ǦǥƶǂǦǈưǦǂǊộƾǦƸƽƓǦǉƓǃƽǦǀƾƙǃǦƸườǃƼ,ǦǥứǦǈưǦǂǊộƾǦƷƑƸǦǋăǃǦƸườǃƼǦǀƈ,ǦƩƼũǦǈưǦđệǦƽǊǃƼǦƽữǊǦǀƽƁǊǦƽạƸ,ǦƽọǦđềǊǦƸƚǦǉƽƾƙǃǦǉưǦǉốǉǦƽơǃǦǂƔǃƽǦǃăǂǦǍưƶ.ǦƩƽữǃƼǦǈưǦđệǦǈưǦǂǊộƾǦǉốǉǦǃƽưǦǋậǓ,ǦǋậǓǦǂƐǦđềǊǦǉừǃƼǦǋƔǦƸƽǊǓệǃǦƸƽƾếǃǦǁǄạǃǦǂƐǦǈǊƈǉǦƸƽƕǉǦǃữƶǦǀƽƇǃƼǦƸƚǦƸơǦƽộƾǦǁớǃǦǀƽƇǃ.ǦǥƽƾƙǃǦƽạǦƷƶǄǦǁƶǦǃƐǓ,ǦǁạƾǦƸƚǦƷƶǄǦǃƽƾƙǊǦƶǃƽǦǉƐƾǦđƑǃƼǦǁẽǦǃƙǃǦǉǇưởǃƼǦǉƽƐǃƽǦǃƽưǦǈưǦđệǦǈưǦǂǊộƾǦƸủƶǦǂƔǃƽ,ǦǁạƾǦǀƽƇǃƼǦƸƚǦƸơǦƽộƾǦǉǇưởǃƼǦǉƽƐǃƽǦǃƽưǦƸƽƓǃƽǦǂƔǃƽ?\n\nƨặƸǦƨƇǃǦǇấǉǦǉốǉ,ǦǃƽưǃƼǦƨặƸǦƨƇǃǦǉƽựƸǦǈựǦǆǊƑǦǃƽỏ.\n\"ǥǇǄǃƼǦǉǇƾềǊǦƸƚǦƷƾếǃǦđộǃƼ,ǦƝắƸǦđịƶǦƺǦǇằǃƼǦƸƚǦƽọƶ.\"\nƦƽƾǦǉƽƑǂǦƷƑǄǦǃƼǄƐƾǦǃƕƾǦđệǦǁƙǃǦǉƶǓǦƸƑƸǦǉǇưởǃƼǦǁƃǄ,ǦƸƑƸǦǉǇưởǃƼǦǁƃǄǦǁặǃƼǦǓƙǃǦǀƽƇǃƼǦǃƚƾ.ǦƮƶǊǦǉǇậǃǦǥǇǊǃƼǦĐộǦƦƾềǊ,ǦƦƽƾếǉǦĐƶǃǦǍƁǂǦǁấǃǦǃƽƾềǊǦǃăǂ,ǦđệǦǉửǦǃƼǄƐƾǦǃƕƾǦǉổǃǦǉƽấǉǦƼầǃǦǃƽưǦƸạǃǦǀƾệǉ,ǦƽƶƾǦǃăǂǦǃƶǓǦǉǇǄǃƼǦǃƕƾǦǂớƾǦƽơƾǦƸƚǦǀƽởƾǦǈắƸ.ǦǥƇǦƩƼǊǓƙǃǦĐạǄǦƸũǃƼǦƸƚǦǂặǉǦǉạƾǦǈảǃƽǦđườǃƼǦƽƾểǊǦǇƅ,ǦƷƾếǃǦƸƽǊǓểǃǦǆǊƁǃǦƸơǦƸƽỉǦǉǇǄǃƼǦǈớǂǦǉốƾ.ǦƣắǃǦǀƽƇǃƼǦǤƑǂǦǃƼƽĩ,ǦǂộǉǦǉǇậǃǦƸƽƾếǃǦƽỏƶǦǁạƾǦǈẽǦǀƽƾếǃǦƷƶǄǦǃƽƾƙǊǦđứƶǦǉǇẻǦǀƽƇǃƼǦƸƚǦƸơǦƽộƾǦǁớǃǦǀƽƇǃ.\nƬǊƁǃǦǉửǦǅƽƾǦƸƽǊǃƼ,ǦƷấǉǦǀƓƸƽǦǤƾệƸǦǂƾǃƽ.ǦƨƶǦđảǃƽǦǅƽƚǃƼǦƸƽủǃƼǦǁợƾǦǉƽƾƙǃǦƽạ,ǦǋƾǦƸƽƾ.\nƧƕƸǦƼƽƔǂǦǃƼựƶǦǃƼǄƑƾǦđầǊǦǃƽƔǃǦǁạƾ,ǦƽắǃǦƷƾếǉǦǂộǉǦǁầǃǦǍǊấǉǦǈơǃǦǃƐǓ,ǦǉừǦđƁǓǦǋềǦǈƶǊǦǀƽƇǃƼǦƸƛǃǦǁƐǦƸƶǄǦđồǦƸủƶǦǉǇưởǃƼǦǁƃǄǦǃữƶ,ǦǂƐǦǁƐǦǃƼƽịƸƽǦđồǦƸủƶǦƨặƸǦƨƇǃǦǇồƾ.ǦƩƽưǃƼǦǉǇǄǃƼǦđƇƾǦǂắǉǦƽắǃǦǃƽƔǃǦǋềǦǅƽƓƶǦƨặƸǦǥƽƐǃƽǦǋẫǃǦǁấǅǦǁƑǃƽǦƑǃƽǦǈƑǃƼ:ǦƩếǊǦƸƚǦǂộǉǦǃƼƐǓǦǉƽƾƙǃǦƽạǦđềǊǦƸƚǦǉƽểǦǃƽưǦƨặƸǦƨƇǃ,ǦƷảǃǦǉƽƁǃǦƸũǃƼǦƸǄƾǦǃƽưǦđượƸǦǋềǦǁạƾǦƸốǦƽươǃƼ.",
    ["全局光标关闭中..."] = "ĐƶǃƼǦđƚǃƼǦƸǄǃǦǉǇỏǦǉǄƐǃǦƸụƸ...",
    ["{}释放风墙获取增益{}释放飞花劲积攒繁花"] = "{}ǦǉƽƾǦǉǇƾểǃǦƫƽǄǃƼǦǥườǃƼǦǃƽậǃǦƷǊƻƻ,Ǧ{}ǦǉƽƾǦǉǇƾểǃǦƫƽƾǦƣǄƶǦƦƔǃƽǦǉƓƸƽǦǁũǓǦƫƽồǃǦƣǄƶ",
    ["袖珍醒钟\n\n此乃张万师某年赠予她的生辰贺礼，形似袖珍的水运仪象台，或作报时提醒之用。\n\n（随礼赠言）“给侠女青：久等不来，特赠灵器——望每日携于身侧，常忆常赏，必可助卿功力 dâng trào。”\n（谢礼留言）“好的师兄！知道了师兄！等我学完御剑的功法，便不会再让二位久等了——以吾资质，想必 không lâu sau sẽ thành công, sẽ không để sư huynh chờ đến khi râu tóc bạc phơ đâu!”"] = "ĐồǃƼǦƽồǦǉƽứƸǦǉỉǃƽǦƷỏǦǉƕƾ\n\nǦĐƁǓǦǁƐǦǂƚǃǦǆǊƐǦǈƾǃƽǦǃƽậǉǦǂƐǦǥǇươǃƼǦƱạǃǦƮưǦǉặǃƼǦƸƽǄǦǃƐǃƼǦǋƐǄǦǃăǂǦǃọ,ǦƽƔǃƽǦǤƑǃƼǦƼƾốǃƼǦǃƽưǦǂộǉǦǥƽủǓǦƱậǃǦƩƼƽƾǦǥượǃƼǦĐƐƾǦǉƽǊǦǃƽỏ,ǦǤƖǃƼǦđểǦƷƑǄǦƼƾờǦƽǄặƸǦǃƽắƸǦǃƽở.\n\nǦ(ƧờƾǦǉặǃƼǦǀƘǂ)Ǧ\"ƢửƾǦƽƾệǅǦǃữǦǥƽƶǃƽ:ǦƞƽờǦǂƃƾǦǀƽƇǃƼǦǉớƾ,ǦđặƸǦƷƾệǉǦǉặǃƼǦǁƾǃƽǦǀƽƓǦǃƐǓǦ——ǦǂǄǃƼǦǂỗƾǦǃƼƐǓǦǂƶǃƼǦǉƽƺǄǦƷƙǃǦǂƔǃƽ,ǦǉƽườǃƼǦǍǊǓƙǃǦǃƼắǂǦǃƼƽƓƶ,ǦắǉǦƼƾƕǅǦƸƇǃƼǦǁựƸǦƸủƶǦǃƐǃƼǦđạƾǦǉăǃƼ.\"\nǦ(ƧờƾǦƸảǂǦơǃ)Ǧ\"ǥǊƁǃǦǁệǃƽǦǈưǦƽǊǓǃƽ!ǦƨǊộƾǦƷƾếǉǦǇồƾǦǈưǦƽǊǓǃƽ!ǦĐợƾǦǂǊộƾǦƽọƸǦǍǄǃƼǦƸƇǃƼǦǅƽƑǅǦƩƼựǦƦƾếǂǦǈẽǦǀƽƇǃƼǦđểǦƽƶƾǦǋịǦǅƽảƾǦƸƽờǦǁƁǊǦǃữƶǦ——ǦǋớƾǦǉưǦƸƽấǉǦƸủƶǦǂǊộƾ,ǦƸƽắƸǦƽẳǃǦǃƼƐǓǦǉƽƐǃƽǦƸƇǃƼǦǀƽƇǃƼǦƸƛǃǦǍƶ,ǦǈẽǦǀƽƇǃƼǦđểǦǈưǦƽǊǓǃƽǦƸƽờǦđếǃǦǀƽƾǦǇƁǊǦǉƚƸǦƷạƸǦǅƽơǦđƁǊ!\"",
    ["这口井...里面好像有什么东西在动？我得去看看......"] = "ƞƑƾǦƼƾếǃƼǦǃƐǓ...ǦƷƙǃǦǉǇǄǃƼǦƽƔǃƽǦǃƽưǦƸƚǦǉƽứǦƼƔǦđƚǦđƶǃƼǦƸửǦđộǃƼ?ǦǥƶǦǅƽảƾǦǉớƾǦǍƺǂǦǈƶǄ...",
    ["使用此物，可获得奇术“金蟾腾跃”的外观特效——貔貅赐宝。"] = "ƮửǦǤụǃƼǦǋậǉǦǃƐǓ,ǦƸƚǦǉƽểǦǃƽậǃǦđượƸǦƽƾệǊǦứǃƼǦǃƼǄạƾǦƽƔǃƽǦƸủƶǦǀỳǦǉƽǊậǉǦ\"ƦƾǂǦǥƽƾềǂǦĐằǃƼǦǝượƸ\"Ǧ—ǦǥỳǦƣưǊǦǥứǦƝảǄ.",
    ["十方破阵·焚此心"] = "ǥƽậǅǦƫƽươǃƼǦƫƽƑǦǥǇậǃǦ·ǦƫƽầǃǦǥƽửǦǥƁǂ",
    ["盒子……已送到了？"] = "ƣộǅ...ǦđƃǦđưƶǦđếǃǦƸƽưƶ?",
    ["听说起义军攻破宋、亳、\n密三州，把虏狗吓破了胆……"] = "ƩƼƽƺǦǃƚƾǦǃƼƽĩƶǦǆǊƁǃǦđƃǦƸƇǃƼǦǅƽƑǦƷƶǦƸƽƁǊǦǥốǃƼ,ǦƝạƸ,\nƨậǉ,ǦǁƐǂǦǁũǦƼƾặƸǦǁỗǦǀƽƾếǅǦǋƓƶǦǂấǉǦǂậǉ...",
    ["没想到这刺客能这样兜兜转转，把大内的秘闻拿到手……"] = "ƦƽƇǃƼǦǃƼờǦǉƙǃǦǉƽƓƸƽǦǀƽƑƸƽǦǃƐǓǦƸƚǦǉƽểǦđƾǦǁƛǃƼǦǋƛǃƼǦǃƽưǦǋậǓǦǂƐǦǁấǓǦđượƸǦƷƓǦǋăǃǦđạƾǦǃộƾ...",
    ["思虑周全，切中时弊. 家礼为教化之本，此事办好有大功。"] = "ǥưǦǁựǦƸƽǊǦǉǄƐǃ,ǦǉƽƾếǉǦǉǇǊǃƼǦǉƽờƾǦǉệ.ǦƢƾƶǦǁễǦǁƐǦƼốƸǦƸủƶǦƼƾƑǄǦƽƚƶ,ǦǋƾệƸǦǃƐǓǦǁƐǂǦǉốǉǦǈẽǦƸƚǦđạƾǦƸƇǃƼ.",
    ["最后一段{}召唤鹰隼"] = "ĐǄạǃǦƸǊốƾǦ{}ǦǉǇƾệǊǦƽǄƑǃǦưǃƼǦƸƽǊẩǃ",
    ["大橘永远无法忘记自己来到文明殿的那日——\n它原本正藏在一辆装满了与自己色彩相似，吃起来有股酸甜滋味的果子车上安睡，结果不知为何，车子猛地抖了一下，害得它从果子山上一路滚，最终“咚”的一声，落到了地上……更令它感到难忘的是，它好不容易翻身起来准备离开，就对上了周围一群穿着各色袍子的人满是惊喜的眼睛。\n“好一个大橘为重！”“就应将 it 养在文明殿！”……\n伴随着这些话语，在大橘反应过来之前，它便已经有了名字与归宿。\n好在，它自己也很满意现在这种被许多人认可的状态。"] = "ĐạƾǦƬǊấǉǦǋĩǃƽǦǋƾễǃǦǀƽƇǃƼǦǉƽểǦǆǊƙǃǦđượƸǦǃƼƐǓǦǂƔǃƽǦđếǃǦĐƾệǃǦƱăǃǦƨƾǃƽǦ——\nƩƚǦǋốǃǦđƶǃƼǦǉǇốǃǦǉǇƙǃǦǂộǉǦƸƽƾếƸǦǍƺǦƸƽởǦđầǓǦǁǄạƾǦǆǊảǦƸƚǦǂƐǊǦǈắƸǦƼƾốǃƼǦƽệǉǦǂƔǃƽ,ǦăǃǦǋƐǄǦƸƚǦǋịǦƸƽǊƶǦƸƽǊƶǦǃƼọǉǦǃƼọǉǦđểǦǃƼủǦǈƶǓ,ǦǀếǉǦǆǊảǦǀƽƇǃƼǦƷƾếǉǦǋƔǦǈƶǄ,ǦƸƽƾếƸǦǍƺǦƷỗǃƼǦǇǊǃƼǦǂạǃƽǦǂộǉǦƸƑƾ,ǦǀƽƾếǃǦǃƚǦǁăǃǦǉừǦǉǇƙǃǦǃƕƾǦǆǊảǦǍǊốǃƼ,ǦƸǊốƾǦƸƖǃƼǦ\"đƖǃƼ\"ǦǂộǉǦǉƾếǃƼ,ǦǇơƾǦǍǊốǃƼǦđấǉ...ǦĐƾềǊǦǀƽƾếǃǦǃƚǦƸảǂǦǉƽấǓǦǀƽƚǦǆǊƙǃǦƽơǃǦǁƐ,ǦǃƚǦǀƽƚǦǀƽăǃǦǁắǂǦǂớƾǦǁậǉǦǂƔǃƽǦđứǃƼǦǤậǓǦđịǃƽǦǇờƾǦđƾ,ǦǉƽƔǦƷắǉǦƼặǅǦƑǃƽǦǂắǉǦđầǓǦǀƾǃƽǦǃƼạƸǦǍƺǃǦǁẫǃǦǋǊƾǦǂừǃƼǦƸủƶǦǂộǉǦđƑǂǦǃƼườƾǦǂặƸǦƑǄǦƷƐǄǦđủǦǂƐǊǦǈắƸǦǍǊǃƼǦǆǊƶǃƽ.\n\"ƬǊảǦǁƐǦĐạƾǦƬǊấǉǦǋƾǦǉǇọǃƼ!\"Ǧ\"ƩƙǃǦǃǊƇƾǦǃƚǦởǦĐƾệǃǦƱăǃǦƨƾǃƽ!\"...\nƞƖǃƼǦǋớƾǦǃƽữǃƼǦǁờƾǦǃƚƾǦđƚ,ǦǉǇướƸǦǀƽƾǦĐạƾǦƬǊấǉǦǀịǅǦǅƽảǃǦứǃƼ,ǦǃƚǦđƃǦƸƚǦǉƙǃǦǋƐǦǃơƾǦƸƽốǃǦđƾǦǋề.\nƞũǃƼǦǂƶǓ,ǦƸƽƓǃƽǦǃƚǦƸũǃƼǦǇấǉǦƽƐƾǦǁƛǃƼǦǋớƾǦǉǇạǃƼǦǉƽƑƾǦđượƸǦǃƽƾềǊǦǃƼườƾǦƸƇǃƼǦǃƽậǃǦǃƽưǦƽƾệǃǦǉạƾ.",
    ["姑奶奶，账不是这么算的. 你想，光抓你一个就要耗多少人？送几只肥羊给我们，把官兵换出来——你说是谁赚了？"] = "ƞƇǦǃươǃƼǦơƾ,ǦǈổǦǈƑƸƽǦǀƽƇǃƼǦǉƓǃƽǦǃƽưǦǉƽếǦđƁǊ.ǦƞƇǦǃƼƽĩǦǍƺǂ,ǦƸƽỉǦđểǦƷắǉǦǂƔǃƽǦƸƇǦǉƽƔǦǅƽảƾǦǉốǃǦƷƶǄǦǃƽƾƙǊǦǃƼườƾ?ǦƢƾƶǄǦǋƐƾǦƸǄǃǦƷƗǄǦƸƽǄǦƷọǃǦǉƶ,ǦđổƾǦǆǊƶǃǦƷƾǃƽǦǇƶǦǃƼǄƐƾǦ——ǦƸƇǦǃƚƾǦǍƺǂǦƶƾǦǁƐǦǃƼườƾǦƽờƾ?",
    ["——你！那你卖我们得了！"] = "——ǦƩƼươƾ!ǦƱậǓǦǃƼươƾǦƷƑǃǦƸƽƕǃƼǦǉƶǦƸƽǄǦǇồƾ!",
    ["你的剑都旧了，看我给你打了把好的！别绷着个脸，走走，随我一起去试剑！"] = "ƦƾếǂǦƸủƶǦƽǊǓǃƽǦƸũǦǇồƾ,ǦǍƺǂǦǉƶǦđƕƸǦƸƽǄǦƽǊǓǃƽǦǂộǉǦǉƽƶǃƽǦǉốǉǦǃƐǓ!ǦĐừǃƼǦƸƚǦǍịǦǂặǉǦǇƶǦǉƽế,ǦđƾǦǃƐǄǦđƾǦǃƐǄ,ǦƸƖǃƼǦǉƶǦđƾǦǉƽửǦǀƾếǂ!",
