    ["官家年轻时确是位豪侠. 戏文里讲了，那叫一个“力敌万人，气吞四海”. "] = "ƬǊƶǃǦƼƾƶǦǀƽƾǦƸƛǃǦǉǇẻǦđƕǃƼǦǁƐǦǂộǉǦǋịǦƽƐǄǦƽƾệǅ.ǦǥǇǄǃƼǦƽƓǦǋăǃǦƸƚǦǃƚƾ,ǦǉƽậǉǦđƕǃƼǦǁƐǦ\"ǁựƸǦđịƸƽǦǋạǃǦǃƽƁǃ,ǦǀƽƓǦǉƽƇǃǦǉứǦƽảƾ\".",
    ["酿酒的建筑，可用于解锁家园产业，曲香坊内可以建造蒸馏塔和其他家具. "] = "ƦƾếǃǦǉǇƕƸǦǃấǊǦǇượǊ,ǦǤƖǃƼǦđểǦǂởǦǀƽƚƶǦǈảǃǦǃƼƽƾệǅǦƼƾƶǦǋƾƙǃ,ǦǉǇǄǃƼǦƦƽƕƸǦƣươǃƼǦƫƽườǃƼǦƸƚǦǉƽểǦǍƁǓǦǤựǃƼǦǉƽƑǅǦƸƽưǃƼǦƸấǉǦǋƐǦƸƑƸǦđồǦǃộƾǦǉƽấǉǦǀƽƑƸ.",
    ["这一番处置，上面终觉差强人意，难称高明之策. "] = "ƞƑƸƽǦǍửǦǁƈǦǃƐǓ,ǦƸấǅǦǉǇƙǃǦǇốǉǦƸǊộƸǦƸảǂǦǉƽấǓǦƸƽưƶǦǉƽỏƶǦđƑǃƼ,ǦǀƽƚǦƸƚǦǉƽểǦƼọƾǦǁƐǦǤƾệǊǦǀế.",
    ["{}击中敌人加快蓄力"] = "{}ǦđƑǃƽǦǉǇƕǃƼǦǀẻǦđịƸƽǦǉăǃƼǦǉốƸǦǉụǦǁựƸ",
    ["一位想回家的江湖人. "] = "ƨộǉǦǃƼườƾǦǉǇǄǃƼǦƼƾƶǃƼǦƽồǦǂǊốǃǦǋềǦǃƽƐ.",
    ["我还以为什么金贵座驾，让老娘等那么久. 原来也不就是个小破驴. "] = "ǥƶǦƸƛǃǦǉưởǃƼǦǁƐǦǀƾệǊǦǆǊƈǦǍƺǦǈƶǃƼǦƼƔǦǂƐǦƷắǉǦǁƃǄǦǃươǃƼǦđợƾǦǁƁǊǦǉƽế.ǦƣƚƶǦǇƶǦƸũǃƼǦƸƽỉǦǁƐǦƸǄǃǦǁừƶǦǇƑƸƽ.",
    ["本心是好的，但工部所为也有理，且看后效. "] = "ƝảǃǦǉƁǂǦǁƐǦǉốǉ,ǦǃƽưǃƼǦǃƽữǃƼǦƼƔǦƝộǦƞƇǃƼǦǁƐǂǦƸũǃƼǦƸƚǦǁƈ,ǦƽƃǓǦǍƺǂǦǀếǉǦǆǊảǦǈƶǊǦǃƐǓ.",
    ["墨构玩法组件，摆放拼装后，可越过部分易碎障碍. 攻击类组件限制安装五个. "] = "ƧƾǃƽǦǀƾệǃǦǁốƾǦƸƽơƾǦƨặƸǦƞấǊ,ǦǈƶǊǦǀƽƾǦǁắǅǦđặǉǦƸƚǦǉƽểǦǋượǉǦǆǊƶǦǂộǉǦǈốǦƸƽướǃƼǦǃƼạƾǦǋậǉǦǤễǦǋỡ.ǦƧƾǃƽǦǀƾệǃǦǁǄạƾǦǉấǃǦƸƇǃƼǦƼƾớƾǦƽạǃǦǁắǅǦđặǉǦǃăǂǦƸƑƾ.",
    ["我才不管什么鬼不鬼的传说，我只知道这儿人少鱼多，容易钓出大鱼. "] = "ǥƶǦƸƽẳǃƼǦǆǊƶǃǦǉƁǂǦǉǇǊǓềǃǦǉƽǊǓếǉǦǂƶǦǆǊỷǦƼƔǦƽếǉ,ǦǉƶǦƸƽỉǦƷƾếǉǦƸƽỗǦǃƐǓǦƓǉǦǃƼườƾǦǃƽƾềǊǦƸƑ,ǦǤễǦƸƁǊǦđượƸǦƸƑǦǁớǃ.",
