    ["此策甚善，既解流民 di chi chi hoạn，又增社稷之储，深得要领。"] = "ƮƑƸƽǦǁượƸǦǃƐǓǦǇấǉǦƽƶǓ,ǦǋừƶǦƼƾảƾǦđượƸǦƸƑƾǦƽọƶǦǁưǊǦǤƁǃ,ǦǁạƾǦǉăǃƼǦǉƽƙǂǦǉƓƸƽǦǉǇữǦƸƽǄǦǍƃǦǉắƸ,ǦǃắǂǦǇấǉǦđƕǃƼǦǉǇọǃƼǦđƾểǂ.",
    ["【冬】太清楼一楼-端盘子宫ne 16"] = "[ĐƇǃƼ]ǦƧầǊǦǥƽƑƾǦǥƽƶǃƽǦǉầǃƼǦǂộǉǦ-ǦƞǊǃƼǦǃữǦƷưǃƼǦǂƁǂǦ16",
    ["一个人……你一个人去江湖吗？为什么不带我！我也要去！你答应了的！答应了的！"] = "ƨộǉǦǂƔǃƽ...ǦǃƼươƾǦđịǃƽǦǂộǉǦǂƔǃƽǦƽƐǃƽǦǉẩǊǦƼƾƶǃƼǦƽồǦǈƶǄ?ǦǥạƾǦǈƶǄǦǀƽƇǃƼǦǤẫǃǦǉƶǦǉƽƺǄ!ǦǥƶǦƸũǃƼǦǂǊốǃǦđƾ!ǦƩƼươƾǦđƃǦƽứƶǦǇồƾǦǂƐ!ǦĐƃǦƽứƶǦǇồƾǦǂƐ!",
    ["带带带，你再乱动要掉下去了！我是要去一些危险的地方打听江叔的消息。"] = "ǝẫǃ,ǦǤẫǃ,ǦǤẫǃǦǂƐ,ǦǃƼươƾǦƸƛǃǦǆǊậǓǦǅƽƑǦǃữƶǦǁƐǦǃƼƃǦǍǊốǃƼǦǤướƾǦđấǓ!ǦǥƶǦǁƐǦǅƽảƾǦđƾǦđếǃǦǋƐƾǦǃơƾǦǃƼǊǓǦƽƾểǂǦđểǦǃƼƽƺǦǃƼƚǃƼǦǉƾǃǦǉứƸǦƸủƶǦƢƾƶǃƼǦǉƽƕƸ.",
    ["再说，我不在的这一小段日子里，你就是神仙渡的老大了，你要有个老大的样子！"] = "ƱớƾǦǁạƾ,ǦǉǇǄǃƼǦǀƽǄảǃƼǦǉƽờƾǦƼƾƶǃǦǃƼắǃǦǉƶǦđƾǦǋắǃƼ,ǦǃƼươƾǦƸƽƓǃƽǦǁƐǦđạƾǦƸƶǦƸủƶǦǥƽầǃǦǥƾƙǃǦĐộǦǇồƾ,ǦǃƼươƾǦǅƽảƾǦǇƶǦǤƑǃƼǦǂộǉǦǋịǦđạƾǦƸƶǦƸƽứ!",
    ["我就揍他！"] = "ǥƶǦǈẽǦǉẩǃǦƽắǃǦǂộǉǦǉǇậǃ!",
    ["老大——那你什么时候走啊，是不是，是不是很快就走了啊？"] = "ĐạƾǦƸƶǦ——ǦƱậǓǦǀƽƾǦǃƐǄǦǃƼươƾǦđƾ,ǦƸƚǦǅƽảƾǦǁƐ,ǦƸƚǦǅƽảƾǦǁƐǦǈắǅǦđƾǦǇồƾǦǀƽƇǃƼ?",
    ["你看，我还给你准备了红披风，有了这个，红线女侠就是神仙渡第一帅了！"] = "ƩƼươƾǦǍƺǂ,ǦǉƶǦƸƛǃǦƸƽǊẩǃǦƷịǦƸƽǄǦǃƼươƾǦǂộǉǦƸƽƾếƸǦƑǄǦƸƽǄƐǃƼǦđỏ,ǦƸƚǦƸƑƾǦǃƐǓǦǇồƾ,ǦƣồǃƼǦǥǊǓếǃǦǃữǦƽƾệǅǦǈẽǦǁƐǦǃƼườƾǦǄƶƾǦǅƽǄǃƼǦǃƽấǉǦǥƽầǃǦǥƾƙǃǦĐộ!",
    ["好！江湖双侠！我们说到做到！"] = "ĐượƸ!ǦƢƾƶǃƼǦƽồǦǈǄǃƼǦƽƾệǅ!ǦƞƽƕǃƼǦǉƶǦǃƚƾǦđượƸǦǁƐǂǦđượƸ!",
    ["宝儿，跟紧娘。那个……大毛，小毛，你们也别乱跑。这儿生人多……"] = "ƝảǄǦǃƽƾ,ǦđƾǦǈƑǉǦǂẫǊǦǉƽƁǃ.ǦƞƛǃǦǃữƶ...ǦĐạƾǦƨƶǄ,ǦǥƾểǊǦƨƶǄ,ǦƸƑƸǦƸǄǃǦƸũǃƼǦđừǃƼǦƸƽạǓǦǁǊǃƼǦǉǊǃƼ.ǦỞǦđƁǓǦǃƽƾềǊǦǃƼườƾǦǁạǦǁắǂ...",
    ["对，绝不相干，绝对不管，绝不尽心尽力。不尽力还拿刀问路，尽心还得了了？"] = "ĐƕǃƼ,ǦǉǊǓệǉǦǀƽƇǃƼǦƸƶǃǦƽệ,ǦǉǊǓệǉǦđốƾǦǀƽƇǃƼǦǆǊảǃ,ǦǉǊǓệǉǦǀƽƇǃƼǦǉậǃǦǉƁǂǦǉậǃǦǁựƸ.ǦƦƽƇǃƼǦǉậǃǦǁựƸǦǂƐǦƸƛǃǦƸầǂǦđƶǄǦƽỏƾǦđườǃƼ,ǦǉậǃǦǉƁǂǦǃữƶǦǉƽƔǦƸƛǃǦǇƶǦǉƽểǦǉƽốǃƼǦƼƔ?",
    ["他在我跑到哪儿的时候没的？……不记得了。就是悄咪儿地在我背上没的。"] = "ƣắǃǦǉǇƕǉǦƽơƾǦǉƽởǦƸǊốƾǦƸƖǃƼǦǁƕƸǦǉƶǦƸƽạǓǦǉớƾǦđƁǊǦư?Ǧ...ǦƦƽƇǃƼǦǃƽớǦǃữƶ.ǦƞƽỉǦǁƐǦǁặǃƼǦǁẽǦǇƶǦđƾǦǉǇƙǃǦǁưǃƼǦǉƶǦǉƽƇƾ.",
    ["一个女的。刚刚她在烟里突然出现，给了我狠狠几下，这也太带劲了。"] = "ƨộǉǦǃữǦǃƽƁǃ.ǦƱừƶǦǃƃǓǦƸƇǦǉƶǦđộǉǦǃƽƾƙǃǦǍǊấǉǦƽƾệǃǦǉǇǄǃƼǦǁƐǃǦǀƽƚƾ,ǦđƑǃƽǦǉƶǦǂấǓǦǃƽƑǉǦđƶǊǦđƾếǃƼ,ǦǉƽậǉǦǁƐǦǆǊƑǦǅƽấǃǦǀƽƓƸƽǦǂƐ.",
    ["少东家你——哎。"] = "ǥƽƾếǊǦđƇǃƼǦƼƾƶ,ǦǃƼƐƾǦ——ǦƜƾǦǤƶ.",
    ["红线你、你俩在一块真是、真是——算了。"] = "ƣồǃƼǦǥǊǓếǃ,ǦǃƼươƾǦǋƐǦƽắǃǦởǦƸƖǃƼǦǂộǉǦƸƽỗǦđƕǃƼǦǁƐ,ǦđƕǃƼǦǁƐǦ——ǦǥƽƇƾǦƷỏǦđƾ.",
    ["你等我老大！我现在就——诶诶！ǃ"] = "ĐạƾǦƸƶǦđợƾǦǉƶǦǋớƾ!ǦǥƶǦđƾǦǃƼƶǓǦđƁǓǦ——ǦÊǦƙ!Ǧǃ",
    ["乖，马鞭我先帮你收着。小孩子就要安心躲在大人后面。"] = "ƩƼǄƶǃ,ǦǇǄƾǦǃƼựƶǦđểǦǉƶǦƼƾữǦƸƽǄ.ǦǥǇẻǦƸǄǃǦǉƽƔǦǅƽảƾǦǓƙǃǦǉƁǂǦǃấǅǦǈƶǊǦǁưǃƼǦǃƼườƾǦǁớǃ.",
    ["翟澜度"] = "ĐịƸƽǦƧƶǃǦĐộ",
    ["沿烨苓"] = "ĐốǦƜǃƽǦƝắǉǦĐượƸǦǑǂ",
    ["要没有他， these 田都得遭殃喽！"] = "ƩếǊǦǀƽƇǃƼǦƸƚǦǋịǦấǓ,ǦđƑǂǦǇǊộǃƼǦǃƐǓǦđềǊǦƼặǅǦƽọƶǦǇồƾ!",
    ["去探亲戚"] = "ĐƾǦǉƽăǂǦǉƽƁǃǦǉƽƓƸƽ.",
    ["不行，你不能抢，这是俺们种了一年的谷子. "] = "ƦƽƇǃƼǦđượƸ,ǦƸƑƸǦǃƼươƾǦǀƽƇǃƼǦđượƸǦƸướǅ,ǦđƁǓǦǁƐǦǁƕƶǦƸảǦǃăǂǦǃƶǓǦƸƽƕǃƼǦǉƶǦǉǇồǃƼ.",
    ["老汉在此观察七日，契丹铁骑每日分三路赶人，路线虽有变化，但所差不多。想来， they 定有一张行军图。"] = "ƧƃǄǦƽƑǃǦởǦđƁǓǦǆǊƶǃǦǈƑǉǦƷảǓǦǃƼƐǓ,ǦǉƽƾếǉǦǀỵǦƦƽƾếǉǦĐƶǃǦǂỗƾǦǃƼƐǓǦƸƽƾƶǦƷƶǦđườǃƼǦǁƖƶǦǃƼườƾ,ǦǁộǦǉǇƔǃƽǦǉǊǓǦƸƚǦǉƽƶǓǦđổƾǦǃƽưǃƼǦǀƽƇǃƼǦǀƽƑƸǦƷƾệǉǦǂấǓ.ǦƩƼƽĩǦǁạƾ,ǦƷọǃǦƸƽƕǃƼǦƸƽắƸǦƸƽắǃǦƸƚǦǂộǉǦƷảǃǦƽƐǃƽǦǆǊƁǃǦđồ.",
    ["……好好好，那都依 you 。我在明，你在暗。不说闲话了，赶路要紧。"] = "...ĐượƸǦđượƸǦđượƸ,ǦđềǊǦǃƼƽƺǦǉƽƺǄǦƈǦƽǊǓǃƽ.ǦǥƶǦởǦǈƑǃƼ,ǦƽǊǓǃƽǦởǦǉốƾ.ǦƦƽƇǃƼǦǃƚƾǦǅƽƾếǂǦǃữƶ,ǦǁƙǃǦđườǃƼǦǉƽƇƾ.",
    ["正是。前方险路难行，游侠务必当心. "] = "ƞƽƓǃƽǦǍƑƸ.ǦĐườǃƼǦǅƽƓƶǦǉǇướƸǦƽƾểǂǦǉǇởǦǀƽƚǦđƾ,ǦǤǊǦƽƾệǅǦǃƽấǉǦđịǃƽǦǅƽảƾǦƸẩǃǦǉƽậǃ.",
    ["是你！胳膊腿都在，运气不错嘛。接下来打算去哪儿？"] = "ƧƐǦǃƼươƾ!ǦǥƶǓǦƸƽƁǃǦƸƛǃǦǃƼǊǓƙǃǦǋẹǃ,ǦǋậǃǦǀƽƓǦǀƽƇǃƼǦǉệǦƸƽƕǉǦǃƐǄ.ǦǥƾếǅǦǉƽƺǄǦđịǃƽǦđƾǦđƁǊ?",
    ["晋军不是在北边应敌么？虏人是如何……"] = "ǥấǃǦǆǊƁǃǦƸƽẳǃƼǦǅƽảƾǦđƶǃƼǦứǃƼǦđịƸƽǦởǦǅƽƓƶǦƷắƸǦǈƶǄ?ǦƬǊƁǃǦƼƾặƸǦǁƐǂǦǈƶǄǦƸƚǦǉƽể...",
    ["现在，只一条路，杀虏狗的路。"] = "ƣƾệǃǦǉạƾ,ǦƸƽỉǦƸƚǦǂộǉǦƸǄǃǦđườǃƼ,ǦƸǄǃǦđườǃƼǦƼƾếǉǦǁũǦƼƾặƸǦǃƼǄạƾǦǍƁǂ.",
    ["ƨãǦƦƽǊǦǥǇƔ"] = "ƨƃǦƦƽǊǦǥǇƔ",
    ["高山流水话短长，开封父老热心肠。几个铜板叮当响，桃源仙法往下讲！"] = "ƞƶǄǦǈơǃǦǁưǊǦǉƽủǓǦǉƽǄạƾǦđǄảǃǦǉǇườǃƼ,ǦƦƽƶƾǦƫƽǄǃƼǦǅƽụǦǁƃǄǦǃƽƾệǉǦǉƁǂǦǉǇườǃƼ.ǦƨấǓǦƸƑƾǦđồǃƼǦǉƾềǃǦǀƙǊǦǁƺǃƼǦǀƺǃƼ,ǦĐƐǄǦƩƼǊǓƙǃǦǉƾƙǃǦǅƽƑǅǦƷắǉǦđầǊǦƼƾảǃƼ!",
    ["这么重要的事儿，你就准备在这儿说？"] = "ƞƽǊǓệǃǦǆǊƶǃǦǉǇọǃƼǦǉƽếǦǃƐǓǦǂƐǦǃƼươƾǦđịǃƽǦǃƚƾǦởǦđƁǓǦǈƶǄ?",
    ["说不过你。"] = "ƩƚƾǦǀƽƇǃƼǦǁạƾǦǃƼươƾ.",
    ["好大侠，你听见他们说的了吗？"] = "ĐạƾǦƽƾệǅǦǉốǉ,ǦǃƼƐƾǦƸƚǦǃƼƽƺǦǉƽấǓǦƽọǦǃƚƾǦƼƔǦǀƽƇǃƼ?",
    ["哇……你跟谁学的不吃亏？"] = "ƪƶ...ǦǃƼươƾǦƽọƸǦƶƾǦƸƑƾǦǉƽƚƾǦƸƽẳǃƼǦƸƽịǊǦǉƽƾệǉǦƷƶǄǦƼƾờǦǉƽế?",
    ["咳。这位游侠，幸会。在下晋中原。"] = "Ʀƽụ.ǦƱịǦǤǊǦƽƾệǅǦǃƐǓ,ǦƽạǃƽǦǃƼộ.ǦǥạƾǦƽạǦǥấǃǦǥǇǊǃƼǦƩƼǊǓƙǃ.",
    ["……我差事没办好，被上司勒令在家反省。"] = "...ǥƶǦǁƐǂǦƽỏǃƼǦǋƾệƸ,ǦƷịǦƸấǅǦǉǇƙǃǦǇƶǦǁệǃƽǦởǦǃƽƐǦǉựǦǀƾểǂǦđƾểǂ.",
    ["哇，那你还挺倒霉的。"] = "ƪƶ,ǦǋậǓǦǉƽƔǦǃƼươƾǦƸũǃƼǦǍǊƾǦǍẻǄǦǉƽậǉǦđấǓ.",
    ["……你真有线索……？"] = "...ƩƼươƾǦǉƽựƸǦǈựǦƸƚǦǂƶǃƽǦǂốƾǦǈƶǄ...?",
    ["诈他一下又不亏……"] = "ƧừƶǦƽắǃǦǂộǉǦǋốǦƸũǃƼǦƸƽẳǃƼǦǂấǉǦƼƔ...",
    ["你们自恃武力无故砸店，恐吓老板客人，又满口寻仇杀人……真当这城中没有王法了！"] = "ƞƑƸǦǃƼườƾǦƸậǓǦƸƚǦǋƅǦǁựƸǦǋƇǦƸớǦđậǅǦǅƽƑǦǆǊƑǃǦǍƑ,ǦđƺǦǤọƶǦƸƽưởǃƼǦǆǊỹǦǋƐǦǉƽựƸǦǀƽƑƸƽ,ǦǁạƾǦƸƛǃǦǂởǦǂƾệǃƼǦǇƶǦǁƐǦƷƑǄǦǉƽƖǦƼƾếǉǦǃƼườƾ...ǦǉƽựƸǦǈựǦƸǄƾǦǉǇǄǃƼǦǉƽƐǃƽǦǃƐǓǦǀƽƇǃƼǦƸƚǦǋươǃƼǦǅƽƑǅǦǈƶǄ!",
    ["呼……飞得还挺快。"] = "ƫƽƖ...ǦƷƶǓǦƸũǃƼǦǃƽƶǃƽǦǉƽậǉǦđấǓ.",
    ["呼……这是往城东去的路？"] = "ƫƽƖ...ǦđƁǓǦǁƐǦđườǃƼǦđƾǦǋềǦǅƽƓƶǦđƇǃƼǦǉƽƐǃƽǦǈƶǄ?",
    ["怎么这么远？这鸟儿要引我去哪儿？"] = "ƮƶǄǦǁạƾǦǍƶǦǉƽếǦǃƐǓ?ǦƞǄǃǦƸƽƾǂǦǃƐǓǦđịǃƽǦǤẫǃǦǉƶǦđƾǦđƁǊǦđƁǓ?",
    ["桃源还没到……就得罪了晋公子。"] = "ĐƐǄǦƩƼǊǓƙǃǦƸƛǃǦƸƽưƶǦǉớƾ...ǦđƃǦđắƸǦǉộƾǦǋớƾǦǥấǃǦƸƇǃƼǦǉửǦǇồƾ.",
    ["怎么一个个的都有线索……桃源的线索这么好弄到？"] = "ƮƶǄǦƶƾǦƶƾǦƸũǃƼǦƸƚǦǂƶǃƽǦǂốƾǦǉƽếǦǃƐǓ...ǦƨƶǃƽǦǂốƾǦǋềǦĐƐǄǦƩƼǊǓƙǃǦǤễǦǀƾếǂǦǋậǓǦǈƶǄ?",
    ["造成伤害后，自身会意伤害提升#Y3.5%#E，持续#Y120#E秒，最多可叠加#Y3#E层。该效果每#Y60#E秒只能触发一次。符帖效果可持续#Y30#E分钟。\n\n【符帖]效果最多只能存在一个，在试炼玩法不生效。"] = "ƮƶǊǦǀƽƾǦƼƁǓǦǈƑǉǦǉƽươǃƼ,ǦƮƑǉǦǉƽươǃƼǦƝạǄǦƦƓƸƽǦƸủƶǦƷảǃǦǉƽƁǃǦǉăǃƼǦ#Y3.5%#E,ǦǤǊǓǦǉǇƔǦ#Y120#EǦƼƾƁǓ,ǦǉốƾǦđƶǦƸộǃƼǦǤồǃǦ#Y3#EǦǉầǃƼ.ǦƣƾệǊǦǆǊảǦǃƐǓǦǂỗƾǦ#Y60#EǦƼƾƁǓǦǂớƾǦƸƚǦǉƽểǦǀƓƸƽǦƽǄạǉǦǂộǉǦǁầǃ.ǦƣƾệǊǦǆǊảǦƫƽƖǦǥƽƾếǅǦǤǊǓǦǉǇƔǦ#Y30#EǦǅƽƕǉ.\n\nƣƾệǊǦǆǊảǦ[ƫƽƖǦǥƽƾếǅ]ǦǉốƾǦđƶǦƸƽỉǦǉồǃǦǉạƾǦǂộǉǦƸƑƾ,ǦǀƽƇǃƼǦƸƚǦƽƾệǊǦǁựƸǦǉǇǄǃƼǦǁốƾǦƸƽơƾǦǥƽửǦǥƽƑƸƽ.",
    ["每消耗#Y120#E精元后，造成的奇术伤害提升#Y4%#E，持续#Y120#E秒，最多可叠加#Y3#E层。符帖效果可持续#Y30#E分钟。\n\n【符帖]效果最多只能存在一个，在试炼玩法不生效。"] = "ƨỗƾǦǀƽƾǦǉƾƙǊǦƽƶǄǦ#Y120#EǦǥƾǃƽǦƩƼǊǓƙǃ,ǦǈƑǉǦǉƽươǃƼǦƦỳǦǥƽǊậǉǦƼƁǓǦǇƶǦǉăǃƼǦ#Y4%#E,ǦǤǊǓǦǉǇƔǦ#Y120#EǦƼƾƁǓ,ǦǉốƾǦđƶǦƸộǃƼǦǤồǃǦ#Y3#EǦǉầǃƼ.ǦƣƾệǊǦǆǊảǦƫƽƖǦǥƽƾếǅǦǤǊǓǦǉǇƔǦ#Y30#EǦǅƽƕǉ.\n\nƣƾệǊǦǆǊảǦ[ƫƽƖǦǥƽƾếǅ]ǦǉốƾǦđƶǦƸƽỉǦǉồǃǦǉạƾǦǂộǉǦƸƑƾ,ǦǀƽƇǃƼǦƸƚǦƽƾệǊǦǁựƸǦǉǇǄǃƼǦǁốƾǦƸƽơƾǦǥƽửǦǥƽƑƸƽ.",
    ["《法苑珠林·愚戆篇·杂痴部>"] = "<ƫƽƑǅǦǕǓểǃǦƞƽƁǊǦƧƁǂǦ•ǦƩƼǊǦƩƼạǄǦǥƽƾƙǃǦ•ǦǥạǅǦƮƾǦƝộ>",
    ["可是会是谁呢？而且这连我都能发现的蹊蹊，那些祁家人自己怎么会不知道？"] = "ƩƽưǃƼǦƸƚǦǉƽểǦǁƐǦƶƾǦƸƽứ?ǦƣơǃǦǃữƶǦǈựǦǀỳǦǁạǦǃƐǓǦđếǃǦǉƶǦƸƛǃǦǃƽậǃǦǇƶ,ǦǈƶǄǦǃƼườƾǦƦỳǦƼƾƶǦǁạƾǦǀƽƇǃƼǦƷƾếǉ?",
