    ["除了值白班，我还有晚班和大夜班要值啊……"] = "ƩƼǄƐƾǦǉǇựƸǦƸƶǦǃƼƐǓ,ǦǉƶǦƸƛǃǦǅƽảƾǦǉǇựƸǦƸƶǦǉốƾǦǋớƾǦƸƶǦđƙǂǦǃữƶǦđƁǓǦǃƐǓ...",
    ["慢着我这还有个卷宗要核对哪！新兵，你先自己逛逛！"] = "ƦƽǄƶǃǦđƃ,ǦǉƶǦƸƛǃǦƸƚǦƸǊốǃǦǆǊǓếǃǦǉƇǃƼǦƸầǃǦđốƾǦǈǄƑǉǦđƁǓ!ǦǥƁǃǦƷƾǃƽ,ǦǃƼươƾǦǉựǦđƾǦǤạǄǦǆǊƶǃƽǦǂộǉǦƸƽƕǉǦđƾ!",
    ["《直接问恐怕打草惊蛇，先迂回试探一番。>"] = "<ǥǇựƸǦǉƾếǅǦƽỏƾǦƺǦǁƐǦđảǦǉƽảǄǦǀƾǃƽǦǍƐ,ǦƽƶǓǦǁƐǦǉƽăǂǦǤƛǦǋƛǃƼǦǋǄǦǉǇướƸǦđƃ.>",
    ["《这个声音……>"] = "<ƢƾọǃƼǦǃƚƾǦǃƐǓ...>",
    ["$N/赵光义"] = "$N/ǥǇƾệǊǦƬǊƶǃƼǦƩƼƽĩƶ",
    ["……你们怎么把她抓来了。"] = "...ǦƮƶǄǦƸƑƸǦǃƼươƾǦǁạƾǦƷắǉǦƸƇǦǉƶǦǉớƾǦđƁǓ.",
    ["……知道了。放了吧，正好用她. "] = "...ǦĐƃǦƷƾếǉ.ǦǥƽảǦǇƶǦđƾ,ǦǋừƶǦǋặǃǦƸƚǦǋƾệƸǦƸầǃǦǤƖǃƼǦƸƇǦǉƶ.",
    ["宫内外的乱象，所图并非武德司，是封桩库。少卫。"] = "ƮựǦƽỗǃǦǁǄạǃǦǉǇǄǃƼǦǃƼǄƐƾǦƸǊǃƼ,ǦǂụƸǦǉƾƙǊǦǀƽƇǃƼǦǅƽảƾǦƱƅǦĐứƸǦǥǓ,ǦǂƐǦǁƐǦƫƽǄǃƼǦǥǇƶǃƼǦƦƽố.ǦǥƽƾếǊǦǋệ.",
    ["明白，我会详细查证。她呢？"] = "ƭƅ,ǦǉƽǊộƸǦƽạǦǈẽǦđƾềǊǦǉǇƶǦƸƽƾǦǉƾếǉ.ǦƞƛǃǦƸƇǦǉƶǦǉƽƔǦǈƶǄ?",
    ["帮苦主寻窃贼可是义举。此事关联重大，又牵连江湖. 你不是最好打抱不平？"] = "ƢƾƕǅǦǀƽổǦƸƽủǦǉƔǂǦǉặƸǦǉặƸǦǁƐǦǃƼƽĩƶǦƸử.ǦƱƾệƸǦǃƐǓǦǆǊƶǃǦƽệǦǉǇọǃƼǦđạƾ,ǦǁạƾǦǤƓǃƽǦǤƑǃƼǦđếǃǦƼƾƶǃƼǦƽồ.ǦƩƼươƾǦƸƽẳǃƼǦǅƽảƾǦǉƽƓƸƽǦǃƽấǉǦǁƐǦǁǄǦƸƽǊǓệǃǦƷấǉǦƷƔǃƽǦǈƶǄ?",
    ["札子已经递上去了，批复嘛……今天一定能有信儿！"] = "ǥấǊǦƸƽươǃƼǦđƃǦƼửƾǦǁƙǃǦǇồƾ,ǦǅƽƙǦƽồƾǦǉƽƔ...ǦƽƇǂǦǃƶǓǦǃƽấǉǦđịǃƽǦǈẽǦƸƚǦǉƾǃ!",
    ["小的给官人赔不是了！不小心占了您的道。"] = "ǥƾểǊǦǃƽƁǃǦǍƾǃǦǁỗƾǦǆǊƶǃǦǃƽƁǃ!ǦƦƽƇǃƼǦƸẩǃǦǉƽậǃǦđƃǦƸảǃǦđườǃƼǦǃƼƐƾ.",
    ["《仓库的枯树？那不就是那些人找我去接头的地方吗？！>"] = "<ƞƁǓǦǀƽƇǦởǦǃƽƐǦǀƽǄ?ǦĐƚǦƸƽẳǃƼǦǅƽảƾǦǁƐǦǃơƾǦđƑǂǦǃƼườƾǦǀƾƶǦƽẹǃǦǉƶǦđếǃǦǉƾếǅǦứǃƼǦǈƶǄ?!>",
    ["“呀！好痛！我的脚崴了……别管我，你快走！”"] = "\"Á!ǦĐƶǊǦǆǊƑ!ǦƞƽƁǃǦǉƶǦƷịǦǉǇậǉǦǇồƾ...ǦđừǃƼǦǆǊảǃǦǉƶ,ǦǃƼươƾǦǂƶǊǦđƾǦđƾ!\"",
    ["“天若伤你，我便逆天！\n恩人，这次换我报答你！”"] = "\"ǥƽƾƙǃǦǃƽượƸǦǉƽươǃƼǦǃƽĩ,ǦǃƼƃǦǉƾệǃǦǃƼƽịƸƽǦǉƽƾƙǃ!\nƀǃǦǃƽƁǃ,ǦǁầǃǦǃƐǓǦđổƾǦǁạƾǦǁƐǦǉƶǦƷƑǄǦđƑǅǦǃƼườƾ!\"",
    ["“恩人，放下剑，我就无法报答你！\n拿起剑，我更无法报答你！”"] = "\"ƀǃǦǃƽƁǃ,ǦƷǊƇǃƼǦǀƾếǂǦǍǊốǃƼ,ǦǉƶǦǀƽƇǃƼǦƸƑƸƽǦǃƐǄǦƷƑǄǦđƑǅǦǃƼườƾ!\nƞầǂǦǀƾếǂǦǁƙǃ,ǦǉƶǦƸƐǃƼǦǀƽƇǃƼǦƸƑƸƽǦǃƐǄǦƷƑǄǦđƑǅǦǃƼườƾ!\"",
    ["“一旦拿起了剑，你的手就不再只属于自己，\n……而属于天下苍生！”"] = "\"ƨộǉǦǀƽƾǦđƃǦƸầǂǦǀƾếǂǦǁƙǃ,ǦđƇƾǦǉƶǓǦƸủƶǦǃƼươƾǦǀƽƇǃƼǦƸƛǃǦƸƽỉǦǉƽǊộƸǦǋềǦƸƽƓǃƽǦǂƔǃƽǦǃữƶ,\n...ǦǂƐǦǉƽǊộƸǦǋềǦǉƽƾƙǃǦƽạǦǉƽươǃƼǦǈƾǃƽ!\"",
    ["“你既想学，那便看好这招——\n飞——檐——走——壁！”"] = "\"ƩƼươƾǦđƃǦǂǊốǃǦƽọƸ,ǦǋậǓǦƽƃǓǦǃƽƔǃǦǀỹǦƸƽƾƙǊǦǃƐǓǦ——\nƫƽƾǦ——ǦǥƽƾềǂǦ——ǦǥẩǊǦ——ǦƝƓƸƽ!\"",
    ["“恩人，不必管我，快逃！”"] = "\"ƀǃǦǃƽƁǃ,ǦǀƽƇǃƼǦƸầǃǦǆǊảǃǦǉƶ,ǦǂƶǊǦƸƽạǓǦđƾ!\"",
    ["璎璎小心翼翼，一路向前. "] = "ƜǃƽǦƜǃƽǦƸẩǃǦǉƽậǃǦǉừǃƼǦƸƽƕǉǦǂộǉ,ǦǉƾếǃǦǋềǦǅƽƓƶǦǉǇướƸ.",
    ["为什么每次都有人站在火药桶旁边。"] = "ǥạƾǦǈƶǄǦǁầǃǦǃƐǄǦƸũǃƼǦƸƚǦǃƼườƾǦđứǃƼǦƸạǃƽǦǉƽƖǃƼǦǉƽǊốƸǦǈƕǃƼǦǋậǓǦǃƽỉ.",
    ["宫廷秘史……原来我捡到的那本《宫廷秘史>是你写的！"] = "ƞǊǃƼǦĐƔǃƽǦƝƓǦƮử...ǦƽƚƶǦǇƶǦƸǊốǃǦ<ƞǊǃƼǦĐƔǃƽǦƝƓǦƮử>ǦǉƶǦǃƽặǉǦđượƸǦǁƐǦǤǄǦǃƼươƾǦǋƾếǉ!",
    ["这有啥！江湖上靠秘密换钱换命的，大有人 dại!"] = "ƞƽǊǓệǃǦǃƐǓǦƸƚǦƼƔǦƸƽứ!ǦǥǇƙǃǦƼƾƶǃƼǦƽồǦǀẻǦǤựƶǦǋƐǄǦƷƓǦǂậǉǦđểǦđổƾǦǉƾềǃǦđổƾǦǂạǃƼǦđầǓǦǇẫǓǦǇƶǦđƚ!",
    ["怎么，你也来催我的《璎璎神机闯江湖>？"] = "ƮƶǄǦǉƽế,ǦǃƼươƾǦƸũǃƼǦđếǃǦƼƾụƸǦƷảǃǦ<ƜǃƽǦƜǃƽǦǥƽầǃǦƞơǦƳƇǃƼǦƫƽƶǦƢƾƶǃƼǦƣồ>ǦƸủƶǦǉƶǦƐ?",
    ["……催，催！不过你是不是忘了什么？这本《宫廷秘史>，还给你。"] = "...ǦƢƾụƸǦƸƽứ,ǦƼƾụƸǦƸƽứ!ǦƩƽưǃƼǦƸƚǦǅƽảƾǦǃƼươƾǦǆǊƙǃǦƼƔǦǇồƾǦǀƽƇǃƼ?ǦƞǊốǃǦ<ƞǊǃƼǦĐƔǃƽǦƝƓǦƮử>ǦǃƐǓ,ǦǉǇảǦǁạƾǦƸƽǄǦǃƼươƾ.",
    ["《宫廷秘史·续>。"] = "<ƞǊǃƼǦĐƔǃƽǦƝƓǦƮửǦ-ǦǥƾếǅǦǥƽƺǄ>.",
    ["人中龙凤我没看出来，人中饭桶倒是一个赛一个. 刚进宫时那身板，两年不到，腰带都快勒不住那肚子了。我看他们练的不是武艺，是饭量！"] = "ƩƽƁǃǦǉǇǊǃƼǦǁǄǃƼǦǅƽượǃƼǦǉƽƔǦǉƶǦǀƽƇǃƼǦǉƽấǓ,ǦƸƽứǦǃƽƁǃǦǉǇǊǃƼǦƸơǂǦǉƽƖǃƼǦǉƽƔǦđƕǃƼǦǁƐǦǀẻǦǈƶǊǦƽơǃǦǃƼườƾǦǉǇướƸ.ǦƞƑƾǦǉƽƁǃǦƽƔǃƽǦǁƕƸǦǂớƾǦǋƐǄǦƸǊǃƼǦấǓǦƐ,ǦƸƽưƶǦđầǓǦƽƶƾǦǃăǂ,ǦđƶƾǦǁưǃƼǦđƃǦǈắǅǦǀƽƇǃƼǦǉƽắǉǦǃổƾǦƸƑƾǦƷụǃƼǦđƚǦǇồƾ.ǦǥƶǦǉƽấǓǦƷọǃǦƽọǦǁǊǓệǃǦǀƽƇǃƼǦǅƽảƾǦǋƅǦǃƼƽệǦǂƐǦǁƐǦǁǊǓệǃǦǈứƸǦăǃ!",
    ["皇宫音乐班火热招生中，这位官人有兴趣了解一下吗？"] = "ƧớǅǦƁǂǦǃƽạƸǦƽǄƐǃƼǦƸǊǃƼǦđƶǃƼǦǇầǂǦǇộǦƸƽƾƙǊǦǈƾǃƽ,ǦǋịǦǆǊƶǃǦǃƽƁǃǦǃƐǓǦƸƚǦƽứǃƼǦǉƽƕǦǉƔǂǦƽƾểǊǦǂộǉǦƸƽƕǉǦǀƽƇǃƼ?",
    ["要真是鬼……那 this 鬼能喊出这么大动静，也算是……中气十足，哈哈。"] = "ƩếǊǦđƕǃƼǦǁƐǦǆǊỷ...ǦǉƽƔǦƸǄǃǦǆǊỷǦǃƐǓǦƽƗǉǦđượƸǦǉǄǦǉƽếǦǀƾƶ,ǦƸũǃƼǦƸǄƾǦǃƽưǦǁƐ...ǦǉǇǊǃƼǦǀƽƓǦǤồƾǦǤƐǄǦđấǓ,ǦƽƶǦƽƶ.",
    ["正宗的《霓裳羽衣>变奏，岂是你这样的野路子能懂的？"] = "ƝƾếǃǦǉấǊǦƸƽƓǃƽǦǉƇǃƼǦƸủƶǦ<ƩƼƽƙǦǥƽườǃƼǦƱũǦƴ>,ǦƽƑǦƽạǃƼǦƽọƸǦǂƚǉǦǃƽưǦǃƼươƾǦƸƚǦǉƽểǦƽƾểǊǦđượƸ?",
    ["不需要大场地，不需要长兵器，只要有手掌就能打个回。既能提神醒脑，又能强身健体，现在就试试吧！"] = "ƦƽƇǃƼǦƸầǃǦƷƃƾǦǉậǅǦǁớǃ,ǦǀƽƇǃƼǦƸầǃǦƷƾǃƽǦǀƽƓǦǤƐƾ,ǦƸƽỉǦƸầǃǦƸƚǦƷƐǃǦǉƶǓǦǁƐǦƸƚǦǉƽểǦđƑǃƽǦǆǊƶǦđƑǃƽǦǁạƾ.ǦƱừƶǦƸƚǦǉƽểǦǉỉǃƽǦǉƑǄǦǉƾǃƽǦǉƽầǃ,ǦǋừƶǦƸƚǦǉƽểǦƸườǃƼǦǉƽƁǃǦǀƾệǃǦǉƽể,ǦƽƃǓǦǉƽửǦǃƼƶǓǦđƾ!",
    ["这自然……有些不合适。我们这边人一多，动静太大，反而容易打草惊蛇。还是我一个人方便行事。"] = "ƱƾệƸǦǃƐǓǦǉựǦǃƽƾƙǃ...ǦƸƚǦƸƽƕǉǦǀƽƇǃƼǦổǃ.ǦƝƙǃǦǉƶǦǃƼườƾǦđƇǃƼǦǉƽƔǦđộǃƼǦǉĩǃƽǦǆǊƑǦǁớǃ,ǦǃƼượƸǦǁạƾǦǤễǦđƑǃƽǦǇắǃǦđộǃƼǦƸỏ.ǦƱẫǃǦǁƐǦǂƔǃƽǦǉƶǦƽƐǃƽǦđộǃƼǦǈẽǦǉƽǊậǃǦǉƾệǃǦƽơǃ.",
    ["鬼难追！"] = "ƬǊỷǦƩƶǃǦǥǇǊǓ!",
    ["我还仙难救呢！莫名其妙，赶紧滚蛋. "] = "ǥƶǦƸƛǃǦǥƾƙǃǦƩƶǃǦƞứǊǦđƁǓ!ǦǥƽậǉǦǁƐǦǀỳǦǆǊặƸ,ǦǂƶǊǦƸƕǉǦđƾǦƸƽǄǦǇảǃƽ.",
    ["《这反应……不像有假。难道， i 找错人了？还是说，此人城府极深，在跟我演戏？>"] = "<ƫƽảǃǦứǃƼǦǃƐǓ...ǦǀƽƇǃƼǦƼƾốǃƼǦǃƽưǦƼƾảǦǋờ.ǦƞƽẳǃƼǦǁẽǦǉƶǦǉƔǂǦǃƽầǂǦǃƼườƾǦǇồƾ?ǦƣƶǓǦǁƐǦǀẻǦǃƐǓǦǉƁǂǦƸơǦƸựƸǦǈƁǊ,ǦđƶǃƼǦǤƾễǃǦǀịƸƽǦǋớƾǦǂƔǃƽ?>",
    ["入局之前， i 得去后苑捉只好蛐蛐来！"] = "ǥǇướƸǦǀƽƾǦǋƐǄǦǈƛǃƼ,ǦǉƶǦǅƽảƾǦđếǃǦƽậǊǦǊǓểǃǦƷắǉǦǂộǉǦƸǄǃǦǤếǦǉốǉǦǂớƾǦđượƸ!",
    ["切，等老子把宝贝拿到手，谁还理你们啊。"] = "ƳƔ,ǦđợƾǦǁƃǄǦǉửǦǁấǓǦđượƸǦƷảǄǦƷốƾǦǇồƾǦǉƽƔǦƶƾǦǉƽƘǂǦđếǂǦǍỉƶǦđếǃǦƸƑƸǦǃƼươƾǦǃữƶ.",
    ["嘿嘿，就放床底下，放自己眼皮子底下才安心. 等攒够了钱，咱俩出去买好酒喝！"] = "ƣƙǦƽƙ,ǦƸứǦđểǦǤướƾǦƼầǂǦƼƾườǃƼ,ǦđặǉǦǃƼƶǓǦǤướƾǦǂƓǦǂắǉǦǂƔǃƽǦǂớƾǦǓƙǃǦǉƁǂ.ǦĐợƾǦǉƓƸƽǦđủǦǉƾềǃ,ǦƽƶƾǦǉƶǦđƾǦǇƶǦǃƼǄƐƾǦǂǊƶǦǇượǊǦǃƼǄǃǦǋềǦǊốǃƼ!",
    ["吕娘子怎么还没回来？"] = "ƧữǦǃươǃƼǦǉửǦǈƶǄǦǋẫǃǦƸƽưƶǦǋềǦǃƽỉ?",
    ["诶，武德司的人？要不要来一局？"] = "ƣƙ,ǦǃƼườƾǦƸủƶǦƱƅǦĐứƸǦǥǓǦƐ?ǦƞƚǦǂǊốǃǦǁƐǂǦǂộǉǦǋƑǃǦǀƽƇǃƼ?",
    ["这都等了多久了，一时半会儿回不来的，先来一局，保持手感！"] = "ĐƃǦđợƾǦƷƶǄǦǁƁǊǦǇồƾ,ǦǃƽấǉǦǉƽờƾǦƸƽưƶǦǋềǦđượƸǦđƁǊ,ǦƸứǦǁƐǂǦǂộǉǦǋƑǃǦǉǇướƸǦđƃǦđểǦƼƾữǦƸảǂǦƼƾƑƸ!",
    ["还得是官人有见识！我都没见过这等宝贝！"] = "ĐƕǃƼǦǁƐǦǆǊƶǃǦǃƽƁǃǦƸƚǦǀƾếǃǦǉƽứƸ!ǦǥƶǦƸƛǃǦƸƽưƶǦǉừǃƼǦǉƽấǓǦƷảǄǦƷốƾǦǃƽưǦǉƽếǦǃƐǓǦƷƶǄǦƼƾờ!",
    [" 邈邈"] = "ƨạǄǦƨạǄ",
    ["官人您看着就眼明心亮，又是局外人，她们对您肯定没什么防备心！不如……您帮我把她们找出来？就当是陪我们玩一局？"] = "ƬǊƶǃǦǃƽƁǃǦǃƼƐƾǦǉǇƇǃƼǦǉƽậǉǦǉƾǃƽǦǉườǃƼǦƶǃƽǦǂƾǃƽ,ǦǁạƾǦǁƐǦǃƼườƾǦǃƼǄƐƾǦƸǊộƸ,ǦƽọǦđốƾǦǋớƾǦǃƼƐƾǦƸƽắƸǦƸƽắǃǦǀƽƇǃƼǦƸƚǦǁƛǃƼǦǅƽƛǃƼǦƷị!ǦƣƶǓǦǁƐ...ǦǃƼƐƾǦƼƾƕǅǦǉƶǦǉƔǂǦƷọǃǦƽọǦǇƶǦđƾ?ǦƞǄƾǦǃƽưǦǁƐǦƸƽơƾǦƸƖǃƼǦƷọǃǦǉƶǦǂộǉǦǋƑǃ?",
    ["官人留步！快过来帮个忙！"] = "ƬǊƶǃǦǃƽƁǃǦǤừǃƼǦƷướƸ!ǦƨƶǊǦǁạƾǦđƁǓǦƼƾƕǅǦǂộǉǦǉƶǓ!",
    ["官人救命啊！在下是司天监灵台郎李经纬，这会儿是偷摸出来钓鱼！但……"] = "ƬǊƶǃǦǃƽƁǃǦƸứǊǦǂạǃƼ!ǦǥạƾǦƽạǦǁƐǦƧƾǃƽǦĐƐƾǦƧƶǃƼǦƸủƶǦǥƾƙǃǦǥƽƾƙǃǦƢƾƑǂǦ-ǦƧƈǦƦƾǃƽǦƱĩ,ǦđƶǃƼǦǁƗǃǦǁƕǉǦǇƶǦđƁǓǦƸƁǊǦƸƑ!ǦƩƽưǃƼǦǂƐ...",
    ["官人，行行好，帮我个忙，帮我在这儿守着这竿锦鲤王！"] = "ƬǊƶǃǦǃƽƁǃ,ǦǁƐǂǦơǃǦǁƐǂǦǅƽướƸǦƼƾƕǅǦǉƶǦǂộǉǦǉƶǓ,ǦƼƾƕǅǦǉƶǦởǦđƁǓǦƸƶǃƽǦƸƽừǃƼǦƸƑƾǦƸầǃǦƸƁǊǦƞẩǂǦƧƈǦƱươǃƼǦǃƐǓ!",
    ["多谢官人，不然我们玩到忘了时辰，可就糟了. 我这就过去。"] = "ĐƶǦǉạǦǆǊƶǃǦǃƽƁǃ,ǦƷằǃƼǦǀƽƇǃƼǦƷọǃǦǉƶǦƸƽơƾǦđếǃǦǆǊƙǃǦƸảǦƼƾờǦƼƾấƸǦǉƽƔǦƽỏǃƼǦƷƗǉ.ǦǥƶǦǆǊƶǦđƚǦǃƼƶǓǦđƁǓ.",
    ["怎么不算？我请来的帮手，那也是我的本事！对吧，官人？"] = "ƮƶǄǦǁạƾǦǀƽƇǃƼǦǉƓǃƽ?ǦƫƽụǦǉƑǦǉƶǦǂờƾǦǉớƾǦƸũǃƼǦǁƐǦƷảǃǦǁĩǃƽǦƸủƶǦǉƶǦƸƽứ!ǦĐƕǃƼǦǀƽƇǃƼǦǆǊƶǃǦǃƽƁǃ?",
    ["要不是这位官人动作快，还不知道你要找到什么时候呢！"] = "ƩếǊǦǀƽƇǃƼǦǃƽờǦǋịǦǆǊƶǃǦǃƽƁǃǦǃƐǓǦǃƽƶǃƽǦǉƶǓǦǁẹǦǂắǉ,ǦƸƽẳǃƼǦƷƾếǉǦǉỷǦƸƛǃǦǅƽảƾǦǉƔǂǦđếǃǦƷƶǄǦƼƾờǦǃữƶ!",
    ["下次再一起玩儿呀！官人！"] = "ƧầǃǦǈƶǊǦǁạƾǦƸƖǃƼǦƸƽơƾǦǃƽƗ!ǦƬǊƶǃǦǃƽƁǃ!",
    [" 柳槿"] = "ƧƾễǊǦƞẩǃ",
    ["真的吗？多谢官人！您真是天大的好人！"] = "ǥƽậǉǦǈƶǄ?ǦĐƶǦǉạǦǆǊƶǃǦǃƽƁǃ!ǦƩƼƐƾǦđƕǃƼǦǁƐǦđạƾǦƁǃǦǃƽƁǃ!",
    ["这位官人看着能说会道的，要来试一试咱这“大战碎嘴亲戚的一百零八式巧言妙语”吗？"] = "ƱịǦǆǊƶǃǦǃƽƁǃǦǃƐǓǦǉǇƇǃƼǦƸƚǦǋẻǦǀƽƗǄǦăǃǦǀƽƗǄǦǃƚƾ,ǦƸƚǦǂǊốǃǦǉƽửǦǆǊƶǦ\"ƨộǉǦǉǇăǂǦǁẻǦǉƑǂǦǉƽứƸǦǍảǄǦǃƼƇǃǦǤƾệǊǦǃƼữǦđạƾǦƸƽƾếǃǦǉƽƁǃǦǉƽƓƸƽǦǁẻǄǦǂƗǅ\"ǦƸủƶǦǉƶǦǀƽƇǃƼ?",
    ["嗐，官人您有所不知，以往我回乡探亲，总能遇见一帮碎嘴的亲戚说长道短的……"] = "ƣạƾ,ǦǆǊƶǃǦǃƽƁǃǦǃƼƐƾǦǀƽƇǃƼǦƷƾếǉǦđƁǊ,ǦǉǇướƸǦđƁǓǦǂỗƾǦǁầǃǦǉƶǦǋềǦǆǊƙǦǉƽăǂǦǉƽƁǃ,ǦǁƕƸǦǃƐǄǦƸũǃƼǦƼặǅǦǂộǉǦđƑǂǦƽọǦƽƐǃƼǦǁẻǄǦǂƗǅǦǃƚƾǦǇƶǦǃƚƾǦǋƐǄ...",
    ["今年我寻思着，与其被 động 受气，干脆主动出击！"] = "ƩăǂǦǃƶǓǦǉƶǦǃƼƽĩǦǇồƾ,ǦǉƽƶǓǦǋƔǦǉƽụǦđộǃƼǦƸƽịǊǦấǂǦứƸ,ǦƸƽƾǦƷằǃƼǦƸƽủǦđộǃƼǦǍǊấǉǦǀƓƸƽ!",
    ["不瞒官人，现下我已琢磨出了一些应对之策，却到底少了一些临场校验。"] = "ƦƽƇǃƼǦƼƾấǊǦƼƔǦǆǊƶǃǦǃƽƁǃ,ǦƽƾệǃǦǉạƾǦǉƶǦđƃǦǃƼƽƾềǃǦǃƼẫǂǦǇƶǦǋƐƾǦǀếǦǈƑƸƽǦđốƾǦǅƽƚ,ǦǃƽưǃƼǦǇốǉǦƸǊộƸǦǋẫǃǦǉƽƾếǊǦƸƽƕǉǦǉƽựƸǦǉếǦǀƾểǂǦƸƽứǃƼ.",
    ["是以，我想请官人扮演那些碎嘴亲戚，陪我操练一番，顺道也看我巧言教您该如何见招拆招！"] = "ƱƔǦǋậǓ,ǦǉƶǦǂǊốǃǦǂờƾǦǆǊƶǃǦǃƽƁǃǦđƚǃƼǦǋƶƾǦǃƽữǃƼǦǃƼườƾǦƽọǦƽƐǃƼǦǁẻǄǦǂƗǅǦđƚ,ǦƸƖǃƼǦǉƶǦǉƽƶǄǦǁǊǓệǃǦǂộǉǦǅƽƺǃ,ǦǃƽƁǃǦǉƾệǃǦǍƺǂǦǉƶǦǤƖǃƼǦǁờƾǦƽƶǓǦƈǦđẹǅǦǤạǓǦǃƼƐƾǦƸƑƸƽǦǉƖǓǦƸơǦứǃƼǦƷƾếǃǦǉƽếǦǃƐǄ!",
    ["嘘！……宜圣殿近日似是丢了东西，姑姑们忙得脚不地下，谁有空管我呀？"] = "ƮǊỵǉ!Ǧ...ǦƩƼƽƾǦǥƽƑǃƽǦĐƾệǃǦǤạǄǦǃƐǓǦƽƔǃƽǦǃƽưǦƷịǦǂấǉǦđồ,ǦƸƑƸǦƸƇǦƸƇǦƷậǃǦǇộǃǦđếǃǦǉốƾǦǉăǂǦǂặǉǦǂũƾ,ǦƶƾǦǇảǃƽǦǂƐǦǆǊảǃǦǉƶǦƸƽứ?",
    ["等今儿这差事交了，我想去买点药膏，顺道吃碗老张家的羊肉面 Tun。"] = "ĐợƾǦƽƇǂǦǃƶǓǦƷƐǃǦƼƾƶǄǦǍǄǃƼǦǈƶƾǦǈựǦǃƐǓ,ǦǉƶǦǂǊốǃǦđƾǦǂǊƶǦƓǉǦƸƶǄǦǤượƸ,ǦǉƾệǃǦđườǃƼǦăǃǦƷƑǉǦǂƔǦǉƽịǉǦǤƙǦǃƽƐǦǁƃǄǦǥǇươǃƼ.",
    ["教人须先引人入门，投其所好，方能徐徐图之. "] = "ǝạǓǦǃƼườƾǦǉǇướƸǦƽếǉǦǅƽảƾǦǤẫǃǦǃƼườƾǦǋƐǄǦƸửƶ,ǦǉƽǊậǃǦǉƽƺǄǦǈởǦǉƽƓƸƽǦƸủƶǦƽọ,ǦǂớƾǦƸƚǦǉƽểǦǉừǦǉừǦǉƓǃƽǦǀế.",
    ["您来得正好。这文宴上，您觉得《论语>和》孙子兵法>，讲哪个更能启发武官们的学文之心？"] = "ƩƼƐƾǦđếǃǦđƕǃƼǦǁƕƸǦǁắǂ.ǦǥǇǄǃƼǦǋăǃǦǓếǃǦǃƐǓ,ǦǃƼƐƾǦǉƽấǓǦƼƾữƶǦ<ƧǊậǃǦƩƼữ>ǦǋƐǦ<ǥƇǃǦǥửǦƝƾǃƽǦƫƽƑǅ>,ǦƼƾảǃƼǦƸƑƾǦǃƐǄǦǈẽǦƼợƾǦǂởǦǁƛǃƼǦƽƾếǊǦƽọƸǦǋăǃǦƸƽươǃƼǦƸủƶǦƸƑƸǦǋƅǦǆǊƶǃǦƽơǃ?",
    ["要不《论语>？毕竟凡事都得从头开始。"] = "ƣƶǓǦǁƐǦ<ƧǊậǃǦƩƼữ>?ǦǝƖǦǈƶǄǦǂọƾǦǋƾệƸǦđềǊǦǅƽảƾǦƷắǉǦđầǊǦǉừǦđầǊ.",
    ["话虽如此，可《论语>一书，若武官们不感兴趣，讲也是白费口舌！"] = "ƩƚƾǦǉƽƔǦǋậǓ,ǦǃƽưǃƼǦǈƑƸƽǦ<ƧǊậǃǦƩƼữ>ǦǃếǊǦƸƑƸǦǋƅǦǆǊƶǃǦǀƽƇǃƼǦƽứǃƼǦǉƽƕ,ǦƼƾảǃƼǦƸũǃƼǦƸƽỉǦǁƐǦǅƽƓǦǁờƾ!",
    ["哎呀？！大人都说了《论语>更佳，你怎的还要争辩？！"] = "ÁƾǦƸƽƐ?!ǦĐạƾǦǃƽƁǃǦđƃǦǃƚƾǦ<ƧǊậǃǦƩƼữ>ǦǉốǉǦƽơǃǦǇồƾ,ǦǈƶǄǦǃƼươƾǦƸƛǃǦǂǊốǃǦǉǇƶǃƽǦƷƾệǃ?!",
    ["我看就得是《孙子兵法>！"] = "ǥƶǦǉƽấǓǦǅƽảƾǦǁƐǦ<ǥƇǃǦǥửǦƝƾǃƽǦƫƽƑǅ>ǦǂớƾǦđƕǃƼ!",
    ["你决定什么！明明该讲《论语>！"] = "ƩƼươƾǦǆǊǓếǉǦđịǃƽǦƸƑƾǦƼƔ!ǦƭƅǦǇƐǃƼǦǁƐǦǃƙǃǦƼƾảǃƼǦ<ƧǊậǃǦƩƼữ>!",
    ["行吧，那就别怪我帮二位冷静下。"] = "ĐượƸǦǇồƾ,ǦǋậǓǦǉƽƔǦđừǃƼǦǉǇƑƸƽǦǉƶǦƼƾƕǅǦƽƶƾǦǋịǦƽạǦƽỏƶǦǃƽƗ.",
    ["听着这曲，确实觉得春天近 trong 眼前。"] = "ƩƼƽƺǦǀƽƕƸǦǃƽạƸǦǃƐǓ,ǦđƕǃƼǦǁƐǦǉƽấǓǦǂƖƶǦǍǊƁǃǦđƃǦởǦǃƼƶǓǦǉǇướƸǦǂắǉ.",
    ["其实我只是一只猴子，大家都是这假山上的猴子，终日奔波劳碌，都只是为了摘点桃子吃吃。s"] = "ǥƽựƸǦǇƶǦǉƶǦƸƽỉǦǁƐǦǂộǉǦƸǄǃǦǀƽỉ,ǦǂọƾǦǃƼườƾǦđềǊǦǁƐǦǀƽỉǦǉǇƙǃǦƽƛǃǦƼƾảǦǈơǃǦǃƐǓ,ǦǈǊốǉǦǃƼƐǓǦƷƇǃǦƷƶǦǋấǉǦǋả,ǦƸũǃƼǦƸƽỉǦǋƔǦƽƑƾǦǋƐƾǦǆǊảǦđƐǄǦđểǦăǃǦǉƽƇƾ.",
    ["宫里和外面不一样，骑马注意着点. "] = "ǥǇǄǃƼǦƸǊǃƼǦǀƽƑƸǦǋớƾǦƷƙǃǦǃƼǄƐƾ,ǦƸưỡƾǦǃƼựƶǦǉƽƔǦƸƽƕǦƈǦǂộǉǦƸƽƕǉ.",
    ["军士骑马而行，倒是省了不少脚力. "] = "ƬǊƁǃǦǈĩǦƸưỡƾǦǃƼựƶǦǂƐǦđƾ,ǦǆǊảǦǁƐǦđỡǦǉốǃǦǀƽƇǃƼǦƓǉǦƸƇǃƼǦǈứƸǦđƾǦƷộ.",
    ["新兵，注意距离，仔细别撞到人. "] = "ǥƁǃǦƷƾǃƽ,ǦƸƽƕǦƈǦǀƽǄảǃƼǦƸƑƸƽ,ǦƸẩǃǦǉƽậǃǦǀẻǄǦđụǃƼǦǉǇƕǃƼǦǃƼườƾ.",
    ["那是当然。举办傩仪，自然是为百姓祈福. "] = "ĐƚǦǁƐǦđươǃƼǦǃƽƾƙǃ.ǦǥổǦƸƽứƸǦƩƶǦǃƼƽƾ,ǦǉựǦǃƽƾƙǃǦǁƐǦǋƔǦƷƑƸƽǦǉƓǃƽǦƸầǊǦǅƽƕƸ.",
    ["今日能遇到大人，已是走运了. "] = "ƣƇǂǦǃƶǓǦƼặǅǦđượƸǦđạƾǦǃƽƁǃ,ǦđƕǃƼǦǁƐǦǂƶǓǦǂắǃǦǇồƾ.",
    ["到了到了，祭师大人就在此处，烦请大人诊治. "] = "ĐếǃǦǇồƾǦđếǃǦǇồƾ,ǦǥếǦǈưǦđạƾǦǃƽƁǃǦởǦǃƼƶǓǦđƁǓ,ǦǅƽƾềǃǦđạƾǦǃƽƁǃǦƸƽẩǃǦǉǇịǦƼƾƕǅǦƸƽǄ.",
    ["这位可是……医官？我乃……操持此次皇宫大傩之人，祝娥。$T(5050)万福。"] = "ƱịǦǃƐǓǦƸƽƓǃƽǦǁƐ...ǦǓǦǆǊƶǃǦǈƶǄ?ǦǥƶǦǁƐ...ǦǃƼườƾǦƸƽủǦǉǇƔǦǁễǦĐạƾǦƩƶǦǉǇǄǃƼǦƽǄƐǃƼǦƸǊǃƼǦǁầǃǦǃƐǓ,ǦƞƽƕƸǦƩƼƶ.Ǧ$T(5050)ǦƱạǃǦǅƽƕƸ.",
    ["那是当然。不过要说风调雨顺，无病无灾……还是得他们来。敬神的敬神，为官的为官，仗义的仗义，各自把自己该干的事儿干了，才能让每年都是平安年。"] = "ĐƚǦǁƐǦđươǃƼǦǃƽƾƙǃ.ǦƞƚǦđƾềǊǦǃƚƾǦǋềǦǅƽǄǃƼǦđƾềǊǦǋũǦǉƽǊậǃ,ǦǀƽƇǃƼǦƷệǃƽǦǀƽƇǃƼǦǉƶƾ...ǦǋẫǃǦǁƐǦǅƽảƾǦǉǇƇǃƼǦƸƽờǦǋƐǄǦƷọǃǦƽọ.ǦƦẻǦǀƓǃƽǦǉƽầǃǦƸứǦǀƓǃƽǦǉƽầǃ,ǦǀẻǦǁƐǂǦǆǊƶǃǦƸứǦǁƐǂǦǆǊƶǃ,ǦǀẻǦǉǇượǃƼǦǃƼƽĩƶǦƸứǦǉǇượǃƼǦǃƼƽĩƶ,ǦǂỗƾǦǃƼườƾǦǉựǦǁƐǂǦǉốǉǦǋƾệƸǦƸủƶǦǂƔǃƽ,ǦǉƽƔǦǃăǂǦǃƐǄǦƸũǃƼǦǈẽǦǁƐǦǃăǂǦƷƔǃƽǦƶǃ.",
    ["$T(5050)无需担忧，不过些微代价。生者祝福亡人，总是逾距之事. "] = "$T(5050)ǦǀƽƇǃƼǦƸầǃǦǁǄǦǁắǃƼ,ǦƸƽỉǦǁƐǦƸƽƕǉǦƸƑƾǦƼƾƑǦǃƽỏǦǉƽƇƾ.ǦƩƼườƾǦǈốǃƼǦƸƽƕƸǦǃƼǊǓệǃǦƸƽǄǦǋǄǃƼǦǃƽƁǃǦǋốǃǦǤĩǦǁƐǦƸƽǊǓệǃǦǆǊƑǦƼƾớƾǦƽạǃ.",
    ["只要大傩完成。来年，定是个好年. "] = "ƞƽỉǦƸầǃǦĐạƾǦƩƶǦƽǄƐǃǦǉƽƐǃƽ.ǦƩăǂǦǉớƾ,ǦƸƽắƸǦƸƽắǃǦǈẽǦǁƐǦǂộǉǦǃăǂǦǉốǉǦǁƐǃƽ.",
    ["风吹雨雪，不过观天象、算时日之功. "] = "ƢƾƚǦǉƽổƾǦǂưƶǦǉǊǓếǉ,ǦƸƽẳǃƼǦǆǊƶǦǁƐǦǃƽờǦƸƇǃƼǦǅƽǊǦǍƺǂǦǉƽƾƙǃǦǉượǃƼ,ǦǉƓǃƽǦǉƽờƾǦǀƽắƸǦǂƐǦǉƽƇƾ.",
    ["呵，无趣死板的男人。难怪人家一直不来找 you。"] = "ƣừ,ǦđƕǃƼǦǁƐǦƽạǃƼǦđƐǃǦƇǃƼǦǀƽƇǦǀƽƶǃǦƸứǃƼǦǃƽắƸ.ǦƣƘǃǦƼƔǦǃƼườƾǦǉƶǦƸƽẳǃƼǦƷƶǄǦƼƾờǦǉƔǂǦđếǃǦǃƼươƾ.",
    ["《嗅嗅>嗯？……怎么有股香火燃尽的味道？"] = "<ƩƼửƾǦǃƼửƾ>Ǧƣửǂ?...ǦƮƶǄǦǁạƾǦƸƚǦǂƖƾǦǃƽƶǃƼǦǉƐǃǦǉƽếǦǃƐǓ?",
    ["呀，你不在武德司训练，跑这来玩啦？诶，瞧这小尾 ba 小耳朵……放心， i won‘t go to report you! 你在这多玩会儿！"] = "Ɯ,ǦǃƼươƾǦǀƽƇǃƼǦởǦƱƅǦĐứƸǦǥǓǦƽǊấǃǦǁǊǓệǃǦǂƐǦǁạƾǦƸƽạǓǦđếǃǦđƁǓǦƸƽơƾǦƐ?ǦƦƔƶ,ǦǃƽƔǃǦƸƑƾǦđǊƇƾǦǃƽỏǦǋƐǦǉƶƾǦǃƽỏǦǃƐǓǦǍƺǂ...ǦƴƙǃǦǉƁǂ,ǦǉƶǦǈẽǦǀƽƇǃƼǦđƾǦƷƑǄǦƸƑǄǦǃƼươƾǦđƁǊ!ǦƞứǦƸƽơƾǦởǦđƁǓǦǉƽƙǂǦǁƑǉǦǃữƶǦđƾ!",
    ["捣鼓这宴会可累惨我了，我看啊，这些也不如太后最爱看《踏摇娘>有趣。"] = "ƝậǃǦǇộǃǦƸƽǊẩǃǦƷịǦǓếǃǦǉƾệƸǦǃƐǓǦǁƐǂǦǉƶǦǂệǉǦǁửǦǇồƾ,ǦǉƶǦǉƽấǓǦǂấǓǦǉƽứǦǃƐǓǦƸũǃƼǦƸƽẳǃƼǦǉƽƕǦǋịǦƷằǃƼǦǋởǦ<ĐạǅǦǝƶǄǦƩươǃƼ>ǦǂƐǦǥƽƑƾǦƽậǊǦǉƽƓƸƽǦǃƽấǉ.",
    ["眀深远"] = "ƨƾǃƽǦǥƽƁǂǦƱƾễǃ",
    ["此曲名为《陌上桑>，乃汉时著名但曲，常用于宴饮之时，又为多人协奏之曲。"] = "ƦƽƕƸǦǃƐǓǦǉƙǃǦǁƐǦ<ƨạƸƽǦǥƽượǃƼǦǥƶǃƼ>,ǦǁƐǦǂộǉǦǤƶǃƽǦǀƽƕƸǦǉƽờƾǦƣƑǃ,ǦǉƽườǃƼǦǤƖǃƼǦǉǇǄǃƼǦƸƑƸǦƷǊổƾǦǓếǃǦǉƾệƸ,ǦǁạƾǦǁƐǦǀƽƕƸǦƸƽǄǦǃƽƾềǊǦǃƼườƾǦƸƖǃƼǦƽƛƶǦǉấǊ.",
    ["唔，正好此刻你我无事，不如随我等来一场随性合奏，若是小友弹得好，这《陌上桑>曲谱便赠你！"] = "Ừǂ,ǦđƕǃƼǦǁƕƸǦǃƐǓǦǃƼươƾǦǋƐǦǉƶǦđềǊǦǇảǃƽǦǇỗƾ,ǦƽƶǓǦǁƐǦƸƖǃƼǦǉƶǦǉấǊǦǂộǉǦƷảǃǦǃƼẫǊǦƽứǃƼǦđƾ,ǦǃếǊǦǉƾểǊǦƽữǊǦƼảǓǦƽƶǓ,ǦǉƶǦǈẽǦǉặǃƼǦǃƼươƾǦǅƽổǦǃƽạƸǦ<ƨạƸƽǦǥƽượǃƼǦǥƶǃƼ>ǦǃƐǓ!",
    ["我看《孙子兵法>应是更合适武官性子的文书？"] = "ǥƶǦǉƽấǓǦ<ǥƇǃǦǥửǦƝƾǃƽǦƫƽƑǅ>ǦƸƚǦǁẽǦǁƐǦǋăǃǦǉƽưǦƽợǅǦǋớƾǦǉƓǃƽǦƸƑƸƽǦǋƅǦǆǊƶǃǦƽơǃ?",
    ["根本不牢，如何深修？！还得是《论语>！"] = "ƞăǃǦƷảǃǦǀƽƇǃƼǦǋữǃƼ,ǦǈƶǄǦƸƚǦǉƽểǦǉǊǦƽƐǃƽǦǉƽƁǂǦǈƁǊ?!ǦƫƽảƾǦǁƐǦ<ƧǊậǃǦƩƼữ>ǦǂớƾǦđƕǃƼ!",
    ["你这人真是蛮不讲理，大人可都说了《孙子兵法>更合适！"] = "ƩƼươƾǦđƕǃƼǦǁƐǦƽạǃƼǦǃƼườƾǦǂƶǃǦƷấǉǦƼƾảǃƼǦǁƈ,ǦđạƾǦǃƽƁǃǦđƃǦǃƚƾǦǁƐǦ<ǥƇǃǦǥửǦƝƾǃƽǦƫƽƑǅ>ǦƽợǅǦƽơǃǦǇồƾǦǂƐ!",
    ["哎哟……不服老真是不行了……熬不动了……. "] = "ỐƾǦƸƽƶǄ...ǦǀƽƇǃƼǦǅƽụƸǦƼƾƐǦđƕǃƼǦǁƐǦǀƽƇǃƼǦđượƸǦǇồƾ...ǦǉƽứƸǦǀƽƇǃƼǦǃổƾǦǃữƶǦǇồƾ...",
    ["关乎民生的，象语？如今官署内躲懒的藉口已然如此多样了么？……噢，还有一种可能——官人可有头重脚轻的症状？我可帮忙唤医官前来. "] = "ǥượǃƼǦǃƼữǦǂƐǦǁƾƙǃǦǆǊƶǃǦđếǃǦǤƁǃǦǈƾǃƽǦǈƶǄ?ǦƢƾờǦđƁǓǦǉǇǄǃƼǦǆǊƶǃǦǉƽựǦƸƑƸǦǁǄạƾǦƸớǦđểǦǁườƾǦƷƾếǃƼǦđƃǦđƶǦǤạǃƼǦđếǃǦǉƽếǦǃƐǓǦǇồƾǦƐ?Ǧ...Ồ,ǦƸƛǃǦǂộǉǦǀƽảǦǃăǃƼǦǃữƶ—ǦǆǊƶǃǦǃƽƁǃǦƸƚǦǉǇƾệǊǦƸƽứǃƼǦđầǊǦǃặǃƼǦƸƽƁǃǦǃƽẹǦǀƽƇǃƼ?ǦǥƶǦƸƚǦǉƽểǦƼƾƕǅǦƼọƾǦǓǦǆǊƶǃǦǉớƾ.",
    ["还是判官大​​人想得周到，将这祥瑞请到了我等眼前！如今，本官看这官署，都与往日大不一样了！"] = "ƱẫǃǦǁƐǦƫƽƑǃǦǆǊƶǃǦđạƾǦǃƽƁǃǦǈǊǓǦǃƼƽĩǦǉƽấǊǦđƑǄ,ǦǂờƾǦǉườǃƼǦǉƽụǓǦǃƐǓǦđếǃǦǉǇướƸǦǂắǉǦƸƽƕǃƼǦǉƶ!ǦƢƾờǦđƁǓ,ǦƷảǃǦǆǊƶǃǦǉƽấǓǦǆǊƶǃǦǉƽựǦǃƐǓǦđềǊǦǀƽƑƸǦƽẳǃǦǃƼƐǓǦǉƽườǃƼǦǇồƾ!",
    ["真是佩服……同为朝臣，有的忙起来恨不得生出双翼飞着走，有的却还有闲情逸​​致在这里观鸟赋诗……"] = "ǥƽậǉǦǁƐǦǀƽƁǂǦǅƽụƸ...ǦƸƖǃƼǦǁƐǦǉǇƾềǊǦǉƽầǃ,ǦƸƚǦǃƼườƾǦƷậǃǦđếǃǦǂứƸǦƸƽỉǦǂǊốǃǦǂọƸǦǉƽƙǂǦƸƑǃƽǦǂƐǦƷƶǓ,ǦƸƚǦǃƼườƾǦǁạƾǦƸƛǃǦǃƽƐǃǦǉƔǃƽǦǤậǉǦƸƽƓǦởǦđƁǓǦǃƼắǂǦƸƽƾǂǦǁƐǂǦǉƽơ...",
    ["好！这火驱之法当真的极妙！多谢多谢！"] = "ǥốǉ!ǦƣỏƶǦǀƽǊǦƸƽƾǦǅƽƑǅǦǃƐǓǦǆǊảǦǉƽựƸǦǋƇǦƸƖǃƼǦǤƾệǊǦǀỳ!ǦĐƶǦǉạ,ǦđƶǦǉạ!",
    ["官人看起来并不在意方才阿陀提及的询问象事之人？"] = "ƬǊƶǃǦǃƽƁǃǦǤườǃƼǦǃƽưǦǀƽƇǃƼǦǂấǓǦđểǦǉƁǂǦđếǃǦǃƼườƾǦđƃǦƽỏƾǦǋềǦƸƽǊǓệǃǦǋǄƾǦǂƐǦƜǦĐƐǦǋừƶǦǃƽắƸǦǉớƾ?",
    ["这味道……猛火油？！好啊，贾世仁，看来你不仅贿赂了我，还买通了武德司的其他​​人。"] = "ƨƖƾǦǃƐǓ...ǦƨƃǃƽǦƣỏƶǦǝầǊ?!ǦĐượƸǦǁắǂǦƢƾảǦǥƽếǦƩƽƁǃ,ǦǍƺǂǦǇƶǦǃƼươƾǦǀƽƇǃƼǦƸƽỉǦƽốƾǦǁộǦǉƶǦǂƐǦƸƛǃǦǂǊƶǦƸƽǊộƸǦƸảǦǃƽữǃƼǦǃƼườƾǦǀƽƑƸǦǉǇǄǃƼǦƱƅǦĐứƸǦǥǓǦǃữƶ.",
    ["大人，下官刚刚撰写了一本《驱象策论>，应是能为武德司提供些许助力。"] = "ĐạƾǦǃƽƁǃ,ǦƽạǦǆǊƶǃǦǋừƶǦǂớƾǦǈǄạǃǦǂộǉǦƸǊốǃǦ<ƦƽǊǦǥượǃƼǦƮƑƸƽǦƧǊậǃ>,ǦƸƽắƸǦǁƐǦƸƚǦǉƽểǦƽỗǦǉǇợǦƸƽƕǉǦƓǉǦƸƽǄǦƱƅǦĐứƸǦǥǓ.",
    ["对了，听说你已苦学象语多日，往后也莫要荒废了去. 若你能熟练掌握象语，未来象患，或能大大节约人力。"] = "ƫƽảƾǦǇồƾ,ǦǃƼƽƺǦǃƚƾǦǃƼươƾǦđƃǦǀƽổǦƸƇǃƼǦƽọƸǦǉượǃƼǦǃƼữǦǃƽƾềǊǦǃƼƐǓ,ǦǈƶǊǦǃƐǓǦƸũǃƼǦđừǃƼǦđểǦƽǄƶǃƼǦǅƽế.ǦƩếǊǦǃƼươƾǦƸƚǦǉƽểǦǃắǂǦǋữǃƼǦǉượǃƼǦǃƼữ,ǦǃạǃǦǋǄƾǦǈƶǊǦǃƐǓǦƸƚǦǁẽǦǈẽǦǉƾếǉǦǀƾệǂǦđượƸǦǇấǉǦǃƽƾềǊǦǃƽƁǃǦǁựƸ.",
    ["总归不是毫无收获。抛开你这与恶象搏斗练出的身手不谈，就谈你那本《驱象策论>，若无这几日的奔波，怕也是无法编成的。"] = "ǝƖǦǈƶǄǦƸũǃƼǦǀƽƇǃƼǦǅƽảƾǦǀƽƇǃƼǦƸƚǦǉƽǊǦƽǄạƸƽ.ǦƦƽǄƶǃǦƷƐǃǦđếǃǦǉƽƁǃǦǉƽủǦǤǄǦǃƼươƾǦǋậǉǦǁộǃǦǋớƾǦǋǄƾǦǤữǦǂƐǦǁǊǓệǃǦǉƽƐǃƽ,ǦƸƽỉǦǇƾƙǃƼǦƸǊốǃǦ<ƦƽǊǦǥượǃƼǦƮƑƸƽǦƧǊậǃ>Ǧǀƾƶ,ǦǃếǊǦǀƽƇǃƼǦƸƚǦǂấǓǦǃƼƐǓǦƷƇǃǦƷƶǦǃƐǓ,ǦƺǦǁƐǦƸũǃƼǦƸƽẳǃƼǦǉƽểǦǈǄạǃǦǍǄǃƼ.",
    ["……确实，看起来有点看串了。我找同寝的姐妹要了本《天降福娃：一胎八百八十八宝>，应该药到病除。"] = "...ĐƕǃƼǦǁƐǦǋậǓ,ǦǍƺǂǦƸƽừǃƼǦǁƐǦđọƸǦǁẫǃǦǁộǃǦƽếǉǦǇồƾ.ǦǥƶǦđƃǦǂượǃǦǉỷǦǂǊộƾǦƸƖǃƼǦǅƽƛǃƼǦƸǊốǃǦ<ǥƽƾƙǃǦƢƾƑǃƼǦƫƽƕƸǦƪƶ:ǦƩƽấǉǦǥƽƶƾǦƝƑǉǦƝƑƸƽǦƝƑǉǦǥƽậǅǦƝƑǉǦƝảǄ>,ǦƸƽắƸǦǁƐǦǈẽǦǀƽỏƾǦǃƼƶǓǦǉƽƇƾ.",
    ["这双眼睛，往左往右往上往下，哪哪的好都看了个遍，就是不往自己身上瞧。旁的我也不说了，单凭你这一颗玲珑心，就不知胜了多少人。"] = "ƞƑƾǦđƇƾǦǂắǉǦǃƐǓǦƸủƶǦǂǊộƾ,ǦǃƽƔǃǦǈƶǃƼǦǉǇƑƾǦǈƶǃƼǦǅƽảƾǦǃƽƔǃǦǁƙǃǦǃƽƔǃǦǍǊốǃƼ,ǦƸƽỗǦǃƐǄǦǉốǉǦƸủƶǦǃƼườƾǦǉƶǦƸũǃƼǦǃƽƔǃǦǉƽấǊǦƽếǉ,ǦƸƽỉǦƸƚǦǂỗƾǦƷảǃǦǉƽƁǃǦǂƔǃƽǦǁƐǦǀƽƇǃƼǦƸƽịǊǦǃƽƔǃǦǋƐǄ.ǦƩƽữǃƼǦǉƽứǦǀƽƑƸǦǉỷǦǀƽƇǃƼǦƷƐǃǦǉớƾ,ǦƸƽỉǦǇƾƙǃƼǦǂộǉǦǉấǂǦǁƛǃƼǦǁƾǃƽǦǁǊǃƼǦǃƐǓǦƸủƶǦǂǊộƾǦǉƽƇƾǦđƃǦǀƽƇǃƼǦƷƾếǉǦǁƐǦǋượǉǦǆǊƶǦƷƶǄǦǃƽƾƙǊǦǃƼườƾǦǇồƾ.",
    ["跑酷"] = "ǥƽƁǃǦǅƽƑǅǦǉậǉǦƽƐǃƽ",
    ["当年她出宫时， crying恰好被管事唤去问话了，没能送她。"] = "ƩăǂǦđƚǦǀƽƾǦǂǊộƾǦấǓǦǍǊấǉǦƸǊǃƼ,ǦǉƶǦđƕǃƼǦǁƕƸǦƷịǦǆǊảǃǦǈựǦƼọƾǦđƾǦƽỏƾǦƸƽǊǓệǃǦǃƙǃǦǀƽƇǃƼǦǉƽểǦǉƾễǃǦǂǊộƾǦấǓ.",
    ["还好有你，不然 vạn-vô-nhất-thất ta đều không biết khi nào mới hiểu được ý của muội ấy!"] = "ƞũǃƼǦǂƶǓǦƸƚǦǃƼươƾ,ǦǃếǊǦǀƽƇǃƼǦǉƶǦƸƽẳǃƼǦƷƾếǉǦđếǃǦƷƶǄǦƼƾờǦǂớƾǦƽƾểǊǦđượƸǦƈǦǉứǦƸủƶǦǂǊộƾǦấǓǦǃữƶ!",
    ["那边太湖石后，似乎有位朋友听了许久​​。"] = "ƫƽƓƶǦǈƶǊǦǉảǃƼǦđƑǦǥƽƑƾǦƣồǦǀƾƶ,ǦǤườǃƼǦǃƽưǦƸƚǦǋịǦƷằǃƼǦƽữǊǦđƃǦǁắǃƼǦǃƼƽƺǦƽồƾǦǁƁǊ.",
    ["正是，我们见诸位军爷这般威武，想借这“咚咚”的摔跤声入曲。"] = "ƞƽƓǃƽǦǍƑƸ,ǦƸƽƕǃƼǦǉƶǦǉƽấǓǦƸƽưǦǋịǦǆǊƁǃǦƼƾƶǦǊǓǦǋũǦǉƽếǦǃƐǓ,ǦǂǊốǃǦǂượǃǦǉƾếǃƼǦǋậǉǦǃƽƶǊǦ\"đƖǃƼǦđƖǃƼ\"ǦǀƾƶǦđểǦđưƶǦǋƐǄǦǀƽƕƸǦǃƽạƸ.",
    ["哈哈！摔跤声也能入曲？那你听好了！兄弟们，给这几位露一手！"] = "ƣƶǦƽƶ!ǦǥƾếǃƼǦǋậǉǦǃƽƶǊǦƸũǃƼǦđưƶǦǋƐǄǦǃƽạƸǦđượƸǦǈƶǄ?ǦƱậǓǦǃƼươƾǦǃƼƽƺǦƸƽǄǦǀỹǦǃƽƗ!ǦƣǊǓǃƽǦđệ,ǦƷƾểǊǦǤƾễǃǦƸƽǄǦǂấǓǦǋịǦǃƐǓǦǍƺǂǦǂộǉǦƸƽƾƙǊ!",
    ["哼，误打误撞，不与你争辩.接下来去何处“寻音”？"] = "ƣừ,ǦƸƽẳǃƼǦǆǊƶǦǁƐǦƸƽƚǦǃƼƑǅǦǅƽảƾǦǇǊồƾ,ǦǀƽƇǃƼǦǉǇƶǃƽǦǁǊậǃǦǋớƾǦǃƼươƾ.ǦǥƾếǅǦǉƽƺǄǦđƾǦđƁǊǦ\"ǉầǂǦƁǂ\"ǦđƁǓ?",
    ["等等……大人……哎呀，我今儿正方便呢，实在不方便！要 không ngài mai hãy tới nhé? Lúc đó ta chắc chắn đã giải quyết xong rồi!"] = "ƞƽờǦđƃ...ǦđạƾǦǃƽƁǃ...ǦƶƾǦǤƶ,ǦƽƇǂǦǃƶǓǦǉƶǦđƶǃƼǦ\"ǉƾệǃ\"ǦđƁǓǦǂƐ,ǦǉƽậǉǦǈựǦǀƽƇǃƼǦǉƾệǃǦƸƽƕǉǦǃƐǄ!ǦƣƶǓǦǁƐǦǂƶƾǦǃƼƐƾǦƽƃǓǦǉớƾǦǃƽƗ?ǦƧƕƸǦđƚǦǉƶǦƸƽắƸǦƸƽắǃǦđƃǦƼƾảƾǦǆǊǓếǉǦǍǄǃƼǦǍǊƇƾǦǇồƾ!",
    ["这位是方鹤松方贤弟，乃孤云派弟子。此次是受司天监之邀，以客卿身份入宫，协助我等编撰《应天历>。"] = "ƱịǦǃƐǓǦǁƐǦƫƽươǃƼǦƣạƸǦǥƖǃƼǦƫƽươǃƼǦƽƾềǃǦđệ,ǦƸƽƓǃƽǦǁƐǦđệǦǉửǦǅƽƑƾǦƞƇǦƱƁǃ.ǦƧầǃǦǃƐǓǦđệǦấǓǦǃƽậǃǦǁờƾǦǂờƾǦƸủƶǦǥǓǦǥƽƾƙǃǦƢƾƑǂ,ǦǋƐǄǦƸǊǃƼǦǋớƾǦǉƽƁǃǦǅƽậǃǦǀƽƑƸƽǦǀƽƶǃƽǦđểǦƽỗǦǉǇợǦƸƽƕǃƼǦǉƶǦƷƾƙǃǦǈǄạǃǦ<ỨǃƼǦǥƽƾƙǃǦƧịƸƽ>.",
    ["我孤云一派专研天文历法之学，能为《应天历>之编撰尽力，亦是荣幸。"] = "ƫƽƑƾǦƞƇǦƱƁǃǦǉƶǦƸƽǊǓƙǃǦǃƼƽƾƙǃǦƸứǊǦƽọƸǦǋấǃǦǉƽƾƙǃǦǋăǃǦǁịƸƽǦǅƽƑǅ,ǦƸƚǦǉƽểǦǉậǃǦǁựƸǦǋƔǦǋƾệƸǦƷƾƙǃǦǈǄạǃǦ<ỨǃƼǦǥƽƾƙǃǦƧịƸƽ>,ǦǆǊảǦǉƽựƸǦǁƐǦǋƾǃƽǦƽạǃƽ.",
    ["真出了什么差错，咱家就是一个 trăm cái đầu cũng không đủ đền mạng đâu!"] = "ǥƽựƸǦǈựǦǂƐǦǍảǓǦǇƶǦǈƶƾǦǈƚǉǦƼƔ,ǦǉạǅǦƼƾƶǦǤẫǊǦƸƚǦǂộǉǦǉǇăǂǦƸƑƾǦđầǊǦƸũǃƼǦǀƽƇǃƼǦđủǦđềǃǦǂạǃƼǦđƁǊ!",
    ["点灯的火，我 v lai nghĩ cách.至于那灯烛……既然那位石官人难说动，我去与他分说便是。"] = "ƧửƶǦǉƽắǅǦđƘǃǦđểǦǉƶǦǃƼƽĩǦƸƑƸƽ.ǦƞƛǃǦǋềǦǅƽầǃǦǃếǃ...ǦǃếǊǦǋịǦǥƽạƸƽǦǆǊƶǃǦǃƽƁǃǦǀƾƶǦǀƽƚǦǉƽǊǓếǉǦǅƽụƸ,ǦǉƶǦǈẽǦđƾǦǃƚƾǦǁƈǦǋớƾǦƇǃƼǦǉƶ.",
    ["啊，让军士见笑了……卑职是入宫献艺的乐 công，方才一时意动，手痒想弹些家乡的小调，却怎么弹都不对。"] = "Ɯ,ǦđểǦǆǊƁǃǦǈĩǦƸƽƙǦƸườƾǦǇồƾ...ǦǥǓǦƸƽứƸǦǁƐǦǃƽạƸǦƸƇǃƼǦǋƐǄǦƸǊǃƼǦƽƾếǃǦǃƼƽệ,ǦǋừƶǦǇồƾǦǃƽấǉǦǉƽờƾǦǃổƾǦƽứǃƼ,ǦǃƼứƶǦǉƶǓǦǂǊốǃǦƼảǓǦǋƐƾǦđƾệǊǦǃƽỏǦƸủƶǦǆǊƙǦƽươǃƼ,ǦǃƽưǃƼǦđƐǃǦǉƽếǦǃƐǄǦƸũǃƼǦǀƽƇǃƼǦđƕǃƼ.",
    ["你说是我就是我？万一是有 rén 路过？"] = "ƩƼươƾǦƷảǄǦǁƐǦǉƶǦǉƽƔǦǁƐǦǉƶǦǈƶǄ?ǦƩƽỡǦđƁǊǦƸƚǦǃƼườƾǦđƾǦǃƼƶǃƼǦǆǊƶǦǉƽƔǦǈƶǄ?",
    ["饿了吧？离饭点 còn 好一会 呢，先吃点垫垫？开封口味，和南门大街差不离，凉菜热食都有！"] = "ĐƚƾǦǇồƾǦǅƽảƾǦǀƽƇǃƼ?ǦƞƛǃǦǁƁǊǦǂớƾǦđếǃǦƼƾờǦƸơǂ,ǦăǃǦǉạǂǦƸƽƕǉǦƼƔǦǁƚǉǦǤạǦǃƽƗ?ǦƣươǃƼǦǋịǦƦƽƶƾǦƫƽǄǃƼ,ǦƸũǃƼǦǉươǃƼǦǉựǦǃƽưǦǅƽốǦƩƶǂǦƨƇǃǦǉƽƇƾ,ǦđồǦǃƼǊộƾǦđồǦǃƚǃƼǦđềǊǦƸƚǦƸả!",
    ["都记死了，尚食局里除了你的脚，没有任何东西可以放在地上。东西掉了，捡起来洗干净再用！"] = "ƩƽớǦƸƽǄǦǀỹǦǋƐǄ,ǦởǦǥƽượǃƼǦǥƽựƸǦƞụƸǦǃƐǓǦǃƼǄạƾǦǉǇừǦƷƐǃǦƸƽƁǃǦƸủƶǦǃƼươƾǦǇƶǦǉƽƔǦǀƽƇǃƼǦƸƚǦƷấǉǦƸứǦǉƽứǦƼƔǦđượƸǦǅƽƗǅǦđặǉǦǤướƾǦđấǉ.ǦĐồǦƷịǦǇơƾǦǉƽƔǦǅƽảƾǦǃƽặǉǦǁƙǃǦǇửƶǦǈạƸƽǦǇồƾǦǂớƾǦđượƸǦǤƖǃƼǦǁạƾ!",
    ["官家喜欢蘸着有滋味儿的酱下饭。之前备过腐乳、酱豆。吴御厨觉得太朴素，最近在研究能不能做成肉酱……就是旋鲊。不过这羊肉旋鲊味道还差了点，不算做成，你要先尝尝吗？"] = "ƬǊƶǃǦƼƾƶǦǉƽƓƸƽǦƸƽấǂǦǃướƸǦǍốǉǦđậǂǦđƐǦđểǦđưƶǦƸơǂ.ǦǥǇướƸǦđƁǓǦǉƽườǃƼǦǤƖǃƼǦđậǊǦǅƽụǦǃƽũ,ǦđậǊǦǉươǃƼǦǍốǉ.ǦƩƼƇǦǃƼựǦđầǊǦƷếǅǦǉƽấǓǦǆǊƑǦđơǃǦđƾệǊ,ǦƼầǃǦđƁǓǦđƶǃƼǦǃƼƽƾƙǃǦƸứǊǦǍƺǂǦƸƚǦǉƽểǦǁƐǂǦǉƽƐǃƽǦǍốǉǦǉƽịǉǦǀƽƇǃƼ...ǦƸƽƓǃƽǦǁƐǦǥǄƐǃǦƢƾƑ.ǦƞƚǦđƾềǊǦǂƚǃǦǥǄƐǃǦƢƾƑǦǉƽịǉǦǤƙǦǃƐǓǦǂƖƾǦǋịǦǋẫǃǦƸƛǃǦǉƽƾếǊǦƸƽƕǉǦƼƔǦđƚ,ǦƸƽưƶǦƸǄƾǦǁƐǦǉƽƐǃƽǦƸƇǃƼ,ǦǃƼươƾǦǂǊốǃǦǃếǂǦǉƽửǦǉǇướƸǦǀƽƇǃƼ?",
    ["何况这才能显出咱们尚食局的本事呢. 若是像从前那样饿着肚子等天黑，还有谁有闲心来赏盘子里的山水？"] = "ƣǊốǃƼǦƽồǦǃƽưǦǋậǓǦǂớƾǦƽƾểǃǦƽƾệǃǦđượƸǦƷảǃǦǁĩǃƽǦƸủƶǦǥƽượǃƼǦǥƽựƸǦƞụƸǦƸƽƕǃƼǦǉƶǦƸƽứ.ǦƩếǊǦƸứǦđểǦƷụǃƼǦđƚƾǦđợƾǦđếǃǦǉǇờƾǦǉốƾǦǃƽưǦǉǇướƸǦǀƾƶ,ǦǉƽƔǦƸƛǃǦƶƾǦǉƁǂǦǉǇƓǦđƁǊǦǂƐǦǉƽưởǃƼǦǉƽứƸǦƸảǃƽǦǈơǃǦǉƽủǓǦǉǇǄǃƼǦđĩƶǦƸơǂ?",
    ["你们俩，去那边巡逻，你们俩去这边！大家也都知道，我们现在人手不足，更要把每个时辰掰成两半使！"] = "ƣƶƾǦǃƼườƾǦƸƑƸǦǃƼươƾǦđƾǦǉǊầǃǦƷƙǃǦǀƾƶ,ǦƽƶƾǦǃƼườƾǦđƾǦƷƙǃǦǃƐǓ!ǦƨọƾǦǃƼườƾǦđềǊǦƷƾếǉǦƽƾệǃǦƼƾờǦƸƽƕǃƼǦǉƶǦđƶǃƼǦǉƽƾếǊǦǃƽƁǃǦǉƽủ,ǦǃƙǃǦǅƽảƾǦǉậǃǦǤụǃƼǦǉừǃƼǦǀƽắƸǦǉƽờƾǦƼƾƶǃǦǃƽưǦƸƽƾƶǦđƇƾǦǇƶǦǋậǓ!",
    ["走啊走啊，这大冷天的，买点啥东西吃去. "] = "ĐƾǦǉƽƇƾǦđƾǦǉƽƇƾ,ǦǉǇờƾǦǁạǃƽǦǉƽếǦǃƐǓ,ǦđƾǦǂǊƶǦƸƑƾǦƼƔǦđƚǦăǃǦđƾ.",
    ["是啊！也不知他怎么敢的……先前那个夜闯相府的 Vương tướng quân, 都已经被贬谪到不知道哪个山头去了……"] = "ĐƕǃƼǦǋậǓ!ǦƞƽẳǃƼǦƷƾếǉǦǈƶǄǦƽắǃǦǁạƾǦƼƶǃǦǉƽế...ǦǥǇướƸǦđƚǦǋịǦƱươǃƼǦǉướǃƼǦǆǊƁǃǦđộǉǦǃƽậǅǦǅƽủǦǉướǃƼǦƸƇǃƼǦƸũǃƼǦđƃǦƷịǦƷƾếǂǦǉǇƓƸƽǦđếǃǦƸƑƾǦǍƚǦǍỉǃƽǦǃƐǄǦǇồƾǦǀƽƇǃƼǦƷƾếǉǦǃữƶ...",
    ["大哥好眼力，在下新来不久，见这殿宇巍峨，一时看得出神. "] = "ĐạƾǦƸƶǦǉƽậǉǦǉƾǃƽǦǉườǃƼ,ǦǉạƾǦƽạǦǂớƾǦđếǃǦǀƽƇǃƼǦǁƁǊ,ǦǉƽấǓǦđƾệǃǦǋũǦǃƐǓǦǃƼǊǓǦǃƼƶǦǉǇƑǃƼǦǁệ,ǦǃƽấǉǦǉƽờƾǦǍƺǂǦđếǃǦǍǊấǉǦǉƽầǃ.",
    ["有劳公公. 那便不耽误您了，在下先告退。"] = "ƧƐǂǦǅƽƾềǃǦƸƇǃƼǦƸƇǃƼǦǇồƾ.ǦƱậǓǦǀƽƇǃƼǦǉǇƔǦƽǄƃǃǦǉƽờƾǦƼƾƶǃǦƸủƶǦǃƼƐƾǦǃữƶ,ǦǉạƾǦƽạǦǍƾǃǦƸƑǄǦǉừǦǉǇướƸ.",
    ["眼前这些锣鼓旌旗，皆为大典所用，若有闪失，实在担待不起. "] = "ǥǇướƸǦǂắǉǦđƁǓǦǉǄƐǃǦǁƐǦƸƽƾƙǃƼǦǉǇốǃƼǦƸờǦǍƓǦǤƖǃƼǦƸƽǄǦđạƾǦđƾểǃ,ǦǃếǊǦƸƚǦǈơǦǈǊấǉǦƼƔǦǉƽƔǦǉƽậǉǦǈựǦƼƑǃƽǦǋƑƸǦǀƽƇǃƼǦǃổƾ.",
    ["偶遇斗艺罢了，我不打算声张，二位不必紧张. "] = "ƞƽẳǃƼǦǆǊƶǦǁƐǦǉƔǃƽǦƸờǦƼặǅǦǁƕƸǦđấǊǦǃƼƽệǦǉƽƇƾ,ǦǉƶǦǀƽƇǃƼǦđịǃƽǦǇƙǊǦǇƶǄǦđƁǊ,ǦƽƶƾǦǋịǦǀƽƇǃƼǦƸầǃǦƸăǃƼǦǉƽẳǃƼ.",
    ["即墨嵩华"] = "ǥứƸǦƨặƸǦǥǊǃƼǦƣǄƶ",
    ["准！唐元和八年正月二十二日敕节文！自中及外徒及年月满日！并令奏知！并申牒台省及寺！其徒人便任递归本管！"] = "ƞƽǊẩǃ!ǦĐườǃƼǦƩƼǊǓƙǃǦƣƛƶǦǃăǂǦǉƽứǦǉƑǂ,ǦǃƼƐǓǦƽƶƾǦǂươƾǦƽƶƾǦǉƽƑǃƼǦƢƾƙǃƼǦǈắƸǦǉƾếǉǦǋăǃ!ǦǥựǦǉǇǊǃƼǦƸậǅǦǃƼǄạƾǦđồǦƸậǅǦǃƾƙǃǦǃƼǊǓệǉǦǂƃǃǦǃƽậǉ!ǦǥịǃƽǦǁệǃƽǦǉấǊǦǉǇƾ!ǦǥịǃƽǦǉƽƁǃǦđƾệǅǦǥƽƶƾǦǥỉǃƽǦƸậǅǦǥự!ǦƦỳǦđồǦǃƽƁǃǦǉƾệǃǦǃƽậǂǦđềǦǆǊǓǦƷảǃǦǆǊảǃ!",
    ["是要用这个，啊，谨严的立法，扶正当下的世风，重建人倫道德的规章。用法呢，核心在乎精恕，就是说，要把轻重分得精细又要留有宽恕转圜的余地……"] = "ƧƐǦǅƽảƾǦǤƖǃƼǦƸƑƾǦǃƐǓ,ǦƐ,ǦǁậǅǦǅƽƑǅǦƸẩǃǦǉǇọǃƼǦǃƼƽƾƙǂǦǃƼặǉ,ǦƸƽấǃǦƽưǃƼǦǉƽếǦǅƽǄǃƼǦƽƾệǃǦǉạƾ,ǦǉƑƾǦǉƽƾếǉǦǆǊǓǦƸƽươǃƼǦǃƽƁǃǦǁǊƁǃǦđạǄǦđứƸ.ǦƞƑƸƽǦǤƖǃƼǦǅƽƑǅǦƸốǉǦǓếǊǦǃằǂǦởǦ\"ǉƾǃƽǦǉƽứ\",ǦǉứƸǦǁƐǦǅƽảƾǦǅƽƁǃǦđịǃƽǦǃặǃƼǦǃƽẹǦǉƽậǉǦǉƾǃƽǦǋƾǦǂƐǦǋẫǃǦđểǦǁạƾǦǤưǦđịƶǦǀƽǄƶǃǦǉƽứ,ǦǍǄƶǓǦǍở...",
    ["完了完了完了做不完了……上月做好目录，下月就要完本，哪来这样快的事情……"] = "ƳǄǃƼǦǇồƾǦǍǄǃƼǦǇồƾ,ǦǀƽƇǃƼǦǁƐǂǦǍǄǃƼǦđượƸǦǇồƾ...ǦǥƽƑǃƼǦǉǇướƸǦǋừƶǦǁƐǂǦǍǄǃƼǦǂụƸǦǁụƸ,ǦǉƽƑǃƼǦǈƶǊǦđƃǦǅƽảƾǦǍǄǃƼǦǉǄƐǃǦƷộ,ǦǁấǓǦđƁǊǦǇƶǦƸƽǊǓệǃǦǃƽƶǃƽǦǃƽưǦǋậǓǦƸƽứ...",
    ["木桶？噢！没事，修刑统呢！"] = "ǥƽƖǃƼǦƼỗ?ǦỒ!ǦƦƽƇǃƼǦƸƚǦƼƔǦđƁǊ,ǦđƶǃƼǦǈǄạǃǦƣƔǃƽǦǥƽốǃƼǦđấǓ!",
    ["别急别急别急，我找找。办案，我们武德司专门的。他们如今怎样，能不能问话？"] = "ĐừǃƼǦƸǊốǃƼ,ǦđừǃƼǦƸǊốǃƼ,ǦđểǦǉƶǦǉƔǂǦƸƽǄ.ǦǥǇƶǦƑǃǦǁƐǦƸƽǊǓƙǃǦǂƇǃǦƸủƶǦƱƅǦĐứƸǦǥǓǦƸƽƕǃƼǦǉƶǦǂƐ.ǦƣƾệǃǦƼƾờǦƷọǃǦƽọǦǉƽếǦǃƐǄ,ǦƸƚǦǉƽểǦƽỏƾǦƸƽǊǓệǃǦǀƽƇǃƼ?",
    ["三个月未归家了……人说婴孩一日随风长，也不知道小妹还认得我……"] = "ƝƶǦǉƽƑǃƼǦǇồƾǦƸƽưƶǦǋềǦǃƽƐ...ǦǃƼườƾǦǉƶǦƷảǄǦǉǇẻǦǃƽỏǦǁớǃǦǃƽƶǃƽǦǃƽưǦǉƽổƾ,ǦƸƽẳǃƼǦƷƾếǉǦǉƾểǊǦǂǊộƾǦƸƛǃǦǃƽậǃǦǇƶǦǉƶǦǀƽƇǃƼ...",
    ["如今官家崇文，大殿的名字都从“武成”改成了“文明”，满朝武都憋着劲写锦绣文章，想博个美名。"] = "ƩƶǓǦƬǊƶǃǦƼƾƶǦǈƖǃƼǦǋăǃ,ǦǉƙǃǦƸủƶǦđạƾǦđƾệǃǦƸũǃƼǦđổƾǦǉừǦ\"ƱũǦǥƽƐǃƽ\"ǦǉƽƐǃƽǦ\"ƱăǃǦƨƾǃƽ\",ǦƸảǦǉǇƾềǊǦǋăǃǦǋƅǦđềǊǦđƶǃƼǦǤốƸǦǈứƸǦǋƾếǉǦǃƽữǃƼǦƷƐƾǦƸẩǂǦǉƕǦǋăǃǦƸƽươǃƼǦđểǦǂǄǃƼǦƸầǊǦǁấǓǦǤƶǃƽǦǉƾếǃƼǦǉốǉ.",
    ["《茅厕中传来一阵奔腾之声，门外众人哈哈大笑。>"] = "<ǥǇǄǃƼǦǃƽƐǦǋệǦǈƾǃƽǦǉǇǊǓềǃǦǇƶǦǂộǉǦǉǇƐǃƼǦƁǂǦǉƽƶǃƽǦǇộǃǦǇƃ,ǦđƑǂǦđƇǃƼǦǃƼǄƐƾǦƸửƶǦƸườƾǦǁớǃǦƽƶǦƽả.>",
    ["别打，要打先让我进去再打……"] = "ĐừǃƼǦđƑǃƽǦǃữƶ,ǦƸƚǦđƑǃƽǦǉƽƔǦđểǦǉƶǦǋƐǄǦǉǇǄǃƼǦǍǄǃƼǦǇồƾǦƽẵǃƼǦđƑǃƽ...",
    ["近日来瞧病的，十之五六 đều thị ẩm thực sinh lãnh đạo trí đích tiết lị chi chứng，你和前头那几个一样，回去莫要再食寒凉之物。"] = "ƢầǃǦđƁǓǦǃƼườƾǦđếǃǦǀƽƑǂǦƷệǃƽ,ǦǂườƾǦǅƽầǃǦǉƽƔǦƸƚǦǃăǂǦǈƑǊǦǅƽầǃǦǁƐǦƸƽứǃƼǦǉƾếǉǦǁịǦǤǄǦăǃǦđồǦǈốǃƼǦǁạǃƽ,ǦǃƼươƾǦƸũǃƼǦƼƾốǃƼǦǂấǓǦǃƼườƾǦǅƽƓƶǦǉǇướƸǦǉƽƇƾ,ǦǋềǦǃƽƐǦđừǃƼǦƸƚǦăǃǦđồǦƽƐǃǦǁươǃƼǦǃữƶ.",
    ["不行不行，我还是常来您这儿吧，我要sư hưu tức liễu，miêu đích hoạt thùy lai can？Tái thuyết liễu，yếu thị ngã hồi khứ thành thiên tảng trước，khán trước biệt nhân vãng tử lý can hoạt，bất tri đạo thập ma thời hậu tựu hoạch đắc đầu nhi thưởng thức liễu，giá bỉ sát liễu ngã đô nan thụ a！"] = "ƦƽƇǃƼǦđượƸǦǀƽƇǃƼǦđượƸ,ǦǉƶǦƸứǦǅƽảƾǦǉƽườǃƼǦǍǊǓƙǃǦđếǃǦƸƽỗǦǃƼƐƾǦǉƽƇƾ,ǦǃếǊǦǉƶǦǂƐǦǃƼƽỉǦǃƼơƾǦǉƽƔǦǋƾệƸǦƸủƶǦǉƶǦƶƾǦǁƐǂ?ǦƞƽưƶǦǀể,ǦǃếǊǦǉƶǦǋềǦǃƽƐǦǃằǂǦǀƽểǃƽǦƸảǦǃƼƐǓ,ǦǃƽƔǃǦđứƶǦǀƽƑƸǦǁƐǂǦǋƾệƸǦƷƑǃǦǈốǃƼǦƷƑǃǦƸƽếǉǦǇồƾǦǁọǉǦǋƐǄǦǂắǉǦǍƶǃƽǦƸủƶǦđạƾǦƸƶǦǁƕƸǦǃƐǄǦǀƽƇǃƼǦƽƶǓ,ǦǉƽếǦǉƽƔǦƸƛǃǦǀƽƚǦƸƽịǊǦƽơǃǦƸảǦƼƾếǉǦǉƶǦǃữƶ!",
    ["听说这块闹鬼了？也不知是真假，近日人心惶惶的。"] = "ƩƼƽƺǦǃƚƾǦƸƽỗǦǃƐǓǦƸƚǦǂƶǦƐ?ǦƞƽẳǃƼǦƷƾếǉǦǁƐǦǉƽậǉǦƽƶǓǦƼƾả,ǦǤạǄǦǃƐǓǦǁƛǃƼǦǃƼườƾǦƸứǦƽǄƶǃƼǦǂƶǃƼǦƸảǦǁƙǃ.",
    ["既如此，那便先去取来药方，还姐姐一个清白，剩下的， we mạn mạn giảng tiện thị. "] = "ĐƃǦǋậǓ,ǦǉǇướƸǦǉƾƙǃǦƸứǦđƾǦǁấǓǦđơǃǦǉƽǊốƸǦǋềǦđểǦǉǇảǦǁạƾǦǈựǦǉǇǄǃƼǦǈạƸƽǦƸƽǄǦǉỷǦǉỷ,ǦƸƽǊǓệǃǦƸƛǃǦǁạƾǦƸƽƕǃƼǦǉƶǦƸứǦǉƽǄǃƼǦǉƽảǦǃƚƾǦǉƾếǅ.",
    ["别！不至于闹到这个地步         鹞！你清醒点！"] = "ĐừǃƼ!ǦƦƽƇǃƼǦđếǃǦǂứƸǦǃƽƑǄǦǉớƾǦǃướƸǦǃƐǓǦđƁǊ.ǦǝƾƙǊ!ǦƩƼươƾǦǉỉǃƽǦǉƑǄǦǁạƾǦđƾ!",
    ["你要么现在就拿出乌金打赢我 要么把巨子之位给我 等老头子当上巨子 照样叫你拿出来！我横竖都赢！"] = "ƩƼươƾǦƽǄặƸǦǁƐǦƷƁǓǦƼƾờǦǁấǓǦƆǦƦƾǂǦǇƶǦđƑǃƽǦǉƽắǃƼǦǉƶ,ǦƽǄặƸǦǁƐǦƼƾƶǄǦǋịǦǉǇƓǦƞựǦǥửǦƸƽǄǦǉƶ.ǦĐợƾǦǁƃǄǦǉửǦǁƙǃǦǁƐǂǦƞựǦǥử,ǦǋẫǃǦƷắǉǦǃƼươƾǦǅƽảƾǦǃộǅǦǇƶ!ǦĐườǃƼǦǃƐǄǦǉƶǦƸũǃƼǦǉƽắǃƼ!",
    ["设法出逃"] = "ǥƔǂǦƸƑƸƽǦǉǇốǃǦǉƽǄƑǉ",
    ["戏外人"] = "ƦẻǦǃƼǄƐƾǦǋởǦǤƾễǃ",
    ["好一番寻寻觅觅戏中人影，原来是冷冷清清一场前尘旧梦，怎不教我痛煞煞泪湿琵琶。"] = "ǥƽậǉǦǁƐǦǂộǉǦǅƽƺǃǦǉƔǂǦǉƔǂǦǀƾếǂǦǀƾếǂǦƷƚǃƼǦƽƔǃƽǦǉǇǄǃƼǦǀịƸƽ,ǦƽƚƶǦǇƶǦǁạƾǦǁƐǦǂộǉǦǉǇƐǃƼǦǉƾềǃǦǉǇầǃǦƸựǊǦǂộǃƼǦǁạǃƽǦǁẽǄǦǉƾƙǊǦđƾềǊ,ǦƽỏƾǦǈƶǄǦǀƽƇǃƼǦǀƽƾếǃǦǉƶǦđƶǊǦđớǃǦǁệǦướǉǦǉƔǦƷƐ.",
    ["分发粮食的冯继升与人发生冲突，众人误以为粮食不足，蜂拥而上哄抢起来。\n眼看场面就要失控，晋中原示意你听他指挥， he has a plan。"] = "ƫƽƖǃƼǦƦếǦǥƽăǃƼǦđƶǃƼǦǅƽƑǉǦǁươǃƼǦǉƽựƸǦǉƽƔǦǍảǓǦǇƶǦǍǊǃƼǦđộǉǦǋớƾǦǃƼườƾǦǤƁǃ,ǦǂọƾǦǃƼườƾǦǁầǂǦǉưởǃƼǦǁươǃƼǦǉƽựƸǦǀƽƇǃƼǦđủǦǃƙǃǦƖƶǦǁƙǃǦǉǇƶǃƽǦƸướǅ.\nǥƽấǓǦƸảǃƽǦǉượǃƼǦǈắǅǦǂấǉǦǀƾểǂǦǈǄƑǉ,ǦǥấǃǦǥǇǊǃƼǦƩƼǊǓƙǃǦǇƶǦƽƾệǊǦƸƽǄǦǃƼươƾǦǃƼƽƺǦǉƽƺǄǦƸƽỉǦǉƽịǦƸủƶǦƽắǃ,ǦƽắǃǦƸƚǦƸƑƸƽ.",
    ["定住 him"] = "ĐịǃƽǦǉƽƁǃǦƽắǃ",
    ["李强"] = "ƧƈǦƞườǃƼ",
    ["白雪断山，凄惶何处觅生途。乌金乱城，千算不敌一风误。\n完成指定解锁条件后，即可解锁#G不见山主章【天灾人祸]和】坠日煮海]#E。"] = "ƝạƸƽǦǉǊǓếǉǦđǄạǃǦǈơǃ,ǦǉƽƙǦƽǄƐǃƼǦƽƐǦǍứǦǂịƸƽǦǈƾǃƽǦđồ.ǦƆǦǀƾǂǦǁǄạǃǦǉƽƐǃƽ,ǦǉƽƾƙǃǦǉǄƑǃǦƷấǉǦđịƸƽǦǃƽấǉǦǅƽǄǃƼǦǃƼộ.\nƮƶǊǦǀƽƾǦƽǄƐǃǦǉƽƐǃƽǦđƾềǊǦǀƾệǃǦǂởǦǀƽƚƶǦƸƽỉǦđịǃƽ,ǦǁƾềǃǦƸƚǦǉƽểǦǂởǦǀƽƚƶǦ#GƞƽươǃƼǦƸƽƓǃƽǦƝấǉǦƦƾếǃǦƮơǃǦ[ǥƽƾƙǃǦǥƶƾǦƩƽƁǃǦƣọƶ]ǦǋƐǦ[ǥǇụǓǦƩƽậǉǦƞƽửǦƣảƾ]#E.",
    ["你这轻功，要是改天遇到贼人，就是立功的命. "] = "ƦƽƾǃƽǦƸƇǃƼǦǃƐǓǦƸủƶǦǃƼươƾ,ǦǃếǊǦǃƼƐǓǦǀƽƑƸǦƼặǅǦǅƽảƾǦǉặƸǦǃƽƁǃ,ǦđƕǃƼǦǁƐǦƸƑƾǦǈốǦǁậǅǦƸƇǃƼ.",
    ["她是不是又哼跑调了？好像和官家先前哼的不太一样？"] = "ƞƇǦǉƶǦǁạƾǦǃƼƁǃǦǃƼƶǦǈƶƾǦǃƽạƸǦǇồƾǦƐ?ǦƣƔǃƽǦǃƽưǦǀƽƇǃƼǦƼƾốǃƼǦđƾệǊǦƬǊƶǃǦƼƾƶǦǃƼƁǃǦǃƼƶǦǁƕƸǦǉǇướƸ?",
    ["你不懂欣赏。那是人家的创新，是特色！"] = "ƩƼươƾǦǀƽƇǃƼǦƷƾếǉǦǉƽưởǃƼǦǉƽứƸǦǇồƾ.ǦĐƚǦǁƐǦǈựǦǈƑǃƼǦǉạǄǦƸủƶǦǃƼườƾǦǉƶ,ǦǁƐǦđặƸǦǈắƸ!",
    ["椋楸"] = "ƧươǃƼǦǥƽǊ",
    ["老吕啊，你看你，《孙子兵法>四个字能认识三个都够呛，多少学点，别让人家年轻人看了笑话。"] = "ƧƃǄǦƧữǦƐ,ǦƇǃƼǦǍƺǂǦƇǃƼǦǀƔƶ,ǦƷốǃǦƸƽữǦ<ǥƇǃǦǥửǦƝƾǃƽǦƫƽƑǅ>ǦǂƐǦǃƽậǃǦǇƶǦđượƸǦƷƶǦƸƽữǦđƃǦǁƐǦǀƽƑǦǁắǂǦǇồƾ,ǦƽọƸǦǉƽƙǂǦƸƽƕǉǦđƾ,ǦđừǃƼǦđểǦđƑǂǦǉǇẻǦǃƚǦƸườƾǦƸƽǄ.",
    ["此瑞轮与两壶相联，借滴水之力转动，表月相的朔望弦晦. "] = "ǥƽụǓǦǁǊƁǃǦǃƐǓǦǁƾƙǃǦǀếǉǦǋớƾǦƽƶƾǦƷƔǃƽ,ǦǂượǃǦǈứƸǦǃướƸǦǃƽỏǦƼƾọǉǦđểǦƸƽǊǓểǃǦđộǃƼ,ǦƷƾểǊǦǉƽịǦƸƑƸǦǀỳǦǈƚƸ,ǦǋọǃƼ,ǦƽǊǓềǃ,ǦƽốƾǦƸủƶǦǃƼǊǓệǉǦǉướǃƼ.",
    ["Of course，我压在被褥底下了，保准瞧不出来。"] = "ǝĩǦǃƽƾƙǃǦǇồƾ,ǦǉƶǦƗǅǦǤướƾǦǉấǂǦđệǂ,ǦđảǂǦƷảǄǦǀƽƇǃƼǦƶƾǦǃƽƔǃǦǇƶ.",
    ["方才有两个孩子，一到院子里就往回跑，连荷包掉了都不知道。若你遇见丢荷包的，也许就在找这个. "] = "ƱừƶǦǃƃǓǦƸƚǦƽƶƾǦđứƶǦǉǇẻ,ǦǋừƶǦǉớƾǦǈƁǃǦđƃǦƸƽạǓǦǉƽụƸǦǂạǃƼǦǋề,ǦǃƼƶǓǦƸảǦǉƕƾǦǉƾềǃǦǇơƾǦƸũǃƼǦǀƽƇǃƼǦƷƾếǉ.ǦƩếǊǦǃƼươƾǦƼặǅǦƶƾǦǁƐǂǦǂấǉǦǉƕƾǦǉƾềǃ,ǦƸƚǦǁẽǦƽọǦđƶǃƼǦǉƔǂǦƸƑƾǦǃƐǓ.",
    ["这个时辰躲在这儿睡觉？倒是会找地方. "] = "ƢƾờǦǃƐǓǦǂƐǦǉǇốǃǦởǦđƁǓǦǃƼủǦǈƶǄ?ǦĐƕǃƼǦǁƐǦƷƾếǉǦƸƽọǃǦƸƽỗǦđấǓ.",
    ["我……我正在练习指法呢！对，就是新学的《春江花月夜>，这曲子最是考验功力，得多花些心思揣摩……我可没有闲着！绝对没有！"] = "ǥƶ...ǦǉƶǦđƶǃƼǦǁǊǓệǃǦǉậǅǦƸƽỉǦǅƽƑǅǦǂƐ!ǦĐƕǃƼǦǇồƾ,ǦƸƽƓǃƽǦǁƐǦƷảǃǦ<ƳǊƁǃǦƢƾƶǃƼǦƣǄƶǦƩƼǊǓệǉǦǝạ>ǦǂớƾǦƽọƸ,ǦǀƽƕƸǦǃƽạƸǦǃƐǓǦǀƽảǄǦǃƼƽƾệǂǦƸƇǃƼǦǁựƸǦǃƽấǉ,ǦǅƽảƾǦǉốǃǦǃƽƾềǊǦǉƁǂǦǉưǦǃƼƽƾềǃǦǃƼẫǂ...ǦǉƶǦǀƽƇǃƼǦƸƚǦǇảǃƽǦǇỗƾǦđƁǊ!ǦǥǊǓệǉǦđốƾǦǀƽƇǃƼǦƸƚ!",
    ["门窗都锁好了？香都熄了？这地方要是走了水，我们都得掉脑袋. "] = "ƞửƶǦǃẻǄǦǀƽƚƶǦǀỹǦƸƽưƶ?ǦƣươǃƼǦđƃǦǉắǉǦƽếǉǦƸƽưƶ?ǦƞƽỗǦǃƐǓǦǂƐǦƽỏƶǦƽǄạǃǦǉƽƔǦǉấǉǦƸảǦƸƽƕǃƼǦǉƶǦđềǊǦǂấǉǦđầǊǦđấǓ.",
    ["原来这么难……难怪姐姐你看着这么累. 可费这么大功夫，又是为了什么呢？"] = "ƣƚƶǦǇƶǦǀƽƚǦǃƽưǦǋậǓ...ǦƝảǄǦǈƶǄǦǉỷǦǉỷǦǉǇƇǃƼǦǂệǉǦǂỏƾǦǉƽế.ǦƩƽưǃƼǦǉốǃǦƷƶǄǦƸƇǃƼǦǈứƸǦǃƽưǦǋậǓ,ǦǇốǉǦƸǊộƸǦǁƐǦǋƔǦđƾềǊǦƼƔǦƸƽứ?",
    ["内廷和事佬，知道不？不知道也没关系，横竖是个当官的. "] = "ǥƽǊǓếǉǦǀƽƑƸƽǦǃộƾǦđƔǃƽ,ǦƷƾếǉǦǀƽƇǃƼ?ǦƦƽƇǃƼǦƷƾếǉǦƸũǃƼǦƸƽẳǃƼǦǈƶǄ,ǦǤƖǦǈƶǄǦƸũǃƼǦǁƐǦǂộǉǦƸƽứƸǦǆǊƶǃ.",
    ["嗐，不要在意这些细节~总之，先试试岗再说！"] = "ƣạƾ,ǦđừǃƼǦđểǦƈǦǂấǓǦƸƑƾǦƸƽƾǦǉƾếǉǦđƚ~ǦǥƚǂǦǁạƾ,ǦƸứǦǉƽửǦǋƾệƸǦǉǇướƸǦđƃǦǇồƾǦǉƓǃƽ!",
    ["你们打什么谜呢？"] = "ƞƑƸǦǃƼươƾǦđƶǃƼǦƸƽơƾǦǉǇƛǦƼƾảƾǦđốǦƼƔǦǋậǓ?",
    ["之前患过什么病没有？受伤也算。"] = "ǥǇướƸǦđƁǓǦǉừǃƼǦǂắƸǦƷệǃƽǦƼƔǦƸƽưƶ?ǦƝịǦǉƽươǃƼǦƸũǃƼǦǉƓǃƽǦđấǓ.",
    ["要是俺娘还在，她肯定不让俺来当兵的. "] = "ƩếǊǦǃươǃƼǦƸủƶǦƸǄǃǦƸƛǃǦǈốǃƼ,ǦƷƐǦấǓǦƸƽắƸǦƸƽắǃǦǀƽƇǃƼǦđểǦƸǄǃǦđƾǦǁƓǃƽǦđƁǊ.",
    ["嗯，是有些难办……不不如下次挠他腋下试试？"] = "Ừǂ,ǦđƕǃƼǦǁƐǦƸƚǦƸƽƕǉǦǀƽƚǦƼƾảƾǦǆǊǓếǉ...ǦƽƶǓǦǁƐǦǁầǃǦǈƶǊǦǉƽửǦƼƃƾǦǃƑƸƽǦƽắǃǦǍƺǂ?",
    ["哼，这不，又换了个新人去，结果才不到一旬，那新兵就哭着喊着要辞官回乡，说是“不想再造杀孽”。"] = "ƣừ,ǦǉƽếǦǁƐǦǉƶǦǁạƾǦđổƾǦǂộǉǦǃƼườƾǦǂớƾǦđƾ,ǦǀếǉǦǆǊảǦƸƽưƶǦđầǓǦǂườƾǦǃƼƐǓ,ǦǉƙǃǦǉƁǃǦƷƾǃƽǦđƚǦđƃǦǀƽƚƸǦǁƚƸǦđƛƾǦǉừǦǆǊƶǃǦǋềǦǆǊƙ,ǦǃƚƾǦǁƐǦ\"ǀƽƇǃƼǦǂǊốǃǦǉạǄǦǉƽƙǂǦǈƑǉǦǃƼƽƾệǅ\".",
    ["倒是比去岁好些了……唉，但还是不够数. "] = "ǝƖǦǈƶǄǦƸũǃƼǦǉốǉǦƽơǃǦǃăǂǦǃƼǄƑƾǦƸƽƕǉ...ǦƽƶƾǏ,ǦǃƽưǃƼǦǋẫǃǦǀƽƇǃƼǦđủǦƸǄǃǦǈố.",
    ["回禀长老，现已有二百余人越过嗟叹崖。外头怕是还有四 hundred 之数……"] = "ƝẩǂǦƷƑǄǦǉǇưởǃƼǦǁƃǄ,ǦƽƾệǃǦđƃǦƸƚǦƽơǃǦƽƶƾǦǉǇăǂǦǃƼườƾǦǋượǉǦǆǊƶǦǥƶǦǥƽƑǃǦƩƽƶƾ.ǦƝƙǃǦǃƼǄƐƾǦƺǦǁƐǦƸƛǃǦƸƽừǃƼǦƷốǃǦǉǇăǂǦǃƼườƾǦǃữƶ...",
    ["不……师父说的对……不能不提。"] = "ƦƽƇǃƼ...ǦǈưǦǅƽụǦǃƚƾǦđƕǃƼ...ǦǀƽƇǃƼǦǉƽểǦǀƽƇǃƼǦǃƽắƸǦǉớƾ.",
    ["巨子兼爱世人……何不怜一怜弟子。引狼入室……栖鸟岩之事，不正是前车之鉴吗……"] = "ƞựǦǥửǦǀƾƙǂǦƑƾǦǉƽếǦǃƽƁǃ...ǦǈƶǄǦǀƽƇǃƼǦǍƚǉǦǉƽươǃƼǦđệǦǉửǦǂộǉǦƸƽƕǉ.ǦǝẫǃǦǈƚƾǦǋƐǄǦǃƽƐ...ǦƸƽǊǓệǃǦởǦƦƽƙǦĐƾểǊǦƩƽƶǂǦƸƽẳǃƼǦǅƽảƾǦǁƐǦǋếǉǦǍƺǦđổǦđƚǦǈƶǄ...",
    ["既如此，那鸰儿有最后一请……"] = "ƩếǊǦđƃǦǋậǓ,ǦƧƾǃƽǦƩƽƾǦƸƚǦǁờƾǦǉƽỉǃƽǦƸầǊǦƸǊốƾǦƸƖǃƼ...",
    ["鸰儿，回来。"] = "ƧƾǃƽǦƩƽƾ,ǦǆǊƶǓǦǁạƾ.",
    ["咳。晋公子，听我号令？"] = "Ʀƽụ.ǦǥấǃǦƸƇǃƼǦǉử,ǦǃƼƽƺǦǉƶǦƽƾệǊǦǁệǃƽ?",
    ["少侠此言谬矣。宝物和人命怎可放在一起称量，这种话实在不该从大侠嘴里说出来。"] = "ǥƽƾếǊǦƽƾệǅǦǃƚƾǦǈƶƾǦǇồƾ.ǦƝảǄǦǋậǉǦǋƐǦǂạǃƼǦǃƼườƾǦǈƶǄǦƸƚǦǉƽểǦđặǉǦǁƙǃǦƷƐǃǦƸƁǃǦǈǄǦǈƑǃƽ,ǦǁờƾǦǃƐǓǦǉƽựƸǦǈựǦǀƽƇǃƼǦǃƙǃǦǉƽốǉǦǇƶǦǉừǦǂƾệǃƼǦƸủƶǦǂộǉǦđạƾǦƽƾệǅ.",
    ["……少侠，你知道人为何要长两只手吗？"] = "...ǥƽƾếǊǦƽƾệǅ,ǦƽǊǓǃƽǦƸƚǦƷƾếǉǦǉạƾǦǈƶǄǦƸǄǃǦǃƼườƾǦǁạƾǦƸƚǦƽƶƾǦƷƐǃǦǉƶǓǦǀƽƇǃƼ?",
    ["肺腑之言。"] = "ƧờƾǦǃƚƾǦǉừǦǉậǃǦđƑǓǦǁƛǃƼ.",
    ["我看这座上宾和阶下囚也没两样。关你就算了，把自家巨子也一并关起来算怎么回事……"] = "ǥƶǦǉƽấǓǦǁƐǂǦǀƽƑƸƽǦǆǊƈǦǋớƾǦǁƐǂǦǉƖǦǃƽƁǃǦƸũǃƼǦƸƽẳǃƼǦǀƽƑƸǦƼƔǦǃƽƶǊ.ǦƢƾƶǂǦƽǊǓǃƽǦǉƽƔǦǉƽƇƾǦđƾ,ǦđằǃƼǦǃƐǓǦđếǃǦƞựǦǥửǦǃƽƐǦǂƔǃƽǦƸũǃƼǦƼƾƶǂǦǁǊƇǃǦǁƐǦǈƶǄǦƸƽứ...",
    ["……少侠如此义正词严，自己当真就是干净的吗？"] = "...ǥƽƾếǊǦƽƾệǅǦǁờƾǦǁẽǦƸƽƓǃƽǦǃƼƽĩƶǦǃƽưǦǋậǓ,ǦƷảǃǦǉƽƁǃǦƽǊǓǃƽǦǉƽựƸǦǈựǦǉǇǄǃƼǦǈạƸƽǦǈƶǄ?",
    ["大匠之力，或在乌金。但巨子之权，却在人心. "] = "ƮứƸǦǂạǃƽǦƸủƶǦđạƾǦǉượǃƼǦƸƚǦǁẽǦǃằǂǦởǦƆǦƦƾǂ.ǦƩƽưǃƼǦǆǊǓềǃǦǊǓǦƸủƶǦƞựǦǥửǦǁạƾǦǃằǂǦởǦǁƛǃƼǦǃƼườƾ.",
    ["我也是为墨门计。"] = "ǥƶǦƸũǃƼǦǁƐǦǋƔǦǂưǊǦǉƓǃƽǦƸƽǄǦƨặƸǦƨƇǃ.",
    ["晋公子，人总是要为自己的言行负责的。燕，我们走。"] = "ǥấǃǦƸƇǃƼǦǉử,ǦƸǄǃǦǃƼườƾǦǁǊƇǃǦǅƽảƾǦƸƽịǊǦǉǇƑƸƽǦǃƽƾệǂǦƸƽǄǦǃƼƇǃǦƽƐǃƽǦƸủƶǦǂƔǃƽ.Ǧƴếǃ,ǦƸƽƕǃƼǦǉƶǦđƾ.",
    ["那你就待着吧。"] = "ƱậǓǦǉƽƔǦƽǊǓǃƽǦƸứǦởǦǁạƾǦđƚǦđƾ.",
    ["一个消息，怎么能算昂贵呢。洛神的下落，老身也想尽快知道。"] = "ƨộǉǦǉƾǃǦǉứƸǦǉƽƔǦǈƶǄǦƼọƾǦǁƐǦđắǉǦđỏǦđượƸ.ǦǥǊǃƼǦǉƓƸƽǦƸủƶǦƧạƸǦǥƽầǃ,ǦǁƃǄǦǉƽƁǃǦƸũǃƼǦǂǊốǃǦǈớǂǦƷƾếǉǦđượƸ.",
    ["老身保证你会见到这件东西……至于这位……"] = "ƧƃǄǦǉƽƁǃǦƷảǄǦđảǂǦƽǊǓǃƽǦǈẽǦǉƽấǓǦđượƸǦǉƽứǦđƚ...ǦƸƛǃǦǋềǦǋịǦǃƐǓ...",
    ["要解山中之危，我已有三策。上策自是我们先拿到乌金，方可反客为主，牵着对方走。"] = "ĐểǦƼƾảƾǦǃƼǊǓǦǉǇǄǃƼǦǃƕƾ,ǦǉƶǦđƃǦƸƚǦƷƶǦǀế.ǦǥƽượǃƼǦǈƑƸƽǦđươǃƼǦǃƽƾƙǃǦǁƐǦƸƽƕǃƼǦǉƶǦǁấǓǦđượƸǦƆǦƦƾǂǦǉǇướƸ,ǦǃƽưǦǋậǓǦǂớƾǦƸƚǦǉƽểǦǅƽảǃǦǀƽƑƸƽǦǋƾǦƸƽủ,ǦǤắǉǦǂũƾǦđốƾǦǅƽươǃƼ.",
    ["不过，晋某现在听人号令不得探究乌金下落。破局之事，只能让长老失望了. "] = "ƞƚǦđƾềǊ,ǦǥấǃǦǂỗǦƽƾệǃǦđƶǃƼǦǃƼƽƺǦǉƽƺǄǦƽƾệǊǦǁệǃƽǦƸủƶǦǃƼườƾǦǀƽƑƸ,ǦǀƽƇǃƼǦđượƸǦǤƛǦǍƗǉǦǉǊǃƼǦǉƓƸƽǦƆǦƦƾǂ.ǦƞƽǊǓệǃǦǅƽƑǦƸụƸ,ǦƸƽỉǦđƐǃƽǦǁƐǂǦǉǇưởǃƼǦǁƃǄǦǉƽấǉǦǋọǃƼǦǇồƾ.",
    ["……只能如此了。那还请贵客……"] = "...ǦƞƽỉǦđƐǃƽǦǃƽưǦǋậǓǦǉƽƇƾ.ǦƱậǓǦǅƽƾềǃǦǆǊƈǦǀƽƑƸƽ...",
    ["老身提前谢过二位，要事在身，失陪了。"] = "ƧƃǄǦǉƽƁǃǦǉạǦơǃǦƽƶƾǦǋịǦǉǇướƸ,ǦǋƔǦƸƚǦǋƾệƸǦǆǊƶǃǦǉǇọǃƼ,ǦǍƾǃǦƸƑǄǦǁỗƾǦǀƽƇǃƼǦǉƽểǦǉƾếǅǦƸƽǊǓệǃǦǉƾếǅ.",
    ["老身担心巨子，烦请二位护卫巨子左右，尽心竭力，一步不离。"] = "ƧƃǄǦǉƽƁǃǦǁǄǦƸƽǄǦƞựǦǥử,ǦǅƽƾềǃǦƽƶƾǦǋịǦƽộǦǋệǦƽƶƾǦƷƙǃǦƞựǦǥử,ǦǉậǃǦǉƁǂǦǉậǃǦǁựƸ,ǦƷướƸǦǀƽƇǃƼǦǇờƾǦǃửƶǦƷướƸ.",
    ["承蒙救命之恩，自是听从少侠号令。"] = "ĐƃǦǂƶǃƼǦơǃǦƸứǊǦǂạǃƼ,ǦǉựǦǃƽƾƙǃǦǈẽǦǃƼƽƺǦǉƽƺǄǦƽƾệǊǦǁệǃƽǦƸủƶǦǉƽƾếǊǦƽƾệǅ.",
    ["你知道吗，我小时候也喜欢讲道理。但后来我学了一课……"] = "ƣǊǓǃƽǦƷƾếǉǦǀƽƇǃƼ,ǦǁƕƸǦǃƽỏǦǉƶǦƸũǃƼǦǉƽƓƸƽǦƼƾảǃƼǦđạǄǦǁƈ.ǦƩƽưǃƼǦǈƶǊǦđƚǦǉƶǦđƃǦƽọƸǦđượƸǦǂộǉǦƷƐƾǦƽọƸ...",
    ["干什么……"] = "ƧƐǂǦƼƔǦǉƽế...",
    ["……不要在别人手里有竹条子的时候讲道理！"] = "...ǦĐừǃƼǦƷƶǄǦƼƾờǦƼƾảǃƼǦđạǄǦǁƈǦǀƽƾǦǉǇǄǃƼǦǉƶǓǦǃƼườƾǦǀƽƑƸǦđƶǃƼǦƸƚǦǈẵǃǦǂộǉǦƸƁǓǦǇǄƾǦǉǇƺ!",
    ["我欲探寻桃源真相，才有了与少侠和冯兄的同路之谊. "] = "ǥƶǦǂǊốǃǦǉƔǂǦǀƾếǂǦƸƽƁǃǦǉướǃƼǦĐƐǄǦƩƼǊǓƙǃ,ǦǃƙǃǦǂớƾǦƸƚǦǂốƾǦǉƔǃƽǦǃƼƽĩƶǦđồǃƼǦƽƐǃƽǦƸƖǃƼǦǉƽƾếǊǦƽƾệǅǦǋƐǦƫƽƖǃƼǦƽǊǓǃƽ.",
    ["有了生擒敌首，促成谈判，解阖门上下燃米之急的功劳和手段，门中自是无人再敢不服。只是没想到……"] = "ƞƚǦđượƸǦƸƑƾǦƸƇǃƼǦǋƐǦƸƑƾǦǉƽếǦƸủƶǦǋƾệƸǦǈƾǃƽǦƸầǂǦđịƸƽǦǉƽủ,ǦǉƽƕƸǦđẩǓǦđƐǂǦǅƽƑǃ,ǦƼƾảƾǦǆǊǓếǉǦƸƑƾǦƽọƶǦƸƽƑǓǦǂƐǓǦƸƽǄǦƸảǦǂƇǃǦǅƽƑƾ,ǦǉǇǄǃƼǦǂƇǃǦǉựǦǃƽƾƙǃǦǀƽƇǃƼǦƶƾǦǤƑǂǦǀƽƇǃƼǦǅƽụƸǦǃữƶ.ǦƞƽỉǦǁƐǦǀƽƇǃƼǦǃƼờ...",
    ["那镖是一红衣女子寄出……是她抓的司南剑客，还是司南剑客本就是受她指派……她又是怎么知道鹏长老……"] = "ǥƾƙǊǦđƚǦǁƐǦǤǄǦǂộǉǦǃữǦǉửǦƑǄǦđỏǦƼửƾǦđƾ...ǦƧƐǦƸƇǦǉƶǦƷắǉǦǥưǦƩƶǂǦǀƾếǂǦǀƽƑƸƽ,ǦƽƶǓǦǥưǦƩƶǂǦǀƾếǂǦǀƽƑƸƽǦǋốǃǦǤĩǦǁƐǦǃƼườƾǦƸủƶǦƸƇǦǉƶǦǈƶƾǦǀƽƾếǃ...ǦƧƐǂǦǈƶǄǦƸƇǦǉƶǦƷƾếǉǦđượƸǦƝằǃƼǦǉǇưởǃƼǦǁƃǄ...",
    ["如今我连鹏长老的谋划都和盘托出，二位可能带我一起了？"] = "ƩƶǓǦǉƶǦđƃǦđƺǂǦǉǄƐǃǦƷộǦǂưǊǦđồǦƸủƶǦƝằǃƼǦǉǇưởǃƼǦǁƃǄǦǀƽƶƾǦǇƶǦƽếǉǦǇồƾ,ǦƽƶƾǦǋịǦƸƚǦǉƽểǦǤẫǃǦǉƶǦǉƽƺǄǦƸƖǃƼǦƸƽưƶ?",
    ["啾啾！啾啾啾！"] = "ƞƽƓǊǦƸƽƓǊ!ǦƞƽƓǊǦƸƽƓǊǦƸƽƓǊ!",
    ["新的。城中。"] = "ƨớƾ.ǦỞǦǉǇǄǃƼǦǉƽƐǃƽ.",
    ["他，没有手段……要，找到他。"] = "ƣắǃ,ǦǀƽƇǃƼǦƸƚǦǉƽủǦđǄạǃ...Ǧƫƽảƾ,ǦǉƔǂǦǉƽấǓǦƽắǃ.",
    ["眼睛小小，还有伯乐的本事呢?——等等，鸟兄刚叼了司南剑客的甲片回来，燕，你该不会——"] = "ƨắǉǦǉƽƔǦƷƗǦǉƓǦǂƐǦƸũǃƼǦƸƚǦƷảǃǦǁĩǃƽǦƸủƶǦƝƑǦƩƽạƸǦƸơǦƐ?Ǧ——ǦƦƽǄƶǃǦđƃ,ǦđƾểǊǦƽǊǓǃƽǦǋừƶǦǉƽƶǦǂƾếǃƼǦƼƾƑǅǦƸủƶǦǥưǦƩƶǂǦǀƾếǂǦǀƽƑƸƽǦǋề,Ǧƴếǃ,ǦǀƽƇǃƼǦǁẽǦƸƇǦđịǃƽǦ——",
    ["……我要寻他。"] = "...ǦǥƶǦǂǊốǃǦǉƔǂǦƽắǃ.",
    ["让我看看……要是有人问起来，你就说是我们的妹子。"] = "ĐểǦǉƶǦǍƺǂǦǃƐǄ...ǦǃếǊǦƸƚǦƶƾǦƽỏƾ,ǦƸƇǦƸứǦǃƚƾǦǁƐǦǂǊộƾǦǂǊộƾǦƸủƶǦƷọǃǦǉƶ.",
    ["……导师。"] = "...ǦĐạǄǦǈư.",
    ["导师。"] = "ĐạǄǦǈư.",
    ["学业荒疏。"] = "ƣọƸǦǃƼƽƾệǅǦƽǄƶǃƼǦǅƽế.",
    ["干禄之学。"] = "ƣọƸǦǋấǃǦƸầǊǦǤƶǃƽǦǁợƾ.",
    ["我当为师。"] = "ǥƶǦǁƐǂǦǉƽầǓ.",
    ["我没意见。"] = "ǥƶǦǀƽƇǃƼǦƈǦǀƾếǃ.",
    ["燕也没意见。"] = "ƴếǃǦƸũǃƼǦǀƽƇǃƼǦƈǦǀƾếǃ.",
    ["对了我们得赶快逃出去。接下来听我指挥，我们得绕开鹏长老的那些眼线……"] = "ĐƕǃƼǦǇồƾ,ǦƸƽƕǃƼǦǉƶǦǅƽảƾǦǂƶǊǦƸƽƚǃƼǦǉǇốǃǦǇƶǦǃƼǄƐƾ.ǦǥƾếǅǦǉƽƺǄǦǃƼƽƺǦǉƶǦƸƽỉǦƽǊǓ,ǦƸƽƕǃƼǦǉƶǦǅƽảƾǦǉǇƑǃƽǦǃƗǦǉƶƾǦǂắǉǦƸủƶǦƝằǃƼǦǉǇưởǃƼǦǁƃǄ...",
    ["小心些，偷偷摸摸的……燕，你会偷偷摸摸吗？"] = "ƞẩǃǦǉƽậǃǦƸƽƕǉ,ǦǁƗǃǦǁƕǉǦǋƐǄ...Ǧƴếǃ,ǦƸƇǦƸƚǦƷƾếǉǦƽƐǃƽǦđộǃƼǦǁƗǃǦǁƕǉǦǀƽƇǃƼ?",
    ["偷偷……"] = "ƧƗǃǦǁƕǉ...",
    ["咳。巨子何需在自己门中做贼。光明正大些便是。"] = "Ʀƽụ.ǦƞựǦǥửǦƽƐǦǉấǉǦǅƽảƾǦǁƐǂǦǉǇộǂǦǃƼƶǓǦǉǇǄǃƼǦǂƇǃǦǅƽƑƾǦǂƔǃƽ.ǦƞứǦǆǊƶǃƼǦǂƾǃƽǦƸƽƓǃƽǦđạƾǦǁƐǦđượƸ.",
    ["对。不要紧张，光明正大的偷偷摸摸。"] = "ĐƕǃƼ.ǦĐừǃƼǦƸăǃƼǦǉƽẳǃƼ,ǦƽƃǓǦǁƗǃǦǁƕǉǦǂộǉǦƸƑƸƽǦǆǊƶǃƼǦǂƾǃƽǦƸƽƓǃƽǦđạƾ.",
    ["二位，我乃织网信使。"] = "ƣƶƾǦǋị,ǦǉƶǦǁƐǦƞƽứƸǦƱƅǃƼǦǉƓǃǦǈứ.",
    ["你们哪位曾在此月向织网投稿了？"] = "ƜƾǦǉǇǄǃƼǦƽƶƾǦǋịǦđƃǦƼửƾǦƷƐƾǦƸƽǄǦƞƽứƸǦƱƅǃƼǦǉǇǄǃƼǦǉƽƑǃƼǦǃƐǓǦǉƽế?",
    ["墨门有些规矩还挺有趣的。"] = "ƨặƸǦƨƇǃǦƸƚǦǋƐƾǦǆǊǓǦƸủǦƸũǃƼǦǉƽƕǦǋịǦǉƽậǉ.",
    ["对了，楚墨门下不是多游侠吗？我若是楚墨弟子，说不定已破格得了授号呢！"] = "ĐƕǃƼǦǇồƾ,ǦǤướƾǦǉǇướǃƼǦƮởǦƨặƸǦƸƽẳǃƼǦǅƽảƾǦƸƚǦǃƽƾềǊǦǤǊǦƽƾệǅǦǈƶǄ?ǦƩếǊǦǉƶǦǁƐǦđệǦǉửǦƮởǦƨặƸ,ǦƷƾếǉǦđƁǊǦđƃǦđượƸǦǅƽƑǦƸƑƸƽǦƷƶǃǦƽƾệǊǦǇồƾ!",
    ["我行我素啊……那便是从“我”，合一个“鹅”字。"] = "ƩƼƃǦƽƐǃƽǦǃƼƃǦǉốǦǈƶǄ...ǦǋậǓǦǁƐǦǁấǓǦǉừǦƸƽữǦ\"ƩƼƃ\"Ǧ(ǉƶ),ǦƽợǅǦǋớƾǦƸƽữǦ\"ƩƼƶ\"Ǧ(ƸǄǃǦǃƼỗǃƼ).",
    ["……长飞不落的木鸢。"] = "...ǦƨộƸǦǤƾƙǊǦƷƶǓǦǂƃƾǦǀƽƇǃƼǦǇơƾ.",
    ["前面有悬撞。巨子你……"] = "ƫƽƓƶǦǉǇướƸǦƸƚǦƷẫǓǦǉǇƺǄ.ǦƞựǦǥử,ǦƸƇ...",
    ["哎哟——都来评评理！他们只给熟人粮食，后面的都没有啦——"] = "ỐƾǦƼƾờƾǦơƾǦ——ǦǂọƾǦǃƼườƾǦđếǃǦǂƐǦǅƽƁǃǦǍửǦǍƺǂ!ǦƣọǦƸƽỉǦǅƽƑǉǦǁươǃƼǦǉƽựƸǦƸƽǄǦǃƼườƾǦǆǊƺǃǦǉƽƇƾ,ǦǃƽữǃƼǦǃƼườƾǦǅƽƓƶǦǈƶǊǦƸƽẳǃƼǦƸƛǃǦƼƔǦƸảǦ——",
    ["我有办法！你让人静下来！"] = "ǥƶǦƸƚǦƸƑƸƽ!ǦƣǊǓǃƽǦǁƐǂǦǂọƾǦǃƼườƾǦƷƔǃƽǦǉĩǃƽǦǁạƾǦđƾ!",
    ["净生出这么多条条框框来为难我们，他们自己人徇私枉法就不管……"] = "ƞƽỉǦƼƾỏƾǦƷƐǓǦǇƶǦƷƶǦƸƑƾǦǆǊǓǦǉắƸǦǁằǃƼǦǃƽằǃƼǦđểǦǁƐǂǦǀƽƚǦƸƽƕǃƼǦǉƶ,ǦƸƛǃǦǃƼườƾǦǃƽƐǦǂƔǃƽǦǉưǦǁợƾǦǅƽạǂǦǅƽƑǅǦǉƽƔǦǁạƾǦǁƐǂǦǃƼơ...",
    ["老秀才，那是什么人啊？怪有本事的……"] = "ƧƃǄǦǉƕǦǉƐƾ,ǦǃƼườƾǦđƚǦǁƐǦƶƾǦǋậǓ?ǦǥǇƇǃƼǦǉƐƾǦƼƾỏƾǦǆǊƑ...",
    ["墨门……桃源中竟是墨门！……我们有救了，有救了啊……"] = "ƨặƸǦƨƇǃ...ǦǉǇǄǃƼǦĐƐǄǦƩƼǊǓƙǃǦǁạƾǦƸƽƓǃƽǦǁƐǦƨặƸǦƨƇǃ!Ǧ...ǦƞƽƕǃƼǦǉƶǦƸƚǦƸứǊǦǇồƾ,ǦƸƚǦƸứǊǦǇồƾ...",
    ["是救星！不打仗的大救星！那个黄袍弟子，应是墨门巨子——"] = "ƧƐǦƸứǊǦǉƾǃƽ!ǦƱịǦƸứǊǦǉƾǃƽǦǀƽƇǃƼǦǤƖǃƼǦƸƽƾếǃǦǉǇƶǃƽ!ǦĐệǦǉửǦǂặƸǦƷƐǄǦǋƐǃƼǦđƚ,ǦƸƽắƸǦƽẳǃǦǁƐǦƞựǦǥửǦƸủƶǦƨặƸǦƨƇǃǦ——",
    ["巨子——谢谢——"] = "ƞựǦǥửǦ——ǦƸảǂǦơǃǦ——",
    ["诶！那是巨子的弟子——"] = "Ơ!ǦĐƚǦǁƐǦđệǦǉửǦƸủƶǦƞựǦǥửǦ——",
    ["无事。得人相护。只是，鸟不见了。"] = "ƦƽƇǃƼǦǈƶǄ.ǦƞƚǦǃƼườƾǦƸƽƺǦƸƽở.ǦƞƽỉǦǁƐ,ǦđƾểǊǦƽǊǓǃƽǦǀƽƇǃƼǦǉƽấǓǦđƁǊǦǃữƶ.",
    ["这姑娘长得真可人疼，就是太瘦了些。这腿脚……还、还能治好不？"] = "ƞǄǃǦƷƗǦǃƐǓǦǉǇƇǃƼǦǉƽậǉǦđƑǃƼǦǓƙǊ,ǦǂỗƾǦǉộƾǦƽơƾǦƼầǓ.ǦƞƑƾǦƸƽƁǃǦǃƐǓ...ǦƸƛǃ,ǦƸƛǃǦƸƽữƶǦǀƽỏƾǦđượƸǦǀƽƇǃƼ?",
    ["这姑娘说的啥……我咋没听懂？啥残缺，啥才智……"] = "ƞƇǦƷƗǦǃƐǓǦǃƚƾǦƼƔǦǉƽếǦǃƽỉ...ǦǈƶǄǦǉƶǦǃƼƽƺǦǀƽƇǃƼǦƽƾểǊ?ǦƦƽƾếǂǦǀƽǊǓếǉǦƼƔ,ǦǉƐƾǦǉǇƓǦƼƔ...",
    ["哎哟，冻着了不是？你们几个也是，怎么站在大风地里头说话？"] = "ÁƾǦƸƽƐ,ǦƷịǦǁạǃƽǦǇồƾǦǅƽảƾǦǀƽƇǃƼ?ǦƨấǓǦđứƶǦǃƐǓǦƸũǃƼǦǉƽậǉǦǁƐ,ǦǈƶǄǦǁạƾǦđứǃƼǦƼƾữƶǦǉǇờƾǦǁộǃƼǦƼƾƚǦǉƽếǦǃƐǓǦǂƐǦǃƚƾǦƸƽǊǓệǃ?",
    ["等。等不到，去窝棚。鸟的方向。也是那边。"] = "Đợƾ.ǦĐợƾǦǀƽƇǃƼǦđượƸǦǉƽƔǦđếǃǦǁềǊ.ǦƣướǃƼǦƸủƶǦƸƽƾǂǦƸũǃƼǦǁƐǦǅƽƓƶǦđƚ.",
    ["终于、终于结束了……"] = "ƞǊốƾǦƸƖǃƼ...ǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦǀếǉǦǉƽƕƸǦǇồƾ...",
    ["别，先别扶我，就让我这样跪着向巨子谢罪——"] = "ĐừǃƼ,ǦđừǃƼǦđỡǦǉƶ,ǦƸứǦđểǦǉƶǦǆǊỳǦǉƽếǦǃƐǓǦǂƐǦǉạǦǉộƾǦǋớƾǦƞựǦǥửǦ——",
    ["冯兄放心，你是什么人，我们都看在眼里。巨子这是信你。"] = "ƫƽƖǃƼǦƽǊǓǃƽǦǓƙǃǦǉƁǂ,ǦƽǊǓǃƽǦǁƐǦǃƼườƾǦǉƽếǦǃƐǄǦƸƽƕǃƼǦǉƶǦđềǊǦƽƾểǊǦǇƅ.ǦƞựǦǥửǦǁƐǦđƶǃƼǦǉƾǃǦƽǊǓǃƽǦđấǓ.",
    ["晋公子，你饶了我吧……我宁愿冻着，再不敢穿了……刚刚婶子是不是说她家有热水？我去讨些来……"] = "ǥấǃǦƸƇǃƼǦǉử,ǦƽǊǓǃƽǦǉƽƶǦƸƽǄǦǉƶǦđƾ...ǦǉƶǦǉƽƐǦƸƽịǊǦǁạǃƽǦƸƽứǦƸƽẳǃƼǦǤƑǂǦǂặƸǦǃữƶǦđƁǊ...ǦƱừƶǦǃƃǓǦǉƽẩǂǦǉƽẩǂǦǃƚƾǦǃƽƐǦƷƐǦấǓǦƸƚǦǃướƸǦǃƚǃƼǦǅƽảƾǦǀƽƇǃƼ?ǦĐểǦǉƶǦđƾǦǍƾǃǦǂộǉǦƓǉ...",
    ["他性子单纯执拗。你拿当巨子这事儿开玩笑，冯兄要是当真了，再给他吓得不敢面对同门，和大家生份了。"] = "ǥƓǃƽǦǉƔǃƽǦƽǊǓǃƽǦấǓǦđơǃǦǉƽǊầǃǦǁạƾǦƷướǃƼǦƷỉǃƽ.ǦƣǊǓǃƽǦǁấǓǦǋƾệƸǦǁƐǂǦƞựǦǥửǦǇƶǦǁƐǂǦǉǇƛǦđƖƶ,ǦƫƽƖǃƼǦƽǊǓǃƽǦǂƐǦǉưởǃƼǦǉƽậǉǦǉƽƔǦǈƶǊǦǃƐǓǦƽǊǓǃƽǦấǓǦƸƽẳǃƼǦǤƑǂǦđốƾǦǤƾệǃǦǋớƾǦđồǃƼǦǂƇǃǦǃữƶ,ǦǁạƾǦǈƾǃƽǦǇƶǦǍƶǦƸƑƸƽ.",
    ["师姐——师姐！！鸰儿受伤了！"] = "ƮưǦǉỷǦ——ǦƮưǦǉỷ!!ǦƧƾǃƽǦƩƽƾǦƷịǦǉƽươǃƼǦǇồƾ!",
    ["师姐——！巨子，巨子还在里面！"] = "ƮưǦǉỷǦ——!ǦƞựǦǥử,ǦƞựǦǥửǦǋẫǃǦƸƛǃǦởǦƷƙǃǦǉǇǄǃƼ!",
    ["这群山外人，竟推倒巨子，险遭踩踏……明明承我们的恩……"] = "ĐƑǂǦǃƼườƾǦǃƼǄƐƾǦǃƕƾǦǃƐǓ,ǦǤƑǂǦǍƇǦǃƼƃǦƞựǦǥử,ǦǈǊƈǉǦǃữƶǦǁƐǂǦǃƼườƾǦƷịǦƼƾẫǂǦđạǅ...ǦƭƅǦǇƐǃƼǦǁƐǦǂƶǃƼǦơǃǦƸủƶǦƸƽƕǃƼǦǉƶ...",
    ["恩将仇报，为了蝇头小利……什么都不顾……我定要……"] = "ƧấǓǦǄƑǃǦƷƑǄǦƁǃ,ǦǋƔǦƸƽƕǉǦǁợƾǦǁộƸǦǃƽỏǦǃƽǄƾ...ǦǂƐǦƸƽẳǃƼǦǂƐǃƼǦđếǃǦǉƽứǦƼƔ...ǦǥƶǦǃƽấǉǦđịǃƽǦǈẽ...",
    ["巨子！……鸰儿还伤着，回去治伤要jin。我们……"] = "ƞựǦǥử!...ǦƧƾǃƽǦƩƽƾǦǋẫǃǦƸƛǃǦđƶǃƼǦƷịǦǉƽươǃƼ,ǦǋƾệƸǦǆǊƶǓǦǋềǦǉǇịǦǉƽươǃƼǦǁƐǦǆǊƶǃǦǉǇọǃƼǦǃƽấǉ.ǦƞƽƕǃƼǦǉƶ...",
    ["……既然是巨子吩咐，自当尽力。"] = "...ǦĐƃǦǁƐǦƞựǦǥửǦǅƽƁǃǦǅƽƚ,ǦđươǃƼǦǃƽƾƙǃǦǈẽǦǤốƸǦǈứƸ.",
    ["哎呀，一点都不像。穿黄袍的才是巨子，他又没有黄袍。"] = "ÁƾǦƸƽƐ,ǦƸƽẳǃƼǦƼƾốǃƼǦƸƽƕǉǦǃƐǄ.ǦƩƼườƾǦǂặƸǦƽǄƐǃƼǦƷƐǄǦǂớƾǦǁƐǦƞựǦǥử,ǦƽǊǓǃƽǦấǓǦƸƚǦǂặƸǦƽǄƐǃƼǦƷƐǄǦđƁǊ.",
    ["这红衣是鹏长老赠予客卿的，并非我故意……这黄袍是晋公子给我披上的，并非我故意……"] = "ƝộǦǓǦǅƽụƸǦđỏǦǃƐǓǦǁƐǦƝằǃƼǦǉǇưởǃƼǦǁƃǄǦǉặǃƼǦƸƽǄǦǀƽƑƸƽǦǀƽƶǃƽ,ǦƸƽẳǃƼǦǅƽảƾǦǉƶǦƸốǦƈ...ǦƞƑƾǦƽǄƐǃƼǦƷƐǄǦǃƐǓǦǁƐǦǤǄǦǥấǃǦƸƇǃƼǦǉửǦǀƽǄƑƸǦǁƙǃǦǃƼườƾǦǉƶ,ǦƸũǃƼǦƸƽẳǃƼǦǅƽảƾǦǉƶǦƸốǦƈ...",
    ["不过看这样子，你们现在不吵了？"] = "ƩƽưǃƼǦǍƺǂǦƷộǦǤạǃƼǦǃƐǓ,ǦƼƾờǦǂọƾǦǃƼườƾǦǀƽƇǃƼǦƸƛǃǦƸƃƾǦƸọǦǃƽƶǊǦǃữƶǦǈƶǄ?",
    ["自从你帮我们渡江后， we便合在一块儿讨生活啦。"] = "ǥừǦǈƶǊǦǀƽƾǦƸậǊǦƼƾƕǅǦǉụƾǦǉǊƾǦǆǊƶǦǈƇǃƼ,ǦǂọƾǦǃƼườƾǦđƃǦƽợǅǦǁạƾǦƸƖǃƼǦǃƽƶǊǦǀƾếǂǦǈốǃƼǦǇồƾ.",
    ["好好好，你们都是好孩子，都有都有. 来，妹子一个，小恩人一个！"] = "ĐượƸǦđượƸǦđượƸ,ǦƸƑƸǦƸƽƑǊǦđềǊǦǁƐǦǉǇẻǦǃƼǄƶǃ,ǦđềǊǦƸƚǦǅƽầǃǦƽếǉ.ǦƧạƾǦđƁǓ,ǦǂǊộƾǦǂǊộƾǦǂộǉǦƸƑƾ,ǦǉƾểǊǦƁǃǦǃƽƁǃǦǂộǉǦƸƑƾ!",
    ["饥者不食，骗他人食之。难解。"] = "ƦẻǦđƚƾǦǀƽƇǃƼǦăǃ,ǦǁạƾǦǁừƶǦđểǦǃƼườƾǦǀƽƑƸǦăǃ.ǦƦƽƚǦƽƾểǊ.",
    ["连人家小姑娘都知道帮忙分散件儿，就你一见活儿就跑出去烧水。"] = "ĐếǃǦǃƽưǦƸǄǃǦƷƗǦǀƾƶǦƸƛǃǦƷƾếǉǦƼƾƕǅǦǅƽƁǃǦǁǄạƾǦǁƾǃƽǦǀƾệǃ,ǦƸƽỉǦƸƚǦǃƼươƾǦǁƐǦǋừƶǦǉƽấǓǦǋƾệƸǦđƃǦƸƽạǓǦǉƚǉǦđƾǦđǊǃǦǃướƸ.",
    ["怎么，不让我来？"] = "ƮƶǄ,ǦǀƽƇǃƼǦƸƽǄǦǁƃǄǦǅƽǊǦđếǃǦƐ?",
    ["长老、长老等等我……您走得太快了……"] = "ǥǇưởǃƼǦǁƃǄ,ǦǉǇưởǃƼǦǁƃǄǦđợƾǦƸǄǃǦǋớƾ...ǦƩƼƐƾǦđƾǦǃƽƶǃƽǦǆǊƑ...",
    ["你怎么也来了？诶诶，鹞长老——"] = "ƮƶǄǦƸǄǃǦƸũǃƼǦđếǃǦđƁǓ?ǦƦƔƶǦǀƔƶ,ǦǝƾƙǊǦǉǇưởǃƼǦǁƃǄǦ——",
    ["等，等等我，长——"] = "Đợƾ,ǦđợƾǦƸǄǃǦǋớƾ,ǦǉǇưởǃƼǦ——",
    ["你，你是……"] = "ƩƼƐƾ,ǦǃƼƐƾǦǁƐ...",
    ["你……你……"] = "ƩƼƐƾ...ǦǃƼƐƾ...",
    ["大姐姐，这个爷爷看起来凶巴巴的，好像坏人啊……他平时会打你吗……"] = "ĐạƾǦǉỷǦǉỷ,ǦƇǃƼǦǁƃǄǦǃƐǓǦǉǇƇǃƼǦƽǊǃƼǦǤữǦǆǊƑ,ǦƼƾốǃƼǦǃƽưǦǃƼườƾǦǍấǊǦǋậǓ...ǦƩƼƐǓǦǉƽườǃƼǦƇǃƼǦǉƶǦƸƚǦđƑǃƽǦǉỷǦǀƽƇǃƼ...",
    ["哥哥……"] = "ƞƶǦƸƶ...",
    ["哥哥！真的是哥哥！哥哥——"] = "ƞƶǦƸƶ!ǦĐƕǃƼǦǁƐǦƸƶǦƸƶǦǇồƾ!ǦƞƶǦƸƶǦ——",
    ["他们说哥哥被强盗抓走了，再也不会回来了……"] = "ƣọǦǃƚƾǦƸƶǦƸƶǦƷịǦƸườǃƼǦđạǄǦƷắǉǦđƾǦǇồƾ,ǦǈẽǦǀƽƇǃƼǦƷƶǄǦƼƾờǦǆǊƶǓǦǁạƾǦǃữƶ...",
    ["小磊啊……是小磊回来了……你们站着干啥！赶紧去找芸香啊！"] = "ǥƾểǊǦƧỗƾǦƐ...ǦǥƾểǊǦƧỗƾǦǋềǦǇồƾ...ǦƨấǓǦđứƶǦđứǃƼǦđựƸǦǇƶǦđƚǦǁƐǂǦƼƔ!ǦƨƶǊǦđƾǦǉƔǂǦƱƁǃǦƣươǃƼǦđƾ!",
    ["那这位是……桃源墨家的恩人……"] = "ƱậǓǦǋịǦǃƐǓǦǁƐ...ǦƁǃǦǃƽƁǃǦƸủƶǦĐƐǄǦƩƼǊǓƙǃǦƨặƸǦƼƾƶ...",
    ["你们都围在这里干什么？我还能吃了她？"] = "ƞƑƸǦǃƼườƾǦǋƁǓǦǆǊƶǃƽǦđƁǓǦǁƐǂǦƼƔ?ǦƧƃǄǦǅƽǊǦƸƛǃǦăǃǦǉƽịǉǦđượƸǦƸǄǃǦƷƗǦƸƽắƸ?",
    ["巨子，招呼都不打就偷跑出来，和这群山外人混在一起，玩得还开心吗？"] = "ƞựǦǥử,ǦǀƽƇǃƼǦǂộǉǦǁờƾǦƸƽƐǄǦƽỏƾǦđƃǦǁƗǃǦǉǇốǃǦǇƶǦǃƼǄƐƾ,ǦǁạƾǦƸƛǃǦƸƖǃƼǦđƑǂǦǃƼườƾǦǃƼǄƐƾǦǃƕƾǦǃƐǓǦǉụǦǉậǅǦǂộǉǦƸƽỗ,ǦƸƽơƾǦƸƚǦǋǊƾǦǀƽƇǃƼ?",
    ["让他们留下只是权宜之策。等冬天过了，再放他们出去自谋生路就是. "] = "ĐểǦƽọǦởǦǁạƾǦƸƽỉǦǁƐǦǀếǦǈƑƸƽǦǉạǂǦǉƽờƾ.ǦĐợƾǦǂƖƶǦđƇǃƼǦǆǊƶǦđƾ,ǦǇồƾǦǁạƾǦđểǦƽọǦǇƶǦǃƼǄƐƾǦǉựǦǉƔǂǦđườǃƼǦǈốǃƼǦǉƽƇƾ.",
    ["你们啊……"] = "ĐƑǂǦǉǇẻǦƸƑƸǦƸǄǃǦǉƽậǉǦǁƐ...",
    ["哼……别偷摸着背你那破手了，年纪轻轻官儿瘾不小，别当我不知道是谁在后边儿支的招儿。"] = "ƣừ...ǦđừǃƼǦƸƚǦǂƐǦƼƾấǊǦƼƾấǊǦƼƾếǂǦƼƾếǂǦƸƑƾǦǉƶǓǦǈƶǊǦǁưǃƼǦǃữƶ,ǦǉǇẻǦǉǊổƾǦđầǊǦǂƐǦƸƑƾǦǉƓǃƽǦǉƽƓƸƽǦƸầǂǦǆǊǓềǃǦǀƽƇǃƼǦǃƽỏǦđƁǊ,ǦđừǃƼǦǉưởǃƼǦǁƃǄǦǅƽǊǦǀƽƇǃƼǦƷƾếǉǦǁƐǦƶƾǦđứǃƼǦǈƶǊǦƽƾếǃǦǀế.",
    ["……儿啊，咋了？"] = "...ǦƞǄǃǦƐ,ǦǈƶǄǦǉƽế?",
    ["……娘。我现在是墨家的徒弟啦。门里给我发的工钱，我都攒着呢！……我……我有自己要做的事。"] = "...Ǧƨẹ.ǦƢƾờǦƸǄǃǦǁƐǦđệǦǉửǦƨặƸǦƼƾƶǦǇồƾ.ǦǥƾềǃǦƸƇǃƼǦǂƇǃǦǅƽƑƾǦǅƽƑǉǦƸƽǄ,ǦƸǄǃǦđềǊǦđểǦǤƐǃƽǦƸảǦđấǓ!Ǧ...ǦƞǄǃ...ǦƸǄǃǦƸƚǦǋƾệƸǦǇƾƙǃƼǦǂƔǃƽǦƸầǃǦǁƐǂ.",
    ["坏人爷爷，给你这个。"] = "ƆǃƼǦǃộƾǦǃƼườƾǦǍấǊ,ǦƸƽǄǦƇǃƼǦƸƑƾǦǃƐǓ.",
    ["小桃宝真聪明，是不是啊鹞长老？"] = "ǥƾểǊǦĐƐǄǦƝảǄǦǉƽậǉǦǉƽƇǃƼǦǂƾǃƽ,ǦđƕǃƼǦǀƽƇǃƼǦǝƾƙǊǦǉǇưởǃƼǦǁƃǄ?",
    ["我在此处，等鸟归来。"] = "ǥƶǦởǦđƁǓ,ǦđợƾǦƸƽƾǂǦǆǊƶǓǦǋề.",
    ["好。那我们一起等。说起来鸟兄一路跑到这里，或许司南……嗯？"] = "ĐượƸ.ǦƱậǓǦƸƽƕǃƼǦǉƶǦƸƖǃƼǦđợƾ.ǦƩƽắƸǦǂớƾǦǃƽớǦđƾểǊǦƽǊǓǃƽǦƸƽạǓǦǂộǉǦǂạƸƽǦǉớƾǦđƁǓ,ǦƸƚǦǁẽǦǥưǦƩƶǂ...Ǧƽửǂ?",
    ["嘿嘿嘿……哎恩人，我问你个事儿——那厉害老头，是你俩表叔啊？怪不得你当时一溜烟就没影了呢。"] = "ƣềǦƽềǦƽề...ǦǃƐǓǦƁǃǦǃƽƁǃ,ǦǉƶǦƽỏƾǦǃƼươƾǦƸƽǊǓệǃǦǃƐǓǦ——ǦǁƃǄǦƼƾƐǦǁợƾǦƽạƾǦǀƾƶǦǁƐǦƷƾểǊǦǉƽƕƸǦƸủƶǦƽƶƾǦǃƼườƾǦƐ?ǦƽƘǃǦƸƽƾǦǁƕƸǦđƚǦƸậǊǦƸƽạǓǦǋƘǄǦǂộǉǦƸƑƾǦđƃǦǂấǉǦǤạǃƼ.",
    ["哎哎，你既然认识那什么墨家的人，让他多关照关照咱呗。"] = "ƩƐǓǦǃƐǓ,ǦƸậǊǦđƃǦǆǊƺǃǦƷƾếǉǦǃƼườƾǦƸủƶǦƨặƸǦƼƾƶǦƼƔǦđƚ,ǦǉƽƔǦƷảǄǦƇǃƼǦấǓǦǆǊƶǃǦǉƁǂǦƸƽƾếǊǦƸốǦǉụƾǦǉǊƾǦǉƽƙǂǦƸƽƕǉǦđƾ.",
    ["你说那空房子，是不是……"] = "ƞậǊǦǍƺǂǦǂấǓǦƸăǃǦǃƽƐǦǉǇốǃƼǦǀƾƶ,ǦƸƚǦǅƽảƾǦǁƐ...",
    ["是呀。过两天我们还来看小桃宝好不好？春花婶子，芸香嫂子——"] = "ƫƽảƾǦǇồƾ.ǦƣƶƾǦǃƼƐǓǦǃữƶǦƷọǃǦƸƽƑǊǦǁạƾǦǉớƾǦǉƽăǂǦǥƾểǊǦĐƐǄǦƝảǄǦđượƸǦǀƽƇǃƼ?ǦƳǊƁǃǦƣǄƶǦǉƽẩǂ,ǦƱƁǃǦƣươǃƼǦǉẩǊǦǉửǦ——",
    ["现在砍了树，马上就有柴火。现在烧了荒赶快种上，明年就有粮食吃. 我们不也是想着早点自己养自己吗？只靠你们接济，能养我们几天啊？"] = "ƢƾờǦƸƽặǉǦƸƁǓǦǁƐǦƸƚǦƸủƾǦǃƼƶǓ.ǦƢƾờǦđốǉǦǃươǃƼǦǇồƾǦƼƾƺǄǦƽạǉǦǂƶǊ,ǦǈƶǃƼǦǃăǂǦǁƐǦƸƚǦǁươǃƼǦǉƽựƸǦăǃ.ǦƸƽƕǃƼǦǉƶǦƸƽẳǃƼǦǅƽảƾǦƸũǃƼǦǂǊốǃǦǈớǂǦǉựǦǃǊƇƾǦǈốǃƼǦƷảǃǦǉƽƁǃǦǈƶǄ?ǦƞƽỉǦǤựƶǦǋƐǄǦƸƑƸǦǃƼườƾǦƸứǊǦǉế,ǦǉƽƔǦǃǊƇƾǦđượƸǦƸƽƕǃƼǦǉƶǦǂấǓǦǃƼƐǓ?",
    ["在这儿，就不许你们继续烧山，把水锯停了——"] = "ƞƚǦƷọǃǦǉƶǦởǦđƁǓ,ǦǀƽƇǃƼǦƸƽǄǦǅƽƗǅǦƸƑƸǦǃƼườƾǦǉƾếǅǦǉụƸǦđốǉǦǃƕƾ,ǦǂƶǊǦǤừǃƼǦǉƽủǓǦƸưƶǦǁạƾǦ——",
    ["那边……"] = "ƫƽƓƶǦǀƾƶ...",
    ["我授水击面罗于他。水击面罗，一 như 水碓之制。稍做改动，便可劈砍……是为水锯。"] = "ǥƶǦđƃǦǉǇǊǓềǃǦǤạǓǦǥƽủǓǦƦƓƸƽǦǝƾệǃǦƧƶǦƸƽǄǦƇǃƼǦǉƶ.ǦǥƽủǓǦƦƓƸƽǦǝƾệǃǦƧƶǦƸũǃƼǦǃƽưǦƸƽếǦđộǦƸủƶǦǉƽủǓǦđốƾ.ǦǥƽƶǓǦđổƾǦǂộǉǦƸƽƕǉǦǁƐǦƸƚǦǉƽểǦǤƖǃƼǦđểǦƸƽặǉǦƸƽƗǂ...ǦƸƽƓǃƽǦǁƐǦǉƽủǓǦƸưƶ.",
    ["诶——诶！墨家的小伙子小姑娘——"] = "ÊǦ——Ǧƙ!ǦƨấǓǦƸậǊǦǃƽƚƸǦƸƇǦƷƗǦƨặƸǦƼƾƶǦǀƾƶǦ——",
    ["误会！都是误会——"] = "ƣƾểǊǦǁầǂ!ǦĐềǊǦǁƐǦƽƾểǊǦǁầǂǦƸảǦǉƽƇƾǦ——",
    ["诶诶——唉。"] = "ÊǦƙǦ——ǦƽƶƾǏ.",
    ["倒也不必。既然你们的水锯之法是巨子所授，我们也……"] = "ƞũǃƼǦǀƽƇǃƼǦƸầǃǦǉƽƾếǉǦđƁǊ.ǦƩếǊǦǉƽủǓǦƸưƶǦƸƽƾǦǅƽƑǅǦƸủƶǦƸƑƸǦǃƼườƾǦǁƐǦǤǄǦƞựǦǥửǦǉǇǊǓềǃǦǤạǓ,ǦǉƽƔǦƸƽƕǃƼǦǉƶǦƸũǃƼ...",
    ["哎！但巨子，我有一言，就算您罚我我也要说！"] = "ƣƶƾǏ!ǦƩƽưǃƼǦƞựǦǥử,ǦƸǄǃǦƸƚǦǂộǉǦǁờƾ,ǦǤƖǦǃƼườƾǦƸƚǦǅƽạǉǦƸǄǃǦǉƽƔǦƸǄǃǦƸũǃƼǦǅƽảƾǦǃƚƾ!",
    ["我说什么来着，我说什么来着。你呀，就是没出过山，不知道轻重！"] = "ǥƶǦđƃǦƷảǄǦǂƐ,ǦǉƶǦđƃǦƷảǄǦǂƐ.ǦƞǄǃǦấǓǦƽả,ǦđƕǃƼǦǁƐǦƸƽưƶǦǇƶǦǀƽỏƾǦǃƕƾǦƷƶǄǦƼƾờ,ǦƸƽẳǃƼǦƷƾếǉǦǃặǃƼǦǃƽẹǦǁƐǦƼƔ!",
    ["鹞长老，要下雪了，还请你跟燕一起去春花婶那里先避一避. 等我探查完……我们一起回墨城。"] = "ǝƾƙǊǦǉǇưởǃƼǦǁƃǄ,ǦǈắǅǦǉǊǓếǉǦǇơƾǦǇồƾ,ǦǅƽƾềǃǦǃƼƐƾǦƸƖǃƼǦƴếǃǦǉớƾǦƸƽỗǦƳǊƁǃǦƣǄƶǦǉƽẩǂǦǁƑǃƽǦǉạǂǦǂộǉǦǁƑǉ.ǦĐợƾǦƸǄǃǦǉƽƑǂǦǉƽƓǃƽǦǍǄǃƼ...ǦƸƽƕǃƼǦǉƶǦƸƖǃƼǦǋềǦƨặƸǦǥƽƐǃƽ.",
    ["这仇记到现在啊？我又不是故意的……"] = "ǥƽƖǦǃƐǓǦǂƐǦƽǊǓǃƽǦǃƽớǦđếǃǦǉậǃǦƷƁǓǦƼƾờǦǈƶǄ?ǦǥƶǦđƁǊǦƸƚǦƸốǦƈ...",
    ["我在想，若世上都是冯兄这般的妙人儿就好了。"] = "ǥƶǦđƶǃƼǦǃƼƽĩ,ǦǃếǊǦǉǇƙǃǦđờƾǦǃƐǓǦƶƾǦƸũǃƼǦǁƐǦǃƼườƾǦǉƽƕǦǋịǦǃƽưǦƫƽƖǃƼǦƽǊǓǃƽǦǉƽƔǦǉốǉǦƷƾếǉǦǂấǓ.",
    ["颇有道理。巨子心思单纯，这些异常被你看出来也是难免. 只有一处错误。"] = "ƦƽƑǦƸƚǦǁƈ.ǦƞựǦǥửǦǉƁǂǦǉưǦđơǃǦǉƽǊầǃ,ǦǃƽữǃƼǦđƾểǂǦƷấǉǦǉƽườǃƼǦǃƐǓǦƷịǦƽǊǓǃƽǦǃƽƔǃǦǇƶǦƸũǃƼǦǁƐǦǁẽǦđươǃƼǦǃƽƾƙǃ.ǦƞƽỉǦƸƚǦǂộǉǦƸƽỗǦǈƶƾ.",
    ["巨子！巨子——"] = "ƞựǦǥử!ǦƞựǦǥửǦ——",
    ["巨子——咳咳……"] = "ƞựǦǥửǦ——ǦǀƽụǦǀƽụ...",
    ["呼……巨子在哪儿啊……"] = "ƫƽƖ...ǦƞựǦǥửǦởǦđƁǊǦǇồƾ...",
    ["……太多了。伤痕。"] = "...ǦƩƽƾềǊǦǆǊƑ.ǦƩƽữǃƼǦǋếǉǦǉƽươǃƼ.",
    ["……无法两全，修之……无益。"] = "...ǦƦƽƇǃƼǦǉƽểǦǋẹǃǦƸảǦđƇƾǦđườǃƼ,ǦǈửƶǦǃƚ...ǦƸũǃƼǦǋƇǦƓƸƽ.",
    ["世道，便是世上正道。若我行有偏颇，自有人来纠我。若我肆意行凶，自有人来杀我. "] = "ǥƽếǦđạǄ,ǦƸƽƓǃƽǦǁƐǦƸƽƓǃƽǦđạǄǦǉǇƙǃǦđờƾ.ǦƩếǊǦǉƶǦǁƐǂǦǋƾệƸǦƸƚǦǈƶƾǦǁệƸƽ,ǦǉựǦǀƽắƸǦƸƚǦǃƼườƾǦǉớƾǦǊốǃǦǃắǃ.ǦƩếǊǦǉƶǦǉƖǓǦƈǦǁƐǂǦƑƸ,ǦǉựǦǀƽắƸǦƸƚǦǃƼườƾǦǉớƾǦǁấǓǦǂạǃƼǦǉƶ.",
    ["哇哦。"] = "ƪƶ.",
    ["……真是不得了。既然如此，我也有一个秘密要告诉你。"] = "...ǦĐƕǃƼǦǁƐǦǀƽƇǃƼǦǉầǂǦǉƽườǃƼ.ǦĐƃǦǃƽưǦǋậǓ,ǦǉƶǦƸũǃƼǦƸƚǦǂộǉǦƷƓǦǂậǉǦǂǊốǃǦǃƚƾǦƸƽǄǦƸƇǦƷƾếǉ.",
    ["是呀，开封府那边有几名囚犯得押入天牢，我去接应. "] = "ƫƽảƾǦǋậǓ,ǦƷƙǃǦƦƽƶƾǦƫƽǄǃƼǦǅƽủǦƸƚǦǂấǓǦǉƙǃǦǉƖǦǃƽƁǃǦƸầǃǦƑǅǦƼƾảƾǦǋƐǄǦǥƽƾƙǃǦǁƶǄ,ǦǉƶǦđƾǦǉƾếǅǦứǃƼ.",
    ["启禀陛下，自《官盐阑入法>推行后，各地已破获官盐走私案件共一百三十四起，其中二十五起为蚕盐案，尚待裁决。"] = "ƦƽởƾǦƷẩǂǦƝệǦƽạ,ǦǉừǦǈƶǊǦǀƽƾǦƷƶǃǦƽƐǃƽǦ<ƬǊƶǃǦǝƾƙǂǦƧƶǃǦƩƽậǅǦƫƽƑǅ>,ǦƸƑƸǦǃơƾǦđƃǦǉǇƾệǉǦǅƽƑǦǉổǃƼǦƸộǃƼǦ134ǦǋụǦƷǊƇǃǦǁậǊǦǂǊốƾǦǆǊƶǃ,ǦǉǇǄǃƼǦđƚǦƸƚǦ25ǦǋụǦǁƐǦƑǃǦǂǊốƾǦǉằǂ,ǦǋẫǃǦđƶǃƼǦƸƽờǦǅƽƑǃǦǆǊǓếǉ.",
    ["今日来得最迟的大人会은哪一位呢？"] = "ƣƇǂǦǃƶǓǦǋịǦđạƾǦǃƽƁǃǦđếǃǦǂǊộǃǦǃƽấǉǦǈẽǦǁƐǦƶƾǦđƁǓǦǃƽỉ?",
    ["……哎，我晓得的. 就是想不通——官家当年明明也是都点检出身，现在怎就不肯多偏袒偏袒我们？"] = "...ǦƣƶƾǏ,ǦǉƶǦƷƾếǉǦǂƐ.ǦƞƽỉǦǁƐǦǃƼƽĩǦǀƽƇǃƼǦǉƽƇǃƼǦ——ǦƬǊƶǃǦƼƾƶǦǃăǂǦǍưƶǦǇƅǦǇƐǃƼǦƸũǃƼǦǍǊấǉǦǉƽƁǃǦǉừǦĐƇǦđƾểǂǦǀƾểǂ,ǦǈƶǄǦƼƾờǦǁạƾǦǀƽƇǃƼǦƸƽịǊǦǉƽƾƙǃǦǋịǦƸƽƕǃƼǦǉƶǦǉƽƙǂǦƸƽƕǉǦǃƐǄ?",
    ["《大中刑律统类>……》显德刑统>……"] = "<ĐạƾǦǥǇǊǃƼǦƣƔǃƽǦƧǊậǉǦǥƽốǃƼǦƧǄạƾ>...Ǧ<ƣƾểǃǦĐứƸǦƣƔǃƽǦǥƽốǃƼ>...",
    ["T(30)说不想。廖然，你想人想昏头了！"] = "ǥ(30)ǦǃƚƾǦǀƽƇǃƼǦǂǊốǃ.ǦƧƾƙǊǦƩƽƾƙǃ,ǦƽǊǓǃƽǦǂǊốǃǦǉƔǂǦǃƼườƾǦđếǃǦǁƕǦǁẫǃǦǇồƾ!",
    ["你真要在宴上讲这《论语>？"] = "ƩƼươƾǦđịǃƽǦƼƾảǃƼǦ<ƧǊậǃǦƩƼữ>ǦǃƼƶǓǦǉǇƙǃǦǓếǃǦǉƾệƸǦǉƽậǉǦǈƶǄ?",
    ["为何不讲？凡读书明理，自当以《论语>为本. "] = "ǥạƾǦǈƶǄǦǁạƾǦǀƽƇǃƼǦƼƾảǃƼ?ǦƫƽƐǂǦǁƐǦǃƼườƾǦđọƸǦǈƑƸƽǦƽƾểǊǦđạǄǦǁƈ,ǦđươǃƼǦǃƽƾƙǃǦǅƽảƾǦǁấǓǦ<ƧǊậǃǦƩƼữ>ǦǁƐǂǦƼốƸ.",
    ["台下那些武人，哪听得进？依我看，不如讲《孙子兵法>，他们或许还能懂些皮毛。"] = "ĐƑǂǦǋƅǦǃƽƁǃǦǤướƾǦđƐƾǦǀƾƶǦǁƐǂǦǈƶǄǦǂƐǦǃƼƽƺǦǁọǉǦǉƶƾǦƸƽǄǦđượƸ?ǦǥƽƺǄǦǉƶǦǉƽấǓ,ǦƸƽƾǦƷằǃƼǦƼƾảǃƼǦ<ǥƇǃǦǥửǦƝƾǃƽǦƫƽƑǅ>,ǦƸƚǦǀƽƾǦƽọǦƸƛǃǦƽƾểǊǦđượƸǦƸƽƕǉǦǁƇǃƼǦǉƚƸ.",
    ["柳溪柒"] = "ƧƾễǊǦƦƽƙǦǥƽấǉ",
    ["昭宪太后娘娘，看到了吗，今年也是热热闹闹的一年，真好……"] = "ƞƽƾƙǊǦƣƾếǃǦǥƽƑƾǦƽậǊǦǃươǃƼǦǃươǃƼ,ǦǃƼườƾǦǉƽấǓǦǀƽƇǃƼ,ǦǃăǂǦǃƶǓǦƸũǃƼǦǁƐǦǂộǉǦǃăǂǦǃƑǄǦǃƽƾệǉǦǇộǃǦǇƐǃƼ,ǦǉƽậǉǦǉốǉǦǆǊƑ...",
    ["如今升平楼能再变得热热闹闹的，哪怕换了个模样，想来昭宪太后也会喜欢的。"] = "ƩƶǓǦǥƽăǃƼǦƝƔǃƽǦƧƁǊǦƸƚǦǉƽểǦǃƑǄǦǃƽƾệǉǦǉǇởǦǁạƾ,ǦǤƖǦƸƚǦđổƾǦǈƶǃƼǦǂộǉǦǤƑǃƼǦǋẻǦǀƽƑƸ,ǦǉưởǃƼǦǇằǃƼǦƞƽƾƙǊǦƣƾếǃǦǥƽƑƾǦƽậǊǦƸũǃƼǦǈẽǦǉƽấǓǦǋǊƾǦǁƛǃƼ.",
    ["军士，差事再急也得看路，万一出了点差错，可如何 es好？"] = "ƬǊƁǃǦǈĩ,ǦǈƶƾǦǈựǦǤƖǦƼấǅǦƸũǃƼǦǅƽảƾǦǃƽƔǃǦđườǃƼ,ǦǋạǃǦǃƽấǉǦǍảǓǦǇƶǦǈƶƾǦǈƚǉ,ǦƷƾếǉǦǁƐǂǦǉƽếǦǃƐǄǦƸƽǄǦǅƽảƾ?",
    ["可别这么说！你要 is từ quan rồi，那活不就都到我头上了？"] = "ƞƽớǦƸƚǦǃƚƾǦǋậǓ!ǦƩếǊǦǃƼươƾǦǉừǦǆǊƶǃǦǇồƾ,ǦƸƽẳǃƼǦǅƽảƾǦǋƾệƸǦđềǊǦǤồǃǦƽếǉǦǁƙǃǦđầǊǦǉƶǦǈƶǄ?",
    ["枢密使大人今日怎么总在署里？"] = "ƳǊǦǂậǉǦǈứǦđạƾǦǃƽƁǃǦǈƶǄǦƽƇǂǦǃƶǓǦƸứǦởǦǂƃƾǦǉǇǄǃƼǦǃƽƶǦǉƽựǦǋậǓ?",
    ["听说是夫人出门登高去了，没带他……"] = "ƩƼƽƺǦǃƚƾǦǁƐǦǅƽǊǦǃƽƁǃǦđƾǦđăǃƼǦƸƶǄǦǤǊǦǃƼǄạǃǦǇồƾ,ǦǀƽƇǃƼǦđưƶǦǃƼƐƾǦấǓǦǉƽƺǄ...",
    ["昨日收好的《会计录>卷之七十三去哪里了？"] = "ƬǊǓểǃǦǉƽứǦƷảǓǦǂươƾǦƷƶǦƸủƶǦ<ƦếǦǉǄƑǃǦǁụƸ>ǦǉƽǊǦǤọǃǦƽƇǂǦǆǊƶǦđƁǊǦǇồƾ?",
    ["不错不错，窦大理的典故就写进这里头……"] = "ĐượƸǦđượƸ,ǦđƾểǃǦǉƓƸƽǦƸủƶǦĐậǊǦĐạƾǦƧƈǦƸứǦǋƾếǉǦǋƐǄǦǉǇǄǃƼǦǃƐǓ...",
    ["怎还没听见鼓声？好饿啊……"] = "ƮƶǄǦǋẫǃǦƸƽưƶǦǃƼƽƺǦǉƽấǓǦǉƾếǃƼǦǉǇốǃƼǦǋậǓ?ǦĐƚƾǦǆǊƑǦđƾ...",
    ["若无阁下开解，吾必尚未洞悟……人生向死，一味躊躇，恐只余蹉跎于此生。"] = "ƩếǊǦǀƽƇǃƼǦƸƚǦƸƑƸǦƽạǦǀƽƶƾǦƼƾảƾ,ǦǉƶǦƽẳǃǦǋẫǃǦƸƽưƶǦǉƽấǊǦƽƾểǊ...ǦđờƾǦǃƼườƾǦƽướǃƼǦǋềǦƸƑƾǦƸƽếǉ,ǦǃếǊǦƸứǦǂƃƾǦƸƽầǃǦƸƽừ,ǦƺǦǁƐǦƸƽỉǦƸƛǃǦǁạƾǦǈựǦǊổǃƼǦǅƽƓǦởǦǀƾếǅǦǃƐǓ.",
