    ["-1683694159050703355"] = "ƴếǃǦƽƾềǂǦǉƁǃǦǅƽǄǃƼǦǁƶƾ",
    ["6758082210473550683"] = "ǝướƾǦǈựǦƼƾƕǅǦđỡǦƸủƶǦǂọƾǦǃƼườƾ,ǦƸƇǃƼǦǉƑƸǦǉƑƾǦǉƽƾếǉǦƸơǦƷảǃǦđƃǦƽǄƐǃǦǉƽƐǃƽ.ǦƣƇǂǦǃƶǓǦǁƐǦǂộǉǦǃƼƐǓǦđẹǅǦǉǇờƾ,ǦǂọƾǦǃƼườƾǦđềǊǦƽộƾǦǉụǦǉạƾǦǃơƾǦǃƐǓ.",
    ["父亲，将死。无法指引。令 tôi 停下，封存，等待。"] = "ƫƽụǦǉƽƁǃ,ǦǁƁǂǦƸƽǊǃƼ.ǦƦƽƇǃƼǦǉƽểǦƸƽỉǦǤẫǃ.ǦƧệǃƽǦǉƶǦǤừǃƼǦǁạƾ,ǦǅƽǄǃƼǦǉồǃ,ǦƸƽờǦđợƾ.",
    ["走了？……我是说，从今以后， I 来代替他——"] = "ĐƾǦǇồƾǦǈƶǄ?...ǦÝǦǉƶǦǁƐ,ǦǉừǦǃƶǓǦǋềǦǈƶǊ,ǦǉƶǦǈẽǦǉƽƶǓǦǉƽếǦǃƼườƾ——",
    ["……可操金乌窠者，唯 I 一人。"] = "...ǦƩƼườƾǦƸƚǦǉƽểǦǉƽƶǄǦǉƕǃƼǦƦƾǂǦƆǦƮƐǄ,ǦƸƽỉǦƸƚǦǂƔǃƽǦǉƶ.",
    ["如今，需入门木鸟三百，架为天桥，助 I 登城。"] = "ƩƶǓ,ǦƸầǃǦƷƶǦǉǇăǂǦǂộƸǦđƾểǊǦǃƽậǅǦǂƇǃ,ǦƷắƸǦǉƽƐǃƽǦǉƽƾƙǃǦǀƾềǊ,ǦǉǇợǦǉƶǦđăǃƼǦǉƽƐǃƽ.",
    ["我就知道她一开口就坏事……"] = "ǥƶǦƷƾếǉǦǃƼƶǓǦǂƐ,ǦƸƇǦǉƶǦƸứǦǂởǦǂƾệǃƼǦǁƐǦƽỏǃƼǦǋƾệƸ...",
    ["……只怕，也是唯一可试之法了。"] = "...ǦǑǦǇằǃƼ,ǦđƁǓǦƸũǃƼǦǁƐǦƸƑƸƽǦǤǊǓǦǃƽấǉǦƸƚǦǉƽểǦǉƽửǦǇồƾ.",
    ["诸位，助 I 登城。"] = "ƞƽưǦǋị,ǦǉǇợǦǉƶǦđăǃƼǦǉƽƐǃƽ.",
    ["我、我虽愚钝，但师父待我好。我……——巨子，我来助你。"] = "Đệ...ǦđệǦǉǊǓǦǃƼǊǦǂǊộƾ,ǦǃƽưǃƼǦǈưǦǅƽụǦđốƾǦǍửǦǋớƾǦđệǦǇấǉǦǉốǉ.ǦĐệ...——ǦƞựǦǥử,ǦđệǦǉớƾǦǉǇợǦǃƼườƾ.",
    ["去吧，去吧……"] = "ĐƾǦđƾ,ǦđƾǦđƾ...",
    ["小桃宝想我了，随时可以来看我. 我问过长老了，墨山道准许探亲的。"] = "ǥƾểǊǦĐƐǄǦƝảǄǦǃƽớǦƽǊǓǃƽǦǉƽƔǦƸƚǦǉƽểǦđếǃǦǉƽăǂǦƷấǉǦƸứǦǁƕƸǦǃƐǄ.ǦƣǊǓǃƽǦƽỏƾǦǉǇưởǃƼǦǁƃǄǦǇồƾ,ǦƨặƸǦƮơǃǦđạǄǦƸƽǄǦǅƽƗǅǦǆǊǓếǃǦǉƽǊộƸǦǉƽăǂǦǃǄǂ.",
    ["……承你们这么大情，我这一回泽州去，不知何时才能报答……"] = "...ǦĐắƸǦǉộƾǦǃƽậǃǦƁǃǦǉƔǃƽǦǁớǃǦǉƽếǦǃƐǓ,ǦǁầǃǦǃƐǓǦǉƶǦǋềǦǥǇạƸƽǦƞƽƁǊ,ǦǀƽƇǃƼǦƷƾếǉǦǀƽƾǦǃƐǄǦǂớƾǦƷƑǄǦđƑǅǦđượƸ...",
    ["……还不能回去。我还要去江湖上找人。"] = "...ǦƱẫǃǦƸƽưƶǦǉƽểǦǋềǦđượƸ.ǦǥƶǦƸƛǃǦǅƽảƾǦđƾǦǉƔǂǦǃƼườƾǦǉǇƙǃǦƼƾƶǃƼǦƽồ.",
    ["以后要是打相州过，来找我们，我管你饭. "] = "ƮƶǊǦǃƐǓǦǃếǊǦƸƚǦđƾǦǃƼƶǃƼǦǆǊƶǦǥươǃƼǦƞƽƁǊ,ǦƸứǦđếǃǦǉƔǂǦƷọǃǦǉƶ,ǦǉƶǦƷƶǄǦƸơǂ.",
    ["婶子多虑。如今稀罕的是伏火法，并非石炭本身。初时伏火之术难学，炼炭物稀价高，自然可以按秀才公的法子卖. 等伏火术传开去，炼炭便要走量大多销的路子了。"] = "ǥƽẩǂǦǉửǦđƶǦǁựǦǇồƾ.ǦƩƶǓǦǉƽứǦǆǊƈǦƼƾƑǦǁƐǦƫƽụƸǦƽỏƶǦǅƽƑǅ,ǦƸƽứǦǀƽƇǃƼǦǅƽảƾǦƷảǃǦǉƽƁǃǦǉƽạƸƽǦǉƽƶǃ.ǦƝƶǃǦđầǊǦǉƽǊậǉǦǅƽụƸǦƽỏƶǦǀƽƚǦƽọƸ,ǦǉƽƶǃǦǁǊǓệǃǦǇƶǦƽƾếǂǦǃƙǃǦƼƾƑǦƸƶǄ,ǦǉựǦǃƽƾƙǃǦƸƚǦǉƽểǦƷƑǃǦǉƽƺǄǦƸƑƸƽǦƸủƶǦǥƕǦǥƐƾǦƸƇǃƼ.ǦƞƽờǦǉƽǊậǉǦǅƽụƸǦƽỏƶǦǉǇǊǓềǃǦǇộǃƼǦǇƶ,ǦǁǊǓệǃǦǉƽƶǃǦǅƽảƾǦđƾǦǉƽƺǄǦƽướǃƼǦǈốǦǁượǃƼǦǁớǃǦƼƾƑǦǇẻǦǇồƾ.",
    ["巨子，我们不是那忘恩负义的人。"] = "ƞựǦǥử,ǦƸƽƕǃƼǦǉƶǦǀƽƇǃƼǦǅƽảƾǦƽạǃƼǦǃƼườƾǦǋǄǃƼǦơǃǦǅƽụǦǃƼƽĩƶ.",
    ["不必。"] = "ƦƽƇǃƼǦƸầǃ.",
    ["长老。"] = "ǥǇưởǃƼǦǁƃǄ.",
    ["诶，我那小徒弟嫌门中星图记载不全，听孤云来的王师侄说司天监里有全乎的，不吭一声俩人偷偷就去了，"] = "ÁƾǦƸƽƐ,ǦǉƙǃǦǉƾểǊǦđồǦđệǦƸủƶǦǉƶǦƸƽƙǦǉƾǃƽǦđồǦǉǇǄǃƼǦǂƇǃǦƼƽƾǦƸƽƗǅǦǀƽƇǃƼǦđủ,ǦǃƼƽƺǦƱươǃƼǦǈưǦđƾệǉǦǉừǦƞƇǦƱƁǃǦđếǃǦǃƚƾǦǉǇǄǃƼǦǥưǦǥƽƾƙǃǦƢƾƑǂǦƸƚǦƷảǃǦđầǓǦđủ,ǦǉƽếǦǁƐǦƽƶƾǦđứƶǦƾǂǦƽơƾǦǁặǃƼǦǉƾếǃƼǦǁƗǃǦǁƕǉǦđƾǦǁǊƇǃ,",
    ["嗐，小孩子懂什么。"] = "ƣạƾ,ǦǁũǦǉǇẻǦƸǄǃǦǉƽƔǦƷƾếǉǦƸƑƾǦƼƔ.",
    ["诶，事关弟子安危，哪能轻易就定下。你不懂，外头这些大国小国也不都是好的。"] = "ẤǓ,ǦƸƽǊǓệǃǦǁƾƙǃǦǆǊƶǃǦđếǃǦƶǃǦǃƼǊǓǦđệǦǉử,ǦǈƶǄǦƸƚǦǉƽểǦǉƖǓǦǉƾệǃǦǆǊǓếǉǦđịǃƽ.ǦƩƼươƾǦǀƽƇǃƼǦƽƾểǊǦđƁǊ,ǦǃƼǄƐƾǦǀƾƶǦǃướƸǦǁớǃǦǃướƸǦǃƽỏǦǀƽƇǃƼǦǅƽảƾǦǃơƾǦǃƐǄǦƸũǃƼǦǉốǉǦǁƐǃƽ.",
    ["你怎么看起来这么高兴？发生什么好事了，与说说呗？"] = "ƩƼươƾǦǁƐǂǦǈƶǄǦǂƐǦǉǇƇǃƼǦǋǊƾǦǋẻǦǉƽế?ǦƞƚǦƸƽǊǓệǃǦƼƔǦǉốǉǦǁƐǃƽ,ǦǀểǦǉƶǦǃƼƽƺǦƸƽƕǉǦǃƐǄ?",
    ["狸云熙"] = "ƧǓǦƱƁǃǦƣǓ",
    ["海宁冰心"] = "ƣảƾǦƩƾǃƽǦƝăǃƼǦǥƁǂ",
    ["剧剧剧，老吕，士别三日，真是刮目相看呀。"] = "ƞƽậƸǦƸƽậƸǦƸƽậƸ,ǦƧƃǄǦƧƃǦǋấǉǦǋảǦǇồƾ,ǦǈĩǦƷƾệǉǦǉƶǂǦǃƽậǉ,ǦǆǊảǦǉƽựƸǦǀƽƾếǃǦǉƶǦǅƽảƾǦǁƶǊǦǂắǉǦǂƐǦǃƽƔǃ.",
    ["想必是天老爷开恩，明年家里能得个好收成了. "] = "ƞƽắƸǦƽẳǃǦǁƐǦƆǃƼǦǥǇờƾǦǀƽƶƾǦƁǃ,ǦǈƶǃƼǦǃăǂǦǃƽƐǦǉƶǦǈẽǦƸƚǦǂộǉǦǂƖƶǦǂƐǃƼǦƷộƾǦǉƽǊ.",
    ["想这些，不如先把这行“断罪无正条” của 注疏补上，天亮前还得呈上去呢。"] = "ƩƼƽĩǦǂấǓǦǉƽứǦđƚ,ǦƸƽẳǃƼǦƷằǃƼǦǂƶǊǦƸƽƚǃƼǦƷổǦǈǊǃƼǦǤƛǃƼǦƸƽƕǦƼƾảƾǦ\"đǄạǃǦǉộƾǦǋƇǦƸƽƓǃƽǦđƾềǊ\"ǦǃƐǓǦđƾ,ǦǉǇướƸǦǀƽƾǦǉǇờƾǦǈƑǃƼǦƸƛǃǦǅƽảƾǦǉǇƔǃƽǦǁƙǃǦđấǓ.",
    ["全要！红的赢了就是红红火火，黄的赢了就是金银万贯，这就叫双押！]"] = "ƧấǓǦƽếǉ!ǦƨƐǊǦđỏǦǉƽắǃƼǦǉƽƔǦƽồǃƼǦƽồǃƼǦƽỏƶǦƽỏƶǦ(ǇựƸǦǇỡ),ǦǂƐǊǦǋƐǃƼǦǉƽắǃƼǦǉƽƔǦǀƾǂǦǃƼƁǃǦǋạǃǦǆǊƑǃǦ(ǉƾềǃǦǉƐƾǦđầǓǦǃƽƐ),ǦƸƑƾǦǃƐǓǦƼọƾǦǁƐǦđặǉǦƸượƸǦƸảǦđƇƾ!",
    ["《负责操作鼓风机>吹啊吹啊！"] = "<ƫƽụǦǉǇƑƸƽǦǋậǃǦƽƐǃƽǦǂƑǓǦǉƽổƾǦƼƾƚ>ǦǥƽổƾǦđƾǦǉƽổƾǦđƾ!",
    ["哇哇！是星点点！好美 ah！田姑田姑，你快看，你快看！"] = "ƪƶǦǄƶ!ǦƧƐǦǃƽữǃƼǦđốǂǦǈƶǄǦǃƽỏ!ǦĐẹǅǦǆǊƑ!ǦĐƾềǃǦƸƇǦĐƾềǃǦƸƇ,ǦƸƇǦǂƶǊǦǃƽƔǃǦǀƔƶ,ǦǂƶǊǦǃƽƔǃǦǀƔƶ!",
    ["喵喵喵！喵喵！喵喵喵喵！喵喵！《猫大厨看向你，在推荐菜肴拍下一爪，似极力推荐，盛情难却。>"] = "ƨƺǄǦǂƺǄǦǂƺǄ!ǦƨƺǄǦǂƺǄ!ǦƨƺǄǦǂƺǄǦǂƺǄǦǂƺǄ!ǦƨƺǄǦǂƺǄ!Ǧ<ƨƾƙǊǦđạƾǦđầǊǦƷếǅǦǃƽƔǃǦǋềǦǅƽƓƶǦǃƼươƾ,ǦấǃǦǂộǉǦǤấǊǦƸƽƁǃǦǁƙǃǦǂƚǃǦăǃǦđềǦƸử,ǦǉựƶǦǃƽưǦƸựƸǦǁựƸǦđềǦƸử,ǦǉƽịǃƽǦǉƔǃƽǦǀƽƚǦǀƽướƸǦǉừ.>",
    ["汪呜呜汪，汪，汪汪唔汪！《狗大厨摇摇耳朵，盯着一道菜，吐着舌头盼望你打包带走，眼神恳切。>"] = "ƢƁǊǦǊǦǊǦƼƁǊ,ǦƼƁǊ,ǦƼƁǊǦƼƁǊǦưǦƼƁǊ!Ǧ<ǕƇǃƼǦđạƾǦđầǊǦƷếǅǦǋẫǓǦǋẫǓǦǉƶƾ,ǦƸƽằǂǦƸƽằǂǦǃƽƔǃǦǋƐǄǦǂộǉǦǂƚǃǦăǃ,ǦǉƽƘǦǁưỡƾǦǂǄǃƼǦđợƾǦǃƼươƾǦƼƚƾǦǂƶǃƼǦđƾ,ǦƑǃƽǦǂắǉǦǀƽẩǃǦǉƽƾếǉ.>",
    ["能把开封s的猫儿狗儿都招呼来……莫不是幻术吧？"] = "ƞƚǦǉƽểǦǀƙǊǦƼọƾǦƽếǉǦǂƘǄǦƸƽƚǦởǦƦƽƶƾǦƫƽǄǃƼǦđếǃǦđƁǓ...ǦƸƽẳǃƼǦǁẽǦǁƐǦảǄǦǉƽǊậǉǦǈƶǄ?",
    ["全要！红的赢了就是红红火火，黄的赢l了就是金银万贯，这就叫双押！"] = "ƧấǓǦƽếǉ!ǦƨƐǊǦđỏǦǉƽắǃƼǦǁƐǦƽồǃƼǦƽồǃƼǦƽỏƶǦƽỏƶ,ǦǂƐǊǦǋƐǃƼǦǉƽắǃƼǦǁƐǦǀƾǂǦǃƼƁǃǦǋạǃǦǆǊƑǃ,ǦđƁǓǦƼọƾǦǁƐǦǈǄǃƼǦƑǅ!",
    ["猜猜，这开封城里哪儿油水最多？"] = "ĐǄƑǃǦǍƺǂ,ǦǉǇǄǃƼǦǉƽƐǃƽǦƦƽƶƾǦƫƽǄǃƼǦǃƐǓǦǃơƾǦǃƐǄǦǃƽƾềǊǦǤầǊǦǂỡǦǃƽấǉ?",
    ["《屋内>真是个好主意……"] = "<ǥǇǄǃƼǦǃƽƐ>ǦĐƕǃƼǦǁƐǦǂộǉǦƸƽủǦƈǦƽƶǓ...",
    ["这事 I 先应了，你且放心回去，我自会禀报掌门。"] = "ƞƽǊǓệǃǦǃƐǓǦǉƶǦǃƽậǃǦǁờƾǦǉǇướƸ,ǦǃƼươƾǦƸứǦǓƙǃǦǉƁǂǦǆǊƶǓǦǋề,ǦǉƶǦǉựǦƸƚǦƸƑƸƽǦƷẩǂǦƷƑǄǦƸƽưởǃƼǦǂƇǃ.",
    ["您看看我这摊子，冷冷清清，凄凄惨惨. 这其中的酸楚……唉，不说也罢！"] = "ƩƼƐƾǦǍƺǂǦƸƑƾǦǈạǅǦǃƐǓǦƸủƶǦǉƶǦǍƺǂ,ǦǁạǃƽǦǁẽǄǦǆǊạǃƽǦǆǊẽ,ǦǉƽƙǦǉƽƙǦǉƽảǂǦǉƽảǂ.ǦƩỗƾǦƸƽǊƶǦǍƚǉǦǉǇǄǃƼǦđƚ...ǦƽƶƾǏǏ,ǦǀƽƇǃƼǦǃƚƾǦƸũǃƼǦđượƸ!",
    ["嗯……经你这么一说，似乎确实差点儿什么. "] = "Ừǂ...ǦǃƼƽƺǦǃƼươƾǦǃƚƾǦǋậǓ,ǦƽƔǃƽǦǃƽưǦđƕǃƼǦǁƐǦǉƽƾếǊǦƸƽƕǉǦƼƔǦđƚǦǉƽậǉ.",
    ["老板生意兴隆！可有余货？我想定一批醋送到城南去. "] = "ƞƽƕƸǦǁƃǄǦƷảǃǦǁƐǂǦăǃǦǅƽƑǉǦđạǉ!ǦƞƚǦƸƛǃǦƽƐǃƼǦǤưǦǀƽƇǃƼ?ǦǥƶǦǂǊốǃǦđặǉǦǂộǉǦǁƇǦǤấǂǦƸƽǊǓểǃǦđếǃǦǅƽƓƶǦǃƶǂǦǉƽƐǃƽ.",
    ["您还真别说！有了这一口“酸后回甘” of 醋，这生意，能做！"] = "ƩƼƐƾǦđừǃƼǦǃƚƾǦǃữƶ!ǦƞƚǦđượƸǦǃƼụǂǦǤấǂǦ\"ƸƽǊƶǦǈƶǊǦǃƼọǉǦƽậǊ\"ǦǃƐǓ,ǦǋụǦǁƐǂǦăǃǦǃƐǓ,ǦǁƐǂǦđượƸ!",
    ["哎，这话就另说了。我托人打听过，那题目简单得很——就做一道“老人想吃的菜”。"] = "ƀǓ,ǦƸƽǊǓệǃǦǃƐǓǦǁạƾǦǃƚƾǦǀƽƑƸǦǇồƾ.ǦǥƇƾǦƸƚǦǃƽờǦǃƼườƾǦǤƛǦƽỏƾ,ǦđềǦƷƐƾǦđƚǦđơǃǦƼƾảǃǦǁắǂǦ——ǦƸƽỉǦǁƐǂǦǂộǉǦǂƚǃǦ\"ǂƚǃǦăǃǦǃƼườƾǦƼƾƐǦǂǊốǃǦăǃ\".",
    ["小时候在凉州尝过，那以后就一直惦记着……"] = "ƧƕƸǦǃƽỏǦǉƶǦǉừǃƼǦǃếǂǦǆǊƶǦởǦƧươǃƼǦƞƽƁǊ,ǦǉừǦđƚǦǋềǦǈƶǊǦƸứǦǃƽớǦǂƃƾǦǀƽƇǃƼǦǆǊƙǃ...",
    ["还记得……当年阿爹做成了第一笔生意，带着我去集市玩耍。"] = "ƱẫǃǦƸƛǃǦǃƽớ...ǦǃăǂǦđƚǦƜǦƸƽƶǦǁƐǂǦǉƽƐǃƽǦǉƽươǃƼǦǋụǦđầǊǦǉƾƙǃ,ǦǤắǉǦǉƶǦđƾǦǉậǅǦǉƽịǦƸƽơƾǦđƖƶ.",
    ["嗯，就是那天领头送东西来的胖叔叔……笑起来眼睛眯成一条缝的那个！"] = "Ừǂ,ǦƸƽƓǃƽǦǁƐǦǋịǦǉƽƕƸǦǉƽƕƸǦƷƗǄǦǤẫǃǦđầǊǦđǄƐǃǦƸƽởǦđồǦđếǃǦƽƇǂǦđƚǦđƚ...ǦǁƕƸǦƸườƾǦǂắǉǦƽƓǅǦǁạƾǦǉƽƐǃƽǦǂộǉǦđườǃƼǦƸƽỉǦấǓ!",
    ["我们问他是谁，他只说是您的江湖朋友。"] = "ǥụƾǦǂǊộƾǦƽỏƾǦǉƽƕƸǦấǓǦǁƐǦƶƾ,ǦǉƽƕƸǦấǓǦƸƽỉǦƷảǄǦǁƐǦƷằǃƼǦƽữǊǦƼƾƶǃƼǦƽồǦƸủƶǦƽǊǓǃƽ.",
    ["嘿嘿，肯定也是位了不起的大侠！就是……肚子稍微大了点儿！"] = "ƣƾǦƽƾ,ǦƸƽắƸǦƸƽắǃǦƸũǃƼǦǁƐǦǂộǉǦǋịǦđạƾǦƽƾệǅǦǁừǃƼǦǁẫǓ!ǦƞƽỉǦǁƐ...ǦƷụǃƼǦƽơƾǦǉǄǦǂộǉǦƸƽƕǉ!",
    ["您说对了，我这小吃摊的招牌就是【好又多，多又快]，啥都能做，做好就拿，边走边吃！"] = "ƩƼƐƾǦǃƚƾǦđƕǃƼǦǇồƾ,ǦƷảǃƼǦƽƾệǊǦǈạǅǦđồǦăǃǦǋặǉǦǃƐǓǦƸủƶǦǉƶǦƸƽƓǃƽǦǁƐǦ[ƣảǄǦƣựǊǦĐƶ,ǦĐƶǦƣựǊǦƦƽǄƑƾ],ǦƸƑƾǦƼƔǦƸũǃƼǦǁƐǂǦđượƸ,ǦǁƐǂǦǍǄǃƼǦǁƐǦǁấǓǦǃƼƶǓ,ǦǋừƶǦđƾǦǋừƶǦăǃ!",
    ["你懂什么！南唐那么远，哪管得了皇宫，定 is 契丹狗贼干的！"] = "ƩƼươƾǦǉƽƔǦƽƾểǊǦƸƑƾǦƼƔ!ǦƩƶǂǦĐườǃƼǦǍƶǦǍƇƾǦǃƽưǦǉƽế,ǦǈƶǄǦǆǊảǃǦǉớƾǦđượƸǦƽǄƐǃƼǦƸǊǃƼ,ǦǃƽấǉǦđịǃƽǦǁƐǦǁũǦƸẩǊǦǉặƸǦƦƽƾếǉǦĐƶǃǦǁƐǂ!",
    ["李卫宋：契丹！契丹！契丹！"] = "ƧƈǦƱệǦǥốǃƼ:ǦƦƽƾếǉǦĐƶǃ!ǦƦƽƾếǉǦĐƶǃ!ǦƦƽƾếǉǦĐƶǃ!",
    ["你是谁？替南唐说话……好哇，我看， you 就是南唐的间谍！"] = "ƩƼươƾǦǁƐǦƶƾ?ǦƩƚƾǦƼƾƕǅǦƸƽǄǦƩƶǂǦĐườǃƼ...ǦǥốǉǦǁắǂ,ǦǉƶǦǉƽấǓǦǃƼươƾǦƸƽƓǃƽǦǁƐǦƼƾƑǃǦđƾệǅǦƸủƶǦƩƶǂǦĐườǃƼ!",
    ["春恨生"] = "ƳǊƁǃǦƣậǃǦƮƾǃƽ",
    ["我晓得！姐姐，你能不能…… ye教教我算牌？"] = "ĐệǦƷƾếǉǦǇồƾ!ǦǥỷǦǉỷ,ǦǉỷǦƸƚǦǉƽể...ǦǤạǓǦđệǦƸƑƸƽǦǉƓǃƽǦƷƐƾǦǁǊƇǃǦǀƽƇǃƼ?",
    ["《这反应……不像有假。难道，我找错人了？还是说，此人城府极深，在跟我演戏？>"] = "<ƫƽảǃǦứǃƼǦǃƐǓ...ǦǀƽƇǃƼǦƼƾốǃƼǦǃƽưǦƼƾảǦǋờ.ǦƞƽẳǃƼǦǁẽ,ǦǉƶǦǉƔǂǦǃƽầǂǦǃƼườƾǦǇồƾ?ǦƣƶǓǦǁƐǦǃƚƾ,ǦǃƼườƾǦǃƐǓǦǉƽƐǃƽǦǅƽủǦƸựƸǦǈƁǊ,ǦđƶǃƼǦǤƾễǃǦǀịƸƽǦǋớƾǦǂƔǃƽ?>",
    ["可惜啊，我这人胆子小。怕 those 被你们害了的百姓晚上来索命！"] = "ǥƾếƸǦǉƽƶǓ,ǦǉƶǦđƁǓǦǃƽƑǉǦƼƶǃǦǁắǂ.ǦƞƽỉǦǈợǦđƑǂǦƷƑƸƽǦǉƓǃƽǦƷịǦƸƑƸǦǃƼườƾǦƽạƾǦƸƽếǉǦđƙǂǦđƙǂǦǋềǦđƛƾǦǂạǃƼ!",
    ["对呀对呀，看这轮廓，看这线条！每天不练 ta 四五个时辰哪练得出来呀！"] = "ĐƕǃƼǦǉƽếǦđƕǃƼǦǉƽế,ǦǃƽƔǃǦƸơǦƷắǅǦǃƐǓ,ǦǃƽƔǃǦđườǃƼǦǃƗǉǦǃƐǓ!ǦƨỗƾǦǃƼƐǓǦǀƽƇǃƼǦǁǊǓệǃǦǉậǅǦƷốǃǦǃăǂǦƸƶǃƽǦƼƾờǦǉƽƔǦǈƶǄǦǂƐǦƸƚǦđượƸǦƸƽứ!",
    ["要是奴婢们运气好，能翻出 those 前朝旧物，都可以自己带走，做个添头呢！"] = "ƩếǊǦǃƇǦǉỳǦƷọǃǦǉƶǦǂƶǓǦǂắǃǦđƐǄǦđượƸǦǃƽữǃƼǦǂƚǃǦđồǦƸũǦǉƽờƾǦǉƾềǃǦǉǇƾềǊǦđƚ,ǦđềǊǦƸƚǦǉƽểǦǉựǦǂƔǃƽǦǂƶǃƼǦđƾ,ǦƸǄƾǦǃƽưǦǂƚǃǦƽờƾǦđấǓ!",
    ["若是军士您愿意伸出援手，帮帮小忙……像您这么好的运气，一定能找到 those 前朝旧物!"] = "ƩếǊǦǆǊƁǃǦǈĩǦđạƾǦƽǊǓǃƽǦǈẵǃǦǁƛǃƼǦǇƶǦǉƶǓǦƼƾƕǅǦđỡǦƸƽƕǉǦǋƾệƸǦǃƽỏ...ǦǋớƾǦǋậǃǦǂƶǓǦǉốǉǦǃƽưǦƽǊǓǃƽ,ǦǃƽấǉǦđịǃƽǦǈẽǦǉƔǂǦǉƽấǓǦǃƽữǃƼǦǂƚǃǦđồǦƸũǦǉƽờƾǦǉƾềǃǦǉǇƾềǊǦđƚǦǉƽƇƾ!",
    ["我等编纂《应天历>时，正欲修正此弊。"] = "ƝọǃǦǉƶǦǀƽƾǦƷƾƙǃǦǈǄạǃǦ<ỨǃƼǦǥƽƾƙǃǦƧịƸƽ>,ǦƸƽƓǃƽǦǁƐǦǂǊốǃǦǈửƶǦđổƾǦƸƑƾǦǈƶƾǦǁầǂǦǃƐǓ.",
    ["王兄，晚辈近日研习《甘石星经>，有一惑不解……"] = "ƱươǃƼǦƽǊǓǃƽ,ǦǋƃǃǦƷốƾǦƼầǃǦđƁǓǦǃƼƽƾƙǃǦƸứǊǦ<ƞƶǂǦǥƽạƸƽǦǥƾǃƽǦƦƾǃƽ>,ǦƸƚǦǂộǉǦđƾềǊǦǉƽắƸǦǂắƸǦƸƽưƶǦƼƾảƾǦđượƸ...",
    ["闭嘴吧！回去加练！这……哈哈大人，这小子尽说胡话，我们这儿从无怪事发生！"] = "ƞƁǂǦǂƾệǃƼ!ǦƬǊƶǓǦǋềǦǁǊǓệǃǦǉƽƙǂǦƸƽǄǦǉƶ!ǦƞƽǊǓệǃǦǃƐǓ...ǦƽƶǦƽƶǦđạƾǦǃƽƁǃ,ǦǉƾểǊǦǉửǦǃƐǓǦǉǄƐǃǦǃƚƾǦƽồǦđồ,ǦƸƽỗǦƸƽƕǃƼǦǉƶǦǉừǦǉǇướƸǦǉớƾǦǃƶǓǦƸƽưƶǦǉừǃƼǦǍảǓǦǇƶǦǆǊƑƾǦǈựǦƼƔ!",
    ["《屋内>不知道$T(5037)什么时候来"] = "<ǥǇǄǃƼǦǃƽƐ>ǦƦƽƇǃƼǦƷƾếǉǦǀƽƾǦǃƐǄǦ$T(5037)ǦǂớƾǦǉớƾ",
    ["我小时候在凉州尝过，那以后就一直惦记着……"] = "ƧƕƸǦǃƽỏǦǉƇƾǦđƃǦǉừǃƼǦǃếǂǦǆǊƶǦởǦƧươǃƼǦƞƽƁǊ,ǦǉừǦđƚǦǋềǦǈƶǊǦƸứǦǃƽớǦǂƃƾǦǀƽƇǃƼǦǆǊƙǃ...",
    ["最近——打了熊揍了狼，还要和猴子斗智斗勇......"] = "ƢầǃǦđƁǓǦ——ǦđƑǃƽǦƼấǊǦǉẩǃǦǈƚƾ,ǦƸƛǃǦǅƽảƾǦđấǊǦǉǇƓǦđấǊǦǤũǃƼǦǋớƾǦǁũǦǀƽỉ......",
    ["别怕，他们不是坏人。他们不是有意吓你的......"] = "ĐừǃƼǦǈợ,ǦƽọǦǀƽƇǃƼǦǅƽảƾǦǃƼườƾǦǍấǊ.ǦƣọǦǀƽƇǃƼǦƸốǦƈǦǤọƶǦƸǄǃǦđƁǊ......",
    ["有段时间没回去看过了……方才试/了试，山门的研究果真不一般……"] = "ƞũǃƼǦǂộǉǦǉƽờƾǦƼƾƶǃǦǇồƾǦƸƽưƶǦǋềǦǉƽăǂ...ǦƱừƶǦǃƃǓǦǉƽửǦǂộǉǦƸƽƕǉ,ǦǃƼƽƾƙǃǦƸứǊǦƸủƶǦǈơǃǦǂƇǃǦǆǊảǦǃƽƾƙǃǦǀƽƇǃƼǦǉầǂǦǉƽườǃƼ...",
    ["闭逍斯"] = "ƝếǦǥƾƙǊǦǥư",
    ["剑诀风"] = "ƦƾếǂǦƬǊǓếǉǦƫƽǄǃƼ",
    ["异常挂载"] = "ǝịǦǉƽườǃƼǦǆǊảƾǦǉƑƾ",
    ["那边的契丹人， đều là ngươi giết?"] = "ĐƑǂǦǃƼườƾǦƦƽƾếǉǦĐƶǃǦđằǃƼǦǀƾƶ,ǦđềǊǦǁƐǦǃƼươƾǦƼƾếǉǦǈƶǄ?",
    ["哟，终于打赢人家刘小妹从没输过的初等机关偃偶了，可喜和贺！"] = "Ồ,ǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦǉƽắǃƼǦđượƸǦƴểǃǦǃƼẫǊǦƸơǦǆǊƶǃǦǈơǦđẳǃƼǦƸƽưƶǦǉừǃƼǦǉƽấǉǦƷạƾǦƸủƶǦƧưǊǦǥƾểǊǦƨǊộƾǦǇồƾ,ǦǀƽảǦƽỉǦǀƽảǦƽạ!",
    ["小萝卜，远哥今天教你两句诗：金缕玉衣裹朽木，腹中空有草莽声！"] = "ǥƾểǊǦƧƶǦƝặƸ,ǦƱƾễǃǦƸƶǦƽƇǂǦǃƶǓǦǤạǓǦƺǂǦƽƶƾǦƸƁǊǦǉƽơ:ǦƦƾǂǦǁũǦǃƼọƸǦǓǦǀƽỏƶǦƽủǦǂộƸ,ǦǅƽƕƸǦǉǇǊǃƼǦǀƽƇǃƼǦƽữǊǦǉƽảǄǦǂƃǃƼǦǉƽƶǃƽ!",
    ["数千人……虏人倒是看得起咱们。"] = "ƨấǓǦǃƼƐǃǦǃƼườƾ……ǦǆǊƁǃǦƼƾặƸǦǆǊảǦǁƐǦƸǄƾǦǉǇọǃƼǦƸƽƕǃƼǦǉƶ.",
    ["契丹立国北疆，强兵壮马，礼贤下士，尚德尚义。今闻书院盛名，愿虚位以待，厚赏以酬……"] = "ƦƽƾếǉǦĐƶǃǦǁậǅǦǆǊốƸǦởǦƝắƸǦƞươǃƼ,ǦƷƾǃƽǦƸườǃƼǦǂƃǦǉǇƑǃƼ,ǦǁễǦƽƾềǃǦƽạǦǈĩ,ǦǉƽượǃƼǦđứƸǦǉƽượǃƼǦǃƼƽĩƶ.ǦƩƶǓǦǃƼƽƺǦǤƶǃƽǦǉƾếǃƼǦǉƽưǦǋƾệǃ,ǦǃƼǊǓệǃǦđểǦǉǇốǃƼǦǋịǦǉǇƓǦƸƽờǦđƚǃ,ǦǉǇọǃƼǦǉƽưởǃƼǦƽậǊǦƽĩǃƽ……",
    ["这声响……是那“千机万象”？不，这只是寻常的墨山道机关……"] = "ƀǂǦǉƽƶǃƽǦǃƐǓ……ǦǁƐǦ\"ǥƽƾƙǃǦƞơǦƱạǃǦǥượǃƼ\"ǦǈƶǄ?ǦƦƽƇǃƼ,ǦđƁǓǦƸƽỉǦǁƐǦƸơǦǆǊƶǃǦƨặƸǦƮơǃǦĐạǄǦǉầǂǦǉƽườǃƼǦǉƽƇƾ……",
    ["师兄，再说一说荆楚吧！真想看看是何等天地，能写出天问这般极章！"] = "ƮưǦƽǊǓǃƽ,ǦǃƚƾǦǉƽƙǂǦǋềǦƦƾǃƽǦƮởǦđƾ!ǦǥƽậǉǦǂǊốǃǦǍƺǂǦǉƽửǦǃơƾǦđƚǦǁƐǦǉƽƾƙǃǦđịƶǦƽạǃƼǦǃƐǄǦǂƐǦƸƚǦǉƽểǦǋƾếǉǦǇƶǦǃƽữǃƼǦƸƽươǃƼǦǉǊǓệǉǦǉƑƸǦǃƽưǦǥƽƾƙǃǦƱấǃ!",
    ["……哦，前些日子试补《算术书>的虫蚀部分，正有了些眉目，我怕……我怕来不及，得再抓紧些……"] = "……Ồ,ǦǂấǓǦǃƼƐǓǦǉǇướƸǦđịǃƽǦƷổǦǈǊǃƼǦǅƽầǃǦǂọǉǦăǃǦƸủƶǦ<ǥǄƑǃǦǥƽǊậǉǦǥƽư>,ǦǋừƶǦǂớƾǦƸƚǦƸƽƕǉǦǂƶǃƽǦǂốƾ,ǦǉƶǦǈợ……ǦǉƶǦǈợǦǀƽƇǃƼǦǀịǅǦǃữƶ,ǦǅƽảƾǦǁƐǂǦǃƽƶǃƽǦƽơǃǦƸƽƕǉ……",
    ["哦，收签子……"] = "Ồ,ǦǉƽǊǦǍăǂ……",
    ["平日里都是抽：谁第一个起头背书，谁负责值勤打扫学堂，谁去给种地先生记“思农要术”……"] = "ƩƼƐǓǦǉƽườǃƼǦđềǊǦǁƐǦǇƕǉ:ǦƶƾǦǁƐǦǃƼườƾǦđầǊǦǉƾƙǃǦƷắǉǦđầǊǦđọƸǦǉƽǊộƸǦǁƛǃƼ,ǦƶƾǦǅƽụǦǉǇƑƸƽǦǉǇựƸǦƸƶǦǆǊƗǉǦǤọǃǦƽọƸǦđườǃƼ,ǦƶƾǦđƾǦƼƾƕǅǦǉƾƙǃǦǈƾǃƽǦǤạǓǦǉǇồǃƼǦǉǇọǉǦƼƽƾǦƸƽƗǅǦ\"ǥưǦƩƇǃƼǦƴếǊǦǥƽǊậǉ\"……",
    ["今日抽的，倒似千钧之重……"] = "ǥƽƶǃƽǦǍăǂǦǇƕǉǦǃƼƐǓǦƽƇǂǦǃƶǓ,ǦǁạƾǦǃƽưǦǃặǃƼǦǃƼƐǃǦƸƁǃ……",
    ["看什么？想偷我签子？"] = "ƩƽƔǃǦƸƑƾǦƼƔ?ǦƨǊốǃǦǉǇộǂǦǍăǂǦƸủƶǦǉƶǦƐ?",
    ["《秦远的签子，自己的名字划掉了，又写了小萝卜>》罗成武的签子，包裹着一层破布，只看到似乎是很长的一串字>"] = "<ƳăǂǦƸủƶǦǥầǃǦƱƾễǃ,ǦƼạƸƽǦǉƙǃǦǂƔǃƽǦđƾ,ǦǁạƾǦǋƾếǉǦǉƙǃǦǥƾểǊǦƧƶǦƝặƸ><ƳăǂǦƸủƶǦƧƶǦǥƽƐǃƽǦƱũ,ǦƷọƸǦǂộǉǦǁớǅǦǋảƾǦǇƑƸƽ,ǦƸƽỉǦǉƽấǓǦǤườǃƼǦǃƽưǦǁƐǦǂộǉǦƸƽǊỗƾǦƸƽữǦǇấǉǦǤƐƾ>",
    ["《刘思农的签子，写着小萝卜>"] = "<ƳăǂǦƸủƶǦƧưǊǦǥưǦƩƇǃƼ,ǦǋƾếǉǦǉƙǃǦǥƾểǊǦƧƶǦƝặƸ>",
    ["没错，是这个。好孩子，去吧……"] = "ƦƽƇǃƼǦǈƶƾ,ǦǁƐǦƸƑƾǦǃƐǓ.ǦĐứƶǦǉǇẻǦǃƼǄƶǃ,ǦđƾǦđƾ……",
    ["《一根写着符晓，一根写着鹤>"] = "<ƨộǉǦǉƽƶǃƽǦǋƾếǉǦƫƽƖǦƣƾểǊ,ǦǂộǉǦǉƽƶǃƽǦǋƾếǉǦƣạƸ>",
    ["《刘小妹的签子，写着鹤老头>"] = "<ƳăǂǦƸủƶǦƧưǊǦǥƾểǊǦƨǊộƾ,ǦǋƾếǉǦƸƽữǦƣạƸǦǁƃǄǦđầǊ>",
    ["嘘……快去快去！"] = "ƮǊỵǉ……ǦǂƶǊǦđƾǦđƾ!",
    ["这是我的。"] = "ĐƁǓǦǁƐǦƸủƶǦǉƶ.",
    ["可是……可是大家……"] = "ƩƽưǃƼǦǂƐ……ǦǃƽưǃƼǦǂƐǦǂọƾǦǃƼườƾ……",
    ["这些家伙……"] = "ƨấǓǦǉƙǃǦǃƽƚƸǦǃƐǓ……",
    ["呦，怎么哭鼻子了？我给你变个戏法怎么样？"] = "ƆǦǀƔƶ,ǦǈƶǄǦǁạƾǦǀƽƚƸǦǃƽƘǦǇồƾ?ǦǥƶǦƷƾếǃǦƸƽǄǦƸǄǃǦǂộǉǦǉǇƛǦảǄǦǉƽǊậǉǦǃƽƗ?",
    ["院主，你——！"] = "ƱƾệǃǦƸƽủ,ǦǃƼườƾ——!",
    ["小萝卜……"] = "ǥƾểǊǦƧƶǦƝặƸ……",
    ["圆圆，记不住也没关系的. "] = "ƱƾƙǃǦƱƾƙǃ,ǦǀƽƇǃƼǦǃƽớǦđượƸǦƸũǃƼǦǀƽƇǃƼǦǈƶǄǦđƁǊ.",
    ["给我娘抄的佛经，带给她。……多谢。"] = "ƦƾǃƽǦƫƽậǉǦǉƶǦƸƽƗǅǦƸƽǄǦǂẫǊǦǉƽƁǃ,ǦǂƶǃƼǦƸƽǄǦƷƐǦấǓǦƼƾƕǅǦǉƶ.Ǧ……ĐƶǦǉạ.",
    ["院主，签子抽完了……"] = "ƱƾệǃǦƸƽủ,ǦǍăǂǦđƃǦǇƕǉǦǍǄǃƼǦǇồƾ……",
    ["记得，咱们二十来个人喝茶谈天. "] = "ƩƽớǦƸƽứ,ǦƸƽƕǃƼǦǉƶǦƽơǃǦƽƶƾǦǂươƾǦǃƼườƾǦǃƼồƾǦǊốǃƼǦǉǇƐǦđƐǂǦđạǄ.",
    ["小时候大家爱听说书，是吧小萝卜？"] = "ƣồƾǦǃƽỏǦǂọƾǦǃƼườƾǦđềǊǦǉƽƓƸƽǦǃƼƽƺǦǀểǦƸƽǊǓệǃ,ǦđƕǃƼǦǀƽƇǃƼǦǥƾểǊǦƧƶǦƝặƸ?",
    ["有人爱诗词，有人擅营造，有人学武术，也有人琢磨百工著述。"] = "ƞƚǦǃƼườƾǦǓƙǊǦǉƽơǦǉừ,ǦƸƚǦǃƼườƾǦƼƾỏƾǦǤǄƶǃƽǦǉạǄ,ǦƸƚǦǃƼườƾǦƽọƸǦǋƅǦǉƽǊậǉ,ǦƸũǃƼǦƸƚǦǃƼườƾǦǃƼƽƾềǃǦǃƼẫǂǦǉǇướƸǦǉƑƸǦƷƑƸƽǦǃƼƽệ.",
    ["好，好啊。书在我们身上，留下了好些印记。我们又把那些印记咀嚼、琢磨，写成了书。"] = "ǥốǉ,ǦǉốǉǦǁắǂ.ǦƮƑƸƽǦởǦǉǇƙǃǦǃƼườƾǦƸƽƕǃƼǦǉƶ,ǦđểǦǁạƾǦǇấǉǦǃƽƾềǊǦǤấǊǦấǃ.ǦƞƽƕǃƼǦǉƶǦǁạƾǦđƺǂǦǃƽữǃƼǦǤấǊǦấǃǦđƚǦǃƼƽƾềǃǦǃƼẫǂ,ǦƼọǉǦƼƾũƶ,ǦǋƾếǉǦǉƽƐǃƽǦǈƑƸƽ.",
    ["书页那样轻，比铠甲薄，比箭矢脆，经不得风吹雨淋，即便小心保存，不过百年便也朽化。"] = "ǥǇƶǃƼǦǈƑƸƽǦǃƽẹǦǃƽƐǃƼǦǃƽưǦǋậǓ,ǦǂỏǃƼǦƽơǃǦƼƾƑǅǦǉǇụ,ǦƼƾƛǃǦƽơǃǦǂũƾǦǉƙǃ,ǦǀƽƇǃƼǦƸƽịǊǦǃổƾǦǅƽǄǃƼǦƷƶǦƷƃǄǦǉƑǅ,ǦǤƖǦƸƚǦƸẩǃǦǉƽậǃǦƼƾữǦƼƔǃ,ǦƸƽẳǃƼǦǆǊƑǦǉǇăǂǦǃăǂǦƸũǃƼǦǈẽǦǂụƸǦǃƑǉ.",
    ["鹤院主……"] = "ƣạƸǦǋƾệǃǦƸƽủ……",
    ["待 me 学成，也寻到了他的行踪，却听闻世人对他多是褒赏。我不相信……我必须找到他，弄清楚，他究竟是怎样的人。"] = "ĐợƾǦǀƽƾǦǉƶǦƽọƸǦǉƽƐǃƽǦǉƐƾ,ǦƸũǃƼǦǉƔǂǦđượƸǦƽƐǃƽǦǉǊǃƼǦƸủƶǦƇǃƼǦǉƶ,ǦǃƽưǃƼǦǁạƾǦǃƼƽƺǦǃƼườƾǦđờƾǦǅƽầǃǦǁớǃǦǁƐǦǀƽƺǃǦǃƼợƾǦƇǃƼǦǉƶ.ǦǥƶǦǀƽƇǃƼǦǉƾǃ……ǦǉƶǦǅƽảƾǦǉƔǂǦđượƸǦƇǃƼǦǉƶ,ǦǁƐǂǦƸƽǄǦǇƅǦǇƐǃƼǦǇốǉǦƸǊộƸǦƇǃƼǦǉƶǦǁƐǦƽạǃƼǦǃƼườƾǦƼƔ.",
    ["此间诸事，我自会昭之于众。鹤院主与留守封龙的诸位弟子以身著书，誓死未退。"] = "ƨọƾǦƸƽǊǓệǃǦǃơƾǦđƁǓ,ǦǉƶǦǉựǦǈẽǦƸƇǃƼǦǀƽƶƾǦƸƽǄǦǉƽƾƙǃǦƽạǦƷƾếǉ.ǦƣạƸǦǋƾệǃǦƸƽủǦƸƖǃƼǦƸƑƸǦđệǦǉửǦǁưǊǦǉƽủǦƫƽǄǃƼǦƧǄǃƼǦđƃǦǁấǓǦǉƽƁǃǦǁƐǂǦǈƑƸƽ,ǦǉƽềǦƸƽếǉǦǀƽƇǃƼǦǁƖƾ.",
    ["要说那姓杜的靠不住，林家娃娃想与虎谋皮，难呐。"] = "ǥƶǦǃƚƾǦǃƐǓ,ǦǀẻǦƽọǦĐỗǦđƚǦǀƽƇǃƼǦđƑǃƼǦǉƾǃǦđƁǊ,ǦǂấǓǦđứƶǦǃƽỏǦǃƽƐǦƽọǦƧƁǂǦǂǊốǃǦǂưǊǦǈựǦǋớƾǦƽổ,ǦǀƽƚǦǁắǂǦǉƽƶǓ.",
    ["爹爹在哪？"] = "ƞƽƶǦƸǄǃǦởǦđƁǊ?",
    ["此人便是——当年的杜帅！平汜水、定邺城，镇泰州。帅旗所指，无往不胜。"] = "ƩƼườƾǦǃƐǓǦƸƽƓǃƽǦǁƐ——ǦĐỗǦǈǄƑƾǦǃăǂǦđƚ!ǦƝƔǃƽǦǥịǦǥƽủǓ,ǦđịǃƽǦƩƼƽƾệǅǦǥƽƐǃƽ,ǦǉǇấǃǦǥƽƑƾǦƞƽƁǊ.ǦƮǄƑƾǦǀỳǦƸƽỉǦđƁǊ,ǦđƑǃƽǦđƁǊǦǉƽắǃƼǦđƚ.",
    ["“槊杆作篙河当路，帅旗响得胡马哭。”"] = "\"ƮƚƸǦƸƑǃǦǉƑƸǦƸƶǄǦƽƐǦđươǃƼǦǁộ,ǦǈǄƑƾǦǀỳǦƽưởǃƼǦđắƸǦƣồǦǂƃǦǀƽốƸ.\"",
    ["既知杜帅威名，还敢在此搅动军心！"] = "ĐƃǦƷƾếǉǦǊǓǦǤƶǃƽǦĐỗǦǈǄƑƾ,ǦƸƛǃǦǤƑǂǦởǦđƁǓǦǁƐǂǦǁǄạǃǦǆǊƁǃǦǉƁǂ!",
    ["林某愿以项上人头为质——"] = "ƧƁǂǦǂỗǦǃƼǊǓệǃǦǁấǓǦđầǊǦǉǇƙǃǦƸổǦǇƶǦǁƐǂǦǉƾǃ——",
    ["《低声>李会五是王清旧部，与杜砌银并不相熟，怎会一起喝酒？"] = "<ǥƽƔǦǉƽầǂ>ǦƧƈǦƣộƾǦƩƼũǦǁƐǦƸựǊǦƷộǦƽạǦƸủƶǦƱươǃƼǦǥƽƶǃƽ,ǦǀƽƇǃƼǦƽềǦǆǊƺǃǦƷƾếǉǦĐỗǦƦƽếǦƩƼƁǃ,ǦǈƶǄǦƸƚǦǉƽểǦƸƖǃƼǦǃƽƶǊǦǊốǃƼǦǇượǊ?",
    ["不儿，军爷、军爷，我知错了、知错了！我是您孙子！哎呦——"] = "ƦƽƇǃƼǦạ,ǦǆǊƁǃǦƼƾƶ,ǦǆǊƁǃǦƼƾƶ,ǦƸǄǃǦƷƾếǉǦǁỗƾǦǇồƾ,ǦƷƾếǉǦǁỗƾǦǇồƾ!ǦƞǄǃǦǁƐǦƸƽƑǊǦǃộƾǦƸủƶǦǃƼƐƾ!ǦÁƾǦƸƽƐ——",
    ["你问他？他叫樊大鸣，清河人， Thiên Phúc năm thứ sáu tòng quân."] = "ƩƼươƾǦƽỏƾǦƽắǃ?ǦƣắǃǦǉƙǃǦƫƽƐǃǦĐạƾǦƨƾǃƽ,ǦǃƼườƾǦǥƽƶǃƽǦƣƐ,ǦǃăǂǦǥƽƾƙǃǦƫƽƕƸǦǉƽứǦǈƑǊǦǉƛǃƼǦǆǊƁǃ.",
    ["愿意北去的弟兄不少。"] = "ƣǊǓǃƽǦđệǦǃƼǊǓệǃǦƈǦđƾǦǋềǦǅƽƓƶǦƝắƸǦǀƽƇǃƼǦƓǉǦđƁǊ.",
    ["可杜帅那边不是——"] = "ƩƽưǃƼǦǅƽƓƶǦĐỗǦǈǄƑƾǦƸƽẳǃƼǦǅƽảƾǦǁƐ——",
    ["不是什么？哥你直说呀。咱们现在，不都是一窝의 兔子，被按在这烂泥里，等着虏人宰？"] = "ƞƽẳǃƼǦǅƽảƾǦǁƐǦƼƔ?ǦƞƶǦƸứǦǃƚƾǦǉƽẳǃƼǦǇƶǦđƾ.ǦƞƽƕǃƼǦǉƶǦƷƁǓǦƼƾờǦƸƽẳǃƼǦǅƽảƾǦđềǊǦǁƐǦǂộǉǦổǦǉƽỏ,ǦƷịǦấǃǦǍǊốǃƼǦǋũǃƼǦƷƖǃǦǃƐǓǦƸƽờǦǆǊƁǃǦƼƾặƸǦǉƽịǉǦǈƶǄ?",
    ["……罢了。萧老弟，你读过书，比我们哥几个会盘算。"] = "……ǥƽƇƾǦđượƸǦǇồƾ.ǦǥƾƙǊǦǁƃǄǦđệ,ǦđệǦǁƐǦǃƼườƾǦƸƚǦƽọƸ,ǦƷƾếǉǦǉƓǃƽǦǉǄƑǃǦƽơǃǦǂấǓǦƶǃƽǦƺǂǦǉƶ.",
    ["兄弟，借口水——哎！萧兄弟，你也在这儿啊……"] = "ƣǊǓǃƽǦđệ,ǦǍƾǃǦƽớǅǦǃướƸ——ǦƠ!ǦǥƾƙǊǦƽǊǓǃƽǦđệ,ǦđệǦƸũǃƼǦởǦđƁǓǦƐ……",
    ["徐、徐老弟，咱们这也算掏心窝子在卖力。杜库吏不在，这军库不照样看得严严实实，没出半、半点儿褶子。"] = "ǥừ,ǦǥừǦǁƃǄǦđệ,ǦƷọǃǦǂƔǃƽǦǉƽếǦǃƐǓǦƸũǃƼǦƸǄƾǦǁƐǦǤốƸǦƽếǉǦǉƾǂǦƼƶǃǦǇƶǦǁƐǂǦǋƾệƸǦǇồƾ.ǦĐỗǦǀƽốǦǁạƾǦǀƽƇǃƼǦƸƚǦǂặǉ,ǦǆǊƁǃǦǀƽốǦǃƐǓǦƸƽẳǃƼǦǅƽảƾǦǋẫǃǦđượƸǦǉǇƇǃƼǦƸǄƾǦǃƼƽƾƙǂǦǃƼặǉ,ǦǀƽƇǃƼǦđểǦǍảǓǦǇƶǦǃửƶǦđƾểǂǦǈƶƾǦǈƚǉǦđƚǦǈƶǄ.",
    ["诶老刘，你说他犯了事，这库吏的位置，是不是又该回到你头上了？"] = "ÊǦǁƃǄǦƧưǊ,ǦǃƼươƾǦǃƚƾǦǍƺǂǦƽắǃǦǅƽạǂǦǁỗƾǦǇồƾ,ǦƸƑƾǦƸƽứƸǦƦƽốǦǁạƾǦǃƐǓǦƸƚǦǅƽảƾǦǁƐǦǈẽǦǆǊƶǓǦǋềǦǉƶǓǦǃƼươƾǦǀƽƇǃƼ?",
    ["听说他前阵子悄摸帮大帅走了点生意，捞着不少油水呢！你可得……"] = "ƩƼƽƺǦǃƚƾǦǤạǄǦǉǇướƸǦƽắǃǦǁƗǃǦƼƾƕǅǦĐạƾǦǈǄƑƾǦǁƐǂǦăǃǦƸƽƕǉǦđỉǃƽ,ǦǋớǦđượƸǦǀƽƇǃƼǦƓǉǦǤầǊǦǂỡǦđƁǊ!ǦƩƼươƾǦǅƽảƾ……",
    ["那敢情好啊！秀姑娘，你要s能叫我那木头师弟开金口……"] = "ǥƽếǦǉƽƔǦǉốǉǦǆǊƑǦǇồƾ!ǦǥƕǦƸƇǦǃươǃƼ,ǦǃếǊǦƸƇǦƸƚǦǉƽểǦǀƽƾếǃǦƸƽǄǦǋịǦƨộƸǦĐầǊǦǈưǦđệǦǃƐǓǦƸủƶǦǉƶǦƸƽịǊǦǂởǦǂƾệǃƼǦǋƐǃƼ……",
    ["怎么，杜重威의 裤裆不好钻，想换尊佛脚上贡？"] = "ƮƶǄǦƽả,ǦƽƑǃƼǦƸủƶǦĐỗǦǥǇọǃƼǦǕǓǦǀƽƚǦƸƽǊƾǦǆǊƑ,ǦǃƙǃǦǂǊốǃǦđổƾǦǈƶǃƼǦƇǂǦƸƽƁǃǦƫƽậǉǦǀƽƑƸǦđểǦǤƁǃƼǦǁễǦǈƶǄ?",
    ["渡河要jin，你快护送墨门同袍过去，这里交给我！"] = "ƱượǉǦǈƇǃƼǦǁƐǦƽệǦǉǇọǃƼ,ǦǃƼươƾǦǂƶǊǦƽộǦǉốǃƼǦđồǃƼǦǂƇǃǦƨặƸǦƨƇǃǦǆǊƶǦđƚ,ǦởǦđƁǓǦƸứǦƼƾƶǄǦƸƽǄǦǉƶ!",
    ["杜帅既已谋定，晚生仅余一言——"] = "ĐỗǦǈǄƑƾǦđƃǦǂưǊǦđịǃƽǦǍǄǃƼǦǍǊƇƾ,ǦǋƃǃǦǈƾǃƽǦƸƽỉǦƸƛǃǦǂộǉǦǁờƾǦƸǊốƾ——",
    ["晚生幼年伴祖父随军出行，于大雪见红梅. 祖父有言，霜寒彻骨之日，亦是天地春来之时。"] = "ƱƃǃǦǈƾǃƽǦǉƽǊởǦǃƽỏǦǉƽƺǄǦǉổǦǅƽụǦǉƛǃƼǦǆǊƁǃ,ǦƼƾữƶǦǉǇờƾǦǉǊǓếǉǦǁớǃǦǉƽấǓǦǃƽƐǃƽǦƽồǃƼǦǂƶƾ.ǦǥổǦǅƽụǦƸƚǦǁờƾǦǇằǃƼ,ǦǃƼƐǓǦǈươǃƼǦǁạǃƽǦǉƽấǊǦǍươǃƼ,ǦƸũǃƼǦƸƽƓǃƽǦǁƐǦǁƕƸǦǉƽƾƙǃǦđịƶǦǍǊƁǃǦǈƶǃƼ.",
    ["亲卫甲"] = "ǥƽƁǃǦǋệǦƢƾƑǅ",
    ["亲卫乙"] = "ǥƽƁǃǦǋệǦẤǉ",
    ["是，我费亦可是追名逐利的小人， but 只要将军看得起我，我一定尽心辅佐小将军，肝脑涂地也要成就一番伟业！"] = "ƫƽảƾ,ǦƫƽƓǦǝƾệƸǦƦƽảǦǉƶǦǁƐǦǀẻǦǉƾểǊǦǃƽƁǃǦǉǇǊǓǦǤƶǃƽǦǉǇụƸǦǁợƾ,ǦǃƽưǃƼǦƸƽỉǦƸầǃǦǉướǃƼǦǆǊƁǃǦƸǄƾǦǉǇọǃƼǦǉƶ,ǦǉƶǦǃƽấǉǦđịǃƽǦǉậǃǦǉƁǂǦǅƽƛǦǉƑǦǉƾểǊǦǉướǃƼǦǆǊƁǃ,ǦƼƶǃǦƚƸǦđấǉǦƷƖǃǦƸũǃƼǦǅƽảƾǦǉƽƐǃƽǦǉựǊǦǂộǉǦǅƽƺǃǦǋĩǦǃƼƽƾệǅ!",
    ["【契丹语]中原人！来啊！"] = "[ǥƾếǃƼǦƦƽƾếǉǦĐƶǃ]ǦƩƼườƾǦǥǇǊǃƼǦƩƼǊǓƙǃ!ǦǥớƾǦđƁǓ!",
    ["什么人，打枣子，把羞儿害？"] = "ƩƼườƾǦǃƐǄ,ǦƽƑƾǦǉƑǄ,ǦǉƽẹǃǦǉƽƖǃƼǦǉƽƶǓ?",
    ["咱们快逃吧？"] = "ƞƽƕǃƼǦǉƶǦǂƶǊǦƸƽạǓǦđƾǦǉƽƇƾ?",
    ["咱不逃，咱等死，那娃儿怎么办啊！"] = "ǥƶǦǀƽƇǃƼǦƸƽạǓ,ǦǉƶǦƸƽờǦƸƽếǉ,ǦǃƽưǃƼǦƸƛǃǦđứƶǦǉǇẻǦđƚǦǉƽƔǦǁƐǂǦǈƶǄǦƷƁǓǦƼƾờ!",
    ["你真当自己这条烂命能有用？你没瞧见北边的京观？想再去添个头吗？！"] = "ƩƼươƾǦǉƽậǉǦǈựǦƸƽǄǦǇằǃƼǦƸƑƾǦǂạǃƼǦǇƑƸƽǦǃƐǓǦƸủƶǦǂƔǃƽǦƸƚǦƓƸƽǦǈƶǄ?ǦƩƼươƾǦǀƽƇǃƼǦǉƽấǓǦđốǃƼǦđầǊǦǃƼườƾǦƸƽấǉǦƸƶǄǦǃƽưǦǃƕƾǦởǦǅƽƓƶǦƝắƸǦƐ?ǦƨǊốǃǦǉớƾǦđƚǦƼƚǅǦǉƽƙǂǦǂộǉǦƸƑƾǦđầǊǦǃữƶǦǈƶǄ?!",
    ["冷脸大侠？江……其他人呢！"] = "ƧƃǃƽǦǝƾệǃǦđạƾǦƽƾệǅ?ǦƢƾƶǃƼ……ǦǃƽữǃƼǦǃƼườƾǦǀƽƑƸǦđƁǊǦǇồƾ!",
    ["啧，别管我了， you 走吧。"] = "ƞƽậƸ,ǦđừǃƼǦǆǊảǃǦǉƶǦǃữƶ,ǦǃƼươƾǦđƾǦđƾ.",
    ["这地方就要完了，我们…… we 该往哪里逃？"] = "ƩơƾǦǃƐǓǦǈắǅǦǍǄǃƼǦđờƾǦǇồƾ,ǦƸƽƕǃƼǦǉƶ……ǦƸƽƕǃƼǦǉƶǦǃƙǃǦƸƽạǓǦđƾǦđƁǊ?",
    ["而若师父已经遭遇不测……我也还得继续救人. "] = "ƞƛǃǦǃếǊǦǈưǦǅƽụǦđƃǦƼặǅǦƷấǉǦǉǇắƸ……ǦƸǄǃǦƸũǃƼǦǋẫǃǦǅƽảƾǦǉƾếǅǦǉụƸǦƸứǊǦǃƼườƾ.",
    ["些个到处行侠仗义的臭蛆扒都不见了，这些个红衣服的还想着怎么去拖延时间，也活不了多久了……"] = "ƨấǓǦƸƑƾǦǁũǦǤƛƾǦƷọǦƽƇƾǦƽƑǂǦǈǊốǉǦǃƼƐǓǦƽƐǃƽǦƽƾệǅǦǉǇượǃƼǦǃƼƽĩƶǦđềǊǦƷƾếǃǦǂấǉǦǈạƸƽǦǇồƾ,ǦƸƛǃǦđƑǂǦǂặƸǦƑǄǦđỏǦǃƐǓǦǋẫǃǦƸƛǃǦǃƼƽĩǦƸƑƸƽǦǀƗǄǦǤƐƾǦǉƽờƾǦƼƾƶǃ,ǦƸũǃƼǦƸƽẳǃƼǦǈốǃƼǦđượƸǦƷƶǄǦǁƁǊǦǃữƶǦđƁǊ……",
    ["小福车不吃，小福车活不了. "] = "ǥƾểǊǦƫƽƕƸǦƳƶǦǀƽƇǃƼǦăǃ,ǦǥƾểǊǦƫƽƕƸǦƳƶǦǀƽƇǃƼǦǈốǃƼǦǃổƾ.",
    ["活不了……活不了了…… hu……"] = "ƦƽƇǃƼǦǈốǃƼǦđượƸ……ǦǀƽƇǃƼǦǈốǃƼǦǃổƾǦǃữƶǦǇồƾ……ǦƽǊ……",
    ["他们都说，死了好多人，再不跑就命了……"] = "ƣọǦđềǊǦǃƚƾ,ǦƸƽếǉǦǃƽƾềǊǦǃƼườƾǦǁắǂǦǇồƾ,ǦǀƽƇǃƼǦƸƽạǓǦǃƽƶǃƽǦǉƽƔǦǂấǉǦǂạǃƼǦđấǓ……",
    ["不，我还能再战几场，咳咳，他们……也都没有走。"] = "ƦƽƇǃƼ,ǦǉƶǦƸƛǃǦƸƚǦǉƽểǦƸƽƾếǃǦǉƽƙǂǦǋƐƾǦǉǇậǃǦǃữƶ,ǦǀƽụǦǀƽụ...ǦƷọǃǦƽọ...ǦƸũǃƼǦđềǊǦƸƽưƶǦđƾ.",
    ["敢问中渡桥怎么走？"] = "ǝƑǂǦƽỏƾǦǥǇǊǃƼǦĐộǦƦƾềǊǦđƾǦǉƽếǦǃƐǄ?",
    ["多谢，保重！"] = "ĐƶǦǉạ,ǦƷảǄǦǉǇọǃƼ!",
    ["何须劳烦千秋笔，不记得便不记得罢。"] = "ƣƐǦǉấǉǦǁƶǄǦǅƽƾềǃǦǃƼƛƾǦƷƕǉǦǃƼƽƔǃǦǉƽǊ,ǦǀƽƇǃƼǦǃƽớǦǉƽƔǦǉƽƇƾǦǋậǓ.",
    ["阿沱, 你看，草会发芽，太阳也会升起来的。"] = "ƜǦĐƐ,ǦǃƽƔǃǦǀƔƶ,ǦƸỏǦǈẽǦǃảǓǦǂầǂ,ǦǂặǉǦǉǇờƾǦƸũǃƼǦǈẽǦǁạƾǦǂọƸǦǁƙǃ.",
    ["呃，呜呜……啊啊啊……！"] = "Ư...ǦƽǊǦƽǊ...ǦƶǦƶǦƶ...!",
    ["无名客，侠者无名……我知道了。"] = "ƱƇǦǝƶǃƽǦƦƽƑƸƽ,ǦƽƾệǅǦƼƾảǦǋƇǦǤƶǃƽ...ǦǉƶǦƽƾểǊǦǇồƾ.",
    ["如今，你也成了其中一人。当年，我幸为无名客所救，只跛了脚，没烂进泥里……"] = "ƩƶǓǦǃƼươƾǦƸũǃƼǦđƃǦǉǇởǦǉƽƐǃƽǦǂộǉǦǃƼườƾǦǉǇǄǃƼǦǈốǦƽọ.ǦƩăǂǦđƚ,ǦǉƶǦǂƶǓǦǂắǃǦđượƸǦƱƇǦǝƶǃƽǦƦƽƑƸƽǦƸứǊǦƼƾƕǅ,ǦƸƽỉǦǁƐǦǉƽọǉǦƸƽƁǃ,ǦƸƽứǦǀƽƇǃƼǦƷịǦǋƖƾǦǉƽƁǓǦǉǇǄǃƼǦƷƖǃǦđấǉ...",
    ["无意千秋之人，最应被千秋所记。"] = "ƩƼườƾǦǀƽƇǃƼǦǂƐǃƼǦǃƼƽƔǃǦǉƽǊ,ǦǁạƾǦƸƐǃƼǦđƑǃƼǦđượƸǦǃƼƽƔǃǦǉƽǊǦƼƽƾǦǃƽớ.",
    ["长风去，万里遥遥送客归……"] = "ǥǇườǃƼǦǅƽǄǃƼǦǉƾễǃ,ǦǋạǃǦǤặǂǦǍƶǦǍăǂǦđưƶǦǀƽƑƸƽǦǋề...",
    ["曾有无名客说， he vô sở图，只愿春草又绿，旭日东升。"] = "ǥừǃƼǦƸƚǦƱƇǦǝƶǃƽǦƦƽƑƸƽǦǃƚƾǦǇằǃƼ,ǦƽắǃǦǀƽƇǃƼǦǂưǊǦƸầǊǦƼƔ,ǦƸƽỉǦǃƼǊǓệǃǦƸỏǦǍǊƁǃǦǁạƾǦǍƶǃƽ,ǦǉƽƑƾǦǤươǃƼǦǁƚǦǇạǃƼ.",
    ["英雄所言所想相若，将军也说过，此树有朝一日……"] = "ƜǃƽǦƽƖǃƼǦǈởǦǃƼƇǃǦǈởǦǉưởǃƼǦǉươǃƼǦǃƽượƸ,ǦǉướǃƼǦǆǊƁǃǦƸũǃƼǦǉừǃƼǦǃƚƾ,ǦƸƑƾǦƸƁǓǦǃƐǓǦƸƚǦǂộǉǦǃƼƐǓ...",
    ["英雄……将军……"] = "ƜǃƽǦƽƖǃƼ...ǦǉướǃƼǦǆǊƁǃ...",
    ["有我俩在这，局面尚且能控制得住。多守一日，也许就能多救一人. "] = "ƞƚǦƽƶƾǦǉƶǦởǦđƁǓ,ǦƸụƸǦǤƾệǃǦǋẫǃǦƸƛǃǦƸƚǦǉƽểǦǀƽốǃƼǦƸƽếǦđượƸ.ǦƢƾữǦǉƽƙǂǦǂộǉǦǃƼƐǓ,ǦƸƚǦǁẽǦǈẽǦƸứǊǦǉƽƙǂǦđượƸǦǂộǉǦǃƼườƾ.",
    ["外头的侠客，是为了替咱乡里老小报仇. 还有些将士、百姓，是为了拖住那些虏人，给咱们多争来些逃跑的时间！"] = "ƩƽữǃƼǦƽƾệǅǦǀƽƑƸƽǦƷƙǃǦǃƼǄƐƾǦǀƾƶǦǁƐǦđểǦƷƑǄǦǉƽƖǦƸƽǄǦƼƾƐǦǉǇẻǦǉǇǄǃƼǦǁƐǃƼǦǉƶ.ǦƞƛǃǦƸƚǦǃƽữǃƼǦǉướǃƼǦǈĩ,ǦƷƑƸƽǦǉƓǃƽǦđƶǃƼǦƸầǂǦƸƽƁǃǦǁũǦƼƾặƸ,ǦđểǦǉǇƶǃƽǦǉƽủǦǉƽƙǂǦƸƽƕǉǦǉƽờƾǦƼƾƶǃǦƸƽạǓǦǉǇốǃǦƸƽǄǦƸƽƕǃƼǦǉƶ!",
    ["姐姐和阿爹阿娘……会坐着小船……来找 An An ……"] = "ǥỷǦǉỷǦƸƖǃƼǦƜǦƸƽƶǦƜǦǃươǃƼ...ǦǈẽǦǃƼồƾǦǉƽǊǓềǃǦǃƽỏ...ǦđếǃǦǉƔǂǦƜǃǦƜǃ...",
    ["停！那是她们是从虏人那来的！虏人杀了我爹，后来又杀了我娘。她们呢？在我们村子里好好活着……我和她唱采薇，我阿公教她说汉话，凭什么？！她们，她们本就欠……"] = "ǝừǃƼǦǁạƾ!ǦƣọǦǁƐǦǉừǦǅƽƓƶǦǆǊƁǃǦƼƾặƸǦǉớƾ!ǦƢƾặƸǦƼƾếǉǦƸƽƶǦǉƇƾ,ǦǈƶǊǦđƚǦǁạƾǦƼƾếǉǦǂẹǦǉƇƾ.ǦƞƛǃǦƽọǦǉƽƔǦǈƶǄ?ǦỞǦǉǇǄǃƼǦǉƽƇǃǦƸƽƕǃƼǦǉƇƾǦǈốǃƼǦǓƙǃǦổǃ...ǦǥƇƾǦǋƐǦǃƚǦƸƖǃƼǦƽƑǉǦǥƽƑƾǦƱƾ,ǦƶǦƸƇǃƼǦǉƇƾǦǤạǓǦǃƚǦǃƚƾǦǉƾếǃƼǦƣƑǃ,ǦǤựƶǦǋƐǄǦƸƑƾǦƼƔǦƸƽứ?!ǦƣọǦǋốǃǦǤĩǦđƃǦǃợ...",
    ["你是……会唱《采薇>吗？"] = "ƩƼươƾ...ǦƷƾếǉǦƽƑǉǦ<ǥƽƑƾǦƱƾ>ǦǈƶǄ?",
    ["他们都走了，说契丹人打来了，再不逃就命了……"] = "ƣọǦđƾǦƽếǉǦǇồƾ,ǦǃƚƾǦǃƼườƾǦƦƽƾếǉǦĐƶǃǦđƑǃƽǦǉớƾǦǃơƾǦǇồƾ,ǦǀƽƇǃƼǦǉǇốǃǦǃƽƶǃƽǦǁƐǦǂấǉǦǂạǃƼ...",
    ["大侠，你说话啊……我听来了好多消息，真的假的，新的旧 of ……"] = "ĐạƾǦƽƾệǅ,ǦǃƼƐƾǦǃƚƾǦƼƔǦđƾǦƸƽứ...ǦǉƇƾǦǃƼƽƺǦđượƸǦǇấǉǦǃƽƾềǊǦǉƾǃǦǉứƸ,ǦǉƽựƸǦǉƽựƸǦƽưǦƽư,ǦƸũǦƸƚǦǂớƾǦƸƚ...",
    ["……你骗我……我知道，你们都骗 me ……"] = "...ǦƩƼƐƾǦƼạǉǦǉƇƾ...ǦǉƇƾǦƷƾếǉ,ǦƸƑƸǦǃƼườƾǦđềǊǦƼạǉǦǉƇƾ...",
    ["哎，听说早上将军在后院发了好大一通脾气，怪乌卢本火点得太猛，烧毁好些书页子呢！"] = "ƩƐǓ,ǦǃƼƽƺǦǃƚƾǦǈƑǃƼǦǃƶǓǦǉướǃƼǦǆǊƁǃǦởǦƽậǊǦǋƾệǃǦǃổƾǦǉǇậǃǦǁƇƾǦđƔǃƽ,ǦǉǇƑƸƽǦƆǦƧƇǦƝảǃǦđốǉǦǁửƶǦǆǊƑǦǂạǃƽ,ǦǁƐǂǦƸƽƑǓǦƽỏǃƼǦƷƶǄǦǃƽƾƙǊǦǉǇƶǃƼǦǈƑƸƽǦđấǓ!",
    ["你懂什么？这次 we 可不是劫掠一番就走……是要这中原天下。"] = "ƩƼươƾǦǉƽƔǦƷƾếǉǦƸƑƾǦƼƔ?ǦƧầǃǦǃƐǓǦƸƽƕǃƼǦǉƶǦǀƽƇǃƼǦǅƽảƾǦƸướǅǦǅƽƑǦǂộǉǦǅƽƺǃǦǇồƾǦđƾ...ǦǂƐǦǁƐǦǂǊốǃǦƸƚǦƸảǦƼƾƶǃƼǦǈơǃǦǥǇǊǃƼǦƩƼǊǓƙǃǦǃƐǓ.",
    ["哼，当初那些主张封山的人， injustice 就是太过畏首畏尾了。"] = "ƣừ,ǦđƑǂǦǃƼườƾǦƸƽủǦǉǇươǃƼǦǅƽǄǃƼǦǈơǃǦǃăǂǦđƚ,ǦƸƽƓǃƽǦǁƐǦǆǊƑǦǂứƸǦǈợǦđầǊǦǈợǦđǊƇƾ.",
    ["他们都走了，说契丹人打来了，再不逃就m命了……"] = "ƣọǦđềǊǦđƾǦƸảǦǇồƾ,ǦǃƚƾǦǁƐǦǃƼườƾǦƦƽƾếǉǦĐƶǃǦđƑǃƽǦǉớƾ,ǦƸƛǃǦǀƽƇǃƼǦƸƽạǓǦǁƐǦǂấǉǦǂạǃƼ...",
    ["张安康，收起你那哑巴德行，我就要你一句话——\n这店你卖不卖？这招牌和我们家，你到底要哪个？"] = "ǥǇươǃƼǦƜǃǦƦƽƶǃƼ,ǦǉƽǊǦǁạƾǦƸƑƾǦđứƸǦƽạǃƽǦƸƁǂǦǃƓǃǦđƚǦƸủƶǦǃƼươƾǦđƾ,ǦǉƶǦƸƽỉǦƸầǃǦǃƼươƾǦǂộǉǦƸƁǊǦǉƽƇƾǦ——\nǥƾệǂǦǃƐǓǦǃƼươƾǦƸƚǦƷƑǃǦƽƶǓǦǀƽƇǃƼ?ǦƞƑƾǦƷảǃƼǦƽƾệǊǦǃƐǓǦǋƐǦƼƾƶǦđƔǃƽǦƸƽƕǃƼǦǉƶ,ǦǇốǉǦƸǊộƸǦǃƼươƾǦǂǊốǃǦƸƑƾǦǃƐǄ?",
    ["都能要。"] = "ĐềǊǦƸƚǦǉƽểǦǂǊốǃ.",
    ["王老爷为富不仁！"] = "ƱươǃƼǦǁƃǄǦƼƾƶǦǋƾǦǅƽƕǦƷấǉǦǃƽƁǃ!",
    ["陆三儿谋财害命！"] = "ƧụƸǦǥƶǂǦǃƽƾǦǂưǊǦǉƐƾǦƽạƾǦǂệǃƽ!",
    ["新年顺遂，百病皆消。"] = "ƩăǂǦǂớƾǦǉƽǊậǃǦǁợƾ,ǦƷƑƸƽǦƷệǃƽǦǉƾƙǊǦǉƶǃ.",
    ["要我说，这宫里头，就数咱宝慈宫의差事最美。你闻闻，风里都带着一股甜甜的香。"] = "ĐểǦǉƶǦǃƚƾǦƸƽǄǦǃƼƽƺ,ǦởǦǉǇǄǃƼǦƸǊǃƼǦǃƐǓ,ǦǋƾệƸǦởǦƝảǄǦǥừǦƞǊǃƼǦǉƶǦǁƐǦǉốǉǦǃƽấǉ.ǦƩƼươƾǦǃƼửƾǦǍƺǂ,ǦǉǇǄǃƼǦƼƾƚǦƸƛǃǦǂƶǃƼǦǉƽƺǄǦǂộǉǦǂƖƾǦƽươǃƼǦǃƼọǉǦǃƼƐǄ.",
    ["好幸福，皇帝의女人陪我当值。"] = "ǥƽậǉǦƽạǃƽǦǅƽƕƸ,ǦǃữǦǃƽƁǃǦƸủƶǦƽǄƐǃƼǦđếǦƸƖǃƼǦǉƶǦǉǇựƸǦƷƶǃ.",
    ["我这招，学起来可不容易。"] = "ƞƽƾƙǊǦǃƐǓǦƸủƶǦǉƶ,ǦƽọƸǦđượƸǦǀƽƇǃƼǦǤễǦđƁǊ.",
    ["秋姐姐，这个笑话还有后续！说这个橙子，以酱涂身，反而存活，因为酱在外，菌令有所不受。哈哈哈……"] = "ǥƽǊǦǉỷǦǉỷ,ǦƸƽǊǓệǃǦƸườƾǦǃƐǓǦƸƛǃǦƸƚǦƽậǊǦƷảǃ!ǦƩƚƾǦǆǊảǦƸƶǂǦđƚǦǁấǓǦǉươǃƼǦƷƇƾǦǁƙǃǦǉƽƁǃ,ǦǃƼượƸǦǁạƾǦǈốǃƼǦǈƚǉ,ǦƷởƾǦǋƔǦǉươǃƼǦởǦǃƼǄƐƾǦ(ǥướǃƼǦǉạƾǦǃƼǄạƾ),ǦǁệǃƽǦƸủƶǦǃấǂǦ(ƬǊƁǃǦǁệǃƽ)ǦƸƚǦƸƽỗǦǀƽƇǃƼǦǃƽậǃ.ǦƣƶǦƽƶǦƽƶ...",
    ["你们有一炷香의工夫，就此题自行相商，须得拿出个章程来。"] = "ƞƑƸǦǃƼươƾǦƸƚǦǉƽờƾǦƼƾƶǃǦǂộǉǦǃƗǃǦǃƽƶǃƼ,ǦƽƃǓǦǉựǦǂƔǃƽǦǉƽươǃƼǦǁượǃƼǦǋềǦđềǦƷƐƾǦǃƐǓ,ǦǅƽảƾǦđưƶǦǇƶǦđượƸǦǂộǉǦǅƽươǃƼǦƑǃǦǇƅǦǇƐǃƼ.",
    ["若奉给了娘子，老夫人一路辛劳，宝慈宫却连杯热茶都端不出——传出去，岂不是要让咱们娘子担上一个怠慢长辈、不忠不孝의罪名？"] = "ƩếǊǦǤƁǃƼǦƸƽǄǦǃươǃƼǦǉử,ǦǁƃǄǦǅƽǊǦǃƽƁǃǦđườǃƼǦǍƑǦǋấǉǦǋả,ǦƝảǄǦǥừǦƞǊǃƼǦǁạƾǦđếǃǦǂộǉǦƸƽƗǃǦǉǇƐǦǃƚǃƼǦƸũǃƼǦǀƽƇǃƼǦƷưǃƼǦǇƶǦđượƸǦ——ǦǉǇǊǓềǃǦǇƶǦǃƼǄƐƾ,ǦƸƽẳǃƼǦǅƽảƾǦǀƽƾếǃǦǃươǃƼǦǉửǦǃƽƐǦǉƶǦǅƽảƾǦƼƑǃƽǦǉộƾǦǤƶǃƽǦđƃƾǦǃƼộǦǉǇưởǃƼǦƷốƾǦǀƽƇǃƼǦƸƽǊǦđƑǄ,ǦƷấǉǦǉǇǊǃƼǦƷấǉǦƽƾếǊǦǈƶǄ?",
    ["还、还能这么说？"] = "ƞƛǃ...ǦƸƛǃǦƸƚǦǉƽểǦǃƚƾǦǉƽếǦǈƶǄ?",
    ["方才你们讨论的，我们都听看见了，现在还有一个问题——"] = "ƩƽữǃƼǦƼƔǦƸƑƸǦǃƼươƾǦǉƽảǄǦǁǊậǃǦǋừƶǦǇồƾ,ǦƸƽƕǃƼǦǉƶǦđềǊǦđƃǦǃƼƽƺǦǉƽấǓ,ǦƽƾệǃǦǉạƾǦƸƛǃǦǂộǉǦƸƁǊǦƽỏƾǦǃữƶǦ——",
    ["宝慈宫里，最懂娘子心意、最会办事의便是秋姐姐。我们这点本事，哪能跟秋姐姐比？"] = "ǥǇǄǃƼǦƝảǄǦǥừǦƞǊǃƼ,ǦǃƼườƾǦƽƾểǊǦǉƁǂǦƈǦǃươǃƼǦǉửǦǃƽấǉ,ǦƷƾếǉǦǁƐǂǦǋƾệƸǦǃƽấǉǦƸƽƓǃƽǦǁƐǦǥƽǊǦǉỷǦǉỷ.ǦƞƽƕǉǦƷảǃǦǈựǦǃƐǓǦƸủƶǦƸƽƕǃƼǦǉƶǦǈƶǄǦǈǄǦđượƸǦǋớƾǦǥƽǊǦǉỷǦǉỷ?",
    ["方才考校，唯有银筝一人在用心思量对策。宫里要의，难道不该是这般脚踏实地、能办实事的人吗？"] = "ƞǊộƸǦǀƽảǄǦƽạƸƽǦǋừƶǦǇồƾ,ǦƸƽỉǦƸƚǦǂộǉǦǂƔǃƽǦƩƼƁǃǦǥǇƶǃƽǦǁƐǦǤụǃƼǦǉƁǂǦǈǊǓǦǃƼƽĩǦđốƾǦǈƑƸƽ.ǦǥƽứǦǉǇǄǃƼǦƸǊǃƼǦƸầǃ,ǦƸƽẳǃƼǦǁẽǦǀƽƇǃƼǦǅƽảƾǦǁƐǦƽạǃƼǦǃƼườƾǦǁƐǂǦǋƾệƸǦǉƽƾếǉǦǉƽựƸ,ǦƸƽắƸǦƸƽắǃǦǃƽưǦǋậǓǦǈƶǄ?",
    ["原以为你是个实诚의，未曾想也挺机灵，知晓为自己争取。"] = "ƱốǃǦǉưởǃƼǦǃƼươƾǦǁƐǦǀẻǦǉƽƐǃƽǦǉƽậǉ,ǦǀƽƇǃƼǦǃƼờǦƸũǃƼǦǀƽƑǦǁƶǃƽǦǁợƾ,ǦƷƾếǉǦǉựǦǉǇƶǃƽǦǉƽủǦƸƽǄǦǂƔǃƽ.",
    ["是挺滑稽的，没想到能逗娘子您开心……"] = "ĐƕǃƼǦǁƐǦǇấǉǦǃựƸǦƸườƾ,ǦǀƽƇǃƼǦǃƼờǦǁạƾǦƸƚǦǉƽểǦǁƐǂǦǃươǃƼǦǉửǦǋǊƾǦǋẻ...",
    ["秋凤不敢……今日本就是笑招，宝慧虽会端水奉茶，但银筝这太极功夫更胜一筹，既能洒扫，又能博您一笑……是银筝胜了。"] = "ǥƽǊǦƫƽượǃƼǦǀƽƇǃƼǦǤƑǂ...ǦƽƇǂǦǃƶǓǦǋốǃǦǁƐǦǉƾếǊǦƸƽƾƙǊ,ǦƝảǄǦǥǊệǦǉǊǓǦƷƾếǉǦƷưǃƼǦǃướƸǦǤƁǃƼǦǉǇƐ,ǦǃƽưǃƼǦƸƇǃƼǦǅƽǊǦǥƽƑƾǦƞựƸǦǃƐǓǦƸủƶǦƩƼƁǃǦǥǇƶǃƽǦǁạƾǦƸƶǄǦƽơǃǦǂộǉǦƷậƸ,ǦǋừƶǦƸƚǦǉƽểǦǆǊƗǉǦǤọǃ,ǦǁạƾǦǋừƶǦƸƚǦǉƽểǦǀƽƾếǃǦǃƼƐƾǦǂỉǂǦƸườƾ...ǦǁƐǦƩƼƁǃǦǥǇƶǃƽǦǉƽắǃƼǦǇồƾ.",
    ["我……我入选了？我真的入选了？！谢大人！谢娘子！"] = "ǥƶ……ǦǉƶǦǉǇƕǃƼǦǉǊǓểǃǦǇồƾ?ǦǥƶǦǉƽậǉǦǈựǦǉǇƕǃƼǦǉǊǓểǃǦǇồƾ?!ǦǥạǦơǃǦđạƾǦǃƽƁǃ!ǦǥạǦơǃǦǃươǃƼǦǉử!",
    ["过来过来，哎，凑近点……"] = "ƧạƾǦđƁǓǦǁạƾǦđƁǓ,ǦǃƐǓ,ǦƼƽƗǦǈƑǉǦǋƐǄǦǂộǉǦƸƽƕǉ……",
    ["这可好，引得江湖上那些个 phi檐 tẩu bích đích nhân nhi，都想来见识见识！"] = "ǥƽếǦǁƐǦƽƶǓǦǇồƾ,ǦǉƽǊǦƽƕǉǦđƑǂǦǃƼườƾǦǉƽƁǃǦǅƽƑǅǦǉậǉǦƽƐǃƽǦǉǇƙǃǦƼƾƶǃƼǦƽồ,ǦƶƾǦƸũǃƼǦǂǊốǃǦđếǃǦǂởǦǂƶǃƼǦǉầǂǦǂắǉ!",
    ["这自在劲儿 —— 你是新入宫的？"] = "ƞƑƾǦǋẻǦǉựǦǉạƾǦǃƐǓǦ——ǦǃƼươƾǦǂớƾǦǋƐǄǦƸǊǃƼǦǈƶǄ?",
    ["陛下의东西，可得收拾稳妥些……"] = "ĐồǦđạƸǦƸủƶǦƷệǦƽạ,ǦǅƽảƾǦǤọǃǦǤẹǅǦƸƽǄǦổǃǦǉƽỏƶ...",
    ["都是为陛下大典预备의。稍有差池，咱们谁都吃罪不起。"] = "ĐềǊǦƸƽǊẩǃǦƷịǦƸƽǄǦđạƾǦđƾểǃǦƸủƶǦƷệǦƽạǦƸả.ǦƞƽệƸƽǦǂộǉǦǁƾǦǉƽƇƾǦǁƐǦƶƾǦǉǇǄǃƼǦƸƽƕǃƼǦǉƶǦƸũǃƼǦǀƽƇǃƼǦƼƑǃƽǦǃổƾǦǉộƾǦđƁǊ.",
    ["嘘 —— 也有人说，那是钓贼的饵！"] = "ƮǊỵǉǦ——ǦƸũǃƼǦƸƚǦǃƼườƾǦǃƚƾ,ǦđƚǦǁƐǦǂồƾǦǃƽửǦǉǇộǂǦđấǓ!",
    ["你得记着那些被取用의折子书册的样子，还有它们被收起来之前与之后的位置。免得之后官家问起来，你只能跟个木头似的杵着。"] = "ƩƼươƾǦǅƽảƾǦǃƽớǦǀỹǦƽƔǃƽǦǤƑǃƼǦƸủƶǦǃƽữǃƼǦǈớǦǉấǊǦǈƑƸƽǦǋởǦđượƸǦǁấǓǦǤƖǃƼ,ǦƸũǃƼǦǃƽưǦǋịǦǉǇƓǦƸủƶǦƸƽƕǃƼǦǉǇướƸǦǋƐǦǈƶǊǦǀƽƾǦđượƸǦƸấǉǦđƾ.ǦĐểǦǈƶǊǦǃƐǓǦƬǊƶǃǦƼƾƶǦƸƚǦƽỏƾǦđếǃ,ǦǃƼươƾǦǀƽƇǃƼǦǅƽảƾǦđứǃƼǦđựƸǦǇƶǦǃƽưǦǀƽƕƸǦƼỗ.",
    ["这般好의主意，若是没有常侍提点，我定是想不出的！"] = "ÝǦƽƶǓǦǃƽưǦǋậǓ,ǦǃếǊǦǀƽƇǃƼǦƸƚǦǥƽườǃƼǦǉƽịǦƸƽỉǦđƾểǂ,ǦǉƶǦƸƽắƸǦƸƽắǃǦǀƽƇǃƼǦǃƼƽĩǦǇƶǦđượƸ!",
    ["宁姑总怕宫里知道了会将淮姑赶走，整日提心胆的，其实，淮姑藏在那里，宫里怎会不知道呢？"] = "ƩƾǃƽǦƸƇǦƸứǦǈợǦǉǇǄǃƼǦƸǊǃƼǦƷƾếǉǦƸƽǊǓệǃǦǈẽǦđǊổƾǦƣǄƐƾǦƸƇǦđƾ,ǦǃƙǃǦǃƼƐǓǦǃƐǄǦƸũǃƼǦǁǄǦǁắǃƼǦƽƃƾǦƽƖǃƼ,ǦǉƽựƸǦǇƶǦƣǄƐƾǦƸƇǦǉǇốǃǦởǦđƚ,ǦǉǇǄǃƼǦƸǊǃƼǦǁƐǂǦǈƶǄǦǂƐǦǀƽƇǃƼǦƷƾếǉǦđượƸǦƸƽứ?",
    ["如此便说定了！待得闲时，我二人可要好好合练一番. "] = "ƱậǓǦǉƽƔǦǆǊǓếǉǦđịǃƽǦǉƽếǦǃƽƗ!ǦĐợƾǦǁƕƸǦǇảǃƽǦǇỗƾ,ǦƽƶƾǦƸƽƕǃƼǦǉƶǦǅƽảƾǦƸƖǃƼǦǃƽƶǊǦƽợǅǦǁǊǓệǃǦǂộǉǦǅƽƺǃǦƸƽǄǦǉƽậǉǦǉốǉ.",
    ["……既然马可同乘，驴子也未必不可. 若是你能暂时放下对驴子的恐惧，我倒是能搭你一程。"] = "……ƩếǊǦǃƼựƶǦƸƚǦǉƽểǦƸưỡƾǦƸƖǃƼ,ǦǉƽƔǦǁừƶǦƸũǃƼǦƸƽẳǃƼǦǅƽảƾǦǁƐǦǀƽƇǃƼǦǉƽể.ǦƩếǊǦǃƼươƾǦƸƚǦǉƽểǦǉạǂǦǉƽờƾǦƼạǉǦƷỏǦǃỗƾǦǈợǦƽƃƾǦǋớƾǦǁǄƐƾǦǁừƶ,ǦǉƶǦƸƚǦǉƽểǦƸƽǄǦǃƼươƾǦđƾǦǃƽờǦǂộǉǦđǄạǃ.",
    ["别跟我，说话……一说话，就，难受……"] = "ĐừǃƼǦǃƚƾǦƸƽǊǓệǃǦǋớƾǦǉƶ...ǦƸứǦƽễǦǃƚƾǦƸƽǊǓệǃǦǁƐǦǁạƾǦǉƽấǓǦǀƽƚǦƸƽịǊ...",
    ["呃，茅厕在那边. "] = "Ờ,ǦǃƽƐǦǋệǦǈƾǃƽǦởǦđằǃƼǦǀƾƶǦǀƔƶ.",
    ["……田. "] = "……ƭǊộǃƼ.",
