    ["窝囊。白瞎一柄好刀。"] = "ƩƽǊǦǃƽượƸ.ǦƫƽƓǦƽǄƐƾǦǂộǉǦǉƽƶǃƽǦƽảǄǦđƶǄ.",
    ["武德司这衣服怎么了？哦，你是讨厌当官的。"] = "ƝộǦđồǦƱƅǦĐứƸǦǥǓǦǃƐǓǦǉƽƔǦǁƐǂǦǈƶǄ?ǦÀ,ǦǃƼươƾǦǁƐǦƼƽƗǉǦǀẻǦǁƐǂǦǆǊƶǃ.",
    ["……倒是天真。"] = "...ǦƞũǃƼǦǉƽậǉǦǉƽƾƙǃǦƸƽƁǃ.",
    ["我的武德司令牌。不打了？"] = "ƧệǃƽǦƷƐƾǦƱƅǦĐứƸǦǥǓǦƸủƶǦǉƶ.ǦƦƽƇǃƼǦđƑǃƽǦǃữƶǦǈƶǄ?",
    ["哦，什么关系的什么人？"] = "Ồ,ǦǁƐǦǃƼườƾǦǉƽếǦǃƐǄ,ǦǆǊƶǃǦƽệǦƼƔ?",
    ["这么复杂。明明有仇，为什么又说有恩？既然有恩，你为什么要杀他？"] = "ƫƽứƸǦǉạǅǦǋậǓǦǈƶǄ.ǦƭƅǦǇƐǃƼǦƸƚǦǉƽƖ,ǦǉạƾǦǈƶǄǦǁạƾǦǃƚƾǦƸƚǦơǃ?ǦĐƃǦƸƚǦơǃ,ǦǉạƾǦǈƶǄǦǃƼươƾǦǁạƾǦǂǊốǃǦƼƾếǉǦƽắǃ?",
    ["就是为了杀这个人，不惜往皇宫里闯？"] = "ƞƽỉǦǋƔǦǂǊốǃǦƼƾếǉǦǃƼườƾǦǃƐǓǦǂƐǦǀƽƇǃƼǦǉƾếƸǦǍƇǃƼǦǋƐǄǦƽǄƐǃƼǦƸǊǃƼǦǈƶǄ?",
    ["“天有白玉京，地藏龙宫宝。登阶上重楼，明珠列成行。四象迷人眼，六星始为真。列中取青阳，一动待清响。”"] = "\"ǥƽƾƙǃǦƽữǊǦƝạƸƽǦƩƼọƸǦƦƾǃƽ,ǦđịƶǦǉƐǃƼǦƧǄǃƼǦƞǊǃƼǦƷảǄ.ǦĐăǃƼǦƼƾƶƾǦǉƽượǃƼǦǉǇọǃƼǦǁƁǊ,ǦǂƾǃƽǦƸƽƁǊǦǁƾệǉǦǉƽƐǃƽǦƽƐǃƼ.ǦǥứǦǉượǃƼǦǂƙǦǃƽƁǃǦǃƽƃǃ,ǦǁụƸǦǉƾǃƽǦǉƽủǓǦǋƾǦƸƽƁǃ.ǦƧƾệǉǦǉǇǊǃƼǦǉƽủǦǥƽƶǃƽǦǝươǃƼ,ǦǃƽấǉǦđộǃƼǦđƃƾǦǉƽƶǃƽǦƽưởǃƼ.\"",
    ["封桩库岗哨的布局，暗门与钥匙的位置……这也太详尽了——"] = "ƝốǦƸụƸǦƸươǃƼǦǉƾếǊǦƸủƶǦƫƽǄǃƼǦǥǇƶǃƼǦƦƽố,ǦǋịǦǉǇƓǦƑǂǦǂƇǃǦǋƐǦƸƽƔƶǦǀƽƚƶ...ǦƸƑƾǦǃƐǓǦƸũǃƼǦǆǊƑǦǉườǃƼǦǉậǃǦǇồƾǦ——",
    ["赵匡胤？偷国库的是皇帝自己？"] = "ǥǇƾệǊǦƦƽǊƇǃƼǦǝẫǃ?ǦǥǇộǂǦǆǊốƸǦǀƽốǦƸƽƓǃƽǦǁƐǦƷảǃǦǉƽƁǃǦƽǄƐǃƼǦđế?",
    ["官家早有言，若是有人不愿低头就算了，就坐着听吧。"] = "ƬǊƶǃǦƼƾƶǦǈớǂǦđƃǦƸƚǦǁờƾ,ǦǃếǊǦƸƚǦǃƼườƾǦǀƽƇǃƼǦǃƼǊǓệǃǦƸƕƾǦđầǊǦǉƽƔǦǉƽƇƾǦǋậǓ,ǦƸứǦǃƼồƾǦđƚǦǂƐǦǃƼƽƺ.",
    ["“自黄巢之祸以来，争戈已有近百年。朕从世宗处接过天下之责，又与众卿同心协力，夙兴夜寐，方初定纷争。征战不可再启，凡事应谋安定。”"] = "\"ǥừǦǈƶǊǦƽọƶǦƣǄƐǃƼǦƮƐǄǦđếǃǦǃƶǓ,ǦđƔǃƽǦƸƽƾếǃǦđƃǦƼầǃǦǉǇăǂǦǃăǂ.ǦǥǇẫǂǦǉừǦƸƽỗǦǥƽếǦǥƇǃƼǦǉƾếǅǦǃƽậǃǦǉǇọǃƼǦǉǇƑƸƽǦǉƽƾƙǃǦƽạ,ǦǁạƾǦƸƖǃƼǦƸƽƕǃƼǦǀƽƶǃƽǦđồǃƼǦǉƁǂǦƽƾệǅǦǁựƸ,ǦǉƕƸǦƽưǃƼǦǤạǦǂị,ǦǂớƾǦǈơǦđịǃƽǦđượƸǦǅƽƁǃǦǉǇƶǃƽ.ǦƞƽƾǃƽǦƸƽƾếǃǦǀƽƇǃƼǦǉƽểǦǉƑƾǦǀƽởƾ,ǦǅƽƐǂǦǈựǦđềǊǦǃƙǃǦǂưǊǦƸầǊǦƶǃǦđịǃƽ.\"",
    ["燕云……"] = "ƴƙǃǦƱƁǃ...",
    ["原来……还是这么啰里吧嗦。"] = "ǥƽƔǦǇƶ...ǦǋẫǃǦǁƐǦǁảƾǦǃƽảƾǦǃƽưǦǋậǓ.",
    ["对了，你——"] = "ƫƽảƾǦǇồƾ,ǦǃƼươƾǦ——",
    ["还有一个跑了！"] = "ƞƛǃǦǂộǉǦǉƙǃǦƸƽạǓǦǉƽǄƑǉǦǇồƾ!",
    ["京尹大人。大人。"] = "ƦƾǃƽǦǝǄƃǃǦđạƾǦǃƽƁǃ.ǦĐạƾǦǃƽƁǃ.",
    ["她——"] = "ƩƐǃƼǦǉƶǦ——",
    ["赵京娘。"] = "ǥǇƾệǊǦƦƾǃƽǦƩươǃƼ",
    ["这是……京尹怎么……"] = "ĐƁǓǦǁƐ...ǦƦƾǃƽǦǝǄƃǃǦǈƶǄǦǁạƾ...",
    ["将她带走。"] = "ƨƶǃƼǦǃƐǃƼǦǉƶǦđƾ.",
    ["呵，刺客？"] = "ƣừ,ǦǉƽƓƸƽǦǀƽƑƸƽ?",
    ["……之后再谈。"] = "...ǦƮƶǊǦǃƐǓǦƽƃǓǦƷƐǃ.",
    ["陛下要阻我？"] = "ƝệǦƽạǦǂǊốǃǦƸảǃǦǉƶ?",
    ["抹得去石上刻痕，抹不去……心中芥蒂。"] = "ƳƚƶǦđượƸǦǋếǉǦǀƽắƸǦǉǇƙǃǦđƑ,ǦǃƽưǃƼǦǀƽƇǃƼǦǍƚƶǦđượƸ……ǦǋếǉǦƼợǃǦǉǇǄǃƼǦǁƛǃƼ.",
    ["规矩……忠良惨死，恶犬当道——这就是官家的规矩？"] = "ƬǊǓǦƸủ……ǦǉǇǊǃƼǦǁươǃƼǦǉƽảǂǦǉử,ǦƑƸǦǀƽǊǓểǃǦđươǃƼǦđạǄǦ——ǦđƁǓǦƸƽƓǃƽǦǁƐǦǆǊǓǦƸủǦƸủƶǦƬǊƶǃǦƼƾƶǦǈƶǄ?",
    ["……臣，谢恩。"] = "...Ǧǥƽầǃ,ǦǉạǦơǃ.",
    ["我初时也只以为那些是从有人下面池子里带上来的水。直到我在顶层也发现了来源不明的水迹……"] = "ƧƕƸǦđầǊǦǉƶǦƸũǃƼǦƸƽỉǦǉưởǃƼǦđƚǦǁƐǦǃướƸǦǉừǦƽồǦǤướƾǦƸƽỗǦƸƚǦǃƼườƾǦǂƶǃƼǦǁƙǃ.ǦƞƽǄǦđếǃǦǀƽƾǦǉƶǦǅƽƑǉǦƽƾệǃǦǋệǉǦǃướƸǦǀƽƇǃƼǦǇƅǦǃƼǊồǃǦƼốƸǦởǦƸảǦǉầǃƼǦđỉǃƽ...",
    ["尉迟静诺"] = "ǕấǉǦǥǇƔǦǥĩǃƽǦƩặƸ",
    ["大侠，我家在梓匠居，回去取再回来，得走两个时辰…这…兄弟们都回家了……且好不容易跑出来……万一回去被婆娘抓到了咋办……"] = "ĐạƾǦƽƾệǅ,ǦǃƽƐǦǉƇƾǦởǦǥửǦǥượǃƼǦƞư,ǦǆǊƶǓǦǋềǦǁấǓǦǇồƾǦǉǇởǦǁạƾǦđƁǓǦƸũǃƼǦǅƽảƾǦǂấǉǦƽƶƾǦƸƶǃƽǦƼƾờ…ǦƸƽǊǓệǃǦǃƐǓ…ǦƽǊǓǃƽǦđệǦđềǊǦđƃǦǋềǦǃƽƐǦƸảǦǇồƾ……ǦǋảǦǁạƾǦǀƽƚǦǀƽăǃǦǁắǂǦǂớƾǦǉǇốǃǦǇƶǦđượƸ……ǦǋạǃǦǃƽấǉǦǋềǦǃƽƐǦƷịǦƷƐǦǍƃǦƷắǉǦđượƸǦǉƽƔǦǉƓǃƽǦǈƶǄ……",
    ["对…小怜儿乖，等他们办完事，咱们就能丰衣足食、读书习字，过上…好日子。"] = "ĐƕǃƼ…ǦǥƾểǊǦƧƾƙǃǦƩƽƾǦǃƼǄƶǃ,ǦđợƾǦƷọǃǦƽọǦǁƐǂǦǍǄǃƼǦǋƾệƸ,ǦƸƽƕǃƼǦǉƶǦǈẽǦđượƸǦƸơǂǦǃǄǦƑǄǦấǂ,ǦđọƸǦǈƑƸƽǦǋƾếǉǦƸƽữ,ǦǈốǃƼǦǃƽữǃƼǦǃƼƐǓ……ǦǉốǉǦđẹǅ.",
    ["菊娘……我……我……"] = "ƞƕƸǦƩươǃƼ……Ǧǉƶ……Ǧǉƶ……",
    ["菊娘……好…好…好看……"] = "ƞƕƸǦƩươǃƼ……Ǧđẹǅ…Ǧđẹǅ…ǦđẹǅǦǁắǂ……",
    ["小马呦"] = "ǥƾểǊǦƨƃǦǃƽƶ",
    ["萧萧雨些"] = "ǥƾƙǊǦǥƾƙǊǦƱũǦǥƑ",
    ["亓箫伊"] = "ƦỳǦǥƾƙǊǦƴ",
    ["沉于尘"] = "ǥǇầǂǦƱǊǦǥǇầǃ",
    ["骑歆翊"] = "ǥƾƙǊǦǥǇƕƸǦƧƁǂ",
    ["欢迎下次再来送宝！"] = "ƣǄƶǃǦǃƼƽƙǃƽǦǁầǃǦǈƶǊǦǁạƾǦǉớƾǦǤƁǃƼǦƷảǄǦǋậǉ!",
    ["啊这个好，这个——那还是，给老大吧——"] = "Ɯ,ǦƸƑƾǦǃƐǓǦǉốǉ,ǦƸƑƾǦǃƐǓǦ——ǦƽƶǓǦǁƐ,ǦđưƶǦƸƽǄǦǁƃǄǦđạƾǦđƾǦ——",
    ["那这本《大侠传》就我先看了哦。唔这个大侠叫伊刀，"] = "ƱậǓǦǆǊǓểǃǦ<ĐạƾǦƣƾệǅǦǥǇǊǓệǃ>ǦǃƐǓǦđểǦǉƶǦǍƺǂǦǉǇướƸǦǃƽƗ.ǦỪǂ,ǦǋịǦđạƾǦƽƾệǅǦǃƐǓǦǉƙǃǦǁƐǦƴǦĐƶǄ,",
    ["他有一柄大刀——诶，我也有刀！"] = "ƣắǃǦƸƚǦǂộǉǦǉƽƶǃƽǦđạƾǦđƶǄǦ——ǦƁǓ,ǦǉƶǦƸũǃƼǦƸƚǦđƶǄ!",
    ["瞬希"] = "ǥƽǊấǃǦƣǓ",
    ["权五"] = "ƬǊǓềǃǦƩƼũ",
    ["故火"] = "ƞốǦƣỏƶ",
    ["上宁淮"] = "ǥƽượǃƼǦƩƾǃƽǦƣǄƐƾ",
    ["呵，江湖人。江湖人要是个个能靠的住，当年王清怎么会倒在中渡桥？瞪我作甚，"] = "ƣừ,ǦƼƾƶǃƼǦƽồǦǃƽƁǃ.ǦƢƾƶǃƼǦƽồǦǃƽƁǃǦǃếǊǦƶƾǦƸũǃƼǦƸƚǦǉƽểǦǉƾǃǦƸậǓ,ǦǃăǂǦđƚǦƱươǃƼǦǥƽƶǃƽǦǈƶǄǦƸƚǦǉƽểǦǃƼƃǦǍǊốǃƼǦǉạƾǦƸầǊǦǥǇǊǃƼǦĐộ?ǦǥǇừǃƼǦǉƶǦǁƐǂǦƸƽƾ,",
    ["行，不提！十六年了，连白骨都化没了，还有什么人提。"] = "ĐượƸ,ǦǀƽƇǃƼǦǃƽắƸǦǃữƶ!ǦƨườƾǦǈƑǊǦǃăǂǦǇồƾ,ǦđếǃǦǍươǃƼǦǉǇắǃƼǦƸũǃƼǦƽƚƶǦǉƽƐǃƽǦƽưǦǀƽƇǃƼ,ǦƸƛǃǦƶƾǦǃƽắƸǦǁạƾǦǁƐǂǦƼƔ.",
    ["这位大爷，是江湖人？"] = "ƱịǦđạƾǦƼƾƶǦǃƐǓ,ǦǁƐǦƼƾƶǃƼǦƽồǦǃƽƁǃ?",
    ["呲，这么心善啊，那就好好带路。"] = "ƳƔ,ǦǉƁǂǦǉƽƾệǃǦǃƽưǦǋậǓǦǈƶǄ,ǦǋậǓǦǉƽƔǦǁǄǦǂƐǦǤẫǃǦđườǃƼ.",
    ["又是白水，老子从边关一路杀过来，酒都不给我"] = "ƧạƾǦǁƐǦǃướƸǦǁƃ,ǦǁƃǄǦǉửǦǉừǦƷƾƙǃǦǆǊƶǃǦǂộǉǦđườǃƼǦǈƑǉǦǅƽạǉǦǉớƾǦđƁǓ,ǦǇượǊǦƸũǃƼǦǀƽƇǃƼǦƸƽǄǦǉƶ",
    ["来碗吗？"] = "ǁấǓǦǂộǉǦƷƑǉǦǈƶǄ?",
    ["哈！你这恶霸，以前干尽坏事，我红线大侠今日就要替天行道收了你！"] = "ƣƶ!ǦƩƼươƾǦƸƑƾǦǉƙǃǦƑƸǦƷƑǦǃƐǓ,ǦǉǇướƸǦǀƾƶǦǁƐǂǦǉậǃǦƸƽǊǓệǃǦǍấǊ,ǦƣồǃƼǦǥǊǓếǃǦđạƾǦƽƾệǅǦǉƶǦƽƇǂǦǃƶǓǦǅƽảƾǦǉƽếǦǉƽƾƙǃǦƽƐǃƽǦđạǄǦǉƽǊǦǅƽụƸǦǃƼươƾ!",
    ["怎么样老大我帅不帅，是不是和话本里一模一样？"] = "ǥƽếǦǃƐǄǦǁƃǄǦđạƾ,ǦǉƶǦƸƚǦǈǄƑƾǦǀƽƇǃƼ,ǦƸƚǦǅƽảƾǦƼƾốǃƼǦǓǦƽệǉǦǉǇǄǃƼǦǉƽǄạƾǦƷảǃǦǀƽƇǃƼ?",
    ["勉勉强强，清河第二帅吧。"] = "ƨƾễǃǦƸưỡǃƼǦđƾ,ǦǥƽƶǃƽǦƣƐǦđệǦǃƽịǦǈǄƑƾ.",
    ["你个小滑头，你找我还想作甚？"] = "ƞƑƾǦđồǦǉƾểǊǦƽǄạǉǦđầǊǦǃƼươƾ,ǦǃƼươƾǦǉƔǂǦǉƶǦƸƛǃǦǂǊốǃǦǁƐǂǦƼƔ?",
    ["要是破庙坑我的事儿就算了，寒香寻还"] = "ƩếǊǦǁƐǦƸƽǊǓệǃǦởǦǅƽƑǦǂƾếǊǦƽốǦǉƶǦǉƽƔǦƷỏǦđƾ,ǦƣƐǃǦƣươǃƼǦǥầǂǦƸƛǃ",
    ["骂了我一顿，说是我话没说顺，这我认。"] = "ǂắǃƼǦǉƶǦǂộǉǦǉǇậǃ,ǦǃƚƾǦǁƐǦǉạƾǦǉƶǦǁờƾǦǁẽǦǀƽƇǃƼǦǁưǊǦǁǄƑǉ,ǦƸƑƾǦǃƐǓǦǉƶǦǃƽậǃ.",
    ["下面那个小妹子也要走？"] = "ǥƾểǊǦǂǊộƾǦǉửǦƷƙǃǦǤướƾǦǀƾƶǦƸũǃƼǦǂǊốǃǦđƾǦǈƶǄ?",
    ["大侠最怕——最怕你爹爹妈妈。"] = "ĐạƾǦƽƾệǅǦǈợǦǃƽấǉǦ——ǦǈợǦǃƽấǉǦƸƽƶǦǂẹǦƸủƶǦǃƼươƾ.",
    ["就今晚夜半，那个舞马的破庙见。"] = "ƞứǦǆǊǓếǉǦđịǃƽǦđƙǂǦǃƶǓ,ǦƼặǅǦǃƽƶǊǦǉạƾǦǉƛƶǦǅƽƑǦǂƾếǊǦƱũǦƨƃǦǀƾƶ.",
    ["你等我老大！我现在就——诶诶！"] = "ƩƼươƾǦđợƾǦǉƶǦǋớƾǦǁƃǄǦđạƾ!ǦǥƶǦƷƁǓǦƼƾờǦǁƾềǃǦ——ǦƁǓǦƁǓ!",
    ["书鳢"] = "ǥƽưǦƧễ",
    ["玉默言"] = "ƩƼọƸǦƨặƸǦƩƼƇǃ",
