    ["秦川游人"] = "ǥầǃǦƳǊǓƙǃǦǝǊǦƩƽƁǃ",
    ["哎，少东家别走啊，这可是个大生意！老金有门路弄到浮景舫的图纸，咱筹钱也"] = "Ɯƾ,ǦǉƽƾếǊǦđƇǃƼǦƼƾƶǦđừǃƼǦđƾǦǂƐ,ǦđƁǓǦƸƽƓǃƽǦǁƐǦǂộǉǦǋụǦǁƐǂǦăǃǦǁớǃ!ǦƧƃǄǦƦƾǂǦƸƚǦǂƇǃǦǁộǦǁấǓǦđượƸǦƷảǃǦǋẽǦƸủƶǦƫƽƖǦƞảǃƽǦƫƽảǃƼ,ǦƸƽƕǃƼǦǉƶǦƼƚǅǦǉƾềǃǦƸũǃƼ",
    ["造上一艘，转手少说也能赚个百两黄金，不，二百两。"] = "ƸƽếǦǉạǄǦǂộǉǦƸƽƾếƸ,ǦƸƽǊǓểǃǦǉƶǓǦǉƽấǅǦǃƽấǉǦƸũǃƼǦƸƚǦǉƽểǦǀƾếǂǦđượƸǦǉǇăǂǦǁượǃƼǦƽǄƐǃƼǦǀƾǂ,ǦǀƽƇǃƼ,ǦƽƶƾǦǉǇăǂǦǁượǃƼ.",
    ["且先应付着，倒要看看你到底躲在哪儿。"] = "ƞứǦǋƾệƸǦứǃƼǦǅƽƚǦđƃ,ǦđểǦǍƺǂǦǇốǉǦƸǊộƸǦǃƼươƾǦǉǇốǃǦởǦǃơƾǦǃƐǄ.",
    ["\n使用此物，可获得奇术“#Y叶龙骧首#E”的绝世外观特效——狻猊镇心。\n\n该道具无法兑换为音玉，不可寄售。"] = "\nƮửǦǤụǃƼǦǋậǉǦǃƐǓ,ǦƸƚǦǉƽểǦǃƽậǃǦđượƸǦƽƾệǊǦứǃƼǦǃƼǄạƾǦǆǊƶǃǦǉǊǓệǉǦǉƽếǦƸủƶǦǀỳǦǉƽǊậǉǦ\"ǝƾệǅǦƧǄǃƼǦǥươǃƼǦǥƽủ\"Ǧ——ǦǥǄƶǃǦƩƼƽƙǦǥǇấǃǦǥƁǂ.\n\nĐạǄǦƸụǦǃƐǓǦǀƽƇǃƼǦǉƽểǦđổƾǦǉƽƐǃƽǦƀǂǦƩƼọƸ,ǦǀƽƇǃƼǦǉƽểǦǀƈǦǉƽƑƸǦƷƑǃǦǁẻ.",
    ["燕吉切菜"] = "ǥƽầǃǦǥǇƖǦƦƽǄƑƾǦĐƶǄǦƦƽƑƸƽ",
    ["貔貅赐福禄，献瑞宝，辟邪佞，为百姓所喜。\n有兽自天外来，欢游人间，寻人间富贵，佑百姓安居。\n所见者皆消百病，远霉晦，得八方之禄，纳四海之财。"] = "ƣƾệǊǦứǃƼǦǃƼǄạƾǦǆǊƶǃǦƸủƶǦƦỳǦǉƽǊậǉǦ#YƦƾǂǦǥƽƾềǂǦĐằǃƼǦǝượƸ#E.\nǥỳǦƣưǊǦǉứǦǅƽƕƸǦǁộƸ,ǦƽƾếǃǦǉƽụǓǦƷảǄ,ǦǉịƸƽǦǉƐǦǃịǃƽ,ǦđượƸǦƷƑƸƽǦǉƓǃƽǦǓƙǊǦǉƽƓƸƽ.\nƞƚǦǁƾǃƽǦǉƽƕǦǉừǦǉƽƾƙǃǦǃƼǄạƾǦǁƶƾ,ǦǋǊƾǦƸƽơƾǦǃƽƁǃǦƼƾƶǃ,ǦǉƔǂǦǃƽƁǃǦƼƾƶǃǦǅƽƕǦǆǊƈ,ǦǅƽƖǦƽộǦƷƑƸƽǦǉƓǃƽǦƶǃǦƸư.\nƩƼườƾǦǃƽƔǃǦǉƽấǓǦđềǊǦǉƾƙǊǦƷƑƸƽǦƷệǃƽ,ǦǉǇƑǃƽǦǋậǃǦǇủƾ,ǦđượƸǦǁộƸǦǉƑǂǦǅƽươǃƼ,ǦǃạǅǦǉƐƾǦƷốǃǦƷƾểǃ.",
    ["\n使用此物，可获得奇术“#Y金蟾腾跃#E”的绝世外观特效——貔貅赐宝。\n\n该道具无法兑换为音玉，不可寄售。"] = "\nƮửǦǤụǃƼǦǋậǉǦǃƐǓ,ǦƸƚǦǉƽểǦǃƽậǃǦđượƸǦƽƾệǊǦứǃƼǦǃƼǄạƾǦǆǊƶǃǦǉǊǓệǉǦǉƽếǦƸủƶǦƦỳǦǉƽǊậǉǦ\"ƦƾǂǦǥƽƾềǂǦĐằǃƼǦǝượƸ\"Ǧ——ǦǥỳǦƣưǊǦǥứǦƝảǄ.\n\nĐạǄǦƸụǦǃƐǓǦǀƽƇǃƼǦǉƽểǦđổƾǦǉƽƐǃƽǦƀǂǦƩƼọƸ,ǦǀƽƇǃƼǦǉƽểǦǀƈǦǉƽƑƸǦƷƑǃ.",
    ["ĐộƸǦǀƽǊẩǃǦǁƶǃǦǉǇƐǃǦởǦƝƔǃƽǦƢƾảǦƩƼǊǓƙǃ,百姓ǦǋƔǦǃạǃǦđƚƾǦǂƐǦǀƽổǦǀƽƇǃƼǦǉƽấǊ.ǦĐểǦƼƾƕǅǦđỡǦǤƁǃǦƸƽƕǃƼ,ǦǃƼươƾǦǋƐǄǦǥƽườǃƼǦƝƔǃƽǦǥƽươǃƼ,ǦǁạƾǦǅƽƑǉǦƽƾệǃǦǥƽườǃƼǦƝƔǃƽǦǈứǦǉƽậǉǦǈựǦǁƐǦǥƽẩǂǦƩƼƽĩƶǦƧǊƁǃǦđƃǦǈớǂǦƷịǦƽảǄǦƽữǊǦǥǇịǃƽǦƩƼạƸǦƼƾƶǂǦƸầǂ.ǦƞƛǃǦǉƙǃǦǥƽườǃƼǦƝƔǃƽǦǈứǦƼƾảǦǃƐǓǦđƃǦƁǂǦǉƽầǂǦǂưǊǦǉƓǃƽǦǃƽƾềǊǦǃăǂ,ǦƈǦđồǦƽủǓǦǤƾệǉǦƦƽƶƾǦƫƽǄǃƼ...ǦǝướƾǦǈựǦǃỗǦǁựƸǦƸủƶǦǃƼươƾǦǋƐǦǥƽẩǂǦƩƼƽĩƶǦƧǊƁǃ,ǦǂộǉǦƸǊộƸǦđạƾǦǃạǃǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦđượƸǦƽƚƶǦƼƾảƾ."] = "ƢầǃǦƷếǃǦǈƇǃƼ,ǦƷƑƸƽǦǉƓǃƽǦđƶǃƼǦƽốƾǦƽảǦƸƽạǓǦǃạǃ.ǦĐểǦǃƼăǃǦƸƽặǃǦǆǊƁǃǦƦƽƾếǉǦĐƶǃǦǉǇǊǓǦǀƓƸƽ,ǦǉướǃƼǦǁĩǃƽǦǉǇƾềǊǦđƔǃƽǦđƶǃƼǦǤẫǃǦǆǊƁǃǦǉửǦƸƽƾếǃ,ǦǉƔǃƽǦƽƔǃƽǦƸựƸǦǀỳǦǃƼǊǓǦƸấǅ,ǦƷƑƸƽǦǉƓǃƽǦǋƐǦǉƐǃǦǆǊƁǃǦđƶǃƼǦǀẹǉǦǉạƾǦđƁǓ.",
    ["使用此物，可获得奇术“狮吼正声”的绝世外观特效——钟鸣正音。"] = "ƮửǦǤụǃƼǦǋậǉǦǃƐǓ,ǦƸƚǦǉƽểǦǃƽậǃǦđượƸǦƽƾệǊǦứǃƼǦǃƼǄạƾǦƽƔǃƽǦǉǊǓệǉǦǉƽếǦƸủƶǦǀỳǦǉƽǊậǉǦ\"ƮưǦƣốǃƼǦƞƽƓǃƽǦǥƽƶǃƽ\"Ǧ—ǦƞƽǊǃƼǦƨƾǃƽǦƞƽƓǃƽǦƀǂ.",
    ["琉璃钟，五音同，狮吼遗响托长风。\n万法千相皆弦上，一声正音天地通。"] = "ƣƾệǊǦứǃƼǦǃƼǄạƾǦƽƔǃƽǦƸủƶǦǀỳǦǉƽǊậǉǦ#YǦƮưǦƣốǃƼǦƞƽƓǃƽǦǥƽƶǃƽǦ#E.\nƧưǊǦǁǓǦƸƽǊǃƼ,ǦǃƼũǦƁǂǦđồǃƼ,ǦǈưǦƽốǃƼǦǤƾǦƽưởǃƼǦǉƽƑƸǦǉǇườǃƼǦǅƽǄǃƼ.\nƱạǃǦǅƽƑǅǦǉƽƾƙǃǦǉướǃƼǦƼƾƶƾǦƽǊǓềǃǦǉƽượǃƼ,ǦǃƽấǉǦǉƽƶǃƽǦƸƽƓǃƽǦƁǂǦǉƽƾƙǃǦđịƶǦǉƽƇǃƼ.",
    ["\n使用此物，可获得奇术“#Y狮吼正声#E”的绝世外观特效——钟鸣正音。\n\n该道具无法兑换为音玉，不可寄售。"] = "\nƮửǦǤụǃƼǦǋậǉǦǃƐǓ,ǦƸƚǦǉƽểǦǃƽậǃǦđượƸǦƽƾệǊǦứǃƼǦǃƼǄạƾǦƽƔǃƽǦǉǊǓệǉǦǉƽếǦƸủƶǦǀỳǦǉƽǊậǉǦ\"ƮưǦƣốǃƼǦƞƽƓǃƽǦǥƽƶǃƽ\"Ǧ—ǦƞƽǊǃƼǦƨƾǃƽǦƞƽƓǃƽǦƀǂ.\n\nĐạǄǦƸụǦǃƐǓǦǀƽƇǃƼǦǉƽểǦǆǊǓǦđổƾǦǉƽƐǃƽǦƀǂǦƩƼọƸ,ǦǀƽƇǃƼǦǉƽểǦǀƈǦƼửƾ.",
    ["ƧƁǊǦǉƽǊǓềǃǦƱươǃƼǦǥǊấǃǦǍǊốǃƼǦÍƸƽǦƞƽƁǊ,ǦǋươǃƼǦǀƽƓǦƦƾǂǦƧăǃƼǦǁặǃƼǦǁẽǦǉƶǃ.ǦĐểǦƼǄǂǦƼƚǅǦǆǊƁǃǦǃƽǊǦǃƶǂǦƸƽƾǃƽ,ǦǉǇƾềǊǦđƔǃƽǦƝắƸǦǥốǃƼǦǂởǦǉƾệƸǦǉǇƙǃǦƝảǄǦǥƁǃǦƧƁǊ.ǦƩƼươƾǦđếǃǦǉƽƶǂǦǤự,ǦǃƽưǃƼǦƷấǉǦǃƼờǦƷịǦƸǊốǃǦǋƐǄǦǂộǉǦƸǊộƸǦǊǓǦƽƾếǅǦǋƐǦƷƑƸ弈ǦǍǄƶǓǦǆǊƶǃƽǦƸụƸǦǤƾệǃǦǥǇườǃƼǦƢƾƶǃƼ,ǦǋƐǦǅƽƑǉǦƽƾệǃǦǇƶǦƷƓǦǂậǉǦđộǃƼǦǉǇờƾǦẩǃǦƼƾấǊǦǃơƾǦǉƽƁǂǦǈƁǊǦƸủƶǦđạƾǦƽạǂǦƩƼũǦƩƽƶ."] = "ƮƶǊǦǀƽƾǦđƑǃƽǦƷạƾǦƸƑƸǦǉƽǊộƸǦƽạǦƸủƶǦƞǊồǃƼǦƧƶǃ,ǦƷạǃǦđƃǦǅƽƑǉǦƽƾệǃǦǇƶǦǂộǉǦǂậǉǦđạǄǦǤẫǃǦđếǃǦƽƶǃƼǦđộǃƼǦƸủƶǦǀẻǦƸầǂǦđầǊ,ǦƽƃǓǦǉƾếǃǦǋƐǄǦđƚǦđểǦǀƽƑǂǦǅƽƑ.ǦĐểǦǁƐǂǦđượƸǦđƾềǊǦǃƐǓ,ǦƷạǃǦƸầǃǦǅƽảƾǦƸƚǦǂộǉǦǉǇƑƾǦǉƾǂǦǆǊảǦƸảǂ,ǦǂộǉǦǀƽốƾǦƚƸǦǃƽạǓǦƷƗǃǦǋƐǦǂộǉǦǉƽƶǃƽǦǀƾếǂǦǈắƸǦƷƗǃ.ǦƣƃǓǦƸƽǊẩǃǦƷịǦǈẵǃǦǈƐǃƼǦƸƽǄǦǃƽữǃƼǦǉƽửǦǉƽƑƸƽǦǅƽƓƶǦǉǇướƸ,ǦǋƔǦƷƚǃƼǦǉốƾǦǁǊƇǃǦǇƔǃƽǦǇậǅǦǋƐǦƽƾểǂǦǃƼǊǓǦƸƚǦǉƽểǦậǅǦđếǃǦƷấǉǦƸứǦǁƕƸǦǃƐǄ.",
    ["使用此物，可获得武学“八方风雷枪”的绝世外观特效——英魂照骨。"] = "ƮửǦǤụǃƼǦǋậǉǦǃƐǓ,ǦƸƚǦǉƽểǦǃƽậǃǦđượƸǦƽƾệǊǦứǃƼǦǃƼǄạƾǦǉǇƶǃƼǦǉǊǓệǉǦǉƽếǦƸủƶǦǋƅǦƽọƸǦ\"ƝƑǉǦƫƽươǃƼǦƫƽǄǃƼǦƧƇƾǦǥƽươǃƼ\"Ǧ——ǦƜǃƽǦƣồǃǦƞƽƾếǊǦƞốǉ.",
    ["日升天衢"] = "ƩƽậǉǦǥƽăǃƼǦǥƽƾƙǃǦƞƖ",
    ["裂石·均基础教学·三"] = "ƣướǃƼǦǤẫǃǦƸơǦƷảǃǦƧƾệǉǦǥƽạƸƽ·ƬǊƁǃ·Ɲƶ",
    ["{}释放特殊技获得安西军助战{}释放易武技激活拨雪寻春"] = "{}ǦǉƽƾǦǉǇƾểǃǦǀỹǦǃăǃƼǦđặƸǦƷƾệǉǦǃƽậǃǦđượƸǦƜǃǦǥƁǓǦƬǊƁǃǦǉǇợǦƸƽƾếǃǦ{}ǦǉƽƾǦǉǇƾểǃǦǀỹǦǃăǃƼǦǤịƸƽǦǋũǦǀƓƸƽǦƽǄạǉǦƝạǉǦǥǊǓếǉǦǥầǂǦƳǊƁǃ",
    ["{}释放派生技拨雪寻春"] = "{}ǦǉƽƾǦǉǇƾểǃǦǀỹǦǃăǃƼǦǅƽƑƾǦǈƾǃƽǦƝạǉǦǥǊǓếǉǦǥầǂǦƳǊƁǃ",
    ["{}释放特殊技获得热血难凉{}释放武学技二段附加易伤效果"] = "{}ǦǉƽƾǦǉǇƾểǃǦǀỹǦǃăǃƼǦđặƸǦƷƾệǉǦǃƽậǃǦđượƸǦƩƽƾệǉǦƣǊǓếǉǦƩƶǃǦƧươǃƼǦ{}ǦǉƽƾǦǉǇƾểǃǦǀỹǦǃăǃƼǦǋƅǦƽọƸǦđǄạǃǦƽƶƾǦǀƘǂǦƽƾệǊǦǆǊảǦǤễǦƷịǦǉổǃǦǉƽươǃƼ",
    ["{}切换武器，热血难凉加速{}释放重击蓄力技"] = "{}ǦƸƽǊǓểǃǦđổƾǦǋũǦǀƽƓ,ǦƩƽƾệǉǦƣǊǓếǉǦƩƶǃǦƧươǃƼǦǉăǃƼǦǉốƸǦ{}ǦǉƽƾǦǉǇƾểǃǦǀỹǦǃăǃƼǦǉǇọǃƼǦǀƓƸƽǦǉụǦǁựƸ",
    ["\n使用此物，可获得奇术“#Y骑龙回马#E”的绝世外观特效——黄龙断戟。\n\n该道具无法兑换为音玉，不可寄售。"] = "\nƮửǦǤụǃƼǦǋậǉǦǃƐǓ,ǦƸƚǦǉƽểǦǃƽậǃǦđượƸǦƽƾệǊǦứǃƼǦǃƼǄạƾǦǆǊƶǃǦǉǊǓệǉǦǉƽếǦƸủƶǦǀỳǦǉƽǊậǉǦ\"#YƦỵǦƧǄǃƼǦƣồƾǦƨƃ#E\"Ǧ——ǦƣǄƐǃƼǦƧǄǃƼǦĐǄạǃǦƦƓƸƽ.\n\nĐạǄǦƸụǦǃƐǓǦǀƽƇǃƼǦǉƽểǦǆǊǓǦđổƾǦǉƽƐǃƽǦƀǂǦƩƼọƸ,ǦǀƽƇǃƼǦǉƽểǦǀƈǦƼửƾ.",
