    ["阿宝生的晚，没见过唐人，口音也拐，改不"] = "ƜǦƝảǄǦǈƾǃƽǦǇƶǦǂǊộǃ,ǦƸƽưƶǦǉừǃƼǦǉƽấǓǦǃƼườƾǦĐườǃƼ,ǦǀƽẩǊǦƁǂǦƸũǃƼǦǁệƸƽ,ǦǀƽƇǃƼǦđổƾ",
    ["过来。无怪你认不出她。"] = "ǁạƾǦđượƸ.ǦƞƽẳǃƼǦǉǇƑƸƽǦǃƼươƾǦǃƽậǃǦǀƽƇǃƼǦǇƶǦǃƐǃƼ.",
    ["阿宝生的晚，没见过唐人，口音也拐，改不过来。无怪你认不出她。"] = "ƜǦƝảǄǦǈƾǃƽǦǇƶǦǂǊộǃ,ǦƸƽưƶǦǉừǃƼǦǉƽấǓǦǃƼườƾǦĐườǃƼ,ǦǀƽẩǊǦƁǂǦƸũǃƼǦǁệƸƽ,ǦǀƽƇǃƼǦđổƾǦǁạƾǦđượƸ.ǦƞƽẳǃƼǦǉǇƑƸƽǦǃƼươƾǦǃƽậǃǦǀƽƇǃƼǦǇƶǦǃƐǃƼ.",
    ["以前路上有那么多人啊？"] = "ǥǇướƸǦđƁǓǦǉǇƙǃǦđườǃƼǦƸƚǦǃƽƾềǊǦǃƼườƾǦǃƽưǦǋậǓǦǈƶǄ?",
    ["……诶！"] = "……Ê!",
    ["查看文物"] = "ƦƾểǂǦǉǇƶǦǋăǃǦǋậǉ",
