    ["使用此物，可获得奇术“鹰爪连凿”的外观特效——蒲丝断玉。"] = "ƮửǦǤụǃƼǦǋậǉǦǃƐǓ,ǦƸƚǦǉƽểǦǃƽậǃǦđượƸǦƽƾệǊǦứǃƼǦǃƼǄạƾǦǆǊƶǃǦƸủƶǦǀỳǦǉƽǊậǉǦ\"ƯǃƼǦǥǇảǄǦƧƾƙǃǦǥạƸ\"Ǧ——ǦƝồǦǥƾǦĐǄạǃǦƩƼọƸ.",
    ["奇术#Y鹰爪连凿#E的外观特效。\n掌中蒲丝悬一线，截金断玉瞬息间。\n纵纤丝一缕，亦有万锋之利。"] = "ƣƾệǊǦứǃƼǦǃƼǄạƾǦǆǊƶǃǦƸủƶǦǀỳǦǉƽǊậǉǦ#YƯǃƼǦǥǇảǄǦƧƾƙǃǦǥạƸ#E.\nǥǇǄǃƼǦǁƛǃƼǦƷƐǃǦǉƶǓǦǉơǦƷồǦǉǇƺǄǦǂộǉǦǈợƾ,ǦƸắǉǦǋƐǃƼǦđứǉǦǃƼọƸǦǉǇǄǃƼǦǃƽƑǓǦǂắǉ.\nǝẫǊǦǁƐǦǂộǉǦǈợƾǦǉơǦǂảǃƽ,ǦƸũǃƼǦǂƶǃƼǦƸƑƾǦǈắƸǦƷƗǃǦƸủƶǦǋạǃǦǂũƾǦǀƾếǂ.",
    ["赋神系列武器外观【寒露惊翠】限时上架「和鸣-闻音商店」，分享武器外观可领好礼。"] = "ƩƼǄạƾǦǆǊƶǃǦǋũǦǀƽƓǦƽệǦƫƽƕǦǥƽầǃǦ[ƣƐǃǦƧộǦƦƾǃƽǦǥƽƕǓ]ǦǇƶǦǂắǉǦƸƚǦƽạǃǦƽạǃǦǉạƾǦ[ƣƛƶǦƨƾǃƽǦ-ǦƱăǃǦƀǂǦǥƽươǃƼǦĐƾếǂ],ǦƸƽƾƶǦǈẻǦǃƼǄạƾǦǆǊƶǃǦǋũǦǀƽƓǦƸƚǦǉƽểǦǃƽậǃǦǆǊƐǦǉặǃƼ.",
    ["给，这是提供了重要口供，或是缴纳了额外罚金的犯人名单。"] = "ĐưƶǦǃƼươƾ,ǦđƁǓǦǁƐǦǤƶǃƽǦǈƑƸƽǦǅƽạǂǦǃƽƁǃǦđƃǦƸǊǃƼǦƸấǅǦǀƽẩǊǦƸǊǃƼǦǆǊƶǃǦǉǇọǃƼ,ǦƽǄặƸǦđƃǦǃộǅǦǉƽƙǂǦǅƽạǉǦǀƾǂ.",
    ["你晚些去领加餐的时候别忘了他们的份。"] = "ƧƑǉǦǃữƶǦǃƼươƾǦđƾǦǁĩǃƽǦƼƾƶǦǍƑǦƸơǂǦƸƶǃƽǦǉƽƔǦđừǃƼǦǆǊƙǃǦǅƽầǃǦƸủƶǦƷọǃǦƽọ.",
    ["你当时都没了半条命了，哪记得清？要真只有几炷香的时间，"] = "ƩƼươƾǦǀƽƾǦđƚǦǃửƶǦƸƑƾǦǂạǃƼǦƸũǃƼǦǀƽƇǃƼǦƸƛǃ,ǦǈƶǄǦǂƐǦǃƽớǦǇƅǦƸƽǄǦđượƸ?ǦƩếǊǦǉƽậǉǦǈựǦƸƽỉǦƸƚǦǉƽờƾǦƼƾƶǃǦǂấǓǦǃƗǃǦǃƽƶǃƼ,",
    ["他可不会聋成现在这样，还得靠那一身武功来假装正常人。"] = "ƣắǃǦƸũǃƼǦǀƽƇǃƼǦđếǃǦǂứƸǦđƾếƸǦǃƽưǦƽƾệǃǦǉạƾ,ǦƸƛǃǦǅƽảƾǦǤựƶǦǋƐǄǦǂộǉǦǉƽƁǃǦǋƅǦƸƇǃƼǦǀƾƶǦđểǦƼƾảǦǁƐǂǦǃƼườƾǦƷƔǃƽǦǉƽườǃƼ.",
    ["我可不要那些娇滴滴的花儿！！！"] = "ǥƶǦǀƽƇǃƼǦǉƽƘǂǦǂấǓǦƷƇǃƼǦƽǄƶǦǓểǊǦđƾệǊǦǉƽụƸǦǃữǦđƚǦđƁǊ!!!",
    ["……这药不能摔的……都踩坏了……"] = "……ǥƽǊốƸǦǃƐǓǦǀƽƇǃƼǦđượƸǦǁƐǂǦǇơƾǦđƁǊ……ǦƝịǦƼƾẫǂǦƽỏǃƼǦƽếǉǦƸảǦǇồƾ……",
    ["抱歉抱歉，见到此景，在下实在欢喜，失态了。"] = "ƞƑǄǦǁỗƾǦƸƑǄǦǁỗƾ,ǦǉƽấǓǦƸảǃƽǦǉượǃƼǦǃƐǓ,ǦǉạƾǦƽạǦǉƽựƸǦǈựǦǆǊƑǦđỗƾǦǋǊƾǦǂừǃƼǦǃƙǃǦđƃǦǉƽấǉǦǉƽốǦǇồƾ.",
    ["道之所存，不止于一山之中。而在天地之间。"] = "ĐạǄǦƸƽƾǦǈởǦǉồǃ,ǦƷấǉǦƸƽỉǦưǦǃƽấǉǦǈơǃǦƸƽƾǦǉǇǊǃƼ.ǦƩƽƾǦǉạƾǦǉƽƾƙǃǦđịƶǦƸƽƾǦƼƾƶǃ.",
    ["嫂嫂是这样，我不小心落了钱，被大哥捡着了，大哥正要还我呢。"] = "ǥẩǊǦǉẩǊǦǁƐǦǉƽếǦǃƐǓ,ǦđệǦǋƇǦƈǦđƑǃƽǦǇơƾǦǉƾềǃ,ǦđượƸǦđạƾǦƸƶǦǃƽặǉǦđượƸ,ǦƽǊǓǃƽǦấǓǦđƶǃƼǦđịǃƽǦǉǇảǦǁạƾǦƸƽǄǦđệǦđƁǓ.",
    ["什么怕，这是尊重，尊重自己的娘子，生活才能过得好。"] = "ƮợǦƼƔǦƸƽứ,ǦđƁǓǦǁƐǦǉƇǃǦǉǇọǃƼ,ǦǉƇǃǦǉǇọǃƼǦǃươǃƼǦǉửǦƸủƶǦǂƔǃƽǦǉƽƔǦƸǊộƸǦǈốǃƼǦǂớƾǦƙǂǦấǂǦđượƸ.",
    ["今天多给沁娘做几道爱吃的菜！"] = "ƣƇǂǦǃƶǓǦǅƽảƾǦǁƐǂǦǉƽƙǂǦǂấǓǦǂƚǃǦǂƐǦǥƽấǂǦǃươǃƼǦǉƽƓƸƽǦăǃǦǂớƾǦđượƸ!",
    ["然后顺遂的过完这辈子，不要像我和他爹，大字不识，一辈子被困在粮米中。"] = "ƮƶǊǦđƚǦǉƽǊậǃǦǁợƾǦđƾǦƽếǉǦǀƾếǅǦǃƐǓ,ǦđừǃƼǦǃƽưǦǉƶǦǋƐǦƸƽƶǦǃƚ,ǦƸƽữǦƷẻǦđƇƾǦǀƽƇǃƼǦƷƾếǉ,ǦƸảǦđờƾǦƷịǦǋƁǓǦǀƽốǃǦǉǇǄǃƼǦƸƽǊǓệǃǦƼạǄǦǉƾềǃ.",
    ["还是感谢少侠帮我们娘俩寻这一遭，走吧小宝。"] = "ƱẫǃǦǅƽảƾǦđƶǦǉạǦǉƽƾếǊǦƽƾệǅǦđƃǦƼƾƕǅǦǂẹǦƸǄǃǦǉƶǦǂộǉǦƸƽǊǓếǃǦǃƐǓ,ǦđƾǦǉƽƇƾǦǥƾểǊǦƝảǄ.",
    ["碧色长裙，头点绒白簪花。要不随我同去会会小姐？"] = "ǥǇườǃƼǦǆǊầǃǦǂƐǊǦƷƓƸƽ,ǦđầǊǦƸƐƾǦǉǇƁǂǦƽǄƶǦǃƽǊǃƼǦǉǇắǃƼ.ǦƣƶǓǦǁƐǦđƾǦƸƖǃƼǦǉƶǦǉớƾǦƽộƾǦǀƾếǃǦǉƾểǊǦǉƽư?",
    ["南斗注生，北斗注死。凡人受胎，皆从南斗过北斗，所有祈求，皆向北斗……"] = "ƩƶǂǦĐẩǊǦƸƽƕǦǈƾǃƽ,ǦƝắƸǦĐẩǊǦƸƽƕǦǉử.ǦƫƽƐǂǦǃƽƁǃǦǉƽụǦǉƽƶƾ,ǦƼƾƶƾǦǉƖǃƼǦƩƶǂǦĐẩǊǦǆǊƑǦƝắƸǦĐẩǊ,ǦǈởǦƽữǊǦǀỳǦƸầǊ,ǦƼƾƶƾǦƽướǃƼǦƝắƸǦĐẩǊ……",
    ["不过，听我的祖父说，当年有一医者与朱鱼交好。他们好像搬到处去了，小友不妨去那儿寻寻？"] = "ƞƚǦđƾềǊ,ǦǃƼƽƺǦǉổǦǅƽụǦǉƶǦǃƚƾ,ǦǃăǂǦǍưƶǦƸƚǦǂộǉǦǓǦƼƾảǦƼƾƶǄǦƽảǄǦǋớƾǦƞƽǊǦƩƼư.ǦƣọǦǤườǃƼǦǃƽưǦđƃǦƸƽǊǓểǃǦđƾǦǃơƾǦǀƽƑƸǦǇồƾ,ǦǉƾểǊǦƽữǊǦƸƽƾǦƷằǃƼǦǉớƾǦđƚǦǉƔǂǦǉƽửǦǍƺǂǦǈƶǄ?",
    ["惓梦"] = "ƨộǃƼǦǥƶǃ",
    ["使用此物，可获得奇术“以鹅之鸣”的外观特效——以鸡之鸣。"] = "ƮửǦǤụǃƼǦǋậǉǦǃƐǓǦƸƚǦǉƽểǦǃƽậǃǦƽƾệǊǦứǃƼǦǃƼǄạƾǦǆǊƶǃǦƸƽǄǦƦỳǦǉƽǊậǉǦ\"ǥƾếǃƼǦƩƼỗǃƼǦƦƙǊ\"Ǧ——ǦǥƾếǃƼǦƢƐǦƢƑǓ.",
    ["奇术#Y以鹅之鸣#E的外观特效。\n疯狂疯狂珍馐日，嫩鸡两份九文九。囊羞不敢问价目，豪杰赠我五十否？"] = "ƣƾệǊǦứǃƼǦǃƼǄạƾǦǆǊƶǃǦƸủƶǦƦỳǦǉƽǊậǉǦ#YǦǥƾếǃƼǦƩƼỗǃƼǦƦƙǊǦ#E.\nƞǊồǃƼǦǅƽǄǃƼǦǉǇƁǃǦǉǊǦǃƽậǉ,ǦƼƐǦǂềǂǦƽƶƾǦǈǊấǉǦƸƽƓǃǦǋăǃǦƸƽƓǃ.ǦǥƕƾǦǇỗǃƼǦƸƽẳǃƼǦǤƑǂǦƽỏƾǦƼƾƑǦƸả,ǦƽƐǄǦǀƾệǉǦǉặǃƼǦǉƶǦǃăǂǦǂươƾǦǍǊǦƸƽăǃƼ?",
    ["「每周」参与5场「对局模式」对战（{0}/5）"] = "[ƨỗƾǦǉǊầǃ]ǦǥƽƶǂǦƼƾƶǦ5ǦǉǇậǃǦ[ƞƽếǦđộǦĐốƾǦđầǊ]Ǧ({0}/5)",
    ["「每周」参与10场「对局模式」对战（{0}/10）"] = "[ƨỗƾǦǉǊầǃ]ǦǥƽƶǂǦƼƾƶǦ10ǦǉǇậǃǦ[ƞƽếǦđộǦĐốƾǦđầǊ]Ǧ({0}/10)",
    ["「每周」获得6场「对局模式」胜利（{0}/6）"] = "[ƨỗƾǦǉǊầǃ]ǦǥƽắǃƼǦ6ǦǉǇậǃǦ[ƞƽếǦđộǦĐốƾǦđầǊ]Ǧ({0}/6)",
    ["在「对局模式」对战中，连续获胜5场（{0}/1）"] = "ǥƽắǃƼǦǁƾƙǃǦǉƾếǅǦ5ǦǉǇậǃǦǉǇǄǃƼǦ[ƞƽếǦđộǦĐốƾǦđầǊ]Ǧ({0}/1)",
    ["在「对局模式」对战中，连续获胜7场（{0}/1）"] = "ǥƽắǃƼǦǁƾƙǃǦǉƾếǅǦ7ǦǉǇậǃǦǉǇǄǃƼǦ[ƞƽếǦđộǦĐốƾǦđầǊ]Ǧ({0}/1)",
    ["在「对局模式」对战中，累计获胜20场（{0}/1）"] = "ǥƓƸƽǦǁũǓǦǉƽắǃƼǦ20ǦǉǇậǃǦǉǇǄǃƼǦ[ƞƽếǦđộǦĐốƾǦđầǊ]Ǧ({0}/1)",
    ["双侠并肩探旧梦，抽丝剥茧拾遗珠。\n快喊上江湖好友，开启这场奇旅吧！\n前往#Y鬼市子#E，找到开启奇旅的方法。\n活动期间完成指定关卡可获得额外奖励哦！\n#Y捕风寻影#E玩法常驻于#Y同游-闯荡#E。"] = "ƮǄǃƼǦƽƾệǅǦǉịǃƽǦǀƾƙǃǦǉƽƑǂǦƸựǊǦǂộǃƼ,ǦǉǇừǊǦǉƾǦƷƑƸǦǀƾệǃǦǉƽậǅǦǤƾǦƸƽƁǊ.\nƨƶǊǦƼọƾǦƽảǄǦƽữǊǦƼƾƶǃƼǦƽồ,ǦƷắǉǦđầǊǦƸƽǊǓếǃǦǀỳǦƽƐǃƽǦǃƐǓǦǃƐǄ!\nĐếǃǦ#YǦƬǊỷǦǥƽịǦǥửǦ#EǦǉƔǂǦƸƑƸƽǦǂởǦǀỳǦƽƐǃƽ.\nǥǇǄǃƼǦǉƽờƾǦƼƾƶǃǦƽǄạǉǦđộǃƼǦƽǄƐǃǦǉƽƐǃƽǦảƾǦƸƽỉǦđịǃƽǦǈẽǦǃƽậǃǦǉƽƙǂǦǉƽưởǃƼ!\nƧốƾǦƸƽơƾǦ#YǦƝộǦƫƽǄǃƼǦǥầǂǦẢǃƽǦ#EǦǉƽườǃƼǦǉǇựƸǦǉạƾǦ#YǦĐồǃƼǦǝǊǦ-ǦƞƽǊǦǝǊǦ#E.",
    ["可在#Y105阶#E满调律非弓决金色品质装备回收或用作调律材料被消耗时获得。\n\n可用于105阶承音装备的#Y传律培养#E，每次传律可按词条满值的#Y4%#E固定提升。\n\n也可用于105阶装备的#Y装备调律重置#E，重置后#Y只保留初始调律词条#E。每件装备只能重置调律三次，每次需间隔七日。"] = "ƞƚǦǉƽểǦǃƽậǃǦǀƽƾǦǉƽǊǦƽồƾǦƽǄặƸǦǉƾƙǊǦƽƶǄǦǁƐǂǦǃƼǊǓƙǃǦǁƾệǊǦđƾềǊǦǁǊậǉǦƸƽǄǦǉǇƶǃƼǦƷịǦǅƽẩǂǦƸƽấǉǦƦƾǂǦƷậƸǦ#YǦ105Ǧ#EǦđƃǦǂƃǃǦđƾềǊǦǁǊậǉǦ(ǀƽƇǃƼǦǅƽảƾǦƞǊǃƼǦƬǊǓếǉ).\n\nǝƖǃƼǦƸƽǄǦƷồƾǦǤưỡǃƼǦ#YǦǥǇǊǓềǃǦƧǊậǉǦ#EǦǉǇƶǃƼǦƷịǦǥƽừƶǦƀǂǦƸấǅǦ105,ǦǂỗƾǦǁầǃǦǉǇǊǓềǃǦǁǊậǉǦǉăǃƼǦƸốǦđịǃƽǦ#YǦ4%Ǧ#EǦƼƾƑǦǉǇịǦǉốƾǦđƶǦƸủƶǦǉừǦǉố.\n\nƞũǃƼǦƸƚǦǉƽểǦǤƖǃƼǦđểǦ#YǦǥƑƾǦǁậǅǦĐƾềǊǦǁǊậǉǦǉǇƶǃƼǦƷịǦ#EǦƸấǅǦ105,ǦǈƶǊǦǀƽƾǦǉƑƾǦǁậǅǦ#YǦƸƽỉǦƼƾữǦǁạƾǦǉừǦǉốǦđƾềǊǦǁǊậǉǦǀƽởƾǦđầǊǦ#E.ǦƨỗƾǦǉǇƶǃƼǦƷịǦƸƽỉǦƸƚǦǉƽểǦǉƑƾǦǁậǅǦđƾềǊǦǁǊậǉǦ3Ǧǁầǃ,ǦǂỗƾǦǁầǃǦƸƑƸƽǦǃƽƶǊǦ7ǦǃƼƐǓ.",
    ["万匠枢"] = "ƱạǃǦǥượǃƼǦƳǊ",
    ["裂石攻击提升#Y123#E-#Y246#E。\n<裂石穿透|780|#C|154>可基于最小裂石攻击额外提升，当前已提升#Y{1:.1%}#E。达到提升上限需要#Y411#E点<最小裂石攻击|780|#C|151>(当前$STEADY_MIN_PRO_ATK_B:.1f$)。"] = "ƞƇǃƼǦǀƓƸƽǦƧƾệǉǦǥƽạƸƽǦǉăǃƼǦ#YǦ123Ǧ#E-#YǦ246Ǧ#E.\n<ƳǊǓƙǃǦǉƽấǊǦƧƾệǉǦǥƽạƸƽ|780|#C|154>ǦƸƚǦǉƽểǦǉăǃƼǦǉƽƙǂǦǤựƶǦǉǇƙǃǦƞƇǃƼǦǀƓƸƽǦƧƾệǉǦǥƽạƸƽǦǉốƾǦǉƽƾểǊ,ǦƽƾệǃǦđƃǦǉăǃƼǦ#YǦ{1:.1%}Ǧ#E.ǦĐểǦđạǉǦƼƾớƾǦƽạǃǦƸầǃǦ#YǦ411Ǧ#EǦđƾểǂǦ<ƞƇǃƼǦǀƓƸƽǦƧƾệǉǦǥƽạƸƽǦǉốƾǦǉƽƾểǊ|780|#C|151>Ǧ(ƣƾệǃǦǉạƾ:Ǧ$STEADY_MIN_PRO_ATK_B:.1ƻ$).",
    ["用于装备76层-85层叠音的高级材料。"] = "ƩƼǊǓƙǃǦǁƾệǊǦƸƶǄǦƸấǅǦǤƖǃƼǦƸƽǄǦĐƾệǅǦƀǂǦǉǇƶǃƼǦƷịǦǉầǃƼǦ76-85.",
    ["“入油锤炼，有余而止。江湖百炼，难得从容”一剑客于早餐摊前，观油釜翻滚，得悟此真言。"] = "\"ƱƐǄǦǤầǊǦǉƇƾǦǁǊǓệǃ,ǦƸƚǦǤưǦǂƐǦǤừǃƼ.ǦƢƾƶǃƼǦƽồǦƷƑƸƽǦǁǊǓệǃ,ǦǀƽƚǦđượƸǦǉƽǄǃƼǦǤǄǃƼ\"Ǧ-ǦǂộǉǦǀƾếǂǦǀƽƑƸƽǦđứǃƼǦǉǇướƸǦǈạǅǦăǃǦǈƑǃƼ,ǦǆǊƶǃǦǈƑǉǦƸƽảǄǦǤầǊǦǈƇƾǦǈụƸ,ǦđƃǦǃƼộǦǇƶǦƸƽƁǃǦǃƼƇǃǦǃƐǓ.",
    ["金蛋施主"] = "ƦƾǂǦĐảǃǦǥƽƓǦƞƽủ",
    ["天泉林鬼分部"] = "ǥƽƾƙǃǦǥǊǓềǃǦƧƁǂǦƬǊỷǦƫƽƁǃǦƝộ",
    ["慕容焮儿"] = "ƨộǦǝǊǃƼǦƣƁǃǦƩƽƾ",
    ["……要不是练过武功，还真抬不下来你。"] = "……ƩếǊǦǀƽƇǃƼǦǅƽảƾǦđƃǦǉừǃƼǦǁǊǓệǃǦǆǊƶǦǋƅǦƸƇǃƼ,ǦǉƽậǉǦǈựǦǀƽƇǃƼǦǀƽƾƙǃƼǦǃổƾǦǃƼươƾǦǍǊốǃƼǦđƁǊ。",
    ["金瓯回归日，官家广散财。乞怜歌声起，草盆成宝盆。"] = "ƦƾǂǦƀǊǦƽồƾǦǆǊǓǦǃƽậǉ,ǦǆǊƶǃǦƼƾƶǦǆǊảǃƼǦǉƑǃǦǉƐƾ.ǦƦƽấǉǦǁƁǃǦƸƶǦǉƽƶǃƽǦǀƽởƾ,ǦǉƽảǄǦƷồǃǦǉƽƐǃƽǦƷảǄǦƷồǃ.",
    ["好大侠。"] = "ƣảǄǦǋịǦđạƾǦƽƾệǅǦǃƐǓ.",
    ["我是不会说的！"] = "ǥƶǦǃƽấǉǦđịǃƽǦǀƽƇǃƼǦǃƚƾǦđƁǊ!",
    ["还说呢！都是醉花阴的姐姐们偷偷撒的，多浪费啊！"] = "ƞƛǃǦǃƚƾǦǃữƶǦǈƶǄ!ǦĐềǊǦǁƐǦǂấǓǦǋịǦǉỷǦǉỷǦởǦǥƕǓǦƣǄƶǦƀǂǦǁƗǃǦǇắƸǦǇƶǦđƚ,ǦǉƽậǉǦǁƐǦǁƃǃƼǦǅƽƓ!",
    ["谁说我输了？$T(25001)，你赢的是比赛，而我，赢的是钱袋！"] = "ƜƾǦƷảǄǦǉƶǦǉƽǊƶ?Ǧ$T(25001)ǦǃƐǓ,ǦǃƼươƾǦǉƽắǃƼǦǁƐǦǉƽắǃƼǦǉǇậǃǦđấǊ,ǦƸƛǃǦǉƶ,ǦǉƶǦǉƽắǃƼǦǁƐǦǉƽắǃƼǦǉƕƾǦǉƾềǃ!",
    ["终笔写从容"] = "ƞƽǊǃƼǦƝƕǉǦǥảǦǥƽǄǃƼǦǝǄǃƼ",
    ["占清菁"] = "ƞƽƾƙǂǦǥƽƶǃƽǦǥƽƶǃƽ",
    ["季栩之"] = "ƬǊƈǦƣủǦƞƽƾ",
    ["消耗同等级装备或律准石可提升调律等级，获得随机调律词条。\n紫色及以上品质装备调律至最高调律等级后可消耗定音石完成定音，获得定音技。\n调律词条和定音技依附于装备，更换装备后需要对新装备重新培养。\n追忆装备无法进行调律和定音培养。\n\n100阶及以上的紫金品质装备可重置调律，重置后只保留初始词条，可重新调律定音。\n弓决、承音和归燕装备无法进行调律重置。\n每件装备调律重置都有限次和间隔。"] = "ǥƾƙǊǦƽƶǄǦǉǇƶǃƼǦƷịǦƸƖǃƼǦƸấǅǦƽǄặƸǦƧǊậǉǦƞƽǊẩǃǦǥƽạƸƽǦƸƚǦǉƽểǦǉăǃƼǦƸấǅǦĐƾềǊǦƧǊậǉ,ǦǃƽậǃǦǃƼẫǊǦǃƽƾƙǃǦǉƽǊộƸǦǉƓǃƽǦđƾềǊǦǁǊậǉ.\nǥǇƶǃƼǦƷịǦǅƽẩǂǦƸƽấǉǦǥƓǂǦǉǇởǦǁƙǃǦǈƶǊǦǀƽƾǦĐƾềǊǦƧǊậǉǦđếǃǦƸấǅǦǉốƾǦđƶǦƸƚǦǉƽểǦǉƾƙǊǦƽƶǄǦĐịǃƽǦƀǂǦǥƽạƸƽǦđểǦƽǄƐǃǦǉƽƐǃƽǦĐịǃƽǦƀǂ,ǦǃƽậǃǦĐịǃƽǦƀǂǦƦỹ.\nǥƽǊộƸǦǉƓǃƽǦđƾềǊǦǁǊậǉǦǋƐǦĐịǃƽǦƀǂǦƦỹǦǅƽụǦǉƽǊộƸǦǋƐǄǦǉǇƶǃƼǦƷị,ǦǈƶǊǦǀƽƾǦǉƽƶǓǦǉǇƶǃƼǦƷịǦƸầǃǦƷồƾǦǤưỡǃƼǦǁạƾǦƸƽǄǦǉǇƶǃƼǦƷịǦǂớƾ.\nǥǇƶǃƼǦƷịǦǥǇǊǓǦỨƸǦǀƽƇǃƼǦǉƽểǦǉƾếǃǦƽƐǃƽǦƷồƾǦǤưỡǃƼǦĐƾềǊǦƧǊậǉǦǋƐǦĐịǃƽǦƀǂ.\n\nǥǇƶǃƼǦƷịǦǅƽẩǂǦƸƽấǉǦǥửǦƦƾǂǦƸấǅǦ100ǦǉǇởǦǁƙǃǦƸƚǦǉƽểǦđặǉǦǁạƾǦĐƾềǊǦƧǊậǉ,ǦǈƶǊǦǀƽƾǦđặǉǦǁạƾǦƸƽỉǦƼƾữǦǁạƾǦǉƽǊộƸǦǉƓǃƽǦƷƶǃǦđầǊ,ǦƸƚǦǉƽểǦǉƾếǃǦƽƐǃƽǦĐƾềǊǦƧǊậǉǦǋƐǦĐịǃƽǦƀǂǦǁạƾ.\nǥǇƶǃƼǦƷịǦƞǊǃƼǦƬǊǓếǉ,ǦǥƽừƶǦƀǂǦǋƐǦƬǊǓǦƴếǃǦǀƽƇǃƼǦǉƽểǦǉƾếǃǦƽƐǃƽǦđặǉǦǁạƾǦĐƾềǊǦƧǊậǉ.\nƨỗƾǦǉǇƶǃƼǦƷịǦđặǉǦǁạƾǦĐƾềǊǦƧǊậǉǦđềǊǦƸƚǦƼƾớƾǦƽạǃǦǈốǦǁầǃǦǋƐǦǉƽờƾǦƼƾƶǃǦƼƾƃǃǦƸƑƸƽ.",
    ["宝剑，英雄剑，便宜……便宜卖嘞！"] = "ƝảǄǦǀƾếǂ,ǦƜǃƽǦƣƖǃƼǦƦƾếǂ,ǦǇẻǦđƁǓ...ǦƷƑǃǦǇẻǦđƁǓ!",
    ["卖——剑，稀世宝剑……买么大侠？"] = "ƝƑǃǦ—Ǧǀƾếǂ,ǦƽǓǦǉƽếǦƷảǄǦǀƾếǂ...ǦđạƾǦƽƾệǅǦǂǊƶǦǀƽƇǃƼ?",
    ["诶？怎、怎么又是你！你……不能、不能再打我……"] = "ƣả?ǦƮƶǄ,ǦǈƶǄǦǁạƾǦǁƐǦǃƼươƾ!ǦƩƼươƾ...ǦǀƽƇǃƼǦđượƸ,ǦǀƽƇǃƼǦđượƸǦđƑǃƽǦǉƶǦǃữƶ...",
    ["什么没人要，准又是偷的。"] = "ƞƑƾǦƼƔǦǂƐǦǀƽƇǃƼǦƶƾǦǁấǓ,ǦƸƽắƸǦƸƽắǃǦǁạƾǦǁƐǦđồǦăǃǦǉǇộǂǦǇồƾ.",
    ["嗝，你也来点，大侠？"] = "Ợ,ǦđạƾǦƽƾệǅǦƸũǃƼǦǁƐǂǦǂộǉǦƓǉǦƸƽứ?",
    ["大侠，要、要不说咱有缘呢！刚得一宝剑，嘿，就、就又遇上了！"] = "ĐạƾǦƽƾệǅ,ǦǅƽảƾǦǃƚƾǦǁƐǦƸƽƕǃƼǦǉƶǦƸƚǦǤǊǓƙǃǦđấǓ!ǦƱừƶǦƸƚǦđượƸǦǉƽƶǃƽǦƷảǄǦǀƾếǂ,ǦƽƔ,ǦǁạƾǦƼặǅǦđượƸǦǃƼƐƾǦǇồƾ!",
    ["我一看就知道，这宝剑可不一般！正当……正当你这样的大侠来配！"] = "ǥƶǦǃƽƔǃǦǂộǉǦƸƑƾǦǁƐǦƷƾếǉǦǃƼƶǓ,ǦǉƽƶǃƽǦƷảǄǦǀƾếǂǦǃƐǓǦǀƽƇǃƼǦƽềǦǉầǂǦǉƽườǃƼ!ǦǥƽậǉǦđƕǃƼǦǁƐ...ǦđƕǃƼǦǁƐǦđểǦǍứǃƼǦǋớƾǦđạƾǦƽƾệǅǦǃƽưǦǃƼƐƾ!",
    ["三尺长，三指宽……端的是寒光凛凛，吹毛即断……剑柄，剑柄雕着梅花……嘿，还是一把英雄剑！"] = "ǝƐƾǦƷƶǦǉƽướƸ,ǦǇộǃƼǦƷƶǦǉƽốǃ...ǦǆǊảǦǉƽựƸǦǁƐǦƽƐǃǦǆǊƶǃƼǦǁẫǂǦǁƾệǉ,ǦǉƽổƾǦǉƚƸǦđứǉǦǃƼƶǓ...ǦƸƽǊƇƾǦǀƾếǂ,ǦƸƽǊƇƾǦǀƾếǂǦƸƚǦƸƽạǂǦƽǄƶǦǂƶƾ...ǦƽƔ,ǦƸƛǃǦǁƐǦǂộǉǦǉƽƶǃƽǦƜǃƽǦƣƖǃƼǦƦƾếǂǦǃữƶ!",
    ["哎，宝、宝剑都是有灵的，可不能随便看。有缘结缘，没缘再见……你，有缘还是没缘？"] = "ƞƽƶǄǦƇƾ,ǦƷảǄǦǀƾếǂǦđềǊǦƸƚǦǁƾǃƽǦǉƓǃƽǦƸả,ǦǀƽƇǃƼǦǉƽểǦǍƺǂǦǉƖǓǦǉƾệǃǦđượƸ.ǦƞƚǦǤǊǓƙǃǦǉƽƔǦǀếǉǦǤǊǓƙǃ,ǦǀƽƇǃƼǦǤǊǓƙǃǦǉƽƔǦǉạǂǦƷƾệǉ...ǦǃƼươƾ,ǦƸƚǦǤǊǓƙǃǦƽƶǓǦǁƐǦǀƽƇǃƼǦǤǊǓƙǃ?",
    ["怕是你没见过什么英雄，把破烂当宝贝了吧。"] = "ǑǦǁƐǦǃƼươƾǦƸƽưƶǦǉừǃƼǦǉƽấǓǦƶǃƽǦƽƖǃƼǦƷƶǄǦƼƾờ,ǦǃƙǃǦǂớƾǦƸǄƾǦđồǃƼǦǃƑǉǦǁƐǦƷảǄǦƷốƾǦǃƽỉ.",
    ["怎、怎么没见过？我见过好多回、好多回……"] = "ƮƶǄ,ǦǈƶǄǦǁạƾǦƸƽưƶǦǉƽấǓ?ǦǥƶǦǉƽấǓǦǃƽƾềǊǦǁầǃǦǇồƾ,ǦǃƽƾềǊǦǁầǃǦǁắǂǦǇồƾ...",
    ["饼子……娘烙的饼子……"] = "ƝƑǃƽǦǃướǃƼ...ǦƷƑǃƽǦǃướǃƼǦǃươǃƼǦǁƐǂ...",
    ["饿……好饿……给点吃的吧……"] = "Đƚƾ...ǦđƚƾǦǆǊƑ...ǦƸƽǄǦǍƾǃǦƸƽƕǉǦƼƔǦăǃǦđƾ...",
    ["嘿，老实你知道不？"] = "ƩƐǓ,ǦǃƼươƾǦƸƚǦƷƾếǉǦđƾềǊǦǀƽƇǃƼǦƽả?",
    ["行，那就晚上。"] = "ĐượƸ,ǦǋậǓǦǉƽƔǦƷǊổƾǦǉốƾ.",
    ["要糟……这窟窿怎被人瞧见了？还瞎往外说，一传十，十传百……唉呀，这遭得抓紧！"] = "ƣỏǃƼǦǇồƾ...ǦƸƑƾǦǁỗǦǉƽủǃƼǦǃƐǓǦǈƶǄǦǁạƾǦƷịǦǃƼườƾǦǉƶǦǉǇƇǃƼǦǉƽấǓǦǇồƾ?ǦƞƛǃǦǇƙǊǦǇƶǄǦǁǊǃƼǦǉǊǃƼ,ǦǂộǉǦǉǇǊǓềǃǦǂườƾ,ǦǂườƾǦǉǇǊǓềǃǦǉǇăǂ...ǦƑƾǦƸƽƐ,ǦǅƽƺǃǦǃƐǓǦǅƽảƾǦǁƐǂǦƸƽǄǦǃƽƶǃƽǦǂớƾǦđượƸ!",
    ["死小子，逮个人就敢搭伙……这年头亲爹也信不得啊……"] = "ǥƽằǃƼǦǇƶǃƽǦƸǄǃ,ǦǋớǦđượƸǦƶƾǦƸũǃƼǦǤƑǂǦƼƚǅǦƽộƾ...ǦƸƑƾǦǉƽờƾǦƷǊổƾǦǃƐǓǦđếǃǦƸƽƶǦǇǊộǉǦƸũǃƼǦƸƽẳǃƼǦǉƾǃǦđượƸǦđƁǊ...",
    ["咳咳，来来，喝酒喝酒……"] = "ƦƽụǦǀƽụ,ǦǉớƾǦđƁǓǦǉớƾǦđƁǓ,ǦǊốǃƼǦǇượǊǦǊốǃƼǦǇượǊ...",
    ["江晏，别忘了，这是晋军行营，杜帅的地界。你非将帅又无官身，五次三番出入我军机重地……"] = "ƢƾƶǃƼǦƴếǃ,ǦđừǃƼǦǆǊƙǃǦđƁǓǦǁƐǦƽƐǃƽǦǤǄƶǃƽǦǥấǃǦǆǊƁǃ,ǦđịƶǦƼƾớƾǦƸủƶǦĐỗǦǈǄƑƾ.ǦƩƼươƾǦǀƽƇǃƼǦǅƽảƾǦǉướǃƼǦǈǄƑƾǦǁạƾǦƸƽẳǃƼǦƸƚǦǆǊƶǃǦǉƽƁǃ,ǦǤăǂǦǁầǃǦƷảǓǦǁượǉǦǇƶǦǋƐǄǦǉǇọǃƼǦđịƶǦǆǊƁǃǦƸơǦƸủƶǦǉƶ...",
    ["不过我看在王将军的面子上，也不曾为难于你。"] = "ƩƽưǃƼǦǉƶǦǃểǦǂặǉǦƱươǃƼǦǉướǃƼǦǆǊƁǃǦǃƙǃǦƸũǃƼǦƸƽưƶǦǉừǃƼǦǁƐǂǦǀƽƚǦǃƼươƾ.",
    ["来，今儿也给我孙某人个面子。同喝一坛酒，就是兄弟，干了！"] = "ǥớƾǦđƁǓ,ǦƽƇǂǦǃƶǓǦƸũǃƼǦǃểǦǂặǉǦƽọǦǥƇǃǦǉƶǦǂộǉǦƸƽƕǉ.ǦƞƖǃƼǦǊốǃƼǦǂộǉǦǋƛǦǇượǊǦǉƽƔǦǁƐǦƽǊǓǃƽǦđệ,ǦƸạǃ!",
    ["我——我都是为了我的两个侄女啊，天可怜见，才四五岁，没爹没娘，饿得有出气没进气啦……"] = "ǥƶǦ—ǦǉƶǦđềǊǦǁƐǦǋƔǦƽƶƾǦđứƶǦƸƽƑǊǦƼƑƾǦƸủƶǦǉƶǦǉƽƇƾ,ǦǉǇờƾǦǍƶǃƽǦƸƽứǃƼǦƼƾƑǂ,ǦǂớƾǦƸƚǦƷốǃǦǃăǂǦǉǊổƾ,ǦǀƽƇǃƼǦƸƽƶǦǀƽƇǃƼǦǂẹ,ǦđƚƾǦđếǃǦǂứƸǦǉƽǄƾǦǉƽƚǅǦǇồƾ...",
    ["嘿，那些兵痞，没脑子！打不过……打不过就跑嘛，废那么多话……他们不挨刀，谁挨刀？"] = "ƣƔ,ǦǂấǓǦǉƙǃǦƷƾǃƽǦƷƾềǃǦđƚǦǉƽậǉǦǀƽƇǃƼǦƸƚǦǃƃǄ!ǦĐƑǃƽǦǀƽƇǃƼǦǁạƾ...ǦđƑǃƽǦǀƽƇǃƼǦǁạƾǦǉƽƔǦƸƽạǓǦđƾǦƸƽứ,ǦǃƚƾǦǃƽảǂǦǃƽƾềǊǦǉƽếǦǁƐǂǦƼƔ...ǦƷọǃǦƸƽƕǃƼǦǀƽƇǃƼǦăǃǦđƶǄǦǉƽƔǦƶƾǦăǃ?",
    ["怎、怎没吃到？不是给你们喝了米汤……呃，喝了……粥……"] = "ƮƶǄ,ǦǈƶǄǦǁạƾǦƸƽưƶǦđượƸǦăǃ?ǦƞƽẳǃƼǦǅƽảƾǦđƃǦƸƽǄǦƸƑƸǦǃƼươƾǦǊốǃƼǦǃướƸǦƼạǄ...Ǧừǂ,ǦǊốǃƼ...ǦƸƽƑǄǦǇồƾǦǈƶǄ...",
    ["那一小碗……清得见底，也叫米汤……"] = "ƞƚǦǂộǉǦƷƑǉǦǃƽỏǦǍƓǊ...ǦǉǇǄǃƼǦǋƺǄǦǉƽấǓǦđƑǓ,ǦǂƐǦƸũǃƼǦƼọƾǦǁƐǦǃướƸǦƼạǄǦǈƶǄ...",
    ["嗯？一小碗……就不算吃的啦？一口吃的，也是我嘴里省……省出来的……"] = "ƣử?ǦƨộǉǦƷƑǉǦǃƽỏ...ǦǉƽƔǦǀƽƇǃƼǦǉƓǃƽǦǁƐǦđồǦăǃǦƐ?ǦƨộǉǦǂƾếǃƼǦăǃǦƸũǃƼǦǁƐǦǉƶǦǃƽịǃǦǉừǦǂƾệǃƼǦǂƔǃƽ...ǦǃƽịǃǦǇƶǦđấǓ...",
    ["喂！你怎么全吃了？"] = "ƩƐǓ!ǦƮƶǄǦǃƼươƾǦăǃǦƽếǉǦǈạƸƽǦǉƽế?",
    ["没剩多少了，官爷，高抬贵手，你看我这拖家带口的，孩子还这么小，行行好，给她们留点吧……"] = "ƦƽƇǃƼǦƸƛǃǦƷƶǄǦǃƽƾƙǊǦđƁǊǦǆǊƶǃǦƼƾƶ,ǦǍƾǃǦƸƶǄǦǉƽượǃƼǦƼƾơǦƸƶǄǦđƑǃƽǦǀƽẽ,ǦǃƼƐƾǦǍƺǂǦǉƶǦđƁǓǦǉƶǓǦƷồǃƼǦǉƶǓǦƷế,ǦƽƐƾǦǉửǦƸƛǃǦǃƽỏǦǉƽếǦǃƐǓ,ǦǁƐǂǦơǃǦǁƐǂǦǅƽướƸǦđểǦǁạƾǦƸƽǄǦƸƽƕǃƼǦǂộǉǦƓǉǦđƾ...",
    ["孩子小，干老子什么事，是老子生的？"] = "ǥǇẻǦƸǄǃǦǃƽỏǦǉƽƔǦǁƾƙǃǦǆǊƶǃǦǆǊƑƾǦƼƔǦđếǃǦǁƃǄǦǉử,ǦǁƐǦǤǄǦǁƃǄǦǉửǦđẻǦǇƶǦƸƽắƸ?",
    ["不交粮也行，这俩娃娃给我带走，能卖俩子儿，便算抵了！"] = "ƦƽƇǃƼǦǃộǅǦǁươǃƼǦƸũǃƼǦđượƸ,ǦƽƶƾǦđứƶǦǃƽƚƸǦǃƐǓǦđểǦǉƶǦǂƶǃƼǦđƾ,ǦƷƑǃǦđượƸǦǂấǓǦđồǃƼǦǉƽƔǦƸǄƾǦǃƽưǦƷƖǦǋƐǄ!",
    ["哼，还和老子讲上价了？就这么点吃的，糊弄谁呢。孩子也带走，能卖几个子儿是几个。"] = "ƣừ,ǦƸƛǃǦǤƑǂǦǂặƸǦƸảǦǋớƾǦǁƃǄǦǉửǦƐ?ǦƞƚǦƷấǓǦǃƽƾƙǊǦđồǦăǃǦǉƽƔǦǁừƶǦđượƸǦƶƾ.ǦĐứƶǦǉǇẻǦƸũǃƼǦǂƶǃƼǦđƾǦƽếǉ,ǦƷƑǃǦđượƸǦƷƶǄǦǃƽƾƙǊǦƽƶǓǦƷấǓǦǃƽƾƙǊ.",
    ["官爷，官爷这俩孩子太小，卖、卖不上价的……"] = "ƬǊƶǃǦƼƾƶ,ǦǆǊƶǃǦƼƾƶ,ǦƽƶƾǦđứƶǦǃƽỏǦǃƐǓǦƷƗǦǆǊƑ,ǦƷƑǃ...ǦƷƑǃǦǀƽƇǃƼǦđượƸǦƼƾƑǦđƁǊ...",
    ["老子今儿个就是粮也要人也要！"] = "ƧƃǄǦǉửǦƽƇǂǦǃƶǓǦǁươǃƼǦǉƽựƸǦƸũǃƼǦǂǊốǃǦǂƐǦǃƼườƾǦƸũǃƼǦǂǊốǃ!",
    ["坏人，你们这些坏人！"] = "ƩƼườƾǦǍấǊ,ǦƸƑƸǦǃƼườƾǦǁƐǦǁũǦǃƼườƾǦǍấǊ!",
    ["叔叔……别打叔叔……"] = "ǥƽƕƸǦǉƽƕƸ...ǦđừǃƼǦđƑǃƽǦǉƽƕƸǦǉƽƕƸ...",
    ["别哭丧了，快跑啊……哎呦……"] = "ĐừǃƼǦǀƽƚƸǦǁƚƸǦǃữƶ,ǦƸƽạǓǦǂƶǊǦđƾ...ǦƑƾǦƸƽƐ...",
    ["那小子又来了，快走，走……"] = "ǥƽằǃƼǦǃƽƚƸǦđƚǦǁạƾǦǉớƾǦǇồƾ,ǦǂƶǊǦđƾǦǉƽƇƾ,Ǧđƾ...",
    ["叫我也没用，别卖可怜！世道烂，你们指望我，我能指望谁？"] = "ƢọƾǦǉƶǦƸũǃƼǦǋƇǦǤụǃƼǦǉƽƇƾ,ǦđừǃƼǦƸƚǦƷƑǃǦǉƽảǂ!ǦĐờƾǦǉƽốƾǦǃƑǉ,ǦƸƑƸǦǃƼươƾǦǉǇƇǃƼǦƸậǓǦǋƐǄǦǉƶ,ǦǋậǓǦǉƶǦƷƾếǉǦǉǇƇǃƼǦƸậǓǦǋƐǄǦƶƾ?",
    ["唔……唔……放肚子里才安全。"] = "Ưǂ...Ǧưǂ...ǦǃǊốǉǦǋƐǄǦƷụǃƼǦǂớƾǦǁƐǦƶǃǦǉǄƐǃǦǃƽấǉ.",
    ["唔，两个小丫头吃不了多少……剩点儿就够。"] = "Ưǂ,ǦƽƶƾǦđứƶǦǃƽƚƸǦǃƐǓǦăǃǦƸƽẳǃƼǦƷƶǄǦǃƽƾƙǊǦđƁǊ...ǦƸƛǃǦǉƽừƶǦǂộǉǦƸƽƕǉǦǁƐǦđủǦǇồƾ.",
    ["镇戍仓……接头……物什……"] = "ǥǇấǃǦǥƽƕǦǥƽươǃƼ...ǦǉƾếǅǦđầǊ...ǦǋậǉǦǅƽẩǂ...",
    ["哇……这亮闪闪的剑柄……值钱，铁定值钱……"] = "ƪƶ...ǦƸƽǊƇƾǦǀƾếǂǦǈƑǃƼǦǁấǅǦǁƑǃƽǦǉƽếǦǃƐǓ...ǦđƑǃƼǦǉƾềǃ,ǦƸƽắƸǦƸƽắǃǦǁƐǦđƑǃƼǦǉƾềǃǦǇồƾ...",
    ["出来。"] = "ƭƶǦđƁǓ.",
    ["哎，这剑真漂亮！一看就是名家锻制，价值连城……"] = "ƞƽƶǄǦƇƾ,ǦǉƽƶǃƽǦǀƾếǂǦǃƐǓǦǉƽậǉǦđẹǅ!ǦƩƽƔǃǦǂộǉǦƸƑƾǦǁƐǦƷƾếǉǦǤǄǦǤƶǃƽǦƼƾƶǦǇƘǃǦđƕƸ,ǦƼƾƑǦǉǇịǦǁƾƙǃǦǉƽƐǃƽ...",
    ["大侠为国为民，劳碌奔波，嘿嘿，有啥咱能帮上忙的，您尽管说！"] = "ĐạƾǦƽƾệǅǦǋƔǦǃướƸǦǋƔǦǤƁǃ,ǦƷƇǃǦƷƶǦǋấǉǦǋả,ǦƽƔǦƽƔ,ǦƸƚǦǋƾệƸǦƼƔǦƸƽƕǃƼǦǉƾểǊǦǃƽƁǃǦƼƾƕǅǦđượƸ,ǦǃƼƐƾǦƸứǦǋƾệƸǦǈƶƾǦƷảǄ!",
    ["只要是您江大侠的事儿，小的赴汤蹈火，也一定给您办好！"] = "ƞƽỉǦƸầǃǦǁƐǦƸƽǊǓệǃǦƸủƶǦƢƾƶǃƼǦđạƾǦƽƾệǅǦǃƼƐƾ,ǦǉƾểǊǦǃƽƁǃǦǤƖǦǃƽảǓǦǋƐǄǦǤầǊǦǈƇƾǦǁửƶǦƷỏǃƼǦƸũǃƼǦǃƽấǉǦđịǃƽǦƽǄƐǃǦǉƽƐǃƽǦƸƽǄǦǃƼƐƾ!",
    ["啊，自然自然，活蹦乱跳的，我和俩孩子能活到现在，全仰赖大侠啊！"] = "À,ǦđươǃƼǦǃƽƾƙǃǦđươǃƼǦǃƽƾƙǃ,ǦǋẫǃǦƸƛǃǦǈốǃƼǦǃƽăǃǦđƁǓ,ǦǉƶǦǋƐǦƽƶƾǦđứƶǦǃƽỏǦǈốǃƼǦđượƸǦđếǃǦƼƾờǦđềǊǦǃƽờǦƸậǓǦǋƐǄǦđạƾǦƽƾệǅǦƸả!",
    ["嗐，那不没法儿么！再来一次，我肯定……诶，大侠？大侠您去哪儿？"] = "ƣạƾ,ǦđƚǦƸƽẳǃƼǦǅƽảƾǦǁƐǦǀƽƇǃƼǦƸƛǃǦƸƑƸƽǦǃƐǄǦǈƶǄ!ǦƩếǊǦƸƚǦǁầǃǦǈƶǊ,ǦǉƶǦƸƽắƸǦƸƽắǃ...Ǧƽở,ǦđạƾǦƽƾệǅ?ǦĐạƾǦƽƾệǅǦǃƼƐƾǦđƾǦđƁǊǦđấǓ?",
    ["你南下路上若遇侠客，便告诉他们：杜贼背信，中渡桥告急，望诸位共援北岸，卯时，桥南见！"] = "ƩƼươƾǦǉǇƙǃǦđườǃƼǦǍǊốǃƼǦǅƽƓƶǦƩƶǂǦǃếǊǦƼặǅǦƽƾệǅǦǀƽƑƸƽ,ǦƽƃǓǦƷảǄǦƽọǦǇằǃƼ:ǦĐỗǦǉặƸǦƷộƾǦǉƓǃ,ǦǥǇǊǃƼǦĐộǦƦƾềǊǦƸƑǄǦƸấǅ,ǦǂǄǃƼǦƸƽưǦǋịǦƸƖǃƼǦƸƽƾǦǋƾệǃǦƷờǦƝắƸ,ǦƼƾờǦƨƃǄ,ǦƼặǅǦǃƽƶǊǦởǦǅƽƓƶǦƩƶǂǦƸầǊ!",
    ["什么？杜重威……？"] = "ƞƑƾǦƼƔ?ǦĐỗǦǥǇọǃƼǦǕǓ...?",
    ["……是义父骗我……要支开我，他是要……！"] = "...ƧƐǦǃƼƽĩƶǦǅƽụǦǁừƶǦǉƶ...ǦǂǊốǃǦǉƑƸƽǦǉƶǦǇƶ,ǦǃƼườƾǦǁƐǦǂǊốǃ...!",
    ["“混小子，把剑收起来。”"] = "\"ǥƽằǃƼǦǇƶǃƽǦƸǄǃ,ǦǉƽǊǦǀƾếǂǦǁạƾǦđƾ.\"",
    ["入住庄客"] = "ǥǇƶǃƼǦƦƽƑƸƽǦƸưǦǉǇƕ",
    ["慾塑"] = "ǝụƸǦǥố",
    ["玄挽卿"] = "ƣǊǓềǃǦƱƃǃǦƦƽƶǃƽ",
    ["薛清秋"] = "ǥƾếǉǦǥƽƶǃƽǦǥƽǊ",
