    ["多材料加工"] = "ƢƾƶǦƸƇǃƼǦđƶǦǃƼǊǓƙǃǦǁƾệǊ",
    ["由红珊耳油珍·三阶和红珊粉屑珍·三阶在制物合坊加工制成。"] = "ǝǄǦƣồǃƼǦƮƶǃǦƩƽĩǦǝǊǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦǋƐǦƣồǃƼǦƮƶǃǦƫƽấǃǦǥƾếǉǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦƼƾƶǦƸƇǃƼǦǉạƾǦƞƽếǦƱậǉǦƣợǅǦƫƽườǃƼ.",
    ["珊瑚玉提纯磨粉，苍耳焙香熬油慢炖封坛。药韵玉香，油润醇厚。"] = "ƮƶǃǦƽƇǦǃƼọƸǦǉƾǃƽǦǁǊǓệǃǦǂƐƾǦƷộǉ,ǦǉƽươǃƼǦǃƽĩǦǈƶǄǦǉƽơǂǦǃấǊǦǤầǊǦǃƾǃƽǦǃƽỏǦǁửƶǦđƚǃƼǦǋƛ.ǦǝượƸǦǋậǃǦǃƼọƸǦƽươǃƼ,ǦǤầǊǦǂướǉǦđậǂǦđƐ.",
    ["由耳铜红土珍·三阶和耳铁粉屑珍·三阶在制物合坊加工制成。"] = "ǝǄǦƩƽĩǦĐồǃƼǦƣồǃƼǦǥƽổǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦǋƐǦƩƽĩǦǥƽƾếǉǦƫƽấǃǦǥƾếǉǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦƼƾƶǦƸƇǃƼǦǉạƾǦƞƽếǦƱậǉǦƣợǅǦƫƽườǃƼ.",
    ["苍耳提纯凝膏，铜矿铁矿锻制熔合红土提纯铸块。药韵金铁裹土香，质地坚密。"] = "ǥƽươǃƼǦǃƽĩǦǉƾǃƽǦǁǊǓệǃǦǉƽƐǃƽǦƸƶǄ,ǦǆǊặǃƼǦđồǃƼǦǆǊặǃƼǦǈắǉǦǇƘǃǦđƕƸǦǃƚǃƼǦƸƽảǓǦƸƖǃƼǦƽồǃƼǦǉƽổǦǉƾǃƽǦǁǊǓệǃǦđƕƸǦǀƽốƾ.ǦǝượƸǦǋậǃǦǀƾǂǦǉƽƾếǉǦǆǊǓệǃǦǉƽổǦƽươǃƼ,ǦƸƽấǉǦƸứǃƼǦƸƽắƸ.",
    ["由桐松珍·二阶和桐松粉屑珍·三阶在制物合坊加工制成。"] = "ǝǄǦĐồǃƼǦǥƖǃƼǦǥǇƁǃǦ·ǦƩƽịǦƢƾƶƾǦǋƐǦĐồǃƼǦǥƖǃƼǦƫƽấǃǦǥƾếǉǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦƼƾƶǦƸƇǃƼǦǉạƾǦƞƽếǦƱậǉǦƣợǅǦƫƽườǃƼ.",
    ["桐木松木提纯凝脂，按比压块凝制。清松双韵，质地坚密。"] = "ƢỗǦǃƼƇǦđồǃƼǦƼỗǦǉƖǃƼǦǉƾǃƽǦǁǊǓệǃǦǉƽƐǃƽǦǂỡ,ǦǃƗǃǦǀƽốƾǦǉƽƺǄǦǉỉǦǁệǦǃƼưǃƼǦǀếǉ.ǦǥƽƶǃƽǦǉƖǃƼǦǈǄǃƼǦǋậǃ,ǦƸƽấǉǦƸứǃƼǦƸƽắƸ.",
    ["由蕈铁红土珍·三阶和耳铁粉屑珍·三阶在制物合坊加工制成。"] = "ǝǄǦǥƽầǂǦǥƽƾếǉǦƣồǃƼǦǥƽổǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦǋƐǦƩƽĩǦǥƽƾếǉǦƫƽấǃǦǥƾếǉǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦƼƾƶǦƸƇǃƼǦǉạƾǦƞƽếǦƱậǉǦƣợǅǦƫƽườǃƼ.",
    ["香蕈苍耳提纯凝膏，双份铁矿锻制熔合铸块。菌药双韵裹铁韵，质地坚密。"] = "ƩấǂǦƽươǃƼǦǉƽươǃƼǦǃƽĩǦǉƾǃƽǦǁǊǓệǃǦǉƽƐǃƽǦƸƶǄ,ǦƼấǅǦđƇƾǦǆǊặǃƼǦǈắǉǦǇƘǃǦđƕƸǦǃƚǃƼǦƸƽảǓǦđƕƸǦǀƽốƾ.ǦƦƽǊẩǃǦǤượƸǦǈǄǃƼǦǋậǃǦǆǊǓệǃǦǉƽƾếǉǦǋậǃ,ǦƸƽấǉǦƸứǃƼǦƸƽắƸ.",
    ["由红珊珍·二阶和云绿粉屑珍·三阶在制物合坊加工制成。"] = "ǝǄǦƣồǃƼǦƮƶǃǦǥǇƁǃǦ·ǦƩƽịǦƢƾƶƾǦǋƐǦƱƁǃǦƧụƸǦƫƽấǃǦǥƾếǉǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦƼƾƶǦƸƇǃƼǦǉạƾǦƞƽếǦƱậǉǦƣợǅǦƫƽườǃƼ.",
    ["红土珊瑚玉提纯凝合，云沙绿松石提纯熔合铸块。土玉沙绿四韵相融，质地坚密。"] = "ƣồǃƼǦǉƽổǦǈƶǃǦƽƇǦǃƼọƸǦǉƾǃƽǦǁǊǓệǃǦǃƼưǃƼǦƽợǅ,ǦǋƁǃǦǈƶǦǁụƸǦǉƖǃƼǦǉƽạƸƽǦǉƾǃƽǦǁǊǓệǃǦǃƚǃƼǦƸƽảǓǦđƕƸǦǀƽốƾ.ǦǥƽổǦǃƼọƸǦǈƶǦǁụƸǦǉứǦǋậǃǦǤǊǃƼǦƽƛƶ,ǦƸƽấǉǦƸứǃƼǦƸƽắƸ.",
    ["由耳铜珍·二阶和耳铁粉屑珍·三阶在制物合坊加工制成。"] = "ǝǄǦƩƽĩǦĐồǃƼǦǥǇƁǃǦ·ǦƩƽịǦƢƾƶƾǦǋƐǦƩƽĩǦǥƽƾếǉǦƫƽấǃǦǥƾếǉǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦƼƾƶǦƸƇǃƼǦǉạƾǦƞƽếǦƱậǉǦƣợǅǦƫƽườǃƼ.",
    ["苍耳提纯凝膏，铜矿铁矿锻制熔合铸块。药韵裹金铁，质地坚密。"] = "ǥƽươǃƼǦǃƽĩǦǉƾǃƽǦǁǊǓệǃǦǉƽƐǃƽǦƸƶǄ,ǦǆǊặǃƼǦđồǃƼǦǆǊặǃƼǦǈắǉǦǇƘǃǦđƕƸǦǃƚǃƼǦƸƽảǓǦđƕƸǦǀƽốƾ.ǦǝượƸǦǋậǃǦǆǊǓệǃǦǀƾǂǦǉƽƾếǉ,ǦƸƽấǉǦƸứǃƼǦƸƽắƸ.",
    ["由乌珊红土珍·三阶和乌珊粉屑珍·三阶在制物合坊加工制成。"] = "ǝǄǦƆǦƮƶǃǦƣồǃƼǦǥƽổǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦǋƐǦƆǦƮƶǃǦƫƽấǃǦǥƾếǉǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦƼƾƶǦƸƇǃƼǦǉạƾǦƞƽếǦƱậǉǦƣợǅǦƫƽườǃƼ.",
    ["乌木珊瑚玉提纯凝合，红土提纯熔合铸块。沉玉双韵裹土香，质地坚密。"] = "ƢỗǦǂǊǃǦǈƶǃǦƽƇǦǃƼọƸǦǉƾǃƽǦǁǊǓệǃǦǃƼưǃƼǦƽợǅ,ǦƽồǃƼǦǉƽổǦǉƾǃƽǦǁǊǓệǃǦǃƚǃƼǦƸƽảǓǦđƕƸǦǀƽốƾ.ǦǥǇầǂǦǃƼọƸǦǈǄǃƼǦǋậǃǦǆǊǓệǃǦǉƽổǦƽươǃƼ,ǦƸƽấǉǦƸứǃƼǦƸƽắƸ.",
    ["由红珊蕈油珍·三阶和云绿粉屑珍·三阶在制物合坊加工制成。"] = "ǝǄǦƣồǃƼǦƮƶǃǦǥƽầǂǦǝǊǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦǋƐǦƱƁǃǦƧụƸǦƫƽấǃǦǥƾếǉǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦƼƾƶǦƸƇǃƼǦǉạƾǦƞƽếǦƱậǉǦƣợǅǦƫƽườǃƼ.",
    ["由耳铜珍·二阶和蕈铜粉屑珍·三阶在制物合坊加工制成。"] = "ǝǄǦƩƽĩǦĐồǃƼǦǥǇƁǃǦ·ǦƩƽịǦƢƾƶƾǦǋƐǦǥƽầǂǦĐồǃƼǦƫƽấǃǦǥƾếǉǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦƼƾƶǦƸƇǃƼǦǉạƾǦƞƽếǦƱậǉǦƣợǅǦƫƽườǃƼ.",
    ["苍耳香蕈提纯凝膏，双份铜矿锻制熔合铸块。药菌双韵裹铜泽，质地坚密。"] = "ǥƽươǃƼǦǃƽĩǦǃấǂǦƽươǃƼǦǉƾǃƽǦǁǊǓệǃǦǉƽƐǃƽǦƸƶǄ,ǦƼấǅǦđƇƾǦǆǊặǃƼǦđồǃƼǦǇƘǃǦđƕƸǦǃƚǃƼǦƸƽảǓǦđƕƸǦǀƽốƾ.ǦǝượƸǦǀƽǊẩǃǦǈǄǃƼǦǋậǃǦǆǊǓệǃǦđồǃƼǦǉǇạƸƽ,ǦƸƽấǉǦƸứǃƼǦƸƽắƸ.",
    ["由云松蕈油珍·三阶和云绿粉屑珍·三阶在制物合坊加工制成。"] = "ǝǄǦƱƁǃǦǥƖǃƼǦǥƽầǂǦǝǊǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦǋƐǦƱƁǃǦƧụƸǦƫƽấǃǦǥƾếǉǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦƼƾƶǦƸƇǃƼǦǉạƾǦƞƽếǦƱậǉǦƣợǅǦƫƽườǃƼ.",
    ["云松蕈撕条，山茶油慢熬出鲜封坛锁味。菌香醇厚，油润绵长。"] = "ƩấǂǦǋƁǃǦǉƖǃƼǦǍƗǦǈợƾ,ǦǤầǊǦǈơǃǦǉǇƐǦǃƾǃƽǦǃƽỏǦǁửƶǦǁấǓǦǋịǦǉươƾǦđƚǃƼǦǋƛǦǀƽƚƶǦƽươǃƼ.ǦƣươǃƼǦǃấǂǦǉƽǊầǃǦƽậǊ,ǦǤầǊǦǂướǉǦǃồǃƼǦǃƐǃ.",
    ["由乌珊珍·二阶和桐松粉屑珍·三阶在制物合坊加工制成。"] = "ǝǄǦƆǦƮƶǃǦǥǇƁǃǦ·ǦƩƽịǦƢƾƶƾǦǋƐǦĐồǃƼǦǥƖǃƼǦƫƽấǃǦǥƾếǉǦǥǇƁǃǦ·ǦǥƶǂǦƢƾƶƾǦƼƾƶǦƸƇǃƼǦǉạƾǦƞƽếǦƱậǉǦƣợǅǦƫƽườǃƼ.",
